window.WPS = window.WPS || {};
WPS.RONJUTSU = [
  // ===== 日本史 =====
  { id: 'j01', s: 'jh', lv: 1, topic: '班田収授法', q: '律令制のもとで、班田収授法は何を目的としていたか。', a: '【戸籍】にもとづいて6歳以上の男女に【口分田】を与え、死後に返させることで、【租】などの税を確実に集めることを目的とした。' },
  { id: 'j02', s: 'jh', lv: 1, topic: '墾田永年私財法', q: '墾田永年私財法（743年）は、土地制度にどのような変化をもたらしたか。', a: '開墾した土地の【私有】を永久に認めたため、貴族や寺社が開墾を進めて【荘園】が広がり、【公地公民】の原則がくずれていった。' },
  { id: 'j03', s: 'jh', lv: 1, topic: '摂関政治', q: '藤原氏は、どのようにして摂関政治の実権を手に入れたか。', a: '娘を天皇の【后】にして、生まれた子を天皇に立てた。天皇の【外戚】として【摂政】や【関白】の地位につき、政治の実権をにぎった。' },
  { id: 'j04', s: 'jh', lv: 1, topic: '院政', q: '院政とはどのような政治か。始めた人物とともに説明せよ。', a: '天皇が位をゆずって【上皇】となったあとも、【院庁】を中心に政治を行うしくみで、1086年に【白河上皇】が始めた。' },
  { id: 'j05', s: 'jh', lv: 1, topic: '御恩と奉公', q: '鎌倉幕府の将軍と御家人の関係を説明せよ。', a: '将軍は御家人の領地を保障したり新しい領地を与えたりする【御恩】を与え、御家人は戦いや警備で【奉公】した。【土地】を仲立ちとしたこの主従関係を【封建制度】という。' },
  { id: 'j06', s: 'jh', lv: 2, topic: '元寇', q: '元寇（蒙古襲来）は、鎌倉幕府の衰退にどうつながったか。', a: '防衛戦では新しい領地が得られず、御家人に十分な【恩賞】を与えられなかった。【分割相続】で困窮していた御家人を救うため【徳政令】を出したが効果は小さく、幕府は信頼を失った。' },
  { id: 'j07', s: 'jh', lv: 2, topic: '日明貿易', q: '足利義満が始めた日明貿易で、勘合が用いられた理由を述べよ。', a: '正式な貿易船と【倭寇】を区別するため、明が与えた【勘合】という合い札を用いた。この貿易は【朝貢】の形式で行われた。' },
  { id: 'j08', s: 'jh', lv: 1, topic: '太閤検地', q: '太閤検地は、社会にどのような変化をもたらしたか。', a: '全国の土地を統一した基準で調べ、生産力を【石高】で表した。耕作者を【検地帳】に登録して年貢の負担者とし、【荘園】のしくみは完全にくずれた。' },
  { id: 'j09', s: 'jh', lv: 2, topic: '刀狩', q: '豊臣秀吉の刀狩の目的と結果を述べよ。', a: '農民から武器を取り上げて【一揆】を防ぎ、農業に専念させた。太閤検地とあわせて、武士と農民の身分を分ける【兵農分離】が進んだ。' },
  { id: 'j10', s: 'jh', lv: 1, topic: '参勤交代', q: '参勤交代は、大名や社会にどのような影響を与えたか。', a: '大名は1年おきに【江戸】と領地を行き来し、妻子は江戸に住まわされた。多額の【出費】で大名の力が弱まる一方、【街道】や宿場町が発達した。' },
  { id: 'j11', s: 'jh', lv: 2, topic: '鎖国', q: '江戸幕府が貿易の相手を限った理由と、その相手を述べよ。', a: '【キリスト教】の広まりを防ぎ、貿易の利益を幕府が独占するため、長崎で【オランダ】と【中国】に限って貿易を認めた。' },
  { id: 'j12', s: 'jh', lv: 2, topic: '享保の改革', q: '徳川吉宗の享保の改革で行われた政策を述べよ。', a: '大名に米を納めさせる【上げ米】を行い、【新田開発】を進めて年貢を増やした。また【公事方御定書】で裁判の基準を定めた。' },
  { id: 'j13', s: 'jh', lv: 2, topic: '田沼の政治', q: '田沼意次の政治の特徴を述べよ。', a: '商人の経済力を利用し、【株仲間】の結成を認めて営業税を取り、【長崎貿易】を拡大した。一方で【わいろ】が横行したと批判された。' },
  { id: 'j14', s: 'jh', lv: 1, topic: '地租改正', q: '地租改正の内容と目的を述べよ。', a: '土地の所有者に【地券】を発行し、【地価】の3%を【現金】で納めさせた。収穫に左右されない、安定した税収を得ることが目的だった。' },
  { id: 'j15', s: 'jh', lv: 2, topic: '自由民権運動', q: '自由民権運動はどのように始まり、何を求めたか。', a: '板垣退助らが【民撰議院設立建白書】を提出して始まり、【国会】の開設や憲法の制定を求めた。政府は1881年に【国会開設の勅諭】を出した。' },
  { id: 'j16', s: 'jh', lv: 2, topic: '条約改正', q: '不平等条約の改正はどのように進んだか。', a: '1894年に【陸奥宗光】が【領事裁判権】の撤廃に成功し、1911年に【小村寿太郎】が【関税自主権】の回復を実現した。' },
  { id: 'j17', s: 'jh', lv: 3, topic: '三国干渉', q: '日清戦争後の三国干渉は、日本にどのような影響を与えたか。', a: '【下関条約】で得た【遼東半島】を、ロシア・ドイツ・フランスの勧告で清に返した。国民のあいだに【ロシア】への反感が高まり、「臥薪嘗胆」を合言葉に【軍備拡張】が進んだ。' },
  { id: 'j18', s: 'jh', lv: 2, topic: '普通選挙法', q: '1925年の普通選挙法と治安維持法は、どのような関係にあるか。', a: '普通選挙法で【満25歳以上の男子】に選挙権が与えられた。同じ年に【治安維持法】を定め、選挙権の拡大で勢いづくおそれのある【共産主義】などの運動を取り締まった。' },
  { id: 'j19', s: 'jh', lv: 3, topic: '満州事変', q: '昭和恐慌は、満州事変にどうつながったか。', a: '【世界恐慌】の影響で農村が深刻な不況におちいり、政党政治への不信が高まった。軍部は【満州】に活路を求め、1931年に【柳条湖事件】を起こして満州事変を始めた。' },
  { id: 'j20', s: 'jh', lv: 1, topic: '農地改革', q: '戦後の農地改革の内容と結果を述べよ。', a: '政府が【地主】の土地を買い上げて【小作人】に安く売り渡し、多くの【自作農】が生まれた。' },
  { id: 'j21', s: 'jh', lv: 2, topic: '高度経済成長', q: '高度経済成長期には、どのような社会問題が生じたか。', a: '工業化が急速に進んだ結果、【公害】が各地で発生し、【四大公害】訴訟が起こった。政府は1967年に【公害対策基本法】を定めた。' },
  { id: 'j22', s: 'jh', lv: 3, topic: '鎌倉新仏教', q: '鎌倉時代に新しい仏教が広まった理由を述べよ。', a: '戦乱やききんで不安が高まる中、【念仏】や【題目】を唱えるなど、わかりやすく実践しやすい教えが示されたため、【武士】や【庶民】に広まった。' },
  { id: 'j23', s: 'jh', lv: 3, topic: '応仁の乱', q: '応仁の乱は、戦国時代の始まりにどうつながったか。', a: '【将軍】のあとつぎ争いに有力【守護大名】の対立が結びついて11年続き、幕府の権威が衰えた。その結果、実力で領国を支配する【戦国大名】が各地に現れた（【下剋上】）。' },
  { id: 'j24', s: 'jh', lv: 3, topic: '天保の改革', q: '水野忠邦の天保の改革が失敗した理由を述べよ。', a: '【株仲間】を解散させたが物価は下がらず、かえって流通が混乱した。江戸・大坂周辺を幕府領にしようとした【上知令】も大名や旗本の反対で撤回され、忠邦は【失脚】した。' },
  // ===== 世界史 =====
  { id: 'w01', s: 'wh', lv: 1, topic: '大運河', q: '隋が建設した大運河は、中国の経済にどのような役割を果たしたか。', a: '【華北】と【江南】を結び、江南でとれた【穀物】を北方の都へ大量に運んだ。豊かな南方の【経済力】が王朝の政治と軍事を支えた。' },
  { id: 'w02', s: 'wh', lv: 1, topic: 'ローマの平和', q: '「ローマの平和」とよばれる時代の特徴を述べよ。', a: '【アウグストゥス】が帝政を始めてから約200年間、地中海世界が政治的に安定した（【パクス=ロマーナ】）。【道路網】の整備などで交易が栄えた。' },
  { id: 'w03', s: 'wh', lv: 1, topic: '十字軍', q: '十字軍の遠征は、ヨーロッパ社会にどのような影響を与えたか。', a: '遠征の失敗で【教皇】の権威が低下し、多くの【諸侯】や騎士が没落した。一方で【東方貿易】がさかんになり、イタリアの諸都市が栄えた。' },
  { id: 'w04', s: 'wh', lv: 2, topic: 'ルネサンス', q: 'ルネサンスがイタリアで始まった理由を述べよ。', a: '東方貿易で栄えた都市に富が集まり、【メディチ家】などの有力者が芸術を保護した。また古代【ギリシア・ローマ】の文化遺産が身近にあり、【ビザンツ帝国】から学者も流入した。' },
  { id: 'w05', s: 'wh', lv: 1, topic: '宗教改革', q: 'ルターが宗教改革を始めたきっかけと、その主張を述べよ。', a: '教皇による【贖宥状】の販売を批判し、1517年に【九十五か条の論題】を発表した。人は【信仰】によってのみ救われ、【聖書】だけが信仰のよりどころだと説いた。' },
  { id: 'w06', s: 'wh', lv: 2, topic: '大航海時代', q: '大航海時代は、ヨーロッパ経済にどのような影響を与えたか。', a: '新航路の開拓で、交易の中心が地中海から【大西洋】沿岸に移った（【商業革命】）。またアメリカ大陸から大量の【銀】が流入し、物価が大きく上がった（【価格革命】）。' },
  { id: 'w07', s: 'wh', lv: 2, topic: '名誉革命', q: '名誉革命の結果、イギリスの政治はどう変わったか。', a: '議会が新しい国王を迎え、【権利の章典】で国王の権力を制限した。これにより【議会】が政治の中心となる【立憲君主制】が確立した。' },
  { id: 'w08', s: 'wh', lv: 1, topic: '産業革命', q: 'イギリスで最初に産業革命が起こった理由を述べよ。', a: '植民地による広い【市場】と原料があったこと、【囲い込み】で生まれた労働力があったこと、【石炭】や鉄などの資源が豊かだったことがあげられる。' },
  { id: 'w09', s: 'wh', lv: 2, topic: 'アメリカ独立革命', q: 'アメリカ独立革命の原因を述べよ。', a: '七年戦争後、財政難のイギリスが【印紙法】などで植民地に課税した。植民地側は「【代表なくして課税なし】」と反発し、1776年に【独立宣言】を発表した。' },
  { id: 'w10', s: 'wh', lv: 1, topic: 'フランス革命', q: 'フランス革命が起こった社会的背景を述べよ。', a: '聖職者の【第一身分】と貴族の【第二身分】は免税などの特権をもち、人口の大部分をしめる【第三身分】が重い負担を負っていた。この【旧体制】への不満が革命につながった。' },
  { id: 'w11', s: 'wh', lv: 2, topic: 'ナポレオン', q: 'ナポレオンの支配は、ヨーロッパにどのような影響を与えたか。', a: '【ナポレオン法典】で法の下の平等など革命の理念を広めた。一方、征服された地域では【ナショナリズム】が高まり、各地で抵抗が起こった。' },
  { id: 'w12', s: 'wh', lv: 3, topic: 'ウィーン体制', q: 'ウィーン体制の基本原則と、崩壊のきっかけを述べよ。', a: 'フランス革命前の王朝と秩序を回復する【正統主義】と、大国の【勢力均衡】を原則とした。しかし【自由主義】やナショナリズムの運動が広がり、1848年の【二月革命】などで崩壊した。' },
  { id: 'w13', s: 'wh', lv: 2, topic: 'アヘン戦争', q: 'アヘン戦争の原因と結果を述べよ。', a: 'イギリスは【茶】の輸入で生じた赤字を補うため、インド産の【アヘン】を清に密輸した。清が取り締まると戦争になり、敗れた清は【南京条約】で香港を割譲し、5港を開いた。' },
  { id: 'w14', s: 'wh', lv: 3, topic: '辛亥革命', q: '辛亥革命は、どのような経過で清朝を倒したか。', a: '1911年に【武昌】で軍隊が蜂起すると各省が独立を宣言し、1912年に【孫文】を臨時大総統とする【中華民国】が成立した。清の実力者【袁世凱】が皇帝を退位させ、清は滅んだ。' },
  { id: 'w15', s: 'wh', lv: 1, topic: '第一次世界大戦', q: '第一次世界大戦は、どのように始まったか。', a: '1914年、オーストリアの帝位継承者夫妻が【サライェヴォ】で暗殺された。これをきっかけに、【三国同盟】側と【三国協商】側の対立が戦争に発展した。' },
  { id: 'w16', s: 'wh', lv: 2, topic: 'ヴェルサイユ条約', q: 'ヴェルサイユ条約は、ドイツにどのような影響を与えたか。', a: 'ドイツはすべての植民地を失い、巨額の【賠償金】と【軍備制限】を課された。国民の不満は高まり、のちに【ナチス】が台頭する一因となった。' },
  { id: 'w17', s: 'wh', lv: 1, topic: 'ニューディール', q: '世界恐慌に対して、アメリカはどのような政策をとったか。', a: '【フランクリン=ローズヴェルト】大統領が【ニューディール】政策を行った。【TVA】などの公共事業で失業者を雇うなど、政府が経済に積極的に関わった。' },
  { id: 'w18', s: 'wh', lv: 2, topic: 'ブロック経済', q: '世界恐慌後のブロック経済は、国際関係にどう影響したか。', a: 'イギリスやフランスは本国と植民地で【ブロック経済】をつくり、外国製品に高い【関税】をかけた。植民地の少ないドイツ・イタリア・日本は対外進出を強め、【第二次世界大戦】の一因となった。' },
  { id: 'w19', s: 'wh', lv: 1, topic: '冷戦', q: '冷戦とはどのような対立か。', a: '第二次世界大戦後の、【アメリカ】を中心とする資本主義陣営と、【ソ連】を中心とする社会主義陣営の対立である。両国が【直接の戦争】をしなかったため冷戦とよばれる。' },
  { id: 'w20', s: 'wh', lv: 3, topic: 'キューバ危機', q: 'キューバ危機の経過と、その後の米ソ関係を述べよ。', a: '1962年、ソ連が【キューバ】に【ミサイル】基地を建設し、核戦争の危機が高まった。ソ連の撤去で回避され、その後米ソ間に【ホットライン】が設けられて【緊張緩和】が進んだ。' },
  { id: 'w21', s: 'wh', lv: 2, topic: 'アッバース朝', q: 'アッバース朝は、ウマイヤ朝とどのような点で異なるか。', a: 'ウマイヤ朝では【アラブ人】が特権をもったが、アッバース朝では【ムスリム】であれば民族に関係なく平等とされ、改宗した非アラブ人も【ジズヤ】（人頭税）を免除された。' },
  { id: 'w22', s: 'wh', lv: 2, topic: 'モンゴル帝国', q: 'モンゴル帝国の成立は、東西の交流にどのような影響を与えたか。', a: 'ユーラシアの広い範囲が一つの勢力のもとにまとまり、【駅伝制】（ジャムチ）が整備されて、陸路と【海路】の交易がさかんになった。【マルコ=ポーロ】などが東方を訪れた。' },
  { id: 'w23', s: 'wh', lv: 3, topic: '銀の流入', q: '16世紀以降、中国に大量の銀が流入した理由と影響を述べよ。', a: '【日本】や【アメリカ大陸】で産出された銀が、生糸や陶磁器の代価として中国に流れ込んだ。その結果、税を銀で一括して納める【一条鞭法】が実施された。' },
  { id: 'w24', s: 'wh', lv: 3, topic: 'ソ連解体', q: 'ソ連が解体に向かった過程を述べよ。', a: '【ゴルバチョフ】が【ペレストロイカ】と情報公開（【グラスノスチ】）を進めたが経済は改善せず、東欧では民主化が進んだ。1991年に各共和国が独立し、ソ連は解体した。' },
  // ===== 追加分(自動) =====
  {"id": "jhx1", "s": "jh", "lv": 1, "topic": "旧石器時代", "q": "岩宿遺跡の発見は、日本の歴史研究にとってどのような意義をもったか説明せよ。", "a": "【相沢忠洋】が群馬県の【岩宿】で【関東ローム層】から【打製石器】を発見し、それまで存在しないと考えられていた日本の旧石器時代の存在が明らかになった。"},
  {"id": "jhx2", "s": "jh", "lv": 1, "topic": "縄文文化の成立", "q": "縄文文化が成立した背景には、どのような自然環境の変化があったか説明せよ。", "a": "氷期が終わって気候が温暖化し、海面が上昇して【日本列島】が形成された。中小動物をとらえるために【弓矢】が使われ、木の実を煮るために【縄文土器】が作られるようになった。"},
  {"id": "jhx3", "s": "jh", "lv": 1, "topic": "貝塚", "q": "縄文時代の貝塚からは、当時のどのようなことがわかるか説明せよ。", "a": "貝塚は当時の【ごみ捨て場】で、貝殻や獣・魚の骨、土器などから人々の【食生活】や暮らしの様子がわかる。人骨が【埋葬】されている例もあり、モースが調査した【大森貝塚】が知られる。"},
  {"id": "jhx4", "s": "jh", "lv": 2, "topic": "縄文時代の信仰", "q": "縄文時代の人々の信仰や風習を、遺物・埋葬法にふれながら説明せよ。", "a": "自然物に霊威を認める【アニミズム】が広まり、女性をかたどった【土偶】で豊かな実りや出産を祈った。死者の手足を折り曲げて葬る【屈葬】や、成人の通過儀礼とされる【抜歯】も行われた。"},
  {"id": "jhx5", "s": "jh", "lv": 2, "topic": "三内丸山遺跡", "q": "三内丸山遺跡から明らかになった縄文時代の社会の特徴を説明せよ。", "a": "青森県の【三内丸山遺跡】は長期間営まれた大規模な集落跡で、大型掘立柱建物の跡や【クリ】の栽培を示す痕跡がある。新潟県産の【ヒスイ】なども出土し、遠隔地との【交易】があったことがわかる。"},
  {"id": "jhx6", "s": "jh", "lv": 1, "topic": "稲作と社会の変化", "q": "弥生時代に水稲耕作が広まると、社会はどのように変化したか説明せよ。", "a": "米を【高床倉庫】に蓄えられるようになると、【貧富の差】や身分の差が生まれた。土地や水をめぐる争いも起こり、各地に指導者が率いる小さな【クニ】が生まれた。"},
  {"id": "jhx7", "s": "jh", "lv": 1, "topic": "弥生時代の戦い", "q": "弥生時代に戦いがあったことは、どのような遺跡からわかるか説明せよ。", "a": "周囲に濠をめぐらせた【環濠集落】や、山頂など高い場所に営まれた【高地性集落】がみられる。佐賀県の【吉野ヶ里遺跡】では、首のない人骨や矢じりの刺さった人骨も見つかっている。"},
  {"id": "jhx8", "s": "jh", "lv": 2, "topic": "弥生時代の金属器", "q": "弥生時代に伝わった鉄器と青銅器は、それぞれ主にどのように用いられたか。", "a": "【鉄器】は農具や工具、武器など実用の道具として用いられた。一方、銅鐸・銅剣・銅矛などの【青銅器】は主に【祭器】として用いられた。稲の穂首刈りには【石包丁】が使われた。"},
  {"id": "jhx9", "s": "jh", "lv": 2, "topic": "漢・後漢と倭", "q": "中国の歴史書は、紀元前後の倭の国々と中国との関係をどのように記しているか。", "a": "『漢書』地理志は、倭が百余国に分かれ【楽浪郡】に定期的に使いを送ったと記す。『後漢書』東夷伝は、57年に【奴国】王が後漢に使いを送り、光武帝から【印綬】を授けられたと記している。"},
  {"id": "jhx10", "s": "jh", "lv": 1, "topic": "邪馬台国", "q": "卑弥呼はどのように国を治め、中国とどのような関係を結んだか説明せよ。", "a": "卑弥呼は【呪術】的な権威によって約30の国々を従えた。239年に【魏】に使いを送り、「【親魏倭王】」の称号と金印、銅鏡などを授けられた。"},
  {"id": "jhx11", "s": "jh", "lv": 2, "topic": "前方後円墳", "q": "前方後円墳が各地に広がったことは、どのようなことを示しているか説明せよ。", "a": "3世紀中ごろから近畿を中心に【前方後円墳】が築かれ、同じ形式の古墳が各地に広がった。これは地方の【首長】たちが【ヤマト政権】と政治的な連合関係を結んでいたことを示している。"},
  {"id": "jhx12", "s": "jh", "lv": 3, "topic": "古墳の副葬品", "q": "古墳時代の前期と中期で副葬品はどう変化したか。その変化が示す被葬者の性格の違いとともに説明せよ。", "a": "前期は【銅鏡】や玉などの呪術的・宗教的な品が中心で、被葬者は【司祭者】的な性格をもっていた。中期には【鉄製武器】や【馬具】が増え、朝鮮半島との交流を背景に、被葬者の【武人】的な性格が強まった。"},
  {"id": "jhx13", "s": "jh", "lv": 2, "topic": "倭の五王", "q": "5世紀に倭の五王が中国の南朝に使いを送ったのはなぜか説明せよ。", "a": "倭の五王は中国【南朝】に朝貢して皇帝の権威を借り、【朝鮮半島】南部での軍事的・外交的な立場を有利にするとともに、国内での地位を高めようとした。478年には倭王【武】が宋に上表文を送った。"},
  {"id": "jhx14", "s": "jh", "lv": 3, "topic": "ワカタケル大王", "q": "稲荷山古墳出土鉄剣と江田船山古墳出土大刀の銘文から、5世紀後半のヤマト政権について何がわかるか。", "a": "埼玉県の【稲荷山古墳】出土の鉄剣と熊本県の【江田船山古墳】出土の大刀には、ともに「【ワカタケル】大王」の名が刻まれている。5世紀後半には大王の勢力が【関東】から九州中部にまで及んでいたことがわかる。"},
  {"id": "jhx15", "s": "jh", "lv": 1, "topic": "渡来人", "q": "4〜6世紀に朝鮮半島などから来た渡来人は、日本にどのような技術や文化を伝えたか。", "a": "渡来人は硬質で灰色の【須恵器】の製作や、機織り・金属加工などの技術を伝えた。また【漢字】を用いて記録や外交文書の作成にあたり、6世紀には【儒教】も伝えられた。ヤマト政権は彼らを【品部】に組織した。"},
  {"id": "jhx16", "s": "jh", "lv": 2, "topic": "氏姓制度", "q": "ヤマト政権が豪族を支配するしくみであった氏姓制度を説明せよ。", "a": "ヤマト政権は豪族を血縁などで結ばれた【氏】に組織し、家柄や地位に応じて臣・連などの【姓】を与えた。豪族は私有民の【部曲】や私有地の田荘を支配しつつ、政権の職務を分担した。"},
  {"id": "jhx17", "s": "jh", "lv": 3, "topic": "磐井の乱", "q": "6世紀前半の磐井の乱の経過と、その後のヤマト政権による地方支配の変化を説明せよ。", "a": "527年、【新羅】と結んだ筑紫国造【磐井】が、朝鮮半島に向かう政権の軍を妨げて反乱を起こしたが、鎮圧された。その後ヤマト政権は地方豪族を【国造】に任じ、各地に直轄地の【屯倉】を設けて地方支配を強めた。"},
  {"id": "jhx18", "s": "jh", "lv": 2, "topic": "仏教の伝来", "q": "6世紀に仏教が伝わると、その受け入れをめぐってどのような対立が起きたか。", "a": "6世紀半ば、【百済】の聖明王から仏教が公式に伝えられた。受け入れをめぐって崇仏派の【蘇我氏】と排仏派の【物部氏】が対立し、587年に蘇我馬子が物部守屋を滅ぼした。"},
  {"id": "jhx19", "s": "jh", "lv": 1, "topic": "推古朝の政治", "q": "推古天皇の時代に、厩戸王（聖徳太子）らはどのような国づくりをめざしたか説明せよ。", "a": "厩戸王は【蘇我馬子】と協力し、家柄にとらわれず才能のある人物を登用するため【冠位十二階】を定めた。また【十七条憲法】で役人の心構えを示し、天皇を中心とする国家をめざした。"},
  {"id": "jhx20", "s": "jh", "lv": 2, "topic": "遣隋使", "q": "遣隋使派遣の目的と、607年の国書にみられる外交姿勢を説明せよ。", "a": "中国の進んだ制度や文化を学ぶため、607年に【小野妹子】を派遣した。国書では倭の王を「天子」と記して【対等】な立場を求める姿勢を示し、隋の皇帝【煬帝】の不興を買ったが、翌年には【留学生】や学問僧も派遣された。"},
  {"id": "jhx21", "s": "jh", "lv": 2, "topic": "飛鳥文化", "q": "7世紀前半に栄えた飛鳥文化の特徴を、代表的な寺院や仏像にふれて説明せよ。", "a": "日本で最初の【仏教】文化で、【法隆寺】などの寺院が建てられた。中国の【南北朝】の文化の影響を受け、鞍作鳥の釈迦三尊像など、【渡来人】の技術に支えられた国際色豊かな文化であった。"},
  {"id": "jhx22", "s": "jh", "lv": 1, "topic": "大化の改新", "q": "7世紀半ばの大化の改新は、どのような国家をめざして行われたか説明せよ。", "a": "645年、【中大兄皇子】と中臣鎌足は蘇我氏を倒した（乙巳の変）。翌年【改新の詔】を出し、豪族の私有地・私有民を廃止する【公地公民】の方針を示して、天皇中心の中央集権国家をめざした。"},
  {"id": "jhx23", "s": "jh", "lv": 2, "topic": "白村江の戦い", "q": "白村江の戦いの結果、日本はどのような防衛策をとったか説明せよ。", "a": "663年、【百済】復興を助けるため出兵したが、唐・新羅の連合軍に大敗した。その後、唐・新羅の侵攻に備えて北九州に【水城】や朝鮮式山城を築き、【防人】を置いて防衛を固め、都を近江大津宮に移した。"},
  {"id": "jhx24", "s": "jh", "lv": 2, "topic": "壬申の乱", "q": "672年の壬申の乱の結果、天皇の権力はどのように変化したか説明せよ。", "a": "672年、【大海人皇子】が大友皇子を破って即位し【天武天皇】となった。近江朝廷側の有力豪族が没落したため天皇の権力が強まり、【八色の姓】による豪族の再編や、律令・国史の編纂が進められた。"},
  {"id": "jhx25", "s": "jh", "lv": 2, "topic": "持統朝と藤原京", "q": "持統天皇の時代に進められた律令国家づくりを、法令・戸籍・都城にふれて説明せよ。", "a": "持統天皇は【飛鳥浄御原令】を施行し、690年にはそれにもとづいて【庚寅年籍】を作成した。694年には条坊制をもつ初めての本格的な都城である【藤原京】に遷都した。"},
  {"id": "jhx26", "s": "jh", "lv": 2, "topic": "白鳳文化", "q": "白鳳文化の特徴を、代表的な建築・美術・文学にふれて説明せよ。", "a": "天武・持統天皇の時代を中心とする文化で、【初唐】の文化の影響を受けた清新な文化である。【薬師寺】東塔などが建てられ、【高松塚古墳】の壁画が描かれた。【柿本人麻呂】らが和歌を詠んだ。"},
  {"id": "jhx27", "s": "jh", "lv": 1, "topic": "大宝律令", "q": "大宝律令によって整えられた中央と地方の統治のしくみを説明せよ。", "a": "701年に【大宝律令】が完成し、中央には神祇官と【太政官】の二官と八省が置かれた。地方は国・郡・里に分けられ、中央から派遣された【国司】と、地方豪族から任じられた【郡司】が治めた。"},
  {"id": "jhx28", "s": "jh", "lv": 2, "topic": "律令制下の農民負担", "q": "律令制のもとで、農民はどのような税や負担を負っていたか説明せよ。", "a": "口分田からの収穫の一部を稲で納める【租】、地方の特産物を納める【調】、労役の代わりに布などを納める【庸】を負担した。ほかに国司のもとで労働する【雑徭】や【兵役】もあり、農民の負担は重かった。"},
  {"id": "jhx29", "s": "jh", "lv": 2, "topic": "三世一身法", "q": "奈良時代に三世一身法が出された理由と、この法の限界を説明せよ。", "a": "人口の増加などで【口分田】が不足したため、723年に【三世一身法】を出し、開墾した土地の一定期間の私有を認めた。しかし期限が近づくと耕地が荒れたため、743年の【墾田永年私財法】につながった。"},
  {"id": "jhx30", "s": "jh", "lv": 3, "topic": "律令制の動揺", "q": "8世紀から9世紀にかけて、班田収授が行われにくくなったのはなぜか説明せよ。", "a": "重い負担から逃れるため農民の【浮浪】・逃亡が増え、男子を女子と偽るなど戸籍をごまかす【偽籍】も広がった。口分田の不足も重なって【戸籍】・計帳による把握がくずれ、班田の間隔が延びて、10世紀初めを最後にほとんど行われなくなった。"},
  {"id": "jhx31", "s": "jh", "lv": 1, "topic": "平城京", "q": "平城京はどのような都であったか、手本とした都や特徴にふれて説明せよ。", "a": "710年、唐の都【長安】にならって【平城京】に遷都した。道路で碁盤の目状に区画する【条坊制】がとられ、東西の市では【和同開珎】などの貨幣も使われた。"},
  {"id": "jhx32", "s": "jh", "lv": 1, "topic": "遣唐使", "q": "遣唐使はどのような目的で派遣され、どのような役割を果たしたか。", "a": "唐の進んだ【制度】や文化を取り入れるために派遣され、【留学生】や学問僧が同行した。【吉備真備】や玄昉は帰国後に政治で活躍した。894年、【菅原道真】の建議で派遣は停止された。"},
  {"id": "jhx33", "s": "jh", "lv": 1, "topic": "鎮護国家", "q": "聖武天皇が国分寺の建立や大仏の造立を命じたのはなぜか説明せよ。", "a": "疫病や藤原広嗣の乱などで社会不安が続いたため、【仏教】の力で国家を守ろうとする【鎮護国家】の思想にもとづいて、741年に【国分寺建立の詔】、743年に【大仏造立の詔】を出した。"},
  {"id": "jhx34", "s": "jh", "lv": 3, "topic": "奈良時代の政争", "q": "奈良時代には、政治の実権がどのように移り変わったか。藤原氏と他の勢力の動きを中心に説明せよ。", "a": "藤原不比等の死後、【長屋王】が政権を握ったが、不比等の4子に倒された。4子が疫病で死ぬと【橘諸兄】が政権を握り、その後【藤原仲麻呂】、さらに僧の【道鏡】が権力をふるうなど、政権の担い手は激しく交代した。"},
  {"id": "jhx35", "s": "jh", "lv": 2, "topic": "天平文化", "q": "天平文化の特徴を、国際性や代表的な文化財・書物にふれて説明せよ。", "a": "聖武天皇の時代を中心とする、仏教色の強い貴族文化である。盛唐の文化の影響を受けて【国際色】豊かで、【正倉院】の宝物には【シルクロード】を通じて伝わった品もある。『古事記』『日本書紀』や『【万葉集】』も編まれた。"},
  {"id": "jhx36", "s": "jh", "lv": 2, "topic": "古事記と日本書紀", "q": "奈良時代初めに成立した『古事記』と『日本書紀』の成立事情と、書き方の違いを説明せよ。", "a": "『【古事記】』は稗田阿礼が誦習したものを太安万侶が筆録して712年に成立した。『【日本書紀】』は舎人親王らが720年に完成させ、【漢文】の【編年体】で書かれ、【六国史】の最初となった。"},
  {"id": "jhx37", "s": "jh", "lv": 2, "topic": "行基", "q": "行基は朝廷からどのように扱われたか。その活動の変化とともに説明せよ。", "a": "行基は民衆に布教しながら用水や橋をつくる【社会事業】を行ったため、はじめは【僧尼令】に反するとして朝廷に弾圧された。のちに【大仏造立】に協力し、【大僧正】に任じられた。"},
  {"id": "jhx38", "s": "jh", "lv": 2, "topic": "東北経営", "q": "律令国家は東北地方の蝦夷に対してどのような政策をとったか説明せよ。", "a": "律令国家は陸奥国に【多賀城】を築いて支配を広げた。桓武天皇は【坂上田村麻呂】を征夷大将軍に任じ、蝦夷の族長【阿弖流為】を降伏させ、【胆沢城】を築いて支配の拠点を北へ進めた。"},
  {"id": "jhx39", "s": "jh", "lv": 2, "topic": "桓武天皇の政治", "q": "桓武天皇が平安京に遷都した理由と、行った政治改革を説明せよ。", "a": "寺院など【仏教】勢力の政治への介入を断ち、政治を立て直すため、784年に長岡京、794年に【平安京】へ遷都した。国司の交代を監督する【勘解由使】を置き、東北などを除いて軍団を廃止し【健児】を置いた。"},
  {"id": "jhx40", "s": "jh", "lv": 2, "topic": "令外官", "q": "平安時代初期に令外官が置かれたのはなぜか。代表的な官職をあげて説明せよ。", "a": "律令の規定だけでは現実の政治に対応できなくなったため、律令にない【令外官】が置かれた。嵯峨天皇は機密を扱う【蔵人頭】や、京の治安を担う【検非違使】を置いた。また法令を整理した【格式】も編纂された。"},
  {"id": "jhx41", "s": "jh", "lv": 1, "topic": "天台宗と真言宗", "q": "平安時代初期に最澄と空海が広めた新しい仏教の特徴を説明せよ。", "a": "最澄は【比叡山】延暦寺を開いて【天台宗】を、空海は高野山金剛峯寺を開いて【真言宗】を広めた。両宗は加持祈祷で災いを除き現世の利益を願う【密教】を取り入れ、貴族の信仰を集めた。"},
  {"id": "jhx42", "s": "jh", "lv": 2, "topic": "弘仁・貞観文化", "q": "平安時代初期の弘仁・貞観文化の特徴を、文学・仏教美術・書道にふれて説明せよ。", "a": "宮廷では【漢詩文】が重んじられ、勅撰漢詩集が編まれた。仏教では【密教】が盛んになり、【曼荼羅】や一木造の神秘的な仏像が作られた。書道では嵯峨天皇・空海・橘逸勢の【三筆】が活躍した。"},
  {"id": "jhx43", "s": "jh", "lv": 2, "topic": "藤原北家の他氏排斥", "q": "藤原北家は、9〜10世紀にどのようにして他の貴族を政界から退けたか説明せよ。", "a": "藤原良房は【承和の変】で伴健岑・橘逸勢を退け、【応天門の変】で伴善男を失脚させた。藤原時平は【菅原道真】を大宰府に左遷させ、969年の【安和の変】で源高明が退けられて北家の地位が確立した。"},
  {"id": "jhx44", "s": "jh", "lv": 3, "topic": "摂関期の政治運営", "q": "摂関政治の時代、政治はどのように運営され、なぜ中・下級貴族は摂関家に近づいたのか説明せよ。", "a": "摂関政治の時代も政治は【太政官】で行われ、重要事項は公卿の会議である【陣定】で審議された。摂政・関白は官吏の【人事権】を握っていたため、中・下級貴族は摂関家に近づき、収入の多い【受領】の地位を求めた。"},
  {"id": "jhx45", "s": "jh", "lv": 1, "topic": "国風文化", "q": "遣唐使の停止前後から栄えた国風文化の特徴を、文字・文学・住宅にふれて説明せよ。", "a": "唐の文化を消化し、日本の風土や生活に合った文化が生まれた。【かな文字】が発達して紫式部の『【源氏物語】』や清少納言の『枕草子』などの女流文学が生まれ、貴族の住宅には【寝殿造】が用いられた。"},
  {"id": "jhx46", "s": "jh", "lv": 2, "topic": "浄土教", "q": "平安時代中期に浄土教が広まった理由と、その広がりを示す例を説明せよ。", "a": "社会不安と、仏の教えが衰えるという【末法思想】の広がりから、【阿弥陀仏】を信じて極楽浄土への往生を願う浄土教が広まった。【空也】が都で念仏を説き、源信は『往生要集』を著し、藤原頼通は【平等院鳳凰堂】を建てた。"},
  {"id": "jhx47", "s": "jh", "lv": 3, "topic": "受領と地方支配の変化", "q": "10世紀に国司による地方支配はどのように変化したか。課税のしくみの変化とあわせて説明せよ。", "a": "政府は国司に一定額の税の納入を請け負わせ、国内の支配を任せた。任国に赴く最上席の国司は【受領】とよばれ、課税対象を人から土地へ改めた。田地を【名】に編成し、有力農民の【田堵】に耕作と納税を請け負わせた。"},
  {"id": "jhx48", "s": "jh", "lv": 2, "topic": "寄進地系荘園", "q": "11世紀ごろに広がった寄進地系荘園は、どのようにして生まれたか説明せよ。", "a": "開発領主は国司の干渉や税の負担を逃れるため、所領を中央の有力な貴族や寺社に【寄進】した。寄進を受けた者は【領家】、さらに上級の者は【本家】となり、荘園は【不輸の権】や不入の権を得て独立性を強めた。"},
  {"id": "jhx49", "s": "jh", "lv": 1, "topic": "承平・天慶の乱", "q": "10世紀前半の承平・天慶の乱は、武士の成長にとってどのような意味をもったか。", "a": "関東で【平将門】が、瀬戸内海で【藤原純友】が反乱を起こした。朝廷は地方の【武士】の力を借りてこれらを鎮圧したため、武士の実力が明らかになり、その地位が高まった。"},
  {"id": "jhx50", "s": "jh", "lv": 2, "topic": "源氏の東国進出", "q": "11世紀の東北地方の争乱は、源氏の勢力拡大とどのように結びついたか説明せよ。", "a": "東北の争乱である【前九年合戦】と【後三年合戦】を源頼義・【源義家】らが鎮めたことで、源氏は【東国】の武士との主従関係を強めた。その後、奥州では【奥州藤原氏】が平泉を拠点に栄えた。"},
  {"id": "jhx51", "s": "jh", "lv": 2, "topic": "延久の荘園整理令", "q": "後三条天皇が出した延久の荘園整理令の内容と、その意義を説明せよ。", "a": "1069年、【後三条天皇】は【記録荘園券契所】を置き、証拠書類の不備な荘園や新しい荘園を停止させた。【摂関家】の荘園も例外とせず、摂関家と外戚関係のない天皇が政治の主導権を取り戻した。"},
  {"id": "jhx52", "s": "jh", "lv": 3, "topic": "院政の権力基盤", "q": "院政期の上皇の権力は、どのようなものに支えられていたか。直面した問題とあわせて説明せよ。", "a": "上皇は【院宣】や院庁下文で政治を動かし、【北面の武士】を置いて武力を備えた。上皇のもとには多くの【荘園】が寄進され、知行国の制度も経済基盤となった。一方、大寺院が僧兵を使って起こす【強訴】に悩まされた。"},
  {"id": "jhx53", "s": "jh", "lv": 2, "topic": "院政期の文化", "q": "院政期の文化の特徴を、地方への広がりや庶民の文化にふれて説明せよ。", "a": "浄土教が地方にも広まり、奥州藤原氏の【中尊寺金色堂】などが建てられた。後白河上皇は庶民の流行歌である【今様】を『梁塵秘抄』にまとめ、『鳥獣戯画』などの【絵巻物】も作られた。"},
  {"id": "jhx54", "s": "jh", "lv": 1, "topic": "平氏政権", "q": "平清盛は、どのようにして政治の実権を握り、どのような政策を行ったか説明せよ。", "a": "清盛は【保元の乱】・平治の乱に勝利し、1167年に武士として初めて【太政大臣】となった。娘を天皇の后として外戚となり、大輪田泊を修築して【日宋貿易】を進め、大きな利益をあげた。"},
  {"id": "jhx55", "s": "jh", "lv": 3, "topic": "平氏政権の性格", "q": "平氏政権がもっていた貴族的な性格と武家政権としての性格を、滅亡の理由とあわせて説明せよ。", "a": "平氏は一門で高位高官を独占し、【外戚】として権力を握るなど摂関家に似た【貴族的】な性格をもった。一方、各地の武士を家人とし【地頭】に任じた点では武家政権の性格もあった。院や旧勢力、地方武士の反発を招き、【治承・寿永の乱】で滅んだ。"},
  {"id": "jhx56", "s": "jh", "lv": 1, "topic": "守護と地頭", "q": "源頼朝が全国に置いた守護と地頭は、それぞれどのような役割を担ったか説明せよ。", "a": "1185年、頼朝は朝廷に認めさせ、国ごとに【守護】を置いて軍事・警察を担当させ、荘園や公領ごとに【地頭】を置いて年貢の徴収や土地の管理にあたらせた。これにより頼朝の支配が【全国】に及んだ。"},
  {"id": "jhx57", "s": "jh", "lv": 2, "topic": "執権政治", "q": "北条氏による執権政治は、どのように確立し、どのような特徴をもったか。", "a": "頼朝の死後、北条時政が【執権】となり、2代義時は【承久の乱】に勝利して地位を固めた。3代泰時は有力御家人による合議制をとって【評定衆】を置き、【御成敗式目】を定めた。"},
  {"id": "jhx58", "s": "jh", "lv": 1, "topic": "承久の乱", "q": "承久の乱の結果、鎌倉幕府の支配はどのように変化したか説明せよ。", "a": "1221年、【後鳥羽上皇】が倒幕の兵をあげたが敗れ、隠岐に流された。幕府は京都に【六波羅探題】を置いて朝廷を監視し、上皇方の所領に【新補地頭】を置いて、支配を西国にまで広げた。"},
  {"id": "jhx59", "s": "jh", "lv": 2, "topic": "御成敗式目", "q": "北条泰時が御成敗式目を定めた目的と、その基準となったものを説明せよ。", "a": "1232年、泰時は頼朝以来の【先例】と武家社会の【道理】にもとづき、【御家人】の間や御家人と荘園領主の間の争いを公平に裁く基準として定めた。最初の【武家法】で、朝廷の法を否定するものではなかった。"},
  {"id": "jhx60", "s": "jh", "lv": 3, "topic": "地頭の荘園侵略", "q": "鎌倉時代に地頭と荘園領主の対立はどのように解決がはかられ、その結果どうなったか説明せよ。", "a": "地頭が年貢を横領するなど荘園領主と対立すると、領主は地頭に一定額の年貢納入を請け負わせる【地頭請】や、土地を領主と地頭で分け合う【下地中分】で解決をはかった。その結果、地頭の【現地支配】が強まり、【荘園】制は変質していった。"},
  {"id": "jhx61", "s": "jh", "lv": 1, "topic": "鎌倉時代の産業", "q": "鎌倉時代には、農業や商業にどのような発達がみられたか説明せよ。", "a": "畿内や西日本で麦を裏作とする【二毛作】が広まり、刈敷や草木灰が肥料に使われた。寺社の門前や交通の要地では【定期市】が開かれ、【宋銭】が流通し、遠隔地の取引には【為替】が用いられた。"},
  {"id": "jhx62", "s": "jh", "lv": 2, "topic": "惣領制", "q": "鎌倉時代の武士の一族結合である惣領制と、その相続方法の変化を説明せよ。", "a": "武士は一族の長である【惣領】が庶子を率いて戦い、幕府への奉公を果たした。所領は【分割相続】されたため細分化が進み、御家人は困窮した。そのため鎌倉後期には惣領が所領を受け継ぐ【単独相続】へと移っていった。"},
  {"id": "jhx63", "s": "jh", "lv": 3, "topic": "得宗専制", "q": "蒙古襲来後の鎌倉幕府でみられた得宗専制とはどのような政治か。成立の経緯とあわせて説明せよ。", "a": "蒙古襲来後、北条氏の嫡流である【得宗】の権力が強まり、得宗の家臣である【御内人】が幕政に大きな影響力をもった。1285年の【霜月騒動】で有力御家人の安達泰盛が滅ぼされると得宗専制が確立し、【御家人】の不満が高まった。"},
  {"id": "jhx64", "s": "jh", "lv": 3, "topic": "鎌倉幕府の滅亡", "q": "鎌倉幕府が滅亡に至った背景を、御家人の状況や社会の変化にふれて説明せよ。", "a": "分割相続や【貨幣経済】の浸透で御家人が困窮する一方、【得宗専制】への反発が強まった。畿内では荘園領主や幕府に反抗する【悪党】が現れた。【後醍醐天皇】の倒幕計画に足利高氏や新田義貞らが応じ、1333年に幕府は滅亡した。"},
  {"id": "jhx65", "s": "jh", "lv": 2, "topic": "鎌倉文化の美術", "q": "鎌倉時代の彫刻・建築には、どのような特徴がみられるか説明せよ。", "a": "武士の気風を反映した力強く写実的な作品が生まれ、東大寺南大門の【金剛力士像】は【運慶】・快慶らが制作した。東大寺の再建では宋の様式を取り入れた【大仏様】が用いられ、禅宗寺院には【禅宗様】が用いられた。"},
  {"id": "jhx66", "s": "jh", "lv": 2, "topic": "鎌倉時代の文学", "q": "鎌倉時代に生まれた文学の特徴を、軍記物語や随筆にふれて説明せよ。", "a": "平氏の興亡を描いた軍記物語『【平家物語】』は、【琵琶法師】によって語られ、文字を読めない人々にも広まった。また【鴨長明】の『方丈記』や兼好法師の『【徒然草】』など、無常観を背景とする随筆も生まれた。"},
  {"id": "jhx67", "s": "jh", "lv": 1, "topic": "建武の新政", "q": "後醍醐天皇の建武の新政が、短期間で失敗したのはなぜか説明せよ。", "a": "【後醍醐天皇】は天皇中心の政治をめざしたが、公家を重んじる政策や、【恩賞】の不公平に【武士】が不満を強めた。武家政治の再興をめざす【足利尊氏】が離反し、新政は約2年半で崩れた。"},
  {"id": "jhx68", "s": "jh", "lv": 3, "topic": "南北朝の動乱", "q": "南北朝の動乱が約60年もの長期に及んだ理由を、武士社会の変化にふれて説明せよ。", "a": "【惣領制】がくずれて武士団の内部で分裂が起こり、一方が北朝につけば他方が南朝につくなど対立が複雑化した。幕府内部でも足利尊氏と直義が争う【観応の擾乱】が起きた。地縁的な結合を強めた武士は【守護】に従い、守護が権限を拡大した。"},
  {"id": "jhx69", "s": "jh", "lv": 2, "topic": "守護大名", "q": "南北朝の動乱の中で、守護はどのようにして守護大名へと成長したか説明せよ。", "a": "幕府は守護に、荘園・公領の年貢の半分を兵粮米として徴収できる【半済令】や、【刈田狼藉】の取り締まりなどの権限を与えた。守護は国内の武士を家臣化し、荘園の年貢納入を請け負う【守護請】も行って、【守護大名】へと成長した。"},
  {"id": "jhx70", "s": "jh", "lv": 2, "topic": "室町幕府の機構", "q": "室町幕府の中央と地方の主な機構と、それぞれの長官に任じられた人々を説明せよ。", "a": "将軍を補佐する【管領】には細川・斯波・畠山の三氏が交代で任じられ、侍所の長官には四職が任じられた。地方には関東を治める【鎌倉府】が置かれ、長官の【鎌倉公方】は足利基氏の子孫が世襲した。"},
  {"id": "jhx71", "s": "jh", "lv": 2, "topic": "足利義満の権力確立", "q": "足利義満はどのようにして室町幕府の権力を確立したか説明せよ。", "a": "義満は1392年に【南北朝の合一】を実現し、【明徳の乱】で山名氏清を、【応永の乱】で大内義弘を討って有力守護の勢力を抑えた。また【太政大臣】となって公家社会でも頂点に立った。"},
  {"id": "jhx72", "s": "jh", "lv": 3, "topic": "室町幕府の財政", "q": "室町幕府の財政はどのような収入によって支えられていたか、その特徴とともに説明せよ。", "a": "直轄領である【御料所】からの収入が少なかったため、高利貸しの【土倉】・酒屋に課す土倉役・酒屋役、交通の要地に設けた【関銭】・津料、日明貿易の利益などに頼った。守護を通じて【段銭】・棟別銭も徴収するなど、商業や流通への課税に依存した。"},
  {"id": "jhx73", "s": "jh", "lv": 3, "topic": "足利義教と嘉吉の乱", "q": "6代将軍足利義教の政治と嘉吉の乱は、室町幕府にどのような影響を与えたか。", "a": "【足利義教】は将軍権力の強化をめざし、【永享の乱】で鎌倉公方足利持氏を滅ぼすなど専制的な政治を行った。しかし守護の反発を招き、1441年に播磨守護【赤松満祐】に殺された（【嘉吉の乱】）。これ以後、将軍の権威は大きく衰えた。"},
  {"id": "jhx74", "s": "jh", "lv": 1, "topic": "惣村", "q": "室町時代の農村で成立した惣村とは、どのような村であったか説明せよ。", "a": "農民が自治的な村である【惣】をつくり、【寄合】で村のおきてである惣掟を定め、入会地や用水を共同で管理した。団結した農民は年貢の減免などを求めて【一揆】を結ぶこともあった。"},
  {"id": "jhx75", "s": "jh", "lv": 2, "topic": "正長の土一揆", "q": "1428年に起きた正長の土一揆の経過と、その歴史的な意味を説明せよ。", "a": "近江の【馬借】の蜂起をきっかけに、京都周辺の農民が【徳政】を要求して酒屋・【土倉】などの高利貸しを襲った。幕府は徳政令を出さなかったが、各地で実力による【私徳政】が行われ、民衆の力が示された。"},
  {"id": "jhx76", "s": "jh", "lv": 2, "topic": "山城の国一揆と加賀の一向一揆", "q": "15世紀後半の山城の国一揆と加賀の一向一揆は、それぞれどのような一揆か説明せよ。", "a": "1485年、南山城の国人と農民は争う【畠山氏】の軍を国外に退去させ、8年間自治を行った。1488年には浄土真宗の門徒らによる加賀の【一向一揆】が守護【富樫政親】を倒し、約100年間にわたって自治を行った。"},
  {"id": "jhx77", "s": "jh", "lv": 2, "topic": "室町時代の産業", "q": "室町時代の農業はどのように発達したか。商品作物や市の発達とあわせて説明せよ。", "a": "畿内では【三毛作】も行われ、人糞尿の【下肥】が肥料として使われた。灯油の原料となる【荏胡麻】や茶などの商品作物も栽培された。地方の市は月に6回開かれる【六斎市】が一般的になった。"},
  {"id": "jhx78", "s": "jh", "lv": 2, "topic": "室町時代の流通", "q": "室町時代の商工業者や流通、貨幣の使用にはどのような特徴がみられたか。", "a": "陸上輸送は【馬借】・車借、港での保管・輸送は問丸が担った。商工業者は【座】を結んで公家や寺社の保護を受け、独占的な営業権を得た。明銭の【永楽通宝】なども使われたが、粗悪な銭を嫌う【撰銭】が行われ、取引の妨げとなった。"},
  {"id": "jhx79", "s": "jh", "lv": 2, "topic": "北山文化", "q": "足利義満の時代の北山文化の特徴を、建築や芸能にふれて説明せよ。", "a": "伝統的な【公家】文化と新しい武家文化が融合し、【禅宗】の影響も受けた文化である。義満が京都の北山に建てた【金閣】がその象徴で、【観阿弥】・世阿弥父子が能を大成した。"},
  {"id": "jhx80", "s": "jh", "lv": 1, "topic": "東山文化", "q": "足利義政の時代の東山文化の特徴を、建築や絵画にふれて説明せよ。", "a": "禅の精神にもとづく簡素で深みのある美が重んじられた。慈照寺の東求堂同仁斎には、現代の和風住宅のもととなる【書院造】が用いられた。【雪舟】は【水墨画】を大成し、石や砂で自然を表す【枯山水】の庭園もつくられた。"},
  {"id": "jhx81", "s": "jh", "lv": 3, "topic": "文化の地方・庶民への広がり", "q": "室町時代後期に文化が地方や庶民に広がったのはなぜか。具体例をあげて説明せよ。", "a": "応仁の乱で京都が荒廃すると、多くの【公家】や禅僧が地方の大名を頼って下り、文化が【地方】に広まった。宗祇らが各地で【連歌】を広め、御伽草子や狂言など庶民も楽しめる文芸が生まれ、都市の町衆や村の農民も文化の担い手となった。"},
  {"id": "jhx82", "s": "jh", "lv": 2, "topic": "日朝貿易", "q": "室町時代の日朝貿易はどのように行われ、どのように衰えたか説明せよ。", "a": "朝鮮は【倭寇】の禁止を求めて日本と通交し、【対馬】の【宗氏】を通じて貿易を統制した。日本は朝鮮から【木綿】などを輸入した。1510年に朝鮮の港に住む日本人が暴動を起こした【三浦の乱】以後、貿易は衰えた。"},
  {"id": "jhx83", "s": "jh", "lv": 1, "topic": "鎌倉幕府の機構", "q": "源頼朝が鎌倉に設けた幕府の主な機関について、それぞれの役割を説明せよ。", "a": "御家人を統率し軍事・警察を担う【侍所】、一般政務や財政を担う【公文所】（のちの【政所】）、裁判を担う【問注所】が置かれた。頼朝は1192年に【征夷大将軍】に任じられた。"},
  {"id": "jhx84", "s": "jh", "lv": 1, "topic": "鎌倉武士の生活", "q": "鎌倉時代の武士は、ふだんどのような生活を送っていたか説明せよ。", "a": "武士は所領の中に堀や塀で囲んだ【館】を構え、周辺の田畑を下人などに耕作させた。日ごろから【流鏑馬】・笠懸・犬追物などで【武芸】をみがき、「弓馬の道」とよばれる武士らしい生き方を重んじた。"},
  {"id": "jhx85", "s": "jh", "lv": 2, "topic": "北条時頼の政治", "q": "5代執権北条時頼は、どのようにして執権政治を強化したか説明せよ。", "a": "時頼は1247年の【宝治合戦】で有力御家人の【三浦氏】を滅ぼし、北条氏の地位を固めた。また評定衆の下に【引付衆】を置いて御家人の所領に関する裁判の迅速化・公正化をはかり、【御家人】の保護に努めた。"},
  {"id": "jhx86", "s": "jh", "lv": 2, "topic": "両統迭立", "q": "鎌倉時代後期の皇位継承をめぐる両統迭立とは何か。後醍醐天皇の即位との関係にもふれて説明せよ。", "a": "皇室は【持明院統】と【大覚寺統】に分かれて皇位や荘園をめぐって争い、幕府の調停で両統が交代で皇位につく【両統迭立】の方式がとられた。大覚寺統から即位した【後醍醐天皇】は、これに介入する幕府を倒そうとした。"},
  {"id": "jhx87", "s": "jh", "lv": 2, "topic": "鎌倉時代の学問と和歌", "q": "鎌倉時代の公家・武家の学問や和歌には、どのような動きがみられたか説明せよ。", "a": "公家の間では伝統文化への関心が高まり、後鳥羽上皇の命で『【新古今和歌集】』が編まれた。武家では北条実時が【金沢文庫】を設けて和漢の書物を集めた。神道では度会家行が【伊勢神道】を唱えた。"},
  {"id": "jhx88", "s": "jh", "lv": 2, "topic": "琉球王国", "q": "15世紀に成立した琉球王国は、どのようにして繁栄したか説明せよ。", "a": "1429年、中山王の【尚巴志】が三山を統一して琉球王国を建てた。首里を都とし、明への朝貢を軸に日本や東南アジアの産物を取り次ぐ【中継貿易】で栄え、【那覇】は国際的な港として発展した。"},
  {"id": "jhx89", "s": "jh", "lv": 2, "topic": "アイヌと和人", "q": "室町時代の蝦夷ヶ島（北海道）における和人とアイヌの関係を説明せよ。", "a": "和人は渡島半島南部に【館】を築いて進出し、アイヌと交易した。和人の圧迫に対して1457年に【コシャマイン】が蜂起したが、【蠣崎氏】に鎮圧された。蠣崎氏はのちに【松前氏】と改め、蝦夷地の支配者となった。"},
  {"id": "jhx90", "s": "jh", "lv": 1, "topic": "戦国大名の領国支配", "q": "戦国大名は、どのようにして自らの領国や家臣を支配したか説明せよ。", "a": "戦国大名は独自の法である【分国法】を定めて家臣や領民を統制した。【指出検地】で土地や収入を把握し、家臣の収入を銭に換算した【貫高】を基準に軍役を課した。また【城下町】を建設して家臣や商工業者を集めた。"},
  {"id": "jhx91", "s": "jh", "lv": 1, "topic": "鉄砲とキリスト教の伝来", "q": "16世紀半ばに伝わった鉄砲とキリスト教は、どのように日本に広まったか。", "a": "1543年、【種子島】に漂着したポルトガル人が鉄砲を伝え、堺などで生産された。1549年には【フランシスコ・ザビエル】がキリスト教を伝えた。宣教師は【南蛮貿易】と結びついて布教し、九州などに【キリシタン大名】も現れた。"},
  {"id": "jhx92", "s": "jh", "lv": 3, "topic": "鉄砲の影響", "q": "鉄砲の普及は、戦国時代の戦い方や城郭、全国統一にどのような影響を与えたか。", "a": "鉄砲は【足軽】の鉄砲隊による集団戦法を広め、騎馬武者中心の戦い方を変えた。1575年の【長篠の戦い】はその典型である。防御のため高い石垣と【天守】をもつ城郭が築かれ、大量の鉄砲を調達できる大名が優位に立ち、【全国統一】が早まった。"},
  {"id": "jhx93", "s": "jh", "lv": 2, "topic": "自治都市", "q": "戦国時代の堺・博多・京都では、どのような自治が行われていたか説明せよ。", "a": "日明貿易や南蛮貿易で栄えた【堺】は【会合衆】、博多は年行司の合議で自治を行った。京都では富裕な商工業者である【町衆】が町を単位に自治を行い、応仁の乱で中断した【祇園祭】を復興した。"},
  {"id": "jhx94", "s": "jh", "lv": 1, "topic": "下剋上の風潮", "q": "戦国時代に広まった下剋上の風潮とは何か。具体例をあげて説明せよ。", "a": "身分の下の者が実力で上の者を倒して地位を奪う風潮を【下剋上】という。守護代や国人などが守護大名を倒して【戦国大名】となる例が多く、【北条早雲】は伊豆・相模を奪い、斎藤道三も美濃の守護を追放した。"},
  {"id": "jhx95", "s": "jh", "lv": 1, "topic": "織田信長の統一事業", "q": "織田信長は、どのような戦いや政策によって全国統一を進めたか説明せよ。", "a": "信長は1560年の【桶狭間の戦い】で今川義元を破り、1573年に将軍足利義昭を追放して【室町幕府】を滅ぼした。【比叡山延暦寺】を焼き打ちし、【石山本願寺】を屈服させるなど、仏教勢力も武力で押さえた。"},
  {"id": "jhx96", "s": "jh", "lv": 1, "topic": "楽市・楽座", "q": "織田信長が楽市・楽座や関所の撤廃を行ったのはなぜか説明せよ。", "a": "信長は安土城下などで【楽市・楽座】令を出し、【座】の特権を否定して自由な営業を認め、商工業者を城下に集めた。また【関所】を撤廃して物資の流通を盛んにし、経済力を強めて統一事業を進めようとした。"},
  {"id": "jhx97", "s": "jh", "lv": 2, "topic": "豊臣秀吉の全国統一", "q": "豊臣秀吉は、どのような権威や手段を用いて全国統一を実現したか説明せよ。", "a": "秀吉は【関白】・太政大臣となり、天皇の権威を利用して大名に私的な争いを禁じる【惣無事令】を出した。これに従わない九州の島津氏を降伏させ、1590年には【小田原】の北条氏を滅ぼして全国統一を果たした。"},
  {"id": "jhx98", "s": "jh", "lv": 2, "topic": "バテレン追放令", "q": "豊臣秀吉がバテレン追放令を出した理由と、それが不徹底に終わった理由を説明せよ。", "a": "1587年、秀吉は【大村純忠】が長崎をイエズス会に寄進していたことなどを知り、【バテレン追放令】を出して宣教師の国外退去を命じた。しかし【南蛮貿易】は奨励したため、宣教師の来日を防げず、禁教は不徹底に終わった。"},
  {"id": "jhx99", "s": "jh", "lv": 2, "topic": "朝鮮侵略", "q": "豊臣秀吉による朝鮮侵略の経過と、それが豊臣政権に与えた影響を説明せよ。", "a": "秀吉は明の征服をめざして【文禄の役】・【慶長の役】で朝鮮に出兵したが、朝鮮の義兵や【李舜臣】の率いる水軍、明の援軍に苦しみ、秀吉の死で撤兵した。多大な負担は大名を疲弊させ、【豊臣政権】を弱体化させた。"},
  {"id": "jhx100", "s": "jh", "lv": 2, "topic": "桃山文化", "q": "桃山文化の特徴を、担い手と代表的な建築・絵画・芸能にふれて説明せよ。", "a": "新興の大名や豪商の気風を反映した、豪華で壮大な文化である。【天守】をもつ城郭が築かれ、内部の襖や屏風には【狩野永徳】らが【障壁画】を描いた。【千利休】は茶の湯を侘び茶として大成した。"},
  {"id": "jhx101", "s": "jh", "lv": 3, "topic": "豊臣政権の身分統制", "q": "豊臣秀吉の政策によって、近世の身分制社会の基礎はどのように形づくられたか説明せよ。", "a": "太閤検地で耕作者を年貢負担者として検地帳に登録し、【刀狩】で百姓の武器を没収した。1591年の【人掃令】（身分統制令）では武士が町人・百姓になることや百姓が商人になることなどを禁じた。これらにより【兵農分離】が進み、近世の【身分制】社会の基礎が固まった。"},
  {"id": "jhx102", "s": "jh", "lv": 1, "topic": "江戸幕府の成立", "q": "徳川家康は、どのようにして江戸幕府を開き、その支配を固めたか説明せよ。", "a": "家康は1600年の【関ヶ原の戦い】で石田三成らを破り、1603年に【征夷大将軍】に任じられて江戸幕府を開いた。1615年の【大坂の陣】で豊臣氏を滅ぼし、幕府の支配を固めた。"},
  {"id": "jhx103", "s": "jh", "lv": 1, "topic": "武家諸法度", "q": "江戸幕府が大名を統制するために出した武家諸法度の内容を説明せよ。", "a": "1615年に初めて出された【武家諸法度】は、城の無断修築や大名どうしの無許可の【婚姻】などを禁じた。1635年には【徳川家光】が【参勤交代】を制度化した。違反した大名は領地を没収する【改易】などで処罰された。"},
  {"id": "jhx104", "s": "jh", "lv": 1, "topic": "大名の配置", "q": "江戸幕府は大名をどのように区別し、全国にどのように配置したか説明せよ。", "a": "徳川氏一門の【親藩】や、関ヶ原の戦い以前から徳川氏の家臣だった【譜代】を江戸周辺などの要地に置き、関ヶ原の戦い以後に従った【外様】は遠隔地に配置した。幕府の要職には主に譜代大名が就いた。"},
  {"id": "jhx105", "s": "jh", "lv": 2, "topic": "江戸幕府の職制", "q": "江戸幕府の主な役職について、それぞれがどのような役割を担ったか説明せよ。", "a": "常置の最高職である【老中】が政務を統括し、非常時には【大老】が置かれた。【若年寄】は老中を補佐して旗本・御家人を監督し、寺社奉行・町奉行・勘定奉行の【三奉行】が実務を担った。重要事項は評定所で合議された。"},
  {"id": "jhx106", "s": "jh", "lv": 3, "topic": "朝廷と寺社の統制", "q": "江戸幕府は、朝廷や寺社をどのように統制したか。紫衣事件の意味にもふれて説明せよ。", "a": "幕府は【禁中並公家諸法度】で天皇・公家の行動を規制し、【京都所司代】に朝廷を監視させた。1627年の【紫衣事件】は幕府の法が天皇の勅許に優越することを示した。寺院は寺院法度で統制され、【寺請制度】でキリシタンでないことを証明する役割を担わされた。"},
  {"id": "jhx107", "s": "jh", "lv": 2, "topic": "村の支配", "q": "江戸時代の村はどのように運営され、幕府や藩は村をどのように支配したか。", "a": "村は【名主】（庄屋）・組頭・百姓代の【村方三役】を中心に自治的に運営された。年貢は村全体の責任で納める【村請制】がとられ、【五人組】をつくらせて年貢の納入や犯罪の防止に連帯責任を負わせた。"},
  {"id": "jhx108", "s": "jh", "lv": 2, "topic": "本百姓と年貢", "q": "江戸時代の本百姓はどのような負担を負い、幕府は本百姓をどのように維持しようとしたか。", "a": "検地帳に登録された【本百姓】は、田畑・屋敷地にかかる【本途物成】を中心に、【小物成】や国役・伝馬役などを負担した。幕府は本百姓の没落を防ぐため、1643年に【田畑永代売買の禁止令】を出した。"},
  {"id": "jhx109", "s": "jh", "lv": 1, "topic": "島原の乱", "q": "島原・天草一揆が起きた理由と、その後の幕府の対外政策を説明せよ。", "a": "1637年、【キリシタン】への弾圧と重い年貢に苦しむ島原・天草の農民らが、【天草四郎】（益田時貞）を首領に一揆を起こした。乱の後、幕府は禁教を強化し、1639年に【ポルトガル】船の来航を禁止した。"},
  {"id": "jhx110", "s": "jh", "lv": 3, "topic": "四つの口", "q": "いわゆる「鎖国」下の江戸幕府は、長崎以外にどのような窓口で異国・異民族と交流したか説明せよ。", "a": "【対馬】藩の宗氏を通じて朝鮮と国交を結び、将軍の代がわりなどに【朝鮮通信使】が来日した。【薩摩】藩は琉球王国を支配しつつ、琉球の中国への朝貢貿易を利用した。【松前】藩はアイヌとの交易を独占した。"},
  {"id": "jhx111", "s": "jh", "lv": 2, "topic": "文治政治への転換", "q": "4代将軍徳川家綱の時代に、武断政治から文治政治へ転換したのはなぜか説明せよ。", "a": "大名の改易で増えた牢人による【由井正雪の乱】（慶安の変）を機に、武力で抑える政治から儒教の徳と礼による【文治政治】へ転換した。牢人の増加を防ぐため【末期養子の禁】をゆるめ、【殉死】も禁止した。"},
  {"id": "jhx112", "s": "jh", "lv": 2, "topic": "徳川綱吉の政治", "q": "5代将軍徳川綱吉の政治の特徴と、幕府の財政難への対応を説明せよ。", "a": "綱吉は【朱子学】を重んじて湯島聖堂を建て、極端な動物愛護令である【生類憐みの令】を出した。財政難に対しては荻原重秀の意見で金の含有量を減らした【元禄小判】を発行したため、【物価】が上昇した。"},
  {"id": "jhx113", "s": "jh", "lv": 3, "topic": "正徳の政治", "q": "新井白石による正徳の政治は、貨幣と長崎貿易についてどのような政策を行ったか、その目的とともに説明せよ。", "a": "朱子学者の【新井白石】は、元禄小判で上がった物価を抑えるため、質をもとに戻した【正徳小判】を発行した。また金銀の海外流出を防ぐため、【海舶互市新例】を出して長崎貿易での中国・オランダ船の数と貿易額を制限した。"},
  {"id": "jhx114", "s": "jh", "lv": 1, "topic": "江戸時代の農業", "q": "江戸時代前期から中期にかけて、農業生産が大きく伸びたのはなぜか説明せよ。", "a": "幕府や藩が【新田開発】を進めて耕地が大きく増えた。深く耕せる【備中鍬】や脱穀用の【千歯扱】などの農具が普及し、干鰯などの【金肥】も使われた。木綿や菜種などの【商品作物】の栽培も広がった。"},
  {"id": "jhx115", "s": "jh", "lv": 2, "topic": "江戸時代の交通", "q": "江戸時代の陸上交通と海上交通は、どのように整備されたか説明せよ。", "a": "陸上では江戸の日本橋を起点とする【五街道】が整備され、関所や宿駅が置かれた。海上では河村瑞賢が【西廻り航路】・東廻り航路を整え、江戸と大坂の間には【菱垣廻船】や樽廻船が運航した。"},
  {"id": "jhx116", "s": "jh", "lv": 1, "topic": "三都", "q": "江戸時代の三都とよばれた江戸・大坂・京都は、それぞれどのような役割をもっていたか。", "a": "【江戸】は「将軍のお膝元」で政治の中心であった。【大坂】は「天下の台所」とよばれ、諸藩の【蔵屋敷】が置かれて年貢米や特産物が集まった。【京都】には朝廷があり、西陣織など高級手工業の中心であった。"},
  {"id": "jhx117", "s": "jh", "lv": 1, "topic": "元禄文化", "q": "17世紀末から18世紀初めに栄えた元禄文化の担い手と、代表的な作者を説明せよ。", "a": "上方の豊かな【町人】を主な担い手とする文化である。【井原西鶴】は浮世草子で町人の生活を描き、【近松門左衛門】は人形浄瑠璃の脚本を書き、【松尾芭蕉】は俳諧を芸術の域に高めた。"},
  {"id": "jhx118", "s": "jh", "lv": 3, "topic": "江戸時代の儒学", "q": "江戸幕府が朱子学を重んじた理由と、朱子学を批判した儒学の学派について説明せよ。", "a": "朱子学は君臣・父子の別など上下の【身分秩序】を重んじたため、幕府の支配に都合がよく重視された。これに対し、知行合一を説く【陽明学】や、孔子・孟子の原典に立ち返ろうとする【古学】が起こり、伊藤仁斎や【荻生徂徠】らが活躍した。"},
  {"id": "jhx119", "s": "jh", "lv": 2, "topic": "江戸時代の貨幣と金融", "q": "江戸時代の貨幣制度の特徴と、両替商が果たした役割を説明せよ。", "a": "金・銀・銭の【三貨】が流通し、東日本では主に【金】、西日本では主に【銀】で取引が行われた。三貨の交換や為替・貸付を行う【両替商】が発達し、大坂・江戸の大商人は諸藩に金を貸す【大名貸】も行った。"},
  {"id": "jhx120", "s": "jh", "lv": 1, "topic": "寛政の改革", "q": "18世紀末に老中松平定信が行った寛政の改革の主な政策を説明せよ。", "a": "定信は、ききんに備えて大名に米を蓄えさせる【囲米】を命じ、旗本・御家人の借金を帳消しにする【棄捐令】を出した。また【寛政異学の禁】で湯島聖堂の学問所での朱子学以外の講義を禁じ、出版も統制した。"},
  {"id": "jhx121", "s": "jh", "lv": 2, "topic": "天明のききん", "q": "天明のききんは、民衆の動きや幕府の政治にどのような影響を与えたか説明せよ。", "a": "1782年からの【天明のききん】で多くの餓死者が出て、各地で【百姓一揆】が多発した。田沼意次の失脚後の1787年には江戸・大坂などで大規模な【打ちこわし】が起き、これを機に松平定信が老中となって【寛政の改革】が始まった。"},
  {"id": "jhx122", "s": "jh", "lv": 2, "topic": "大塩の乱", "q": "1837年に大塩平八郎が乱を起こした背景と、その乱が幕府に与えた衝撃を説明せよ。", "a": "【天保のききん】で大坂でも餓死者が出る中、奉行所が米を江戸へ回していることに憤った元大坂町奉行所与力の【大塩平八郎】が、門弟らと蜂起した。幕府の直轄都市で元役人が反乱を起こしたことは幕府に大きな衝撃を与え、越後でも【生田万】の乱が起きた。"},
  {"id": "jhx123", "s": "jh", "lv": 2, "topic": "異国船打払令", "q": "19世紀前半、幕府の外国船への対応はどのように変化したか説明せよ。", "a": "イギリス船などの接近が続いたため、幕府は1825年に【異国船打払令】を出し、1837年にはアメリカ商船を砲撃する【モリソン号事件】が起きた。しかし【アヘン戦争】で清が敗れたことを知ると、1842年に【天保の薪水給与令】を出して方針を緩めた。"},
  {"id": "jhx124", "s": "jh", "lv": 3, "topic": "北方の緊張", "q": "18世紀末から19世紀初めにかけてロシアが接近すると、幕府はどのように対応したか説明せよ。", "a": "1792年に【ラクスマン】が根室に来航して通商を求め、1804年には【レザノフ】が長崎に来航した。幕府は通商を拒否する一方、近藤重蔵や【間宮林蔵】らに蝦夷地・樺太を調査させ、蝦夷地を【直轄】にして防備を固めた。"},
  {"id": "jhx125", "s": "jh", "lv": 3, "topic": "雄藩の藩政改革", "q": "薩摩藩と長州藩の藩政改革の内容と、その後の政局に与えた影響を説明せよ。", "a": "薩摩藩では【調所広郷】が借財を整理し、奄美の黒砂糖の専売や琉球を通じた貿易で財政を立て直した。長州藩では【村田清風】が借財を整理し、越荷方で利益をあげた。改革に成功した藩は【雄藩】として幕末の政局で発言力を強めた。"},
  {"id": "jhx126", "s": "jh", "lv": 2, "topic": "化政文化", "q": "19世紀前半の化政文化の特徴を、担い手や絵画・文学にふれて説明せよ。", "a": "【江戸】の町人を中心とする文化で、多色刷りの【浮世絵】が広まり、【葛飾北斎】や歌川広重が風景画を描いた。【十返舎一九】の滑稽本や、川柳・狂歌が流行し、庶民の旅や寺社参詣も盛んになった。"},
  {"id": "jhx127", "s": "jh", "lv": 1, "topic": "国学と蘭学", "q": "江戸時代中期以降に発達した国学と蘭学について、代表的な人物と業績をあげて説明せよ。", "a": "国学では【本居宣長】が『古事記伝』を著して大成した。蘭学では【杉田玄白】らがオランダ語の解剖書を翻訳して『【解体新書】』を出版した。また【伊能忠敬】は全国を測量して正確な日本地図をつくった。"},
  {"id": "jhx128", "s": "jh", "lv": 1, "topic": "江戸時代の教育", "q": "江戸時代には、武士や庶民の教育はどのように行われていたか説明せよ。", "a": "庶民の子どもは【寺子屋】で読み・書き・そろばんを学び、識字率が高まった。藩は藩士の子弟のために【藩校】を設けた。民間でも緒方洪庵の【適塾】など私塾が開かれ、多くの人材を育てた。"},
  {"id": "jhx129", "s": "jh", "lv": 2, "topic": "手工業の発達", "q": "江戸時代後期の手工業生産には、どのような変化がみられたか説明せよ。", "a": "問屋が農民に原料や道具を貸して製品を買い取る【問屋制家内工業】が広がった。19世紀には地主や問屋が作業場に奉公人を集め、分業と協業で生産する【工場制手工業】（マニュファクチュア）が、大坂周辺や尾張の【綿織物】業などで始まった。"},
  {"id": "jhx130", "s": "jh", "lv": 3, "topic": "百姓一揆の変化", "q": "江戸時代の百姓一揆の形態は、時期によってどのように変化したか。背景とともに説明せよ。", "a": "17世紀には村の代表者が領主に直訴する【代表越訴型一揆】が多かった。17世紀末からは村々の百姓が広く団結する【惣百姓一揆】が増えた。貨幣経済の浸透で農民の貧富の差が広がると、幕末には社会の変革を求める【世直し一揆】が起きた。"},
  {"id": "jhx131", "s": "jh", "lv": 3, "topic": "関東農村の治安", "q": "19世紀前半の関東農村で治安が乱れた理由と、幕府の対策を説明せよ。", "a": "関東では商品経済の浸透で貧富の差が広がり、土地を失った農民が村を離れて【無宿人】や博徒となり、治安が乱れた。幕府は1805年に【関東取締出役】を設けて巡回させ、1827年には近隣の村々を組み合わせた【寄場組合】をつくらせて治安維持にあたらせた。"},
  {"id": "jhx132", "s": "jh", "lv": 3, "topic": "洋学の発達", "q": "江戸時代に洋学が発達した経緯と、幕府の洋学に対する姿勢を説明せよ。", "a": "徳川吉宗が【漢訳洋書】の輸入制限をゆるめ、実学を奨励したことから蘭学が発達した。19世紀には幕府が天文方に【蛮書和解御用】を設けて翻訳を進め、洋学を実用的に利用した。一方、幕政批判には【蛮社の獄】で渡辺崋山・高野長英を処罰するなど弾圧を加えた。"},
  {"id": "jhx133", "s": "jh", "lv": 1, "topic": "ペリー来航と開国", "q": "ペリー来航の翌年に結ばれた日米和親条約の主な内容を説明せよ。", "a": "1853年、【ペリー】が浦賀に来航して開国を求めた。翌1854年に【日米和親条約】が結ばれ、【下田】と箱館を開港し、アメリカ船に燃料や食料を供給すること、アメリカに一方的な【最恵国待遇】を与えることなどを認めた。"},
  {"id": "jhx134", "s": "jh", "lv": 1, "topic": "日米修好通商条約", "q": "日米修好通商条約はどのように結ばれ、どのような点が不平等だったか説明せよ。", "a": "1858年、大老【井伊直弼】は天皇の勅許を得ないまま条約に調印し、神奈川・長崎など5港を開いた。この条約は日本に【関税自主権】がなく、アメリカに【領事裁判権】を認める不平等条約であった。"},
  {"id": "jhx135", "s": "jh", "lv": 3, "topic": "開港の経済的影響", "q": "開港による貿易の開始は、国内の経済と政治にどのような影響を与えたか説明せよ。", "a": "最大の輸出品である【生糸】が大量に輸出されて国内で品不足となり、物価が上昇した。また日本と外国の【金銀比価】の違いから大量の金貨が流出し、幕府が質を落とした【万延小判】を発行したため物価上昇が加速した。生活が苦しくなった人々の不満は【攘夷運動】を高めた。"},
  {"id": "jhx136", "s": "jh", "lv": 2, "topic": "安政の大獄と桜田門外の変", "q": "井伊直弼による安政の大獄と、その結果起きた桜田門外の変について説明せよ。", "a": "井伊直弼は、条約調印や将軍継嗣問題で対立した大名や公家、志士らを【安政の大獄】で処罰し、【吉田松陰】らを処刑した。これに憤った水戸藩などの浪士が1860年【桜田門外の変】で井伊を暗殺し、幕府の権威は大きく揺らいだ。"},
  {"id": "jhx137", "s": "jh", "lv": 2, "topic": "公武合体", "q": "老中安藤信正が進めた公武合体策の内容と、その結果を説明せよ。", "a": "老中【安藤信正】は朝廷と幕府の融和をはかる【公武合体】を進め、孝明天皇の妹【和宮】を将軍徳川家茂の妻に迎えた。しかし尊王攘夷派の反発を受け、1862年の【坂下門外の変】で負傷して失脚した。"},
  {"id": "jhx138", "s": "jh", "lv": 2, "topic": "攘夷から倒幕へ", "q": "薩摩藩と長州藩が攘夷の方針を転換するに至った経緯を説明せよ。", "a": "【生麦事件】の報復としてイギリスと薩英戦争が起き、長州藩の外国船砲撃の報復として四国艦隊による【下関砲撃事件】が起きた。両藩は欧米の軍事力の強さを知って【攘夷】が不可能であると悟り、開国と軍備の近代化、そして【倒幕】へと方針を転換した。"},
  {"id": "jhx139", "s": "jh", "lv": 2, "topic": "長州征討", "q": "幕府による2度の長州征討の経過と、その結果幕府はどうなったか説明せよ。", "a": "1864年、長州藩は【禁門の変】で敗れ、【第1次長州征討】で幕府に恭順した。しかし【高杉晋作】らが藩の実権を握って倒幕に転じ、薩摩藩と結んで【第2次長州征討】で幕府軍を退けたため、幕府の権威は大きく失墜した。"},
  {"id": "jhx140", "s": "jh", "lv": 1, "topic": "薩長同盟", "q": "1866年に薩長同盟が結ばれた経緯と、その歴史的な意味を説明せよ。", "a": "土佐藩出身の【坂本龍馬】らの仲介で、対立していた【薩摩藩】と【長州藩】が軍事同盟を結んだ。これにより両藩は協力して【倒幕】へと向かうことになった。"},
  {"id": "jhx141", "s": "jh", "lv": 1, "topic": "大政奉還と王政復古", "q": "大政奉還と王政復古の大号令によって、政治の体制はどのように変わったか説明せよ。", "a": "1867年、将軍【徳川慶喜】は【大政奉還】を行い、政権を朝廷に返した。倒幕派は【王政復古の大号令】を出して幕府を廃止し、天皇中心の新政府を樹立した。これに旧幕府側が反発し、【戊辰戦争】が始まった。"},
  {"id": "jhx142", "s": "jh", "lv": 1, "topic": "五箇条の誓文", "q": "明治新政府が示した五箇条の誓文と五榜の掲示は、それぞれどのような内容か。", "a": "1868年、新政府は【五箇条の誓文】で、広く会議を開いて【公議世論】を尊重することや、知識を世界に求めることなどの基本方針を示した。一方、民衆向けの【五榜の掲示】では、【キリスト教】の禁止など旧幕府の政策を引き継いだ。"},
  {"id": "jhx143", "s": "jh", "lv": 1, "topic": "版籍奉還と廃藩置県", "q": "版籍奉還と廃藩置県によって、明治政府はどのように中央集権体制を築いたか。", "a": "1869年の【版籍奉還】で藩主に領地と領民を天皇に返させたが、旧藩主は知藩事として藩を治めた。1871年の【廃藩置県】で藩を廃止して府県を置き、中央から【府知事・県令】を派遣して全国を直接支配した。"},
  {"id": "jhx144", "s": "jh", "lv": 1, "topic": "徴兵令", "q": "1873年に出された徴兵令の内容と、それに対する国民の反応を説明せよ。", "a": "満20歳以上の男子に兵役を課す【徴兵令】を出し、【国民皆兵】による近代的な軍隊をめざした。しかし戸主や長男などには【免役規定】があり、兵役は主に農家の二男・三男が負った。反対する【血税一揆】も各地で起こった。"},
  {"id": "jhx145", "s": "jh", "lv": 1, "topic": "殖産興業", "q": "明治政府が進めた殖産興業とは、どのような目的と内容の政策か説明せよ。", "a": "欧米に追いつくため、政府が主導して近代産業を育成する【殖産興業】を進めた。【富岡製糸場】などの【官営模範工場】を建て、外国人技術者を招いて技術を広めた。また鉄道の敷設や【郵便】制度の整備も進めた。"},
  {"id": "jhx146", "s": "jh", "lv": 1, "topic": "文明開化", "q": "明治初期の文明開化によって、人々の教育や生活はどのように変化したか説明せよ。", "a": "1872年に【学制】が公布され、国民皆学がめざされた。【福沢諭吉】の『学問のすゝめ』が広く読まれ、【太陽暦】の採用やガス灯・洋服・牛なべの普及など、欧米風の生活様式が都市を中心に広がった。"},
  {"id": "jhx147", "s": "jh", "lv": 2, "topic": "岩倉使節団", "q": "1871年に派遣された岩倉使節団の目的と成果、帰国後の政治への影響を説明せよ。", "a": "1871年、【岩倉具視】を全権大使とする使節団が欧米に派遣された。【条約改正】の予備交渉は失敗したが、欧米の政治や産業を視察した。帰国後、大久保利通らは【内治優先】を主張し、【征韓論】に反対した。"},
  {"id": "jhx148", "s": "jh", "lv": 3, "topic": "明治六年の政変", "q": "明治六年の政変は、どのような対立から起こり、その後の政治や社会にどのような影響を与えたか。", "a": "留守政府の【西郷隆盛】・板垣退助らは朝鮮に武力で開国を迫る【征韓論】を唱えたが、帰国した大久保利通らが内治優先を主張して退け、西郷らは政府を去った。下野した板垣らは【民撰議院設立建白書】を出して自由民権運動を始め、西郷はのちに【西南戦争】を起こした。"},
  {"id": "jhx149", "s": "jh", "lv": 2, "topic": "秩禄処分と士族反乱", "q": "士族の特権が失われていった過程と、それに対する士族の反乱を説明せよ。", "a": "政府は1876年に【廃刀令】を出し、同年【秩禄処分】で金禄公債証書を与えて家禄の支給を打ち切った。特権を失った士族は不満を強め、1877年には【西郷隆盛】を中心とする最大の士族反乱【西南戦争】を起こしたが、政府軍に鎮圧された。"},
  {"id": "jhx150", "s": "jh", "lv": 3, "topic": "明治初期の国境画定", "q": "明治初期の日本は、ロシア・朝鮮・琉球との関係をどのように定めたか説明せよ。", "a": "1875年、ロシアと【樺太・千島交換条約】を結び、樺太をロシア領、千島全島を日本領とした。1876年には江華島事件を機に、朝鮮と日本に有利な不平等条約の【日朝修好条規】を結んだ。琉球に対しては【琉球処分】を行い、1879年に沖縄県を設置した。"},
  {"id": "jhx151", "s": "jh", "lv": 2, "topic": "北海道の開拓", "q": "明治政府は北海道の開拓をどのように進め、アイヌの人々にどのような影響を与えたか。", "a": "1869年に蝦夷地を北海道と改め、【開拓使】を置いて開拓を進めた。【屯田兵】制度により士族などを移住させ、開拓と北方の防備にあたらせた。アイヌの人々は土地や生活を奪われ、1899年の【北海道旧土人保護法】で同化政策が進められた。"},
  {"id": "jhx152", "s": "jh", "lv": 3, "topic": "神仏分離と宗教政策", "q": "明治初期の政府の宗教政策を、神道・仏教・キリスト教それぞれへの対応にふれて説明せよ。", "a": "政府は祭政一致をめざして【神仏分離令】を出し、各地で寺院や仏像を壊す【廃仏毀釈】が起きた。大教宣布の詔で【神道】の国教化をはかったが進まなかった。キリスト教は五榜の掲示で禁止したが、欧米の抗議を受け、1873年に禁教の【高札】を撤去して事実上黙認した。"},
  {"id": "jhx153", "s": "jh", "lv": 3, "topic": "明治十四年の政変", "q": "明治十四年の政変の経緯と、その後の立憲制度づくりへの影響を説明せよ。", "a": "1881年、【開拓使官有物払下げ事件】で政府への批判が高まると、政府は早期の国会開設を主張する【大隈重信】を罷免するとともに、10年後の国会開設を約束した。これにより【伊藤博文】らを中心とする薩長藩閥政権が確立し、【ドイツ】流の憲法制定が進められた。"},
  {"id": "jhx154", "s": "jh", "lv": 1, "topic": "政党の結成", "q": "国会開設の勅諭が出されたのち、どのような政党が結成されたか説明せよ。", "a": "国会開設に備え、1881年に【板垣退助】がフランス流の急進的な自由主義を掲げる【自由党】を、翌1882年に【大隈重信】がイギリス流の議会政治をめざす【立憲改進党】を結成した。"},
  {"id": "jhx155", "s": "jh", "lv": 3, "topic": "松方財政", "q": "松方正義による財政政策の内容と、それが農村や民権運動に与えた影響を説明せよ。", "a": "西南戦争の戦費で不換紙幣が増え【インフレ】が進んだため、大蔵卿【松方正義】は増税と緊縮財政で紙幣を整理し、【日本銀行】を設立して銀兌換銀行券を発行した。その結果激しい【デフレ】となって米や繭の価格が下がり、土地を失う農民が増え、【秩父事件】などの激化事件が起きた。"},
  {"id": "jhx156", "s": "jh", "lv": 1, "topic": "大日本帝国憲法", "q": "大日本帝国憲法はどのようにつくられ、どのような特徴をもっていたか説明せよ。", "a": "【伊藤博文】らがドイツ（プロイセン）の憲法を参考に草案をつくり、1889年に天皇が定める【欽定憲法】として発布された。天皇は陸海軍を指揮する【統帥権】など強い権限をもち、国民は【臣民】として法律の範囲内で権利を認められた。"},
  {"id": "jhx157", "s": "jh", "lv": 2, "topic": "初期議会", "q": "最初の衆議院議員選挙の選挙権と、初期議会での民党と政府の対立を説明せよ。", "a": "1890年の第1回総選挙で、選挙権は直接国税【15円】以上を納める満25歳以上の男子に限られた。初期議会では、多数を占めた【民党】が「政費節減・【民力休養】」を掲げ、政府の予算案に反対した。"},
  {"id": "jhx158", "s": "jh", "lv": 3, "topic": "民法典論争", "q": "明治期の民法典論争とは何か。その結果制定された民法の特徴とともに説明せよ。", "a": "フランス人【ボアソナード】の起草による民法が1890年に公布されたが、「民法出デテ忠孝亡ブ」と【穂積八束】らが批判し、施行が延期された。1898年に施行された修正民法は、戸主に強い権限を認める【家制度】を定めた。"},
  {"id": "jhx159", "s": "jh", "lv": 1, "topic": "日清戦争", "q": "1894年に日清戦争が始まったきっかけと、講和条約である下関条約の内容を説明せよ。", "a": "1894年、朝鮮で【甲午農民戦争】が起こると、日清両国が出兵して日清戦争となった。勝利した日本は【下関条約】で清に朝鮮の独立を認めさせ、【遼東半島】・台湾などと多額の【賠償金】を得た。"},
  {"id": "jhx160", "s": "jh", "lv": 1, "topic": "日英同盟", "q": "1902年に日本とイギリスが日英同盟を結んだのはなぜか説明せよ。", "a": "義和団事件後も【ロシア】が満州に軍隊をとどめ、韓国への影響力を強めようとした。ロシアの南下を警戒する点で利害が一致した日本と【イギリス】は【日英同盟】を結び、これが【日露戦争】を進めるうえで日本の支えとなった。"},
  {"id": "jhx161", "s": "jh", "lv": 1, "topic": "ポーツマス条約", "q": "日露戦争の講和条約であるポーツマス条約の内容と、それに対する国民の反応を説明せよ。", "a": "1905年の【ポーツマス条約】で、日本は韓国に対する指導・監督権、旅順・大連の租借権、【南樺太】などを得たが、【賠償金】は得られなかった。重税に耐えて戦争に協力した国民は不満を爆発させ、【日比谷焼打ち事件】が起きた。"},
  {"id": "jhx162", "s": "jh", "lv": 2, "topic": "韓国併合", "q": "日露戦争後、日本はどのような過程を経て韓国を併合したか説明せよ。", "a": "1905年の第2次日韓協約で韓国の外交権を奪って【統監府】を置き、【伊藤博文】が初代統監となった。韓国では【義兵運動】が広がり、伊藤はハルビンで暗殺された。1910年、日本は韓国を併合し【朝鮮総督府】を置いた。"},
  {"id": "jhx163", "s": "jh", "lv": 1, "topic": "産業革命と軽工業", "q": "明治時代の日本の産業革命は、どのような産業を中心に進んだか説明せよ。", "a": "1880年代後半から、大阪紡績会社の成功を機に機械制の【紡績業】が発展した。製糸業では【生糸】が最大の輸出品となって外貨を稼いだ。日清戦争の賠償金の一部をもとに1897年に【金本位制】を確立した。"},
  {"id": "jhx164", "s": "jh", "lv": 2, "topic": "重工業の発達", "q": "日清・日露戦争の前後に、日本の重工業や経済のしくみはどのように発達したか。", "a": "官営【八幡製鉄所】が建てられ、1901年に操業を開始した。日露戦争後は造船・機械などの重工業が発展し、主要な私鉄は【鉄道国有法】で国有化された。三井・三菱などの【財閥】は持株会社を中心に多角経営を進めた。"},
  {"id": "jhx165", "s": "jh", "lv": 1, "topic": "明治の社会問題", "q": "産業革命の進展にともなって、どのような社会問題が起こり、政府はどう対応したか。", "a": "製糸・紡績工場で働く【女工】の長時間労働などが問題となり、【足尾銅山鉱毒事件】では田中正造が操業停止を訴えた。政府は【治安警察法】で労働運動を取り締まる一方、1911年に初の労働者保護法である【工場法】を制定した。"},
  {"id": "jhx166", "s": "jh", "lv": 1, "topic": "明治の文化と教育", "q": "明治時代の文学・美術・教育には、どのような新しい動きがみられたか説明せよ。", "a": "文学では【坪内逍遙】が写実主義を唱え、二葉亭四迷は【言文一致】体で小説を書いた。美術では岡倉天心と【フェノロサ】が伝統美術の復興に努めた。1890年には【教育勅語】が出され、忠君愛国が教育の基本とされた。"},
  {"id": "jhx167", "s": "jh", "lv": 3, "topic": "藩閥と政党の接近", "q": "日清戦争後、藩閥政府と政党の関係はどのように変化したか。立憲政友会の結成に至る過程を説明せよ。", "a": "藩閥政府は議会の協力を得るため政党と提携し、1898年には初の政党内閣である【隈板内閣】が成立した。続く山県有朋内閣は文官任用令の改正や【軍部大臣現役武官制】で政党の影響力を抑えたが、伊藤博文は政党の必要を認め、1900年に自ら【立憲政友会】を結成した。"},
  {"id": "jhx168", "s": "jh", "lv": 1, "topic": "第一次護憲運動", "q": "1912年から翌年にかけての第一次護憲運動の経過と、その結果を説明せよ。", "a": "陸軍の2個師団増設問題で内閣が倒れたあと【桂太郎】が組閣すると、尾崎行雄・犬養毅らが「【閥族打破・憲政擁護】」を掲げて運動を起こした。民衆も議会を取り囲み、桂内閣は50日余りで退陣した（【大正政変】）。"},
  {"id": "jhx169", "s": "jh", "lv": 1, "topic": "第一次世界大戦と日本", "q": "日本はどのような理由で第一次世界大戦に参戦し、中国に対して何を行ったか。", "a": "日本は【日英同盟】を理由にドイツに宣戦し、中国のドイツの拠点【青島】や南洋諸島を占領した。1915年には中国の袁世凱政府に【二十一か条の要求】を出し、その大部分を認めさせた。"},
  {"id": "jhx170", "s": "jh", "lv": 1, "topic": "大戦景気", "q": "第一次世界大戦中に日本が好景気となった理由と、その影響を説明せよ。", "a": "ヨーロッパ諸国がアジア市場から後退したため輸出が急増し、日本は【債務国】から【債権国】に転じた。海運業・造船業が好況となって【成金】が生まれ、【重化学工業】も発展した。一方で物価が上がり、民衆の生活は苦しくなった。"},
  {"id": "jhx171", "s": "jh", "lv": 1, "topic": "米騒動と原敬内閣", "q": "1918年の米騒動はなぜ起こり、政治にどのような変化をもたらしたか。", "a": "【シベリア出兵】を見こした米の買い占めなどで米価が急騰し、富山県から全国に【米騒動】が広がった。寺内正毅内閣は責任をとって退陣し、立憲政友会総裁の【原敬】が初の本格的な【政党内閣】を組織した。"},
  {"id": "jhx172", "s": "jh", "lv": 3, "topic": "原敬内閣の政策", "q": "原敬内閣はどのような政策を進めたか。普通選挙に対する姿勢にふれて説明せよ。", "a": "原敬は衆議院に議席をもつ初の首相で「平民宰相」とよばれた。高等教育機関の拡充や鉄道網の整備など【積極政策】を進めたが、【普通選挙】の実施には慎重で、選挙権の納税資格を直接国税【3円】以上に引き下げ、【小選挙区制】を導入するにとどめた。"},
  {"id": "jhx173", "s": "jh", "lv": 1, "topic": "大正デモクラシー", "q": "大正デモクラシーを理論的に支えた考え方を、代表的な人物とともに説明せよ。", "a": "【吉野作造】は、主権の所在を問わず民衆の意向を重んじる政治を求める【民本主義】を唱えた。【美濃部達吉】は、統治権は国家にあり天皇はその最高機関であるとする【天皇機関説】を唱え、政党政治を支えた。"},
  {"id": "jhx174", "s": "jh", "lv": 2, "topic": "大正期の社会運動", "q": "大正時代には、どのような社会運動が展開されたか。具体的な団体をあげて説明せよ。", "a": "労働争議や小作争議が増え、1922年に【日本農民組合】が結成された。被差別部落の人々は差別からの解放をめざして【全国水平社】を結成した。平塚らいてう・市川房枝らは女性の地位向上を求めて【新婦人協会】を結成した。"},
  {"id": "jhx175", "s": "jh", "lv": 2, "topic": "ワシントン会議", "q": "ワシントン会議で結ばれた条約の内容と、それが日本に与えた影響を説明せよ。", "a": "1921〜22年の会議で、主力艦の保有を制限する【ワシントン海軍軍縮条約】、太平洋地域の現状維持を約す【四か国条約】、中国の主権尊重を約す【九か国条約】が結ばれた。四か国条約により【日英同盟】は廃棄された。"},
  {"id": "jhx176", "s": "jh", "lv": 3, "topic": "護憲三派内閣", "q": "第二次護憲運動から「憲政の常道」の時代とその終わりまでの政党政治の流れを説明せよ。", "a": "1924年、貴族院中心の清浦奎吾内閣に対して【第二次護憲運動】が起こり、総選挙で勝利した【加藤高明】が護憲三派内閣を組織した。以後、衆議院の多数党の党首が内閣を組織する「【憲政の常道】」が続いたが、1932年の【五・一五事件】で終わった。"},
  {"id": "jhx177", "s": "jh", "lv": 2, "topic": "金融恐慌", "q": "1927年に起きた金融恐慌の背景と、政府による収拾策を説明せよ。", "a": "関東大震災で決済できなくなった【震災手形】が多く残り、銀行の経営が不安定になっていた。1927年、大蔵大臣の失言をきっかけに預金者が銀行に殺到する【取付け騒ぎ】が起こり、銀行の休業が相次いだ。田中義一内閣は【モラトリアム】（支払猶予令）を出して混乱を鎮めた。"},
  {"id": "jhx178", "s": "jh", "lv": 1, "topic": "昭和恐慌", "q": "1930年に始まった昭和恐慌は、なぜ深刻なものになったか説明せよ。", "a": "浜口雄幸内閣の井上準之助蔵相が【金解禁】を行ったが、前年に始まった【世界恐慌】と重なり、輸出が激減して深刻な不況となった。生糸の対米輸出が減って繭の価格が暴落し、【農村】では欠食児童や娘の身売りが問題となった。"},
  {"id": "jhx179", "s": "jh", "lv": 3, "topic": "高橋財政", "q": "高橋是清の財政政策の内容と、それが景気や国際関係に与えた影響を説明せよ。", "a": "犬養毅内閣の【高橋是清】蔵相は【金輸出再禁止】を行い、管理通貨制度へ移行した。円安を利用して綿織物などの輸出を伸ばし、【赤字国債】による軍事費・農村救済費の支出で景気を回復させた。一方、イギリスなどは日本の輸出を【ソーシャル・ダンピング】と非難した。"},
  {"id": "jhx180", "s": "jh", "lv": 2, "topic": "協調外交", "q": "1920年代の幣原外交の特徴と、ロンドン海軍軍縮条約をめぐる問題を説明せよ。", "a": "外務大臣【幣原喜重郎】は欧米との協調と、中国への内政不干渉を原則とする【協調外交】を進めた。1930年に浜口内閣が【ロンドン海軍軍縮条約】に調印すると、野党や海軍軍令部などが【統帥権干犯】だと政府を攻撃した。"},
  {"id": "jhx181", "s": "jh", "lv": 1, "topic": "国際連盟脱退", "q": "満州事変後、日本が国際連盟を脱退するに至った経緯を説明せよ。", "a": "日本は1932年に【満州国】を建国させたが、国際連盟は【リットン調査団】の報告にもとづき、日本に満州からの撤兵を求める勧告を可決した。これに反発した日本は1933年に【国際連盟】脱退を通告し、国際的に孤立していった。"},
  {"id": "jhx182", "s": "jh", "lv": 1, "topic": "五・一五事件と二・二六事件", "q": "五・一五事件と二・二六事件は、日本の政治にどのような影響を与えたか説明せよ。", "a": "1932年の【五・一五事件】で海軍青年将校らが【犬養毅】首相を暗殺し、政党内閣の時代が終わった。1936年の【二・二六事件】では陸軍の皇道派青年将校が首相官邸などを襲撃した。鎮圧後、【陸軍】の政治的発言力はいっそう強まった。"},
  {"id": "jhx183", "s": "jh", "lv": 1, "topic": "日中戦争", "q": "1937年に始まった日中戦争はどのように起こり、なぜ長期化したか説明せよ。", "a": "1937年の【盧溝橋事件】をきっかけに日中戦争が始まった。日本軍は首都【南京】を占領したが、中国では国民党と共産党が協力して【抗日民族統一戦線】を結び、国民政府も拠点を重慶に移して抗戦を続けたため、戦争は長期化した。"},
  {"id": "jhx184", "s": "jh", "lv": 1, "topic": "国家総動員法", "q": "日中戦争の長期化にともなって、国内の体制はどのように変化したか説明せよ。", "a": "1938年、近衛文麿内閣は【国家総動員法】を制定し、政府が議会の承認なしに【勅令】で物資や労働力を動員できるようにした。1940年には政党が解散して【大政翼賛会】が結成された。"},
  {"id": "jhx185", "s": "jh", "lv": 3, "topic": "太平洋戦争への道", "q": "日本が日米開戦に至るまでの過程を、南進政策とアメリカの対応にふれて説明せよ。", "a": "日本は資源を求めて1940年に【北部仏印進駐】を行い、同年【日独伊三国同盟】を結んだ。1941年に南部仏印に進駐すると、アメリカは【石油】の対日輸出を禁止した。日米交渉は中国からの撤兵などを求める【ハル・ノート】で行き詰まり、日本は12月に開戦した。"},
  {"id": "jhx186", "s": "jh", "lv": 1, "topic": "戦時下の国民生活", "q": "太平洋戦争中、国民の生活や植民地の人々にはどのような影響が及んだか。", "a": "生活必需品が不足し、米などは【配給制】となった。1943年には大学生などが【学徒出陣】で戦場に送られ、都市の子どもは空襲を避けて【学童疎開】を行った。朝鮮や台湾では創氏改名などの【皇民化政策】が進められた。"},
  {"id": "jhx187", "s": "jh", "lv": 1, "topic": "大衆文化の誕生", "q": "大正から昭和初期にかけて大衆文化が広まったのはなぜか説明せよ。", "a": "都市化が進み、事務職などの【サラリーマン】が増え、中等教育を受ける人も増えた。新聞や雑誌の発行部数が伸び、1925年には【ラジオ放送】が始まった。映画も人気を集め、【大衆文化】が生まれた。"},
  {"id": "jhx188", "s": "jh", "lv": 1, "topic": "敗戦", "q": "1945年に日本がポツダム宣言を受諾して降伏するまでの経過を説明せよ。", "a": "1945年、沖縄戦を経て、8月には広島・長崎に【原子爆弾】が投下され、【ソ連】も日ソ中立条約を破って対日参戦した。日本は【ポツダム宣言】を受諾し、8月15日に天皇のラジオ放送で降伏が国民に伝えられた。"},
  {"id": "jhx189", "s": "jh", "lv": 1, "topic": "GHQの民主化政策", "q": "敗戦後、GHQは日本でどのような目的のもとに、どのような改革を進めたか。", "a": "GHQは最高司令官【マッカーサー】のもとで、日本の【非軍事化】と民主化を進めた。【五大改革指令】では、女性参政権の付与、労働組合の結成の奨励、教育の自由主義化、圧政的制度の撤廃、経済の民主化を求めた。"},
  {"id": "jhx190", "s": "jh", "lv": 1, "topic": "日本国憲法", "q": "戦後に制定された日本国憲法の三つの基本原則と、天皇の地位を説明せよ。", "a": "日本国憲法は1946年11月3日に公布、翌年5月3日に施行された。【国民主権】・【基本的人権の尊重】・【平和主義】を三原則とし、天皇は日本国と日本国民統合の【象徴】とされた。"},
  {"id": "jhx191", "s": "jh", "lv": 2, "topic": "財閥解体", "q": "GHQが財閥解体を進めた理由と、その経過および結果を説明せよ。", "a": "財閥が軍国主義を経済面で支えたとして、GHQは【持株会社】の解散などを進めた。1947年には【独占禁止法】と【過度経済力集中排除法】が制定された。しかし冷戦の進展で占領政策が転換すると緩和され、不徹底に終わった。"},
  {"id": "jhx192", "s": "jh", "lv": 1, "topic": "戦後の教育改革", "q": "戦後の教育改革によって、日本の教育制度はどのように変わったか説明せよ。", "a": "1947年に【教育基本法】が制定され、教育の機会均等や男女共学などが定められた。同年の【学校教育法】で【六・三・三・四制】が導入され、義務教育は9年となった。また公選制の【教育委員会】が置かれた。"},
  {"id": "jhx193", "s": "jh", "lv": 2, "topic": "戦後の労働改革", "q": "戦後の労働改革の内容と、占領下での労働運動の展開を説明せよ。", "a": "【労働組合法】・労働関係調整法・【労働基準法】の労働三法が制定され、労働者の権利が保障された。労働組合が急増し運動が高まったが、1947年に計画された【二・一ゼネスト】は【GHQ】の指令で中止された。"},
  {"id": "jhx194", "s": "jh", "lv": 1, "topic": "女性の地位の向上", "q": "戦後の改革によって、女性の政治的・法的な地位はどのように変わったか説明せよ。", "a": "1945年の選挙法改正で満【20歳】以上の男女に選挙権が与えられ、翌年の総選挙では39名の【女性議員】が誕生した。1947年の【民法】改正で【家制度】が廃止され、男女平等が定められた。"},
  {"id": "jhx195", "s": "jh", "lv": 3, "topic": "占領政策の転換", "q": "冷戦の進展により、アメリカの対日占領政策はどのように転換したか。経済と軍事の両面から説明せよ。", "a": "冷戦が激しくなると、アメリカは日本を【反共の防壁】とするため、経済の自立と復興を重視するようになった。【経済安定九原則】の実行のため【ドッジ・ライン】で財政を引き締め、1ドル＝360円の単一為替レートを設定した。朝鮮戦争が始まると【警察予備隊】が創設された。"},
  {"id": "jhx196", "s": "jh", "lv": 1, "topic": "朝鮮特需", "q": "1950年に始まった朝鮮戦争は、日本経済にどのような影響を与えたか説明せよ。", "a": "1950年に【朝鮮戦争】が始まると、日本はアメリカ軍の物資やサービスの調達地となり、【特需】が発生した。日本経済は【ドッジ・ライン】による不況から回復し、1951年には工業生産が戦前の水準を回復した。"},
  {"id": "jhx197", "s": "jh", "lv": 1, "topic": "サンフランシスコ平和条約", "q": "サンフランシスコ平和条約と日米安全保障条約の内容と、その問題点を説明せよ。", "a": "1951年、【吉田茂】内閣は48か国とサンフランシスコ平和条約を結び、翌年日本は独立を回復した。ソ連などは調印せず【単独講和】となった。同日に【日米安全保障条約】を結び、独立後も米軍の駐留を認めた。沖縄・小笠原はアメリカの施政下に残った。"},
  {"id": "jhx198", "s": "jh", "lv": 1, "topic": "55年体制", "q": "1955年に成立した55年体制とは、どのような政治体制か説明せよ。", "a": "1955年、左右に分裂していた【日本社会党】が統一すると、保守の日本民主党と自由党も【保守合同】して【自由民主党】を結成した。以後、自民党が政権を保ち社会党が野党第一党となる体制が1993年まで続いた。"},
  {"id": "jhx199", "s": "jh", "lv": 1, "topic": "日ソ共同宣言", "q": "1956年の日ソ共同宣言は、日本の国際社会への復帰にどのような意味をもったか。", "a": "【鳩山一郎】内閣は【日ソ共同宣言】に調印してソ連との国交を回復した。これにより、それまで日本の加盟に反対していたソ連が支持に転じ、同年日本の【国際連合】加盟が実現した。"},
  {"id": "jhx200", "s": "jh", "lv": 2, "topic": "安保改定", "q": "1960年の日米安全保障条約の改定とその反対運動、その後の政治の変化を説明せよ。", "a": "【岸信介】内閣は安保条約を改定し、アメリカの日本防衛義務などを明記した。戦争に巻き込まれるとの不安から大規模な【安保闘争】が起こり、条約の発効後に岸内閣は総辞職した。後継の【池田勇人】内閣は「【所得倍増】」を掲げて経済成長を重視した。"},
  {"id": "jhx201", "s": "jh", "lv": 3, "topic": "高度経済成長の要因", "q": "1950年代半ばから約20年間、日本が高度経済成長を続けられた要因を多面的に説明せよ。", "a": "民間企業の活発な【設備投資】と技術革新が進み、安価な輸入【石油】がエネルギー源となった。農村から都市へ若い労働力が豊富に供給され、高い貯蓄率が投資を支えた。政府も【国民所得倍増計画】で成長を後押しし、1ドル＝360円の【固定相場制】も輸出に有利に働いた。"},
  {"id": "jhx202", "s": "jh", "lv": 2, "topic": "エネルギー革命", "q": "1950年代後半から進んだエネルギー革命とは何か。それが社会に与えた影響とともに説明せよ。", "a": "エネルギー源の中心が【石炭】から【石油】へと移った変化をエネルギー革命という。各地の炭鉱は閉山が進み、1960年には大量解雇に反対する【三井三池争議】が起きるなど、炭鉱地域は大きな打撃を受けた。"},
  {"id": "jhx203", "s": "jh", "lv": 2, "topic": "日韓・日中の国交", "q": "日本は、韓国および中華人民共和国とどのようにして国交を結んだか説明せよ。", "a": "1965年、【佐藤栄作】内閣は【日韓基本条約】を結び、韓国政府を朝鮮にある唯一の合法的な政府と認めた。1972年には【田中角栄】首相が訪中して【日中共同声明】を発表し、中国との国交を正常化した。"},
  {"id": "jhx204", "s": "jh", "lv": 1, "topic": "沖縄返還", "q": "沖縄はどのようにして日本に返還されたか。返還後に残った課題とともに説明せよ。", "a": "沖縄は平和条約後もアメリカの施政下にあったが、祖国復帰運動が高まり、1972年に【佐藤栄作】内閣のもとで返還された。政府は【非核三原則】を掲げたが、返還後も沖縄には多くの【アメリカ軍基地】が残された。"},
  {"id": "jhx205", "s": "jh", "lv": 1, "topic": "石油危機", "q": "1973年の石油危機は、日本経済にどのような影響を与えたか説明せよ。", "a": "【第4次中東戦争】をきっかけに原油価格が高騰し、【第1次石油危機】が起きた。日本では「【狂乱物価】」とよばれる激しいインフレが起き、1974年には戦後初のマイナス成長となって【高度経済成長】は終わった。"},
  {"id": "jhx206", "s": "jh", "lv": 1, "topic": "高度成長期の暮らし", "q": "高度経済成長期に、人々の暮らしや地域社会はどのように変化したか説明せよ。", "a": "白黒テレビ・電気洗濯機・電気冷蔵庫の【三種の神器】が普及し、のちにはカラーテレビ・自動車・クーラーの【3C】が広まった。農村から都市へ人口が移動し、農村の【過疎】と都市の【過密】が問題となった。"},
  {"id": "jhx207", "s": "jh", "lv": 2, "topic": "バブル経済", "q": "1980年代後半のバブル経済が発生した理由と、その崩壊後の影響を説明せよ。", "a": "1985年の【プラザ合意】後の円高不況に対し、日本銀行は低金利政策をとった。余った資金が株式や土地に流れて株価・地価が急騰し、【バブル経済】となった。1990年代初めに崩壊すると、【不良債権】を抱えた金融機関の経営が悪化し、長い不況が続いた。"},
  {"id": "jhx208", "s": "jh", "lv": 3, "topic": "55年体制の崩壊", "q": "1993年に55年体制が崩壊した背景と、その後の政治制度の変化を説明せよ。", "a": "【リクルート事件】や佐川急便事件など汚職事件が相次ぎ、政治不信が高まった。1993年の総選挙で自民党が過半数を割り、【細川護熙】を首相とする非自民の連立内閣が成立して【55年体制】は崩壊した。細川内閣のもとで衆議院に【小選挙区比例代表並立制】が導入された。"},
  {"id": "jhx209", "s": "jh", "lv": 3, "topic": "冷戦後の国際貢献", "q": "冷戦終結後、日本の国際貢献のあり方が問われたのはなぜか。自衛隊の海外派遣とあわせて説明せよ。", "a": "1991年の【湾岸戦争】で日本は多額の資金を拠出したが、人的な貢献がないとして国際的に十分評価されなかった。そのため1992年に【PKO協力法】が成立し、自衛隊が国連の平和維持活動として【カンボジア】に派遣された。"},
  {"id": "whx1", "s": "wh", "lv": 1, "topic": "ハンムラビ法典", "q": "バビロン第1王朝のハンムラビ王が制定した法典の特徴を述べよ。", "a": "メソポタミアを統一した【ハンムラビ王】が制定した。「目には目を、歯には歯を」の【同害復讐】を原則としながら、被害者や加害者の【身分】によって刑罰に差をつけた。"},
  {"id": "whx2", "s": "wh", "lv": 1, "topic": "古代エジプトの王権", "q": "古代エジプトのファラオは、どのような存在として国を支配したか。", "a": "ファラオは太陽神【ラー】の子とされ、生ける神として【神権政治】をおこなった。【ナイル川】の治水と農業を管理する強大な権力をもち、古王国時代には巨大な【ピラミッド】を建設させた。"},
  {"id": "whx3", "s": "wh", "lv": 2, "topic": "アケメネス朝の統治", "q": "アケメネス朝ペルシアは、多様な民族が住む広大な領土をどのように統治したか。", "a": "全国を州に分けて知事【サトラップ】をおき、「王の目」「王の耳」とよばれる監察官に監視させた。幹線道路【王の道】と駅伝制で交通を整え、服属民の宗教や慣習には【寛容】な政策をとった。"},
  {"id": "whx4", "s": "wh", "lv": 2, "topic": "フェニキア人", "q": "フェニキア人の活動は、地中海世界にどのような影響を与えたか。", "a": "【シドン】や【ティルス】を拠点に地中海交易で活躍し、北アフリカに【カルタゴ】などの植民市を建設した。彼らの表音文字はギリシア人に伝わり、【アルファベット】の起源となった。"},
  {"id": "whx5", "s": "wh", "lv": 1, "topic": "ユダヤ教", "q": "ヘブライ人のユダヤ教は、どのような特徴をもつ宗教として成立したか。", "a": "【バビロン捕囚】などの苦難のなかで、唯一神【ヤハウェ】を信じる【一神教】として確立した。自分たちだけが神に救われるとする【選民思想】や、救世主（メシア）を待望する信仰をもった。"},
  {"id": "whx6", "s": "wh", "lv": 1, "topic": "ポリス", "q": "古代ギリシアのポリスとはどのような共同体か、その特徴を述べよ。", "a": "有力者を中心に人々が【集住】して成立した都市国家で、城山の【アクロポリス】と広場の【アゴラ】を中心とした。ポリスは互いに独立していたが、同一民族として【ヘレネス】という意識をもった。"},
  {"id": "whx7", "s": "wh", "lv": 1, "topic": "アテネ民主政", "q": "ペルシア戦争後、ペリクレス時代のアテネで完成した民主政の特徴を述べよ。", "a": "【ペリクレス】の時代に完成し、成年男子市民が【民会】で国政を決める【直接民主政】がおこなわれた。一方で、女性・【奴隷】・在留外人には参政権がなかった。"},
  {"id": "whx8", "s": "wh", "lv": 2, "topic": "民主政の発展", "q": "アテネで平民の発言力が高まり、民主政が発展した背景を述べよ。", "a": "交易で富を得た平民が武具を自弁して【重装歩兵】となり、国防の主力となって発言力を強めた。【ソロンの改革】や【クレイステネスの改革】を経て、【サラミスの海戦】では無産市民も軍船の漕ぎ手として活躍し、民主政が完成に向かった。"},
  {"id": "whx9", "s": "wh", "lv": 2, "topic": "ペロポネソス戦争", "q": "ペロポネソス戦争は、ギリシア世界にどのような結果をもたらしたか。", "a": "【デロス同盟】を率いるアテネと、【ペロポネソス同盟】を率いるスパルタが争い、スパルタが勝利した。その後もポリス間の抗争が続いてポリス社会は衰え、北方の【マケドニア】に支配された。"},
  {"id": "whx10", "s": "wh", "lv": 2, "topic": "ヘレニズム文化", "q": "アレクサンドロス大王の遠征後に生まれたヘレニズム文化の特徴を述べよ。", "a": "【アレクサンドロス大王】の東方遠征後、ギリシア文化がオリエントに広まって生まれた文化。ポリスの枠をこえた【世界市民主義】（コスモポリタニズム）が特徴で、エジプトの【アレクサンドリア】が学術の中心となった。"},
  {"id": "whx11", "s": "wh", "lv": 1, "topic": "スパルタ", "q": "ギリシアのポリスであるスパルタは、どのような体制で国家を維持したか。", "a": "少数の市民が多数の隷属農民【ヘイロータイ】を支配したため、反乱に備えて市民に厳しい軍事訓練を課す【軍国主義】をとった。この体制は【リュクルゴスの制】とよばれ、他国との交流を制限する【鎖国】政策をとった。"},
  {"id": "whx12", "s": "wh", "lv": 1, "topic": "ローマの身分闘争", "q": "共和政ローマで、平民が政治的権利を拡大していった過程を述べよ。", "a": "重装歩兵として国防を担った平民は貴族に対抗し、【護民官】と平民会が設けられた。【十二表法】で慣習法が成文化され、前287年の【ホルテンシウス法】で平民会の議決が国法とされ、平民と貴族は法的に平等となった。"},
  {"id": "whx13", "s": "wh", "lv": 2, "topic": "共和政の動揺", "q": "ポエニ戦争後のローマで、共和政が動揺した理由を社会の変化から述べよ。", "a": "属州から安い穀物が流入し、長期の従軍で疲弊した【中小農民】が没落した。富裕層は奴隷を使う大土地所有【ラティフンディア】を広げた。農民の再建をめざす【グラックス兄弟】の改革は失敗し、【内乱の一世紀】に入った。"},
  {"id": "whx14", "s": "wh", "lv": 1, "topic": "キリスト教の公認", "q": "ローマ帝国でキリスト教が迫害から公認、国教化へと至った過程を述べよ。", "a": "当初は皇帝崇拝を拒んだため迫害されたが、信者は増え続けた。【コンスタンティヌス帝】が313年の【ミラノ勅令】でキリスト教を公認し、392年には【テオドシウス帝】が国教とし、他の宗教を禁止した。"},
  {"id": "whx15", "s": "wh", "lv": 2, "topic": "3世紀の危機", "q": "3世紀のローマ帝国はどのような危機にみまわれ、どのように再建されたか。", "a": "各地の軍団が皇帝を擁立する【軍人皇帝】時代となり、異民族の侵入も重なって帝国は混乱した。【ディオクレティアヌス帝】は皇帝を神格化する【専制君主政】（ドミナトゥス）を始め、帝国を四分統治して秩序を回復した。"},
  {"id": "whx16", "s": "wh", "lv": 2, "topic": "コロナトゥス", "q": "ローマ帝政後期に広がったコロナトゥスとは、どのような生産体制か。", "a": "征服戦争が終わって【奴隷】の供給が減ると、【ラティフンディア】にかわり、没落農民などを小作人の【コロヌス】として使う体制が広がった。コロヌスはやがて土地に縛られ、中世の【農奴】の先駆けとなった。"},
  {"id": "whx17", "s": "wh", "lv": 3, "topic": "ギリシアとローマの市民権", "q": "古代アテネとローマの市民権のあり方を比較し、それが国家の発展に与えた影響を論ぜよ。", "a": "アテネは市民権を【血統】によって厳しく限定し、閉鎖的だった。ローマは征服した都市を【分割統治】しつつ段階的に市民権を与え、【同盟市戦争】を経てイタリア全域に拡大し、212年には【カラカラ帝】が帝国の全自由民に市民権を与え、広大な帝国の統合を支えた。"},
  {"id": "whx18", "s": "wh", "lv": 3, "topic": "ローマ法", "q": "ローマ法はどのように発展し、それが後世にどのような影響を与えたかを述べよ。", "a": "当初はローマ市民にのみ適用される【市民法】だったが、帝国の拡大にともない、あらゆる民族に適用される【万民法】へと発展した。6世紀に【ユスティニアヌス帝】が【ローマ法大全】に集大成し、近代ヨーロッパの法体系の基礎となった。"},
  {"id": "whx19", "s": "wh", "lv": 1, "topic": "ゲルマン人の大移動", "q": "ゲルマン人の大移動はどのように始まり、どのような結果をもたらしたか。", "a": "4世紀後半、アジア系の【フン人】に圧迫された【西ゴート人】がローマ帝国領内に移動したことで始まった。この混乱のなかで【西ローマ帝国】は476年に滅亡し、各地にゲルマン人の国家が建てられた。"},
  {"id": "whx20", "s": "wh", "lv": 3, "topic": "アッシリアとアケメネス朝", "q": "オリエントを統一したアッシリアとアケメネス朝の支配のあり方の違いを論ぜよ。", "a": "アッシリアは鉄製武器と戦車で征服し、服属民の【強制移住】や重税をともなう【武断的な支配】をおこなったため、反乱を招いて短期間で崩壊した。アケメネス朝は【サトラップ】による州制度で統治しつつ、服属民の宗教や慣習に【寛容】で、約200年にわたり広大な領域を維持した。"},
  {"id": "whx21", "s": "wh", "lv": 1, "topic": "インダス文明", "q": "インダス川流域に栄えたインダス文明の特徴を、都市と文字に触れて述べよ。", "a": "前2600年ごろからインダス川流域に栄えた青銅器文明で、【モエンジョ=ダーロ】や【ハラッパー】などの計画的な都市を築いた。都市には排水設備や沐浴場が整えられていた。印章に刻まれた【インダス文字】は未解読である。"},
  {"id": "whx22", "s": "wh", "lv": 1, "topic": "ヴァルナ制", "q": "アーリヤ人の社会で形成されたヴァルナ制とは、どのような身分制度か。", "a": "司祭の【バラモン】を最上位に、武士の【クシャトリヤ】、庶民のヴァイシャ、隷属民の【シュードラ】の4つの身分に分ける制度。のちに世襲の職業集団【ジャーティ】と結びつき、【カースト制度】が形成された。"},
  {"id": "whx23", "s": "wh", "lv": 1, "topic": "仏教の成立", "q": "古代インドで、仏教はどのような背景のもとで成立し、何を説いたか。", "a": "前6世紀ごろ、バラモンの権威や祭式主義への批判が高まるなかで、【ガウタマ=シッダールタ】が開いた。ヴァルナによる差別を否定し、【八正道】の実践による【解脱】を説き、【クシャトリヤ】や商人から支持された。"},
  {"id": "whx24", "s": "wh", "lv": 2, "topic": "アショーカ王", "q": "マウリヤ朝のアショーカ王は、どのような理念にもとづいて統治をおこなったか。", "a": "【カリンガ】征服の悲惨さを反省し、倫理である【ダルマ】（法）による政治を理想とした。【仏教】を保護して【仏典結集】をおこない、各地に詔勅を刻んだ石柱碑や磨崖碑を建てた。"},
  {"id": "whx25", "s": "wh", "lv": 2, "topic": "ガンダーラ美術", "q": "クシャーナ朝の時代に栄えた仏教と仏教美術の特徴について述べよ。", "a": "【カニシカ王】の保護のもと、菩薩信仰により広く人々の救済をめざす【大乗仏教】が広まった。ヘレニズム文化の影響を受けた【ガンダーラ美術】で仏像が作られ、仏教は中央アジアを経て東アジアへ伝わった。"},
  {"id": "whx26", "s": "wh", "lv": 2, "topic": "グプタ朝の文化", "q": "グプタ朝の時代に、インド古典文化が成立したことについて述べよ。", "a": "バラモン教に民間信仰が融合した【ヒンドゥー教】が定着し、【マヌ法典】が完成した。【サンスクリット語】が公用語化され、カーリダーサの『シャクンタラー』などの文学が栄えた。数学では【ゼロの概念】が生まれた。"},
  {"id": "whx27", "s": "wh", "lv": 1, "topic": "周の封建制", "q": "周王朝がおこなった封建制とは、どのような仕組みの統治制度か。", "a": "周王が一族や功臣に【封土】を与えて【諸侯】とし、諸侯は王に貢納と軍役の義務を負った。この主従関係は、父系の血縁集団の規範である【宗法】によって支えられた。"},
  {"id": "whx28", "s": "wh", "lv": 1, "topic": "諸子百家", "q": "春秋・戦国時代に諸子百家が登場した背景と、その主な思想を述べよ。", "a": "【鉄製農具】の普及で生産力が高まり、諸侯が富国強兵のため有能な人材を求めた。こうしたなかで、仁と礼を説く【儒家】、法による統治を説く【法家】、無為自然を説く【道家】など多様な思想家が活躍した。"},
  {"id": "whx29", "s": "wh", "lv": 1, "topic": "始皇帝の統一政策", "q": "中国を統一した秦の始皇帝がおこなった、主な統一政策を述べよ。", "a": "全国に【郡県制】をしいて中央集権化を進め、【貨幣】・度量衡・文字を統一した。【焚書・坑儒】で思想統制をおこない、北方の匈奴に備えて【万里の長城】を修築した。"},
  {"id": "whx30", "s": "wh", "lv": 2, "topic": "郡国制", "q": "前漢の高祖（劉邦）が採用した郡国制とは、どのような統治制度か。", "a": "秦の急激な中央集権化の失敗をふまえ、都の周辺には【郡県制】をしき、地方には一族や功臣を王とする【封建制】を併用した。景帝が【呉楚七国の乱】を鎮圧したことで、実質的に中央集権化が進んだ。"},
  {"id": "whx31", "s": "wh", "lv": 2, "topic": "武帝の政策", "q": "前漢の武帝の対外政策と、それにともなう財政政策について述べよ。", "a": "【匈奴】を攻撃して西域へ進出し、朝鮮やベトナム北部にも郡をおいた。遠征で財政が悪化したため、【塩・鉄・酒の専売】や、物価を調整する【均輸・平準】をおこなった。"},
  {"id": "whx32", "s": "wh", "lv": 2, "topic": "儒学の官学化", "q": "漢代に儒学が国家の学問となった経緯と、それが政治や社会に与えた影響を述べよ。", "a": "武帝は【董仲舒】の献策で【五経博士】をおき、儒学を官学とした。官吏登用法の【郷挙里選】により地方の【豪族】が官界に進出した。後漢では経典の字句を解釈する【訓詁学】が発達した。"},
  {"id": "whx33", "s": "wh", "lv": 3, "topic": "漢とローマの交流", "q": "前2世紀から後2世紀のユーラシア東西交流について、漢とローマの関係に触れて述べよ。", "a": "武帝が【張騫】を大月氏に派遣して西域の事情が知られ、オアシス都市を結ぶ【シルク=ロード】が開けた。後漢の【班超】は西域を経営し、部下を大秦（ローマ）に派遣した。166年には【大秦王安敦】の使者を称する者が海路で日南郡に至った。"},
  {"id": "whx34", "s": "wh", "lv": 3, "topic": "九品中正", "q": "魏で始まった官吏登用法の九品中正が、魏晋南北朝時代の社会に与えた影響を論ぜよ。", "a": "【九品中正】は地方の中正官が人材を九等に評価して推薦する制度だが、実際には有力【豪族】の子弟が高く評価され、「上品に寒門なく、下品に勢族なし」といわれた。官職を独占する【門閥貴族】が形成され、【貴族制社会】が成立した。"},
  {"id": "whx35", "s": "wh", "lv": 1, "topic": "均田制", "q": "北魏の孝文帝が実施した均田制の目的と、その後の展開を述べよ。", "a": "戦乱で荒れた土地を農民に分け与えて耕作させ、【税収】を確保することを目的とした。成人男子のほか、妻や【奴婢】・耕牛にも土地を支給した。隋・唐に受け継がれ、【租調庸制】や【府兵制】の基盤となった。"},
  {"id": "whx36", "s": "wh", "lv": 2, "topic": "孝文帝の漢化政策", "q": "北魏の孝文帝がおこなった漢化政策の内容と、それがもたらした結果を述べよ。", "a": "都を平城から【洛陽】に移し、鮮卑の服装や言語を禁止するなど【漢化政策】を進めた。しかし、これに反発した北辺の軍人たちが【六鎮の乱】を起こし、北魏は東西に分裂した。"},
  {"id": "whx37", "s": "wh", "lv": 1, "topic": "中国への仏教伝来", "q": "魏晋南北朝時代に、仏教が中国に広まった過程を主な人物に触れて述べよ。", "a": "西域から来た【仏図澄】や【鳩摩羅什】が布教や仏典の翻訳をおこない、東晋の【法顕】はインドへ赴いて仏典を持ち帰った。北魏では【雲崗】や竜門に石窟寺院が造営された。"},
  {"id": "whx38", "s": "wh", "lv": 2, "topic": "江南の開発", "q": "魏晋南北朝時代に、長江下流域の江南で開発が進んだ理由を述べよ。", "a": "華北の戦乱を避けて多くの漢人が【江南】に移住し、【東晋】や南朝の諸王朝のもとで開発が進んだ。貴族を担い手とする優雅な【六朝文化】が栄え、のちに【経済の中心】が南に移る基礎となった。"},
  {"id": "whx39", "s": "wh", "lv": 3, "topic": "古代地中海の奴隷制", "q": "古代地中海世界で奴隷が果たした役割を、アテネとローマを対比して論ぜよ。", "a": "アテネでは【債務奴隷】が禁止されたのち、戦争捕虜や購入した奴隷が家内労働や鉱山で働き、市民が政治に参加する余裕を支えた。ローマではポエニ戦争以降、大量の捕虜奴隷が【ラティフンディア】で使役され、【スパルタクスの反乱】のような大反乱も起きた。"},
  {"id": "whx40", "s": "wh", "lv": 3, "topic": "東西ローマの命運", "q": "西ローマ帝国が早くに滅亡した一方、東ローマ帝国が長く存続した理由を論ぜよ。", "a": "西方では都市が衰え、【コロナトゥス】による自給的な経済が広がり、【ゲルマン人】の侵入に抵抗できなかった。東方は【コンスタンティノープル】を中心に商業と【貨幣経済】が維持され、強固な【官僚制】と皇帝権のもとで1000年以上存続した。"},
  {"id": "whx41", "s": "wh", "lv": 1, "topic": "科挙の創設", "q": "隋で始まった科挙は、それまでの官吏登用法と比べてどのような特徴をもっていたか。", "a": "九品中正にかわり、【隋】の文帝が【学科試験】によって広く人材を登用する制度として始めた。家柄によらず能力で官僚を選ぶ点が特徴で、宋代には皇帝みずからが試験官となる【殿試】が加わり、【皇帝】の権力を支える制度となった。"},
  {"id": "whx42", "s": "wh", "lv": 1, "topic": "唐の律令体制", "q": "唐が整えた律令体制とは、どのような仕組みで国家を運営する体制か。", "a": "刑法の【律】と行政法の【令】にもとづく統治体制。中央に【三省・六部】をおき、土地制度の【均田制】、税制の【租調庸制】、兵制の府兵制を組み合わせて運営された。"},
  {"id": "whx43", "s": "wh", "lv": 2, "topic": "両税法", "q": "唐の後半に両税法が施行された背景と、その課税の仕組みを述べよ。", "a": "均田制がくずれて農民の逃亡が増え、【租調庸制】が維持できなくなった。780年、宰相楊炎の献策で【両税法】が施行され、実際に所有する土地や資産に応じて【夏と秋の2回】課税した。これは【大土地所有】を事実上認める転換となった。"},
  {"id": "whx44", "s": "wh", "lv": 1, "topic": "安史の乱", "q": "8世紀半ばにおこった安史の乱は、唐の政治と社会にどのような影響を与えたか。", "a": "755年に【節度使】の安禄山らが起こした反乱で、唐はウイグルの援助を得て鎮圧した。乱後は節度使が地方で自立して【藩鎮】となり、中央の統制が弱まった。財政難を補うため【塩の専売】が強化された。"},
  {"id": "whx45", "s": "wh", "lv": 2, "topic": "国際都市長安", "q": "唐の都長安が国際都市として栄えた理由と、その文化の特徴を述べよ。", "a": "唐は周辺諸国と【冊封】関係を結び、【シルク=ロード】や海路を通じて各地から商人や留学生が集まった。長安には【ゾロアスター教】やネストリウス派キリスト教、マニ教の寺院が建てられ、国際色豊かな【貴族文化】が栄えた。"},
  {"id": "whx46", "s": "wh", "lv": 1, "topic": "宋の文治主義", "q": "宋の太祖（趙匡胤）が採用した文治主義とは、どのような政策か。", "a": "五代の武人政治の弊害をふまえ、【節度使】の権限を弱めて文官を重視した。【科挙】を整備して【殿試】を設け、皇帝による【君主独裁体制】を確立した。一方で軍事力が弱まり、北方民族の圧迫を受けた。"},
  {"id": "whx47", "s": "wh", "lv": 2, "topic": "王安石の新法", "q": "北宋の王安石がおこなった新法の目的と、その主な内容を述べよ。", "a": "財政難と軍事力の低下を克服する【富国強兵】を目的とした。中小農民に低利で資金を貸す【青苗法】、中小商人を助ける【市易法】、農閑期に農民を訓練する【保甲法】などを実施したが、【旧法党】の反対で激しい党争を招いた。"},
  {"id": "whx48", "s": "wh", "lv": 1, "topic": "宋代の経済発展", "q": "宋代の中国で経済が大きく発展したことについて、農業と商業の面から述べよ。", "a": "江南ではひでりに強い【占城稲】の導入などで稲作が発展し、「蘇湖熟すれば天下足る」といわれた。商業では草市や鎮などの商業都市が成長し、紙幣の【交子】が使われた。商人の同業組合【行】や手工業者の【作】も結成された。"},
  {"id": "whx49", "s": "wh", "lv": 2, "topic": "士大夫", "q": "宋代に新たな支配層となった士大夫とは、どのような人々か説明せよ。", "a": "唐末五代に門閥貴族が没落したのち、新興地主層の【形勢戸】が台頭した。彼らは【科挙】に合格して官僚となり、儒学的教養を身につけた【士大夫】として政治と文化を担った。官僚を出した家は【官戸】として特権を得た。"},
  {"id": "whx50", "s": "wh", "lv": 2, "topic": "朱子学", "q": "南宋の朱熹が大成した朱子学の特徴と、その後の東アジアへの影響を述べよ。", "a": "宇宙の原理である【理】と、万物を構成する【気】によって世界を説明し、君臣・華夷の区別を重んじる【大義名分論】を説いた。四書を重視し、明代には科挙の基準とされ、朝鮮や日本でも【官学】として受容された。"},
  {"id": "whx51", "s": "wh", "lv": 1, "topic": "宋と北方民族", "q": "北宋・南宋と北方民族の国家との関係について、遼と金を中心に述べよ。", "a": "北宋は契丹の【遼】と【澶淵の盟】を結び、毎年銀や絹を贈った。のち女真の【金】と結んで遼を滅ぼしたが、金に都の開封を攻略される【靖康の変】で滅亡した。江南に逃れた南宋は金に臣下の礼をとった。"},
  {"id": "whx52", "s": "wh", "lv": 3, "topic": "征服王朝の統治", "q": "遼と金が中国の農耕地帯を支配する際に用いた統治体制の特徴を論ぜよ。", "a": "遼は遊牧民を部族制で、農耕民を州県制で治める【二重統治体制】をとり、【契丹文字】を作って民族の独自性を保った。金も女真人を軍事・行政組織の【猛安・謀克】で、漢人を州県制で治めた。両国とも漢文化を受容しつつ、固有の文化と体制を維持しようとした。"},
  {"id": "whx53", "s": "wh", "lv": 2, "topic": "元の中国支配", "q": "元が中国を支配する際にとった統治の特徴を、民族の扱いに触れて述べよ。", "a": "要職はモンゴル人が独占し、中央アジア・西アジア出身の【色目人】が財務官僚として重用された。旧金領の住民は【漢人】、旧南宋の住民は【南人】とよばれた。【科挙】は一時停止され、儒学的教養をもつ士大夫は政治の中枢から遠ざけられた。"},
  {"id": "whx54", "s": "wh", "lv": 1, "topic": "元の滅亡", "q": "中国を支配した元が、14世紀に衰退して北方へ退いた理由を述べよ。", "a": "帝位争いが続き、チベット仏教への過剰な保護で財政が悪化した。不足を補うため紙幣の【交鈔】を乱発して物価が高騰し、民衆が困窮した。白蓮教徒を中心とする【紅巾の乱】がおこり、【朱元璋】が明を建てると、元は北方へ退いた。"},
  {"id": "whx55", "s": "wh", "lv": 1, "topic": "洪武帝の政策", "q": "明の洪武帝が皇帝独裁と農村支配を強化するためにおこなった政策を述べよ。", "a": "【中書省】を廃止して六部を皇帝直属とし、【皇帝独裁】を強化した。農村には【里甲制】をしき、租税台帳の【賦役黄冊】と土地台帳の【魚鱗図冊】を作成した。民衆教化のため六諭も定めた。"},
  {"id": "whx56", "s": "wh", "lv": 1, "topic": "鄭和の南海遠征", "q": "明の永楽帝が鄭和に命じた南海遠征の目的と、その影響を述べよ。", "a": "【永楽帝】はイスラーム教徒の宦官【鄭和】に大艦隊を率いさせ、東南アジアからアフリカ東岸まで派遣した。諸国に【朝貢】をうながし、明を中心とする国際秩序を広げることが目的だった。遠征の拠点となった【マラッカ】は中継港として発展した。"},
  {"id": "whx57", "s": "wh", "lv": 2, "topic": "明の海禁", "q": "明がおこなった海禁政策とはどのようなものか、その目的と結果を述べよ。", "a": "民間人の海外渡航や交易を禁止し、貿易を国家間の【朝貢貿易】に限定した政策。【倭寇】の取り締まりと国家による貿易独占が目的だった。しかし密貿易はやまず、16世紀に【後期倭寇】が活発化したため、明は【海禁】を緩和した。"},
  {"id": "whx58", "s": "wh", "lv": 2, "topic": "北虜南倭", "q": "16世紀の明を苦しめた「北虜南倭」とは何か、その影響とともに説明せよ。", "a": "北方では【モンゴル】の【アルタン=ハーン】が侵入をくり返し、北京を包囲した。南方の沿岸では中国人を主体とする【倭寇】が密貿易や略奪をおこなった。これらへの防衛費が明の【財政】を圧迫した。"},
  {"id": "whx59", "s": "wh", "lv": 1, "topic": "明清交替", "q": "17世紀前半に明が滅亡し、清が中国支配を始めた経緯を述べよ。", "a": "豊臣秀吉の朝鮮出兵への援軍や女真との戦いで財政が悪化し、重税で民衆が困窮した。1644年、【李自成の乱】で北京が陥落し明は滅亡した。山海関を守っていた【呉三桂】が清に降り、【清】が北京に入って中国支配を始めた。"},
  {"id": "whx60", "s": "wh", "lv": 1, "topic": "清の漢人統治", "q": "清が漢人を支配するために用いた懐柔策と威圧策について述べよ。", "a": "懐柔策として、要職に満洲人と漢人を同数任命する【満漢併用制】をとり、『四庫全書』などの大編纂事業で知識人を優遇した。威圧策として、満洲人の髪型である【辮髪】を強制し、【文字の獄】や禁書で反清思想を弾圧した。"},
  {"id": "whx61", "s": "wh", "lv": 2, "topic": "康熙帝", "q": "清の康熙帝が支配を安定させるためにおこなった内政・外交の政策を述べよ。", "a": "漢人武将が南方で起こした【三藩の乱】を鎮圧し、【鄭氏台湾】を降して中国全土を平定した。北方ではロシアと【ネルチンスク条約】を結んで国境を定め、通商を認めた。"},
  {"id": "whx62", "s": "wh", "lv": 2, "topic": "地丁銀制", "q": "清代に実施された地丁銀制とは、どのような税制か、その影響とともに述べよ。", "a": "明の一条鞭法を受けつぎ、【人頭税】（丁税）を【土地税】（地税）にくりこんで一本化した税制。康熙帝が丁税額を固定したのち、【雍正帝】の時代に全国に広まった。人頭税が事実上廃止され、【人口】の急増を後押しした。"},
  {"id": "whx63", "s": "wh", "lv": 3, "topic": "清の藩部統治", "q": "清はモンゴル・チベット・新疆などの地域をどのように統治したかを論ぜよ。", "a": "これらの地域を【藩部】とし、【理藩院】に管轄させた。現地の有力者に自治を認め、モンゴルの王侯やチベット仏教の権威を利用する間接統治をおこなった。清の皇帝はモンゴルに対しては遊牧君主の【ハーン】として、チベットに対しては仏教の保護者としてふるまった。"},
  {"id": "whx64", "s": "wh", "lv": 1, "topic": "新羅の統一", "q": "7世紀に朝鮮半島を統一した新羅について、統一の過程と社会の特徴を述べよ。", "a": "新羅は唐と結んで【百済】と【高句麗】を滅ぼし、その後唐の勢力を排除して半島を統一した。唐の律令制を取り入れる一方、血統による厳格な身分制度である【骨品制】が社会を支え、都の慶州では【仏教】文化が栄えた。"},
  {"id": "whx65", "s": "wh", "lv": 2, "topic": "高麗の文化", "q": "10世紀に朝鮮半島で成立した高麗の時代に生まれた文化について述べよ。", "a": "仏教が国家の保護を受け、モンゴルの侵入からの加護を願って【高麗版大蔵経】が刊行された。世界最古級の【金属活字】も作られ、宋の影響を受けた【高麗青磁】が名品として知られた。"},
  {"id": "whx66", "s": "wh", "lv": 1, "topic": "朝鮮王朝", "q": "14世紀末に朝鮮半島で成立した朝鮮王朝の政治と文化について述べよ。", "a": "倭寇の撃退で名声を得た【李成桂】が建てた。【朱子学】を官学とし、科挙で官僚を選んだが、官僚を輩出した【両班】が特権身分となった。15世紀に世宗は表音文字の【訓民正音】（ハングル）を制定した。"},
  {"id": "whx67", "s": "wh", "lv": 2, "topic": "突厥とウイグル", "q": "6〜9世紀にモンゴル高原で活躍した突厥とウイグルについて述べよ。", "a": "【突厥】は6世紀に柔然を倒して強大化し、独自の【突厥文字】を作った。8世紀には【ウイグル】が台頭し、【安史の乱】で唐を援助した。ウイグルはソグド人と結びつき、【マニ教】を信仰した。"},
  {"id": "whx68", "s": "wh", "lv": 2, "topic": "ソグド人", "q": "ソグド人が内陸アジアの東西交流において果たした役割を述べよ。", "a": "中央アジアの【サマルカンド】などのオアシス都市を拠点に、【シルク=ロード】の交易で活躍したイラン系の民族。遊牧国家や唐と結びついて活動し、【ソグド文字】は【ウイグル文字】の起源となった。"},
  {"id": "whx69", "s": "wh", "lv": 3, "topic": "遊牧国家とオアシス都市", "q": "内陸アジアにおいて、遊牧国家とオアシス都市がどのような関係を結んでいたかを論ぜよ。", "a": "【遊牧国家】は騎馬軍事力でオアシス都市を保護・支配し、オアシス都市は【隊商交易】の利益や農産物を提供した。遊牧国家は中国王朝から絹などを【貢納】や交易で獲得し、オアシスの商人がそれを西方へ運んだ。両者は互いに依存する【共生関係】にあった。"},
  {"id": "whx70", "s": "wh", "lv": 3, "topic": "唐宋変革", "q": "唐から宋の時代に中国社会がどのように変わったのか、支配層と経済の変化から論ぜよ。", "a": "唐末の戦乱で【門閥貴族】が没落し、宋では【科挙】出身の官僚と新興地主の【形勢戸】が支配層となった。土地制度は均田制から小作人の【佃戸】を使う地主制に移り、商業では坊市制がくずれて【貨幣経済】が発展した。"},
  {"id": "whx71", "s": "wh", "lv": 3, "topic": "明清の貿易体制", "q": "明から清にかけて、中国の対外貿易体制がどのように変化したかを論ぜよ。", "a": "明初は【海禁】と【朝貢貿易】によって国家が貿易を独占したが、16世紀後半に海禁を緩めて民間貿易を許した。清は台湾の鄭氏を降すと海禁を解き、民間の【互市】を広く認めたが、18世紀半ばにはヨーロッパとの貿易を【広州】一港に限定した。"},
  {"id": "whx72", "s": "wh", "lv": 1, "topic": "宋代の文化", "q": "宋代の中国文化の特徴を、印刷などの技術と美術の面から述べよ。", "a": "【木版印刷】が普及して書物が広まり、【羅針盤】や【火薬】が実用化された。絵画では宮廷画家による院体画と、士大夫による【文人画】が描かれ、陶磁器では【青磁】や白磁が作られた。"},
  {"id": "whx73", "s": "wh", "lv": 1, "topic": "明代の文化", "q": "明代後期の中国文化の特徴を、儒学などの学問と庶民文化の面から述べよ。", "a": "【王守仁】（王陽明）は知識と実践の一致を説く【陽明学】をおこした。実用的な学問も重視され、『本草綱目』や『天工開物』が著された。庶民の間では『西遊記』『水滸伝』などの口語【小説】が広く読まれた。"},
  {"id": "whx74", "s": "wh", "lv": 2, "topic": "イエズス会宣教師", "q": "明末清初に中国で活動したイエズス会宣教師の役割と、その後の布教禁止について述べよ。", "a": "【マテオ=リッチ】は世界地図「坤輿万国全図」を作り、徐光啓と『幾何原本』を訳した。【アダム=シャール】らは暦の作成に関わった。のち布教方法をめぐる【典礼問題】がおこり、【雍正帝】はキリスト教の布教を禁止した。"},
  {"id": "whx75", "s": "wh", "lv": 2, "topic": "考証学", "q": "清代の中国で考証学が盛んになった背景と、その学風の特徴を述べよ。", "a": "明末清初の【顧炎武】らは、空論におちいった陽明学を批判し、経書を実証的に研究する学風をおこした。清の【文字の獄】による思想統制で政治的な議論が難しくなると、学者は古典の文献研究に向かい、【考証学】が隆盛した。"},
  {"id": "whx76", "s": "wh", "lv": 1, "topic": "隋の滅亡", "q": "南北朝を統一した隋が、わずか30年ほどで滅亡した理由を述べよ。", "a": "第2代の【煬帝】は【大運河】の建設などの大土木事業や、3度にわたる【高句麗遠征】をおこなった。重い負担に苦しむ民衆の反乱が各地でおこり、隋は統一から約30年で滅亡した。"},
  {"id": "whx77", "s": "wh", "lv": 2, "topic": "冊封体制", "q": "中国王朝が周辺諸国と結んだ冊封体制とは、どのような国際関係か。", "a": "中国皇帝が周辺諸国の君主に【官爵】を与えて君臣関係を結び、君主は皇帝に【朝貢】した。皇帝の徳が周辺に及ぶとする【中華思想】にもとづく秩序で、周辺国は権威の承認と【交易】の利益を得た。"},
  {"id": "whx78", "s": "wh", "lv": 1, "topic": "白蓮教徒の乱", "q": "18世紀末に清でおこった白蓮教徒の乱の背景と、その影響を述べよ。", "a": "18世紀の【人口】急増で耕地が不足し、山間部に移住した貧民が【白蓮教】を信仰して反乱をおこした。正規軍の【八旗】は役に立たず、【郷勇】とよばれる義勇軍によって鎮圧された。財政も悪化し、清の衰退が始まった。"},
  {"id": "whx79", "s": "wh", "lv": 3, "topic": "明清の江南経済", "q": "明代後期から清代にかけて、長江流域の経済構造がどのように変化したかを論ぜよ。", "a": "長江下流域では【綿織物】や【生糸】などの家内手工業が発達し、商品作物の栽培が広がった。そのため穀倉地帯は中流域に移り「【湖広熟すれば天下足る】」といわれた。【山西商人】や【徽州商人】など、遠隔地商業で富を得た商人が活躍した。"},
  {"id": "whx80", "s": "wh", "lv": 1, "topic": "イスラーム教の成立", "q": "7世紀にムハンマドが創始したイスラーム教の特徴と、その成立の過程を述べよ。", "a": "【メッカ】の商人ムハンマドが唯一神【アッラー】の啓示を受けたとして始めた。神の前での信者の平等を説き、偶像崇拝を厳しく禁じた。迫害を受けて622年にメディナへ移住した【ヒジュラ】（聖遷）がイスラーム暦の元年とされ、教えは聖典【コーラン】にまとめられた。"},
  {"id": "whx81", "s": "wh", "lv": 1, "topic": "正統カリフ時代", "q": "ムハンマドの死後、正統カリフ時代にイスラーム勢力がどのように拡大したかを述べよ。", "a": "信者の合意で選ばれた【カリフ】が共同体を指導した。【ジハード】（聖戦）による大征服でビザンツ帝国からシリアやエジプトを奪い、イランの【ササン朝】を滅ぼした。征服地の異教徒には人頭税の【ジズヤ】と地租の【ハラージュ】を課した。"},
  {"id": "whx82", "s": "wh", "lv": 2, "topic": "スンナ派とシーア派", "q": "イスラーム教のスンナ派とシーア派は、どのような点で考え方が異なるかを説明せよ。", "a": "【シーア派】は第4代正統カリフの【アリー】とその子孫だけを正統な指導者（イマーム）とする。一方、多数派の【スンナ派】は歴代カリフの権威を認め、ムハンマドの言行（スンナ）に従う共同体の合意を重視する。"},
  {"id": "whx83", "s": "wh", "lv": 2, "topic": "知恵の館と翻訳", "q": "アッバース朝の時代に学問が発達した理由と、それがヨーロッパに与えた影響を述べよ。", "a": "都【バグダード】の【知恵の館】でギリシア語文献がアラビア語に翻訳され、哲学・医学・天文学が発達した。【イブン=シーナー】の『医学典範』などは、のちに【ラテン語】に翻訳されて西欧に伝わり、【12世紀ルネサンス】をもたらした。"},
  {"id": "whx84", "s": "wh", "lv": 2, "topic": "3カリフの並立", "q": "10世紀のイスラーム世界で、3人のカリフが並び立った経緯を述べよ。", "a": "アッバース朝のカリフに対し、北アフリカに興ったシーア派の【ファーティマ朝】の君主がカリフを称し、イベリア半島の【後ウマイヤ朝】の君主もカリフを称した。さらに、バグダードはシーア派の【ブワイフ朝】に占領され、アッバース朝カリフの政治的権威は低下した。"},
  {"id": "whx85", "s": "wh", "lv": 2, "topic": "セルジューク朝", "q": "11世紀に成立したセルジューク朝が、イスラーム世界で果たした役割について述べよ。", "a": "トルコ系の【セルジューク朝】は1055年にバグダードに入り、カリフから【スルタン】の称号を得て政治権力を握った。アナトリアに進出してビザンツ帝国を圧迫し、これが【十字軍】のきっかけとなった。軍人に徴税権を与える【イクター制】を広く施行した。"},
  {"id": "whx86", "s": "wh", "lv": 3, "topic": "イクター制", "q": "イスラーム世界におけるイクター制の成立と、その特徴を西欧の封建制と比べて論ぜよ。", "a": "【ブワイフ朝】が軍人に俸給のかわりに土地の【徴税権】を与えたことで始まり、【セルジューク朝】が広く施行した。現金収入の不足に対応して軍事力を維持する制度だった。西欧の封建制と異なり、原則として【世襲】は認められず、国家による土地支配が維持された。"},
  {"id": "whx87", "s": "wh", "lv": 1, "topic": "オスマン帝国の拡大", "q": "オスマン帝国が14〜16世紀に勢力を拡大した過程を、主な君主に触れて述べよ。", "a": "バルカン半島へ進出し、1453年に【メフメト2世】が【コンスタンティノープル】を攻略してビザンツ帝国を滅ぼした。セリム1世はマムルーク朝を滅ぼして聖地を支配下におき、【スレイマン1世】の時代には【ウィーン】を包囲するなど最盛期を迎えた。"},
  {"id": "whx88", "s": "wh", "lv": 2, "topic": "オスマン帝国の統治", "q": "オスマン帝国は、多民族・多宗教の人々をどのように統治したかを述べよ。", "a": "キリスト教徒やユダヤ教徒の宗教共同体【ミッレト】に、納税と引きかえに自治を認めた。キリスト教徒の子弟を強制的に集める【デヴシルメ】で官僚や常備歩兵軍の【イェニチェリ】を養成し、騎士には【ティマール制】で徴税権を与えた。"},
  {"id": "whx89", "s": "wh", "lv": 2, "topic": "サファヴィー朝", "q": "16世紀初めにイランで成立したサファヴィー朝の特徴を述べよ。", "a": "神秘主義教団の長イスマーイールが建国し、【シーア派】を国教としてスンナ派のオスマン帝国と対立した。君主はイラン伝統の【シャー】の称号を用いた。【アッバース1世】は新都【イスファハーン】を建設し、「世界の半分」といわれるほど繁栄した。"},
  {"id": "whx90", "s": "wh", "lv": 1, "topic": "アクバルの統治", "q": "ムガル帝国のアクバルが、多数のヒンドゥー教徒を統治するためにおこなった政策を述べよ。", "a": "【アクバル】は非ムスリムに課される人頭税の【ジズヤ】を廃止し、ヒンドゥー教徒の【ラージプート】の王女と結婚するなど融和を図った。官僚の位階に応じて給与と保持すべき騎兵数を定める【マンサブダール制】で支配体制を整えた。"},
  {"id": "whx91", "s": "wh", "lv": 2, "topic": "アウラングゼーブ", "q": "ムガル帝国のアウラングゼーブ帝の宗教政策は、帝国にどのような影響を与えたか。", "a": "熱心なスンナ派ムスリムの【アウラングゼーブ】は、【ジズヤ】を復活させるなどヒンドゥー教徒を圧迫した。そのため【ラージプート】やデカン高原の【マラーター】、パンジャーブの【シク教徒】の反抗を招き、彼の死後、帝国は急速に衰退した。"},
  {"id": "whx92", "s": "wh", "lv": 2, "topic": "インド=イスラーム文化", "q": "ムガル帝国時代に生まれたインド=イスラーム文化の特徴を述べよ。", "a": "イスラーム文化とインドの文化が融合した文化。建築ではシャー=ジャハーンが造った【タージ=マハル】、絵画ではペルシアの影響を受けた【細密画】が発達した。言語では【ウルドゥー語】が生まれ、宗教ではナーナクが【シク教】を開いた。"},
  {"id": "whx93", "s": "wh", "lv": 1, "topic": "インドのイスラーム化", "q": "10世紀以降、北インドにイスラーム教が広まった過程を述べよ。", "a": "10世紀末から【ガズナ朝】や【ゴール朝】が北インドに侵入した。13世紀には【奴隷王朝】がデリーを都として成立し、以後の五王朝は【デリー=スルタン朝】とよばれた。神との合一をめざす【神秘主義】（スーフィズム）の聖者の活動で、民衆にも改宗が広まった。"},
  {"id": "whx94", "s": "wh", "lv": 3, "topic": "東南アジアのイスラーム化", "q": "13世紀以降、東南アジアの島嶼部にイスラーム教が広まった経緯を論ぜよ。", "a": "インド洋交易に従事する【ムスリム商人】の来航とともに、港市の支配者が改宗していった。15世紀には【マラッカ王国】が国王の改宗によってイスラーム化し、交易の拠点として布教の中心となった。その後、スマトラの【アチェ王国】やジャワの【マタラム王国】などのイスラーム国家が成立した。"},
  {"id": "whx95", "s": "wh", "lv": 1, "topic": "アンコール朝", "q": "9世紀以降カンボジアで栄えたアンコール朝の特徴を、建造物に触れて述べよ。", "a": "クメール人が建てた王朝で、インドから伝わった【ヒンドゥー教】や仏教の影響を受けた。12世紀にはヒンドゥー教寺院の【アンコール=ワット】が造営され、のちに仏教色の強い都城【アンコール=トム】も建てられた。"},
  {"id": "whx96", "s": "wh", "lv": 2, "topic": "シュリーヴィジャヤ", "q": "7世紀にスマトラ島を中心に栄えたシュリーヴィジャヤが繁栄した理由を述べよ。", "a": "【マラッカ海峡】を押さえる位置にあり、中国とインドを結ぶ【海上交易】の中継で栄えた【港市国家】である。唐の僧【義浄】がインドへの往復で滞在して記録を残したように、仏教が盛んだった。"},
  {"id": "whx97", "s": "wh", "lv": 2, "topic": "東南アジアのインド化", "q": "東南アジアの「インド化」とはどのような現象か、具体例を挙げて述べよ。", "a": "交易を通じて、インドから【ヒンドゥー教】や【仏教】、サンスクリット語、神聖な王権の観念などが受け入れられた現象。ジャワ島の【シャイレンドラ朝】は大乗仏教の寺院【ボロブドゥール】を建設した。"},
  {"id": "whx98", "s": "wh", "lv": 2, "topic": "ベトナムの諸王朝", "q": "中国の支配から独立したベトナムの諸王朝と、中国との関係について述べよ。", "a": "10世紀に独立し、11世紀に【李朝】が大越国を建てた。【陳朝】は元の侵攻を撃退し、漢字をもとに独自の文字【チュノム】（字喃）を作った。15世紀の【黎朝】は明の支配を退けたのち、明の制度を取り入れて中央集権化を進めた。"},
  {"id": "whx99", "s": "wh", "lv": 1, "topic": "上座部仏教の広がり", "q": "東南アジアの大陸部に、スリランカから上座部仏教が広まったことについて述べよ。", "a": "11世紀以降、ビルマの【パガン朝】やタイの【スコータイ朝】、のちの【アユタヤ朝】で、スリランカから伝わった【上座部仏教】が信仰された。上座部仏教は王権と結びつき、民衆の間にも定着した。"},
  {"id": "whx100", "s": "wh", "lv": 1, "topic": "西アフリカの諸王国", "q": "西アフリカのガーナ王国やマリ王国が繁栄した理由を、交易品に触れて述べよ。", "a": "サハラ砂漠をこえる【サハラ縦断交易】で、西アフリカの【金】と北方の【岩塩】を交換して栄えた。マリ王国の【マンサ=ムーサ】はメッカ巡礼で大量の金を使い、その富を広く知らせた。【トンブクトゥ】は交易と学問の中心となった。"},
  {"id": "whx101", "s": "wh", "lv": 2, "topic": "スワヒリ文化", "q": "東アフリカ沿岸の海港都市の繁栄と、そこで生まれた文化について述べよ。", "a": "【マリンディ】や【キルワ】などの海港都市が、【ムスリム商人】による【インド洋交易】で栄えた。現地のバントゥー系言語にアラビア語の語彙が加わった【スワヒリ語】が共通語として広まった。"},
  {"id": "whx102", "s": "wh", "lv": 2, "topic": "大ジンバブエ", "q": "アフリカ南部のジンバブエ高原で栄えた国家と、大ジンバブエ遺跡について述べよ。", "a": "ショナ人の国家が【金】や象牙の輸出で栄え、巨大な石造建築の【大ジンバブエ遺跡】を残した。遺跡からは【インド洋交易】を通じてもたらされた中国の陶磁器も出土している。15世紀以降は【モノモタパ王国】が栄えた。"},
  {"id": "whx103", "s": "wh", "lv": 3, "topic": "アフリカのイスラーム化", "q": "中世のアフリカで、イスラーム教が受容された経路と、その特徴を論ぜよ。", "a": "西アフリカでは【サハラ縦断交易】を通じてムスリム商人が来訪し、【マリ王国】や【ソンガイ王国】の支配層が改宗した。東アフリカ沿岸では【インド洋交易】を通じてイスラームが浸透し、【スワヒリ文化】が生まれた。いずれも交易を担う商人と、王権や都市の支配層を通じて広まった。"},
  {"id": "whx104", "s": "wh", "lv": 1, "topic": "カールの戴冠", "q": "カール大帝の戴冠は、ヨーロッパ史においてどのような意義をもつか述べよ。", "a": "800年、教皇【レオ3世】がフランク王【カール大帝】にローマ皇帝の冠を与えた。これにより【ローマ=カトリック教会】とゲルマン人の国家が結びつき、ビザンツ帝国から自立した【西ヨーロッパ世界】が成立した。"},
  {"id": "whx105", "s": "wh", "lv": 1, "topic": "封建的主従関係", "q": "中世西ヨーロッパの封建的主従関係とは、どのような関係かを説明せよ。", "a": "主君が家臣に【封土】を与えて保護し、家臣は主君に【軍事的奉仕】の義務を負う関係。双方が義務を負う【双務的契約】である点が特徴で、一人の家臣が複数の主君に仕えることもあった。"},
  {"id": "whx106", "s": "wh", "lv": 1, "topic": "荘園と農奴", "q": "中世西ヨーロッパの荘園において、農民はどのような立場におかれていたか。", "a": "農民の多くは移動の自由のない【農奴】で、領主直営地での【賦役】と、保有地からの生産物を納める【貢納】の義務を負った。結婚税や死亡税も課された。領主は国王の役人の立ち入りや課税を拒む【不輸不入権】をもち、荘園を支配した。"},
  {"id": "whx107", "s": "wh", "lv": 2, "topic": "叙任権闘争", "q": "11〜12世紀の叙任権闘争とはどのような争いか、その経過と結果を述べよ。", "a": "聖職者の任命権をめぐる教皇と神聖ローマ皇帝の争い。教皇【グレゴリウス7世】が皇帝【ハインリヒ4世】を破門し、皇帝が教皇に謝罪する【カノッサの屈辱】がおこった。1122年の【ヴォルムス協約】で、叙任権は教皇がもつことが確認された。"},
  {"id": "whx108", "s": "wh", "lv": 2, "topic": "中世都市の自治", "q": "中世西ヨーロッパで都市が発達した背景と、都市の自治について述べよ。", "a": "農業生産力の向上で余剰生産物が生まれ、【商業の復活】が進んで都市が発達した。都市は皇帝や国王から【特許状】を得て自治権を獲得した。北イタリアの【コムーネ】やドイツの【自由都市】が成立し、【ハンザ同盟】などの都市同盟も結ばれた。"},
  {"id": "whx109", "s": "wh", "lv": 2, "topic": "ギルド", "q": "中世都市のギルドとはどのような組織か、その特徴と都市政治への影響を述べよ。", "a": "商人や手工業者の同業組合。【同職ギルド】では親方だけが組合員となり、職人や徒弟を従えた。自由な競争を禁止し、製品の品質・価格・生産量を統制した。市政を独占した【商人ギルド】に対し、手工業者は【ツンフト闘争】をおこして市政への参加を実現した。"},
  {"id": "whx110", "s": "wh", "lv": 1, "topic": "黒死病", "q": "14世紀にヨーロッパで流行した黒死病は、社会にどのような影響を与えたか。", "a": "人口の約3分の1が失われ、労働力不足から農民の地位が向上し、イギリスでは【独立自営農民】（ヨーマン）が成長した。領主が再び束縛を強めると【ジャックリーの乱】や【ワット=タイラーの乱】がおこり、【封建社会】は解体に向かった。"},
  {"id": "whx111", "s": "wh", "lv": 2, "topic": "百年戦争", "q": "14〜15世紀の百年戦争の原因と、それが英仏両国に与えた影響を述べよ。", "a": "フランスの王位継承問題と、毛織物産業の盛んな【フランドル地方】の支配をめぐって英仏が争った。【ジャンヌ=ダルク】の活躍もありフランスが勝利した。戦争で両国の諸侯や騎士が没落し、【中央集権化】が進んだ。イギリスではその後【バラ戦争】がおこった。"},
  {"id": "whx112", "s": "wh", "lv": 1, "topic": "教皇権の衰退", "q": "13世紀末以降、ローマ教皇の権威が衰退していった経過を述べよ。", "a": "フランス王【フィリップ4世】が教皇ボニファティウス8世をとらえる【アナーニ事件】がおこった。その後、教皇庁が南フランスのアヴィニョンに移される【教皇のバビロン捕囚】が続き、さらに複数の教皇が並び立つ【教会大分裂】がおこった。"},
  {"id": "whx113", "s": "wh", "lv": 2, "topic": "ビザンツ帝国", "q": "東ローマ（ビザンツ）帝国の政治体制の特徴と、その文化について述べよ。", "a": "皇帝が政治と宗教の両方の最高権力をもつ【皇帝教皇主義】をとった。7世紀以降、異民族の侵入に対して【軍管区制】（テマ制）をしき、【屯田兵制】で防衛した。ギリシア正教とギリシア古典文化を融合した文化が栄え、【ハギア=ソフィア聖堂】が建てられた。"},
  {"id": "whx114", "s": "wh", "lv": 2, "topic": "東西教会の分裂", "q": "キリスト教会がローマ=カトリック教会とギリシア正教会に分裂した経緯を述べよ。", "a": "726年、ビザンツ皇帝レオン3世が【聖像禁止令】を出すと、ゲルマン人への布教に聖像を用いていたローマ教会が反発し、フランク王国に接近した。両教会の対立は深まり、1054年に【ローマ=カトリック教会】と【ギリシア正教会】に分裂した。"},
  {"id": "whx115", "s": "wh", "lv": 1, "topic": "ノルマン人の移動", "q": "9〜11世紀のノルマン人の移動は、ヨーロッパ各地にどのような国家を生んだか。", "a": "北フランスに【ノルマンディー公国】を建て、そこから【ノルマン=コンクェスト】でイングランドを征服した。南イタリアとシチリアには【両シチリア王国】を建て、東ではルーシの一派が【ノヴゴロド国】を建てた。"},
  {"id": "whx116", "s": "wh", "lv": 2, "topic": "イギリス議会の起源", "q": "中世イングランドで、議会政治の基礎が形成された過程を13世紀を中心に述べよ。", "a": "ジョン王は貴族らの要求で1215年に【大憲章】（マグナ=カルタ）を認め、課税には貴族の同意が必要とされた。13世紀後半の【シモン=ド=モンフォール】の議会を経て、エドワード1世が【模範議会】を招集した。14世紀には貴族院と庶民院の【二院制】が成立した。"},
  {"id": "whx117", "s": "wh", "lv": 3, "topic": "中世の農業革命", "q": "11〜13世紀の西ヨーロッパで農業生産力が向上した理由と、その社会的影響を論ぜよ。", "a": "秋耕地・春耕地・休耕地を輪作する【三圃制】や、牛馬に引かせる【重量有輪犂】の普及で生産力が高まり、人口が増加した。余剰生産物は【商業の復活】と都市の発達を促し、人口増加はエルベ川以東への【東方植民】や十字軍など、ヨーロッパの対外的な拡大をもたらした。"},
  {"id": "whx118", "s": "wh", "lv": 3, "topic": "ビザンツ帝国の変容", "q": "11世紀以降のビザンツ帝国で、国家体制がどのように変化したかを論ぜよ。", "a": "テマ制を支えた【屯田兵】などの自由農民が没落し、軍管区制はくずれた。帝国は有力者に軍役と引きかえに土地の管理と徴税を委ねる【プロノイア制】を導入し、地方の有力者が自立して【封建化】が進んだ。【第4回十字軍】によるコンスタンティノープル占領で、帝国はさらに衰えた。"},
  {"id": "whx119", "s": "wh", "lv": 3, "topic": "レコンキスタ", "q": "イベリア半島でのレコンキスタの過程と、それが近世スペインの性格に与えた影響を論ぜよ。", "a": "キリスト教諸国がイスラーム勢力から領土を奪回する【レコンキスタ】が進み、【カスティリャ】と【アラゴン】が統合してスペイン王国が成立した。1492年に【グラナダ】を攻略して完了した。強いカトリック信仰が王権と結びつき、ユダヤ教徒の追放や、新大陸への進出と布教につながった。"},
  {"id": "whx120", "s": "wh", "lv": 1, "topic": "マムルーク朝", "q": "13世紀にエジプトで成立したマムルーク朝が、イスラーム世界で果たした役割を述べよ。", "a": "トルコ系の軍人奴隷【マムルーク】が建てた王朝で、【モンゴル軍】の侵攻を撃退し、十字軍勢力も一掃した。首都【カイロ】はイスラーム世界の政治・経済・文化の中心として栄え、【カーリミー商人】が香辛料交易で活躍した。"},
  {"id": "whx121", "s": "wh", "lv": 1, "topic": "ティムール朝", "q": "14世紀後半に中央アジアで成立したティムール朝について述べよ。", "a": "【ティムール】はモンゴル帝国の再興をめざして中央アジアから西アジアに大帝国を築き、【アンカラの戦い】でオスマン帝国を破った。都の【サマルカンド】は交易と文化の中心として栄え、細密画などの【トルコ=イスラーム文化】が発達した。"},
  {"id": "whx122", "s": "wh", "lv": 1, "topic": "絶対王政", "q": "16〜18世紀のヨーロッパで成立した絶対王政の特徴を、その支柱に触れて述べよ。", "a": "国王は【王権神授説】を唱えて強大な権力をふるった。その権力を支えたのは、国王に忠実な【官僚制】と【常備軍】であり、それらを維持する財源を得るため、【重商主義】政策がとられた。"},
  {"id": "whx123", "s": "wh", "lv": 1, "topic": "三十年戦争", "q": "三十年戦争の性格と、ウェストファリア条約の内容および意義を述べよ。", "a": "ドイツの新旧両派の宗教対立から始まり、周辺各国が介入する【国際戦争】に発展した。1648年の【ウェストファリア条約】でカルヴァン派が公認され、ドイツの諸邦がほぼ完全な【主権】を認められて神聖ローマ帝国は有名無実化した。オランダとスイスの独立も承認され、【主権国家体制】が確立した。"},
  {"id": "whx124", "s": "wh", "lv": 2, "topic": "オランダの独立", "q": "オランダがスペインから独立し、17世紀に繁栄した経緯を述べよ。", "a": "スペイン王【フェリペ2世】のカトリック強制と重税に対し、ネーデルラントのカルヴァン派などが反乱をおこした。北部7州は【ユトレヒト同盟】を結んで【ネーデルラント連邦共和国】の独立を宣言した。17世紀には【東インド会社】を設立してアジア貿易で栄え、アムステルダムは国際金融の中心となった。"},
  {"id": "whx125", "s": "wh", "lv": 1, "topic": "エリザベス1世", "q": "エリザベス1世の時代に、イギリスが国力を高めた理由を述べよ。", "a": "【統一法】でイギリス国教会を確立し、宗教対立をおさめた。1588年にスペインの【無敵艦隊】を破り、海外進出の基礎を築いた。国内では【毛織物工業】を保護し、1600年には【東インド会社】を設立した。"},
  {"id": "whx126", "s": "wh", "lv": 2, "topic": "ピューリタン革命", "q": "イギリスのピューリタン革命がおこった原因と、その経過を述べよ。", "a": "ジェームズ1世とチャールズ1世が王権神授説をかかげて議会を軽視したため、議会は1628年に【権利の請願】を提出した。王が議会を解散して専制を続けると内戦となり、【クロムウェル】の率いる議会派が勝利して1649年に国王を処刑し、【共和政】が成立した。"},
  {"id": "whx127", "s": "wh", "lv": 1, "topic": "ルイ14世", "q": "「太陽王」とよばれたフランスのルイ14世の時代の政治について述べよ。", "a": "【ルイ14世】は王権神授説を唱えて絶対王政の最盛期を築いた。財務総監【コルベール】が重商主義政策を進め、壮大な【ヴェルサイユ宮殿】を造営した。しかし【ナントの王令】を廃止したため、ユグノーの商工業者が国外に流出した。"},
  {"id": "whx128", "s": "wh", "lv": 2, "topic": "啓蒙専制君主", "q": "啓蒙専制君主とはどのような君主か、プロイセンのフリードリヒ2世を例に述べよ。", "a": "【啓蒙思想】の影響を受け、上からの近代化を進めた君主。【フリードリヒ2世】は「君主は国家第一の僕」と称し、宗教寛容や産業の育成を進めた。一方で、領主貴族【ユンカー】による農場領主制は維持され、改革は国家の強化を目的とする限界をもった。"},
  {"id": "whx129", "s": "wh", "lv": 2, "topic": "ピョートル1世", "q": "ロシアのピョートル1世がおこなった近代化政策と対外政策を述べよ。", "a": "みずから西欧を視察して技術を学び、【西欧化】を進めた。【北方戦争】でスウェーデンを破ってバルト海に進出し、新都【ペテルブルク】を建設した。東方ではシベリア経営を進め、清と【ネルチンスク条約】を結んだ。"},
  {"id": "whx130", "s": "wh", "lv": 3, "topic": "再版農奴制", "q": "16世紀以降のエルベ川以東の地域で、再版農奴制が成立した理由を論ぜよ。", "a": "西欧で商工業が発展して都市人口が増えると、東欧は西欧への【穀物】輸出地域となった。領主は輸出用の穀物を生産するため、農民の賦役を強化して【農場領主制】（グーツヘルシャフト）を経営し、【再版農奴制】が成立した。これは西欧を中心とする【国際分業】の一環であった。"},
  {"id": "whx131", "s": "wh", "lv": 1, "topic": "啓蒙思想", "q": "18世紀の啓蒙思想家が唱えた、政治に関する主な思想を述べよ。", "a": "【モンテスキュー】は『法の精神』で【三権分立】を説いた。【ルソー】は『社会契約論』で人民主権を唱え、フランス革命に影響を与えた。【ヴォルテール】は理性にもとづいて教会の権威や専制政治を批判した。"},
  {"id": "whx132", "s": "wh", "lv": 2, "topic": "科学革命", "q": "17世紀ヨーロッパの科学革命について、主な人物と業績を挙げて述べよ。", "a": "観察と実験にもとづく近代科学が成立した。【ガリレイ】は望遠鏡による観測から【地動説】を支持し、【ニュートン】は万有引力の法則を発見した。哲学ではフランシス=ベーコンが帰納法、【デカルト】が演繹法を唱えた。"},
  {"id": "whx133", "s": "wh", "lv": 2, "topic": "英仏植民地戦争", "q": "17〜18世紀の英仏による植民地争奪戦の経過と、その結果を述べよ。", "a": "両国は北アメリカやインドで戦争をくり返した。七年戦争と並行した【フレンチ=インディアン戦争】でイギリスが勝ち、1763年の【パリ条約】でカナダやミシシッピ川以東を獲得した。インドでも【プラッシーの戦い】に勝利し、イギリスの優位が確立した。"},
  {"id": "whx134", "s": "wh", "lv": 3, "topic": "大西洋三角貿易", "q": "17〜18世紀の大西洋三角貿易の仕組みと、それがヨーロッパに与えた影響を論ぜよ。", "a": "ヨーロッパから【武器】や綿織物をアフリカへ運び、アフリカから【黒人奴隷】を南北アメリカへ運び、アメリカから【砂糖】・綿花・タバコをヨーロッパに運んだ。この貿易で得た利益はイギリスの資本蓄積を進め、【産業革命】の前提となった。"},
  {"id": "whx135", "s": "wh", "lv": 1, "topic": "1848年革命", "q": "1848年にヨーロッパ各地でおこった革命の内容と、その結果を述べよ。", "a": "フランスの【二月革命】で七月王政が倒れ、第二共和政が成立した。その影響でオーストリアやドイツで【三月革命】がおこり、【メッテルニヒ】が失脚した。各地の民族運動も高まり【諸国民の春】とよばれたが、多くは保守勢力に鎮圧された。"},
  {"id": "whx136", "s": "wh", "lv": 1, "topic": "イタリア統一", "q": "19世紀のイタリア統一は、どのような過程で実現したかを述べよ。", "a": "【サルデーニャ王国】の首相【カヴール】が近代化を進め、フランスと結んでオーストリアからロンバルディアを獲得した。【ガリバルディ】が両シチリア王国を占領してサルデーニャ王に献上し、1861年に【イタリア王国】が成立した。"},
  {"id": "whx137", "s": "wh", "lv": 1, "topic": "ドイツ統一", "q": "19世紀後半、プロイセンが中心となってドイツ統一を実現した過程を述べよ。", "a": "プロイセン首相【ビスマルク】は【鉄血政策】による軍備拡張を進め、デンマーク戦争、【普墺戦争】、普仏戦争に勝利した。1871年、ヴェルサイユ宮殿でプロイセン王がドイツ皇帝に即位し、【ドイツ帝国】が成立した。"},
  {"id": "whx138", "s": "wh", "lv": 2, "topic": "ビスマルク外交", "q": "ドイツ帝国成立後のビスマルク外交の目的と、その内容を述べよ。", "a": "普仏戦争で敵対した【フランスの孤立化】を目的とした。オーストリア・ロシアと【三帝同盟】を結び、オーストリア・イタリアと【三国同盟】を結成した。のちにロシアとは【再保障条約】を結び、ヨーロッパの勢力均衡を維持した。"},
  {"id": "whx139", "s": "wh", "lv": 2, "topic": "ビスマルクの内政", "q": "ビスマルクがドイツ帝国でおこなった内政を、「アメとムチ」に触れて述べよ。", "a": "カトリック勢力を抑えるため【文化闘争】をおこない、【社会主義者鎮圧法】で社会主義運動を弾圧した。一方で労働者を体制にとりこむため、災害保険や養老保険などの【社会保険制度】を整備した。この政策は「アメとムチ」とよばれた。"},
  {"id": "whx140", "s": "wh", "lv": 1, "topic": "南北戦争", "q": "1861年に始まったアメリカ南北戦争の原因と、その結果を述べよ。", "a": "工業が発展し【保護関税】を求める北部と、綿花を輸出するため自由貿易を求め、【奴隷制】を維持したい南部が対立した。奴隷制拡大に反対する【リンカン】の大統領当選を機に南部が分離して戦争となり、北部が勝利した。戦争中には【奴隷解放宣言】が出された。"},
  {"id": "whx141", "s": "wh", "lv": 2, "topic": "アメリカの領土拡大", "q": "19世紀のアメリカ合衆国の領土拡大の過程と、それが先住民に与えた影響を述べよ。", "a": "フランスからルイジアナを買収し、【アメリカ=メキシコ戦争】でカリフォルニアなどを獲得した。領土拡大は【明白な天命】として正当化されたが、【先住民強制移住法】などで先住民は土地を奪われた。1890年には【フロンティア】の消滅が宣言された。"},
  {"id": "whx142", "s": "wh", "lv": 1, "topic": "ロシアの農奴解放", "q": "ロシアのアレクサンドル2世が農奴解放令を出した理由と、その結果を述べよ。", "a": "【クリミア戦争】の敗北で国の後進性が明らかになり、【アレクサンドル2世】は1861年に【農奴解放令】を出した。農民は人格的な自由を得たが、土地の取得は有償で、【ミール】（農村共同体）に縛られたままだった。"},
  {"id": "whx143", "s": "wh", "lv": 2, "topic": "イギリスの自由主義的改革", "q": "19世紀前半のイギリスで進められた自由主義的改革について述べよ。", "a": "【審査法】の廃止とカトリック教徒解放法で宗教上の差別が緩和され、【第1回選挙法改正】で産業資本家が選挙権を得た。選挙権のない労働者は【チャーティスト運動】で普通選挙を要求した。自由貿易を求める運動の結果、【穀物法】が廃止された。"},
  {"id": "whx144", "s": "wh", "lv": 2, "topic": "東方問題とクリミア戦争", "q": "19世紀の「東方問題」とは何か、クリミア戦争を例に説明せよ。", "a": "オスマン帝国の衰退にともない、その領土や民族問題をめぐって列強が対立した国際問題。ロシアは不凍港を求めて【南下政策】を進め、聖地管理権を口実にオスマン帝国と【クリミア戦争】をおこしたが、【イギリス】とフランスがオスマン帝国を支援し、ロシアは敗北した。"},
  {"id": "whx145", "s": "wh", "lv": 2, "topic": "ベルリン会議", "q": "1878年に開かれたベルリン会議の背景と、その結果を述べよ。", "a": "【ロシア=トルコ戦争】に勝利したロシアは、【サン=ステファノ条約】でブルガリアを保護下においた。これにイギリスとオーストリアが反発したため、【ビスマルク】が仲介してベルリン会議が開かれた。ブルガリアは縮小され、ロシアの南下は再び阻まれた。"},
  {"id": "whx146", "s": "wh", "lv": 1, "topic": "帝国主義", "q": "19世紀末に欧米列強が帝国主義政策をとるようになった理由を述べよ。", "a": "【第2次産業革命】で重化学工業が発展し、巨大企業による【独占資本】が形成された。列強は原料供給地や商品市場、【資本輸出】の対象を求めて植民地獲得を競い、アジア・アフリカを分割した。"},
  {"id": "whx147", "s": "wh", "lv": 1, "topic": "アフリカ分割", "q": "19世紀末のアフリカ分割において、イギリスとフランスがとった政策と、両国の衝突を述べよ。", "a": "イギリスはエジプトとケープ植民地を結ぶ【アフリカ縦断政策】をとり、フランスはアルジェリアなどから東へ進む【アフリカ横断政策】をとった。両国は1898年にスーダンで【ファショダ事件】をおこしたが、フランスが譲歩し、のちに【英仏協商】が結ばれた。"},
  {"id": "whx148", "s": "wh", "lv": 2, "topic": "ベルリン=コンゴ会議", "q": "1884〜85年のベルリン会議（ベルリン=コンゴ会議）が、アフリカ分割に与えた影響を述べよ。", "a": "ビスマルクの主催で開かれ、【コンゴ自由国】をベルギー国王の私有地として認めた。また、アフリカの土地を先に【実効支配】した国が領有できるという【先占権】の原則が確認され、列強による分割が加速した。"},
  {"id": "whx149", "s": "wh", "lv": 3, "topic": "大不況と独占資本", "q": "19世紀後半の「大不況」の時期に、欧米の経済と社会がどのように変化したかを論ぜよ。", "a": "1873年から長期の不況が続き、企業は競争を避けて【カルテル】やトラストを形成し、【独占資本】が成長した。各国は【保護関税】政策に転じ、市場と投資先を求めて植民地獲得を進めた。また、困窮した多くの人々が新大陸へ【移民】として渡った。"},
  {"id": "whx150", "s": "wh", "lv": 1, "topic": "社会主義思想", "q": "19世紀に社会主義思想が生まれた背景と、その主な思想を述べよ。", "a": "産業革命による資本主義の発展で、長時間労働などの【労働問題】や貧富の差が深刻化した。オーウェンらの初期社会主義に続き、【マルクス】はエンゲルスとともに『【共産党宣言】』を著し、労働者階級の革命によって【社会主義】社会を実現すると説いた。"},
  {"id": "whx151", "s": "wh", "lv": 2, "topic": "第三共和政の危機", "q": "19世紀末にフランス第三共和政を揺るがした事件と、その影響について述べよ。", "a": "対独復讐を唱える元陸軍大臣を担いだ【ブーランジェ事件】や、ユダヤ系軍人がスパイ容疑で冤罪を受けた【ドレフュス事件】がおこった。ドレフュス事件ではゾラらが軍を批判し、共和派が勢力を強め、1905年に【政教分離法】が制定された。"},
  {"id": "whx152", "s": "wh", "lv": 3, "topic": "国民国家の形成", "q": "19世紀のヨーロッパで、国民国家の形成がどのように進められたかを論ぜよ。", "a": "フランス革命を通じて、国民が主権をもつという【国民主義】（ナショナリズム）の理念が広まった。各国は【義務教育】や【徴兵制】を整え、国語や国民の歴史を教えて【国民意識】を育てた。イタリアやドイツでは、統一運動を通じて【国民国家】が形成された。"},
  {"id": "whx153", "s": "wh", "lv": 3, "topic": "世界の工場イギリス", "q": "19世紀半ばのイギリスが「世界の工場」として築いた経済体制と、その対外政策を論ぜよ。", "a": "圧倒的な工業力をもつイギリスは、【穀物法】や【航海法】を廃止して【自由貿易】体制を確立した。工業製品を輸出し原料や食料を輸入する国際分業を進め、ロンドンは国際金融の中心となった。軍事力を背景に通商を開かせる【自由貿易帝国主義】で、アジアやラテンアメリカに影響力を広げた。"},
  {"id": "whx154", "s": "wh", "lv": 1, "topic": "ヴィクトリア時代の議会政治", "q": "ヴィクトリア女王時代のイギリスで発達した議会政治について述べよ。", "a": "自由党と保守党の【二大政党】が交互に政権を担当し、自由党の【グラッドストン】と保守党の【ディズレーリ】が活躍した。第2回・第3回の【選挙法改正】で、都市労働者や農業労働者にも選挙権が拡大された。"},
  {"id": "whx155", "s": "wh", "lv": 2, "topic": "アイルランド問題", "q": "19世紀から20世紀初めにかけての、イギリスにおけるアイルランド問題の経過を述べよ。", "a": "1801年にアイルランドはイギリスに【併合】され、カトリック教徒への差別や不在地主の支配が続いた。1840年代の【ジャガイモ飢饉】では多くの人々が餓死し、アメリカなどへ移住した。グラッドストンの【アイルランド自治法案】は否決が続き、1914年に成立したが実施は延期された。"},
  {"id": "whx156", "s": "wh", "lv": 1, "topic": "対抗宗教改革", "q": "宗教改革に対して、カトリック側がおこなった対抗宗教改革の内容を述べよ。", "a": "【トリエント公会議】で教皇の至上権とカトリックの教義を再確認し、教会内部の粛正を進めた。【イエズス会】が設立され、ザビエルらがアジアやラテンアメリカで【海外布教】をおこなった。異端の取り締まりのため【宗教裁判】や禁書目録も強化された。"},
  {"id": "whx157", "s": "wh", "lv": 2, "topic": "ユグノー戦争", "q": "16世紀後半のフランスでおこったユグノー戦争の経過と、その終結について述べよ。", "a": "カトリックとカルヴァン派の【ユグノー】の対立に貴族の争いが結びつき、内戦となった。1572年の【サンバルテルミの虐殺】ではユグノーが多数殺害された。ブルボン朝を開いた【アンリ4世】が1598年に【ナントの王令】を出し、ユグノーに信仰の自由を認めて内戦を終結させた。"},
  {"id": "whx158", "s": "wh", "lv": 3, "topic": "重商主義", "q": "絶対王政期の重商主義とはどのような経済政策か、フランスとイギリスの例を挙げて論ぜよ。", "a": "国家が経済に介入して国富を増大させようとする政策。初期には金銀の獲得をめざす【重金主義】がとられ、のちに輸出拡大で利益を得る【貿易差額主義】が中心となった。フランスでは【コルベール】が王立マニュファクチュアを育成し、イギリスは【航海法】でオランダの中継貿易に打撃を与えた。"},
  {"id": "whx159", "s": "wh", "lv": 2, "topic": "第2次囲い込み", "q": "18世紀イギリスの第2次囲い込みと農業革命は、社会にどのような影響を与えたか。", "a": "【第2次囲い込み】では、大地主が議会の承認のもとで開放耕地や共有地を囲い込み、【ノーフォーク農法】などで生産力を高めた。土地を失った小農民は賃金労働者となり、工業の【労働力】を提供した。農業でも地主・農業資本家・農業労働者による【資本主義的経営】が広がった。"},
  {"id": "whx160", "s": "wh", "lv": 1, "topic": "ラテンアメリカ諸国の独立", "q": "19世紀前半にラテンアメリカ諸国が独立した背景と、その指導者について述べよ。", "a": "植民地生まれの白人【クリオーリョ】が、アメリカ独立革命やフランス革命の影響を受けて独立運動をおこした。ナポレオンの侵攻で本国スペインが混乱したことも独立を後押しし、【シモン=ボリバル】や【サン=マルティン】が運動を指導した。"},
  {"id": "whx161", "s": "wh", "lv": 2, "topic": "ハイチの独立", "q": "カリブ海のハイチが独立した経緯と、その歴史的な意義を述べよ。", "a": "フランス領サン=ドマングで、【トゥサン=ルヴェルチュール】らの指導のもと黒人奴隷が蜂起した。1804年に【ハイチ】は独立し、【奴隷制の廃止】を実現した世界で最初の【黒人共和国】となった。"},
  {"id": "whx162", "s": "wh", "lv": 2, "topic": "モンロー宣言", "q": "1823年にアメリカ合衆国が発したモンロー宣言の背景と、その内容を述べよ。", "a": "ウィーン体制下のヨーロッパ諸国がラテンアメリカの独立運動に干渉することを警戒し、大統領【モンロー】は、アメリカ大陸とヨーロッパの【相互不干渉】を宣言した。ラテンアメリカとの貿易を重視するイギリスの外相【カニング】も干渉に反対した。"},
  {"id": "whx163", "s": "wh", "lv": 3, "topic": "ラテンアメリカの経済的従属", "q": "独立後のラテンアメリカ諸国で、経済的な従属が続いた理由を論ぜよ。", "a": "独立後も植民地時代以来の【大土地所有制】が残り、クリオーリョの地主層が支配を続けた。経済は欧米向けのコーヒー・砂糖・食肉などの【一次産品】の輸出に依存する【モノカルチャー】となり、鉄道建設などで【イギリス資本】に従属した。20世紀にはアメリカ合衆国の影響が強まった。"},
  {"id": "whx164", "s": "wh", "lv": 2, "topic": "メキシコ革命", "q": "1910年に始まったメキシコ革命の背景と、その成果を述べよ。", "a": "【ディアス】の長期独裁のもとで外国資本が優遇され、土地が大地主に集中した。【マデロ】の蜂起で独裁は倒れ、農民指導者の【サパタ】らも土地改革を求めて戦った。1917年には土地改革や地下資源の国有を定めた【民主的な憲法】が制定された。"},
  {"id": "whx165", "s": "wh", "lv": 1, "topic": "カリブ海政策", "q": "19世紀末から20世紀初めに、アメリカ合衆国がカリブ海地域で進めた政策を述べよ。", "a": "1898年の【アメリカ=スペイン戦争】に勝利してプエルトリコやフィリピンを獲得し、キューバを事実上の保護国とした。セオドア=ローズヴェルト大統領は武力を背景とする【棍棒外交】を進め、【パナマ運河】の建設に着手した。"},
  {"id": "whx166", "s": "wh", "lv": 1, "topic": "太平天国", "q": "19世紀半ばの中国でおこった太平天国の乱の背景と、その主張を述べよ。", "a": "アヘン戦争後の銀の流出と重税で民衆が困窮した。キリスト教の影響を受けた【洪秀全】が拝上帝会を組織して挙兵し、【滅満興漢】をかかげた。土地を均分する【天朝田畝制度】や辮髪の廃止をうちだしたが、【郷勇】や外国人の指揮する常勝軍に鎮圧された。"},
  {"id": "whx167", "s": "wh", "lv": 1, "topic": "洋務運動", "q": "19世紀後半の清でおこなわれた洋務運動の内容と、その限界を述べよ。", "a": "【曽国藩】や【李鴻章】ら漢人官僚が、西洋の技術を導入して軍需工業や鉄道、鉱山の開発を進めた。しかし「【中体西用】」の考えにもとづき政治体制は改めなかったため、【日清戦争】の敗北で限界が明らかになった。"},
  {"id": "whx168", "s": "wh", "lv": 2, "topic": "アロー戦争", "q": "アロー戦争の結果、清が結んだ条約の内容と、ロシアの動きを述べよ。", "a": "英仏連合軍に敗れた清は【天津条約】と【北京条約】を結んだ。【外国公使の北京駐在】やキリスト教布教の自由が認められ、天津などが開港された。ロシアは講和を仲介した代償として、北京条約で【沿海州】を獲得した。"},
  {"id": "whx169", "s": "wh", "lv": 2, "topic": "変法運動", "q": "日清戦争後の清でおこった変法運動の内容と、その結果を述べよ。", "a": "【康有為】らは日本の明治維新にならい、【立憲君主政】の樹立をめざす改革を光緒帝に進言した。1898年に【戊戌の変法】が始まったが、【西太后】ら保守派のクーデタによって約100日で失敗した。"},
  {"id": "whx170", "s": "wh", "lv": 1, "topic": "義和団事件", "q": "1900年におこった義和団事件の経過と、それが清に与えた影響を述べよ。", "a": "列強の進出とキリスト教布教に反発した【義和団】が「【扶清滅洋】」をかかげて蜂起し、清朝もこれに乗じて列強に宣戦した。日本とロシアを主力とする8か国連合軍が北京を占領し、清は【北京議定書】で巨額の賠償金と外国軍隊の北京駐屯を認めた。"},
  {"id": "whx171", "s": "wh", "lv": 2, "topic": "中国分割", "q": "日清戦争の後、列強による中国分割が進んだ経緯と、アメリカの対応を述べよ。", "a": "列強は清に借款を与え、鉄道敷設権や鉱山採掘権を獲得し、【租借地】と【勢力範囲】を設定した。ドイツは膠州湾、ロシアは遼東半島南部、イギリスは威海衛と九竜半島を租借した。出遅れたアメリカは国務長官【ジョン=ヘイ】が【門戸開放】を提唱した。"},
  {"id": "whx172", "s": "wh", "lv": 2, "topic": "光緒新政", "q": "義和団事件の後に清がおこなった光緒新政の内容と、その結末を述べよ。", "a": "清は近代化改革に着手し、1905年に【科挙】を廃止した。日本にならって【憲法大綱】を発表し、国会開設を約束した。新軍の創設も進めたが、民営鉄道の【鉄道国有化】に対する反発が辛亥革命のきっかけとなった。"},
  {"id": "whx173", "s": "wh", "lv": 1, "topic": "インド大反乱", "q": "インド大反乱（シパーヒーの反乱）の原因と、その結果を述べよ。", "a": "イギリス東インド会社の支配への不満が広がり、1857年に会社のインド人傭兵【シパーヒー】が反乱をおこした。反乱は鎮圧され、【ムガル帝国】は滅亡した。イギリスは【東インド会社】を解散して直接統治に移り、1877年に【インド帝国】が成立した。"},
  {"id": "whx174", "s": "wh", "lv": 2, "topic": "ベンガル分割令", "q": "インドで民族運動が高まった経緯を、ベンガル分割令に触れて述べよ。", "a": "1885年、イギリスの協力のもとで【インド国民会議】が結成された。1905年に【ベンガル分割令】が出されると反英運動が高まり、翌年の【カルカッタ大会】で英貨排斥・スワデーシ（国産品愛用）・【スワラージ】（自治獲得）・民族教育の4綱領が決議された。"},
  {"id": "whx175", "s": "wh", "lv": 3, "topic": "インドの植民地経済", "q": "イギリスの支配が、インドの経済と社会をどのように変えたかを論ぜよ。", "a": "イギリスの機械製綿布が流入し、インドの手工業による【綿織物業】は大きな打撃を受けた。インドは綿花・アヘン・藍などの【原料供給地】、イギリス製品の市場とされた。地税徴収のため【ザミンダーリー制】や【ライヤットワーリー制】が導入され、土地の私的所有権が設定され、農民の負担が重くなった。"},
  {"id": "whx176", "s": "wh", "lv": 1, "topic": "東南アジアの植民地化", "q": "19世紀に東南アジアの大部分が植民地化された経緯を、主な国ごとに述べよ。", "a": "イギリスはマレー半島に【海峡植民地】を形成し、ビルマを併合した。オランダはジャワで【強制栽培制度】を実施し、フランスはベトナム・カンボジアなどを合わせて【フランス領インドシナ連邦】を形成した。タイは英仏の【緩衝国】として独立を保った。"},
  {"id": "whx177", "s": "wh", "lv": 2, "topic": "タイの独立維持", "q": "19世紀のタイが、植民地化されずに独立を維持できた理由を述べよ。", "a": "タイ（ラタナコーシン朝）は、イギリス領ビルマとフランス領インドシナの間の【緩衝地帯】に位置した。国王【ラーマ5世】（チュラロンコン）は行政・司法の改革や奴隷制の廃止などの【近代化政策】を進め、巧みな【外交】で独立を守った。"},
  {"id": "whx178", "s": "wh", "lv": 2, "topic": "強制栽培制度", "q": "オランダがジャワで実施した強制栽培制度の内容と、その影響を述べよ。", "a": "1830年からオランダ政府は、ジャワの農民にコーヒー・サトウキビ・藍などの【商品作物】を指定して栽培させ、安い価格で買い上げた。オランダは大きな利益を得て【財政】を立て直したが、農民は食料生産が減って【飢饉】に苦しんだ。"},
  {"id": "whx179", "s": "wh", "lv": 2, "topic": "フィリピン革命", "q": "フィリピンの民族運動の展開と、その後のアメリカによる支配について述べよ。", "a": "【ホセ=リサール】がスペインの支配を批判する言論活動をおこなった。1896年にフィリピン革命が始まり、【アギナルド】がフィリピン共和国を樹立したが、【アメリカ=スペイン戦争】でフィリピンの領有権を得た【アメリカ】に鎮圧された。"},
  {"id": "whx180", "s": "wh", "lv": 2, "topic": "ドンズー運動", "q": "20世紀初めのベトナムの民族運動について、ファン=ボイ=チャウの活動を中心に述べよ。", "a": "日露戦争での日本の勝利に刺激された【ファン=ボイ=チャウ】は、フランスからの独立をめざして維新会を組織し、日本に留学生を送る【ドンズー運動】を進めた。しかし日本が【日仏協約】を結んでフランスに協力したため、留学生は国外に追放された。"},
  {"id": "whx181", "s": "wh", "lv": 1, "topic": "タンジマート", "q": "19世紀のオスマン帝国でおこなわれたタンジマートとミドハト憲法について述べよ。", "a": "1839年に始まった【タンジマート】では、西欧化をめざし、宗教を問わない法の前の平等などが進められた。1876年には宰相【ミドハト=パシャ】が起草した【ミドハト憲法】が制定されたが、【アブデュルハミト2世】はロシア=トルコ戦争を理由に憲法を停止した。"},
  {"id": "whx182", "s": "wh", "lv": 2, "topic": "青年トルコ革命", "q": "1908年にオスマン帝国でおこった青年トルコ革命の内容と、その影響を述べよ。", "a": "専制政治に反対する【青年トルコ人】が革命をおこし、【ミドハト憲法】を復活させた。しかし、この混乱に乗じて【オーストリア】がボスニア=ヘルツェゴヴィナを併合し、ブルガリアが独立を宣言するなど、帝国は領土を失った。"},
  {"id": "whx183", "s": "wh", "lv": 2, "topic": "ムハンマド=アリー", "q": "19世紀のエジプトで、ムハンマド=アリーが進めた近代化と、その後のイギリスの進出を述べよ。", "a": "【ムハンマド=アリー】は富国強兵策を進め、オスマン帝国から事実上自立した。のち【スエズ運河】の建設などで財政が破綻し、イギリスは運河会社の株を買収した。1882年に【ウラービー運動】を鎮圧したイギリスは、エジプトを事実上の【保護国】とした。"},
  {"id": "whx184", "s": "wh", "lv": 3, "topic": "イランの抵抗運動", "q": "19世紀末から20世紀初めのイランで、外国勢力の進出に対しておこった抵抗運動を論ぜよ。", "a": "カージャール朝がイギリス人に【タバコ利権】を与えると、ウラマーと商人を中心に【タバコ=ボイコット運動】がおこり、利権は撤回された。1905年には【イラン立憲革命】がおこって議会が開設されたが、英露の干渉で挫折した。1907年の【英露協商】でイランは両国の勢力範囲に分けられた。"},
  {"id": "whx185", "s": "wh", "lv": 3, "topic": "パン=イスラーム主義", "q": "19世紀後半にアフガーニーが唱えたパン=イスラーム主義の内容と、その影響を論ぜよ。", "a": "【アフガーニー】は、ヨーロッパ列強の侵略に対抗するため、民族や国家の違いをこえたイスラーム世界の【連帯】と、専制を改めるイスラームの改革を訴えた。その思想は各地の反帝国主義運動を刺激し、エジプトの【ウラービー運動】やイランの【タバコ=ボイコット運動】に影響を与えた。"},
  {"id": "whx186", "s": "wh", "lv": 1, "topic": "南アフリカ戦争", "q": "19世紀末におこった南アフリカ戦争（ブール戦争）の背景と、その結果を述べよ。", "a": "ケープ植民地首相の【セシル=ローズ】は拡張政策を進めた。イギリスは金やダイヤモンドを産出する【トランスヴァール共和国】とオレンジ自由国を併合しようとし、オランダ系移民の子孫の【ブール人】と戦って勝利した。1910年には自治領の【南アフリカ連邦】が成立した。"},
  {"id": "whx187", "s": "wh", "lv": 2, "topic": "エチオピアの独立維持", "q": "19世紀末のエチオピアが、列強の侵略に対して独立を守ることができた理由を述べよ。", "a": "皇帝【メネリク2世】は近代的な武器を輸入して軍隊を整え、1896年の【アドワの戦い】でイタリア軍を破った。こうしてエチオピアは、アメリカの解放奴隷が建てた【リベリア】とともに、アフリカ分割の時代に独立を保った。"},
  {"id": "whx188", "s": "wh", "lv": 3, "topic": "東アジアの開国", "q": "19世紀半ばの東アジア諸国が欧米と結んだ条約の共通点と、その後の対応の違いを論ぜよ。", "a": "清・日本・朝鮮はいずれも、【領事裁判権】の承認や【関税自主権】の喪失を含む【不平等条約】を結ばされた。清は「【中体西用】」の洋務運動にとどまり、日本は明治維新で立憲国家を形成した。朝鮮では開化派と保守派の対立が続き、清と日本の介入を招いた。"},
  {"id": "whx189", "s": "wh", "lv": 2, "topic": "朝鮮の開国と日清戦争", "q": "1870年代の朝鮮の開国から、日清戦争に至るまでの経緯を述べよ。", "a": "1876年、日本は【日朝修好条規】で朝鮮を開国させた。朝鮮では日本に接近する開化派と清に頼る勢力が対立し、1884年に【甲申政変】がおこった。1894年に東学を信仰する農民が【甲午農民戦争】をおこすと、日清両国が出兵して【日清戦争】となった。"},
  {"id": "whx190", "s": "wh", "lv": 1, "topic": "韓国併合", "q": "日露戦争の後、日本が韓国を保護国とし、さらに植民地とした過程を述べよ。", "a": "日本は【日露戦争】後、日韓協約で韓国を【保護国】とし、統監府をおいて外交権を奪った。韓国では義兵闘争が広がったが、1909年に伊藤博文が安重根に暗殺されると、日本は1910年の【韓国併合】で韓国を植民地とした。"},
  {"id": "whx191", "s": "wh", "lv": 3, "topic": "日露戦争とアジア", "q": "日露戦争の結果が、アジアの民族運動にどのような影響を与えたかを論ぜよ。", "a": "アジアの国である日本がヨーロッパの大国ロシアに勝利したことは、アジアの人々の【民族意識】を刺激した。ベトナムでは【ドンズー運動】、イランでは【立憲革命】、オスマン帝国では【青年トルコ革命】がおこった。一方、日本自身は韓国を植民地化し、【帝国主義】国としてふるまった。"},
  {"id": "whx192", "s": "wh", "lv": 1, "topic": "アメリカ大陸の古代文明", "q": "16世紀にスペインに征服された、アメリカ大陸の文明について述べよ。", "a": "メキシコ高原には【アステカ王国】が栄え、首都テノチティトランを築いた。アンデス地方の【インカ帝国】は道路網を整え、文字のかわりに【キープ】（結縄）で記録した。いずれもスペインの【コルテス】と【ピサロ】によって征服された。"},
  {"id": "whx193", "s": "wh", "lv": 3, "topic": "スペインの植民地支配", "q": "スペインのアメリカ大陸支配が先住民社会に与えた影響を、制度と人口の面から論ぜよ。", "a": "スペインは入植者に先住民の保護とキリスト教化を委ねる【エンコミエンダ制】をしいたが、実際には先住民は鉱山や農園で酷使された。過酷な労働と持ち込まれた【伝染病】で先住民の人口は激減し、【ラス=カサス】はその惨状を告発した。労働力を補うため、アフリカから【黒人奴隷】が運ばれた。"},
  {"id": "whx194", "s": "wh", "lv": 1, "topic": "ロシア革命", "q": "1917年のロシア革命は、どのような経過をたどったかを述べよ。", "a": "第一次世界大戦の長期化で生活が困窮し、【三月革命】（ロシア暦二月革命）で皇帝ニコライ2世が退位した。その後、【レーニン】の率いる【ボリシェヴィキ】が【十一月革命】（ロシア暦十月革命）で臨時政府を倒し、ソヴィエト政権を樹立した。"},
  {"id": "whx195", "s": "wh", "lv": 2, "topic": "戦時共産主義とネップ", "q": "ソヴィエト政権が実施した戦時共産主義と、新経済政策（ネップ）について述べよ。", "a": "内戦と【対ソ干渉戦争】に対応するため、【戦時共産主義】によって穀物の強制徴発や企業の国有化をおこなったが、生産は低下した。そこで1921年に【新経済政策】（ネップ）を採用し、小規模な私企業や農産物の自由販売を認めて経済を回復させた。"},
  {"id": "whx196", "s": "wh", "lv": 3, "topic": "スターリン体制", "q": "スターリンが進めた五か年計画の内容と、その社会的な影響を論ぜよ。", "a": "【スターリン】は【一国社会主義論】を唱え、第1次【五か年計画】で重工業化を進めるとともに、農業の【集団化】によってコルホーズやソフホーズを建設した。工業生産は急増し世界恐慌の影響も受けなかったが、農民の抵抗と飢饉で多数の犠牲者が出て、反対派は【粛清】された。"},
  {"id": "whx197", "s": "wh", "lv": 1, "topic": "ワシントン会議", "q": "1921〜22年のワシントン会議で結ばれた条約と、その目的を述べよ。", "a": "アジア・太平洋地域の秩序を定めるために開かれ、主力艦の保有比率を定めた【海軍軍備制限条約】、中国の主権尊重と門戸開放を約した【九か国条約】、太平洋の現状維持を定めた【四か国条約】が結ばれた。これにより【日英同盟】は解消された。"},
  {"id": "whx198", "s": "wh", "lv": 1, "topic": "国際連盟", "q": "第一次世界大戦後に設立された国際連盟の特徴と、その問題点を述べよ。", "a": "アメリカ大統領【ウィルソン】の【十四か条】にもとづいて設立された。しかし提唱国のアメリカは上院の反対で参加せず、当初はドイツやソ連も除外された。議決は【全会一致】が原則で、制裁手段も【経済制裁】に限られたため、紛争を解決する力は弱かった。"},
  {"id": "whx199", "s": "wh", "lv": 1, "topic": "ガンディーの民族運動", "q": "第一次世界大戦後、ガンディーが指導したインドの民族運動について述べよ。", "a": "イギリスは戦後の自治を約束したが、【ローラット法】で民族運動を弾圧した。【ガンディー】は【非暴力・不服従】運動を指導し、1930年には【塩の行進】をおこなった。国民会議派は【プールナ=スワラージ】（完全独立）を決議した。"},
  {"id": "whx200", "s": "wh", "lv": 1, "topic": "五・四運動", "q": "1919年に中国でおこった五・四運動の背景と、その結果を述べよ。", "a": "パリ講和会議で、中国が求めた【二十一か条要求】の取り消しが退けられ、山東省の旧ドイツ権益の返還も認められなかった。これに抗議して北京の学生が立ち上がり、全国的な【反帝国主義】運動に発展した。中国政府は【ヴェルサイユ条約】の調印を拒否した。"},
  {"id": "whx201", "s": "wh", "lv": 2, "topic": "第1次国共合作", "q": "1920年代の中国で、第1次国共合作が成立し、崩壊した経緯を述べよ。", "a": "【孫文】は「連ソ・容共・扶助工農」をかかげ、1924年に中国国民党と中国共産党の【第1次国共合作】が成立した。孫文の死後、【蔣介石】が北伐を開始したが、1927年の【上海クーデタ】で共産党を弾圧し、合作は崩壊した。"},
  {"id": "whx202", "s": "wh", "lv": 1, "topic": "トルコ共和国", "q": "トルコ共和国の成立の経緯と、ムスタファ=ケマルがおこなった改革を述べよ。", "a": "第一次世界大戦後、【ムスタファ=ケマル】は連合国と結んだセーヴル条約に反対して戦い、【ローザンヌ条約】で新たな国境を認めさせ、1923年に【トルコ共和国】を樹立した。カリフ制の廃止や【政教分離】、文字改革、女性参政権など近代化を進めた。"},
  {"id": "whx203", "s": "wh", "lv": 2, "topic": "パレスチナ問題の起源", "q": "第一次世界大戦中のイギリス外交が、パレスチナ問題の原因となったことを述べよ。", "a": "イギリスは【フセイン・マクマホン協定】でアラブ人に独立を約束する一方、【サイクス・ピコ協定】で英仏露による中東分割を取り決め、【バルフォア宣言】でユダヤ人の民族的郷土建設を支持した。この矛盾した【三枚舌外交】がアラブ人とユダヤ人の対立を生んだ。"},
  {"id": "whx204", "s": "wh", "lv": 1, "topic": "イタリアのファシズム", "q": "第一次世界大戦後のイタリアで、ファシズム政権が成立した経緯を述べよ。", "a": "戦勝国でありながら領土拡大の要求が十分に認められず、戦後の不況で労働争議や社会不安が広がった。【ムッソリーニ】は【ファシスト党】を率いて、1922年の【ローマ進軍】で政権を握り、一党独裁体制を築いた。"},
  {"id": "whx205", "s": "wh", "lv": 1, "topic": "ナチ党の独裁", "q": "ドイツでナチ党が政権を獲得し、独裁体制を築いた過程を述べよ。", "a": "世界恐慌で失業者が急増すると、【ヒトラー】の率いるナチ党が支持を拡大し、1932年に第一党となった。1933年に首相となったヒトラーは【全権委任法】で立法権を握り、一党独裁を確立した。【ユダヤ人】を迫害し、ヴェルサイユ体制の打破をめざして【再軍備】を宣言した。"},
  {"id": "whx206", "s": "wh", "lv": 3, "topic": "ヴァイマル共和国", "q": "ヴァイマル共和国で民主政が定着しなかった理由を、経済の動きに触れて論ぜよ。", "a": "男女普通選挙や社会権を定めた【ヴァイマル憲法】をもったが、敗戦と巨額の賠償の負担を背負った。1923年の【ルール占領】で激しい【インフレーション】がおこって中間層が没落し、ドーズ案で一時安定したが、【世界恐慌】で経済が再び崩壊した。大統領緊急令に頼る政治のなかで議会は機能を失い、ナチ党の台頭を許した。"},
  {"id": "whx207", "s": "wh", "lv": 2, "topic": "宥和政策", "q": "1930年代後半にイギリスやフランスがとった宥和政策と、その結果を述べよ。", "a": "英仏はドイツとの戦争を避けるため、ヒトラーの要求に譲歩する【宥和政策】をとった。1938年の【ミュンヘン会談】で【ズデーテン地方】の割譲を認めたが、ドイツはチェコスロヴァキアを解体した。さらに【独ソ不可侵条約】を結んでポーランドに侵攻し、第二次世界大戦が始まった。"},
  {"id": "whx208", "s": "wh", "lv": 1, "topic": "連合国の戦後構想", "q": "第二次世界大戦中に、連合国が戦後の国際秩序についてどのような構想を示したかを述べよ。", "a": "1941年にローズヴェルトとチャーチルは【大西洋憲章】を発表し、領土不拡大や民族自決などをかかげた。1945年の【ヤルタ会談】ではドイツの戦後処理やソ連の対日参戦が決められ、同年には【国際連合】が発足した。"},
  {"id": "whx209", "s": "wh", "lv": 1, "topic": "国際連合の仕組み", "q": "1945年に発足した国際連合の仕組みについて、国際連盟と比べた特徴を述べよ。", "a": "【安全保障理事会】が強い権限をもち、軍事的な制裁も可能となった。米英仏ソ中の5大国が【常任理事国】となり、【拒否権】が与えられた。総会では全会一致ではなく【多数決】による議決が採用された。"},
  {"id": "whx210", "s": "wh", "lv": 1, "topic": "ブレトン=ウッズ体制", "q": "第二次世界大戦後の国際経済体制（ブレトン=ウッズ体制）について述べよ。", "a": "1930年代のブロック経済が戦争の一因となった反省から、【国際通貨基金】（IMF）と国際復興開発銀行を設立し、金と交換できる【ドル】を基軸通貨とする固定相場制をとった。また【GATT】（関税と貿易に関する一般協定）で自由貿易の推進がはかられた。"},
  {"id": "whx211", "s": "wh", "lv": 3, "topic": "1970年代の世界経済", "q": "1970年代に世界経済が大きく転換した理由を、ドル危機と石油危機から論ぜよ。", "a": "ベトナム戦争の戦費などでアメリカの国際収支が悪化し、1971年に【ニクソン】大統領はドルと金の交換を停止した。73年には主要国が【変動相場制】に移行し、ブレトン=ウッズ体制は崩壊した。同年の第4次中東戦争で【石油危機】がおこり、先進国の高度成長は終わった。先進国は【サミット】で経済政策を協議するようになった。"},
  {"id": "whx212", "s": "wh", "lv": 1, "topic": "中華人民共和国の成立", "q": "第二次世界大戦後の中国で、中華人民共和国が成立した経緯を述べよ。", "a": "日本の降伏後、国民党と共産党の【国共内戦】が再開された。土地改革で農民の支持を得た共産党が勝利し、1949年に【毛沢東】を主席とする【中華人民共和国】が成立した。敗れた【蔣介石】の国民党政府は台湾に逃れた。"},
  {"id": "whx213", "s": "wh", "lv": 2, "topic": "大躍進と文化大革命", "q": "毛沢東の時代の中国でおこった「大躍進」と文化大革命について述べよ。", "a": "1958年からの【大躍進】政策で【人民公社】を設立し急速な増産をめざしたが、無理な計画で多数の餓死者を出した。毛沢東は1966年に【プロレタリア文化大革命】をおこし、【紅衛兵】を動員して実権派を攻撃したため、社会は大混乱におちいった。"},
  {"id": "whx214", "s": "wh", "lv": 1, "topic": "改革開放", "q": "鄧小平の指導のもとで中国が進めた改革開放政策について述べよ。", "a": "【鄧小平】は人民公社を解体して農家の生産請負制を導入し、沿岸部に【経済特区】を設けて外国資本を導入した。1990年代には【社会主義市場経済】をかかげて急成長した。一方で政治の民主化は認めず、1989年の【天安門事件】で民主化運動を弾圧した。"},
  {"id": "whx215", "s": "wh", "lv": 1, "topic": "朝鮮戦争", "q": "1950年に始まった朝鮮戦争の経過と、その国際的な影響を述べよ。", "a": "北朝鮮が南北統一をめざして韓国に侵攻した。アメリカ軍を主力とする【国連軍】が韓国を、【中国人民義勇軍】が北朝鮮を支援して戦い、1953年に【休戦協定】が結ばれた。この戦争で冷戦はアジアに拡大し、日本は特需によって経済復興を進めた。"},
  {"id": "whx216", "s": "wh", "lv": 1, "topic": "ベトナム戦争", "q": "1960〜70年代のベトナム戦争の経過と、その結果を述べよ。", "a": "南ベトナム政府に対抗して【南ベトナム解放民族戦線】が結成されると、アメリカは1965年から【北爆】を開始して本格的に介入した。戦争は泥沼化して世界で反戦運動がおこり、1973年にアメリカ軍は撤退した。76年に南北が統一され【ベトナム社会主義共和国】が成立した。"},
  {"id": "whx217", "s": "wh", "lv": 2, "topic": "アジア=アフリカ会議", "q": "1955年に開かれたアジア=アフリカ会議の内容と、その意義を述べよ。", "a": "インドネシアの【バンドン】で29か国が参加して開かれ、反植民地主義と平和共存をかかげる【平和十原則】を採択した。前年の【ネルー・周恩来会談】で示された平和五原則を発展させたもので、東西どちらの陣営にも属さない【第三世界】の結集を示した。"},
  {"id": "whx218", "s": "wh", "lv": 1, "topic": "アフリカの年", "q": "1960年が「アフリカの年」とよばれる理由と、独立後のアフリカ諸国の課題を述べよ。", "a": "1960年にアフリカで17か国が独立したためである。独立後の諸国は、植民地時代に引かれた【国境線】が民族の分布と一致しないことから【民族対立】や内戦に苦しんだ。また、特定の一次産品に頼る【モノカルチャー経済】から抜け出せず、経済的な自立が課題となった。"},
  {"id": "whx219", "s": "wh", "lv": 2, "topic": "アパルトヘイト", "q": "南アフリカのアパルトヘイトとはどのような政策か、その撤廃の経緯とともに述べよ。", "a": "少数の白人が多数派の黒人などを支配するための【人種隔離政策】で、居住地や結婚、教育などを差別した。国際的な批判と【経済制裁】を受け、1991年に関連法が撤廃された。1994年の全人種参加の選挙で、アフリカ民族会議の【マンデラ】が大統領に就任した。"},
  {"id": "whx220", "s": "wh", "lv": 1, "topic": "中東戦争", "q": "第二次世界大戦後のイスラエルの建国と、それに続く中東戦争の展開を述べよ。", "a": "1947年の国連の【パレスチナ分割案】にもとづき、1948年にユダヤ人が【イスラエル】を建国した。これに反対するアラブ諸国との間で第1次中東戦争がおこり、多くのアラブ人が故郷を追われて【パレスチナ難民】となった。1967年の第3次中東戦争でイスラエルは占領地を拡大した。"},
  {"id": "whx221", "s": "wh", "lv": 3, "topic": "オスロ合意", "q": "1990年代のパレスチナ和平の進展と、その後も対立が続いた理由を論ぜよ。", "a": "【パレスチナ解放機構】（PLO）とイスラエルは1993年に【オスロ合意】を結んで相互に承認し、【パレスチナ暫定自治】が始まった。しかしラビン首相の暗殺や、イスラエルの入植地拡大、過激派のテロが続いて和平は停滞した。【エルサレム】の帰属や難民の帰還も未解決のままである。"},
  {"id": "whx222", "s": "wh", "lv": 3, "topic": "スエズ戦争", "q": "1956年のスエズ戦争が、中東の国際関係に与えた影響を論ぜよ。", "a": "エジプトの【ナセル】はアスワン=ハイダムの建設資金を得るため【スエズ運河の国有化】を宣言した。英仏とイスラエルが出兵して【第2次中東戦争】となったが、米ソや国際世論の非難を受けて撤退した。ナセルは【アラブ民族主義】の指導者として威信を高め、中東での英仏の影響力は低下し、米ソの影響力が強まった。"},
  {"id": "whx223", "s": "wh", "lv": 3, "topic": "ヨーロッパ統合", "q": "第二次世界大戦後のヨーロッパで経済統合が進められた理由と、その過程を論ぜよ。", "a": "独仏の対立を克服して平和を確保し、米ソに対抗できる経済力を得ることがめざされた。1952年に石炭と鉄鋼を共同管理する【ECSC】が発足し、67年にEECなどと統合して【EC】となった。93年の【マーストリヒト条約】で【EU】が発足し、のちに共通通貨【ユーロ】が導入された。"},
  {"id": "whx224", "s": "wh", "lv": 3, "topic": "東欧革命と冷戦の終結", "q": "1989年の東欧革命がおこった背景と、それが冷戦の終結に与えた影響を論ぜよ。", "a": "ソ連のゴルバチョフが【新思考外交】をかかげて東欧への内政干渉を否定すると、ポーランドの自主管理労組【連帯】などの民主化運動が広がり、各国で共産党政権が倒れた。【ベルリンの壁】が開放され、同年末の【マルタ会談】で米ソ首脳は冷戦の終結を宣言した。翌年、ドイツは統一された。"},
  {"id": "whx225", "s": "wh", "lv": 3, "topic": "デタント", "q": "1960〜70年代に米ソ関係が緊張緩和（デタント）に向かった理由と、その成果を論ぜよ。", "a": "キューバ危機で核戦争の危険が現実となり、米ソは直通通信回線を設け、1963年に【部分的核実験禁止条約】を結んだ。1968年には【核拡散防止条約】、72年には第1次【戦略兵器制限交渉】の協定が調印された。西ドイツのブラントによる【東方外交】も緊張緩和を進めた。"},
  {"id": "whx226", "s": "wh", "lv": 3, "topic": "南北問題", "q": "第二次世界大戦後に「南北問題」が生じた理由と、発展途上国の対応を論ぜよ。", "a": "独立後の発展途上国の多くは、植民地時代以来の【モノカルチャー経済】から抜け出せず、一次産品の価格低迷で先進国との格差が拡大した。途上国は【国連貿易開発会議】（UNCTAD）で改善を求め、1974年には国連で【新国際経済秩序】樹立宣言を採択させた。産油国は【石油輸出国機構】（OPEC）を通じて資源ナショナリズムを強めた。"},
  {"id": "whx227", "s": "wh", "lv": 3, "topic": "開発独裁とASEAN", "q": "1960年代以降の東南アジアにおける開発独裁と地域協力の展開を論ぜよ。", "a": "インドネシアの【スハルト】やフィリピンのマルコスらは、反共をかかげ、政治的自由を制限しつつ外資を導入して経済成長を進める【開発独裁】をおこなった。1967年に反共的な地域協力機構として【ASEAN】が結成されたが、冷戦後にはベトナムなども加盟し、経済協力を中心とする機構へと変化した。"},
  {"id": "whx228", "s": "wh", "lv": 3, "topic": "冷戦期のラテンアメリカ", "q": "冷戦期のラテンアメリカで、アメリカ合衆国がどのように影響力を行使したかを論ぜよ。", "a": "アメリカは1948年に【米州機構】（OAS）を結成し、反共体制を固めた。キューバ革命後は【カストロ】政権と対立し、ラテンアメリカ諸国への経済援助も進めた。1973年にはチリの社会主義政権である【アジェンデ】政権が軍部のクーデタで倒れ、アメリカの支持を受けた【軍事政権】が成立した。"},
  {"id": "whx229", "s": "wh", "lv": 1, "topic": "インド・パキスタンの分離独立", "q": "1947年にインドとパキスタンが分離して独立した経緯を述べよ。", "a": "独立運動のなかで、【全インド=ムスリム連盟】の指導者ジンナーはイスラーム国家の建設を主張した。そのため1947年の【インド独立法】により、ヒンドゥー教徒が多数を占める【インド】と、ムスリムが多数を占める【パキスタン】に分かれて独立した。カシミールの帰属をめぐる対立も続いた。"},
  {"id": "whx230", "s": "wh", "lv": 1, "topic": "東南アジア諸国の独立", "q": "第二次世界大戦後に東南アジア諸国が独立を達成した過程を、インドネシアとベトナムを例に述べよ。", "a": "インドネシアでは【スカルノ】が独立を宣言し、オランダとの戦争を経て1949年に独立が承認された。ベトナムでは【ホー=チ=ミン】がベトナム民主共和国の独立を宣言し、【インドシナ戦争】でフランスを破った。1954年の【ジュネーヴ休戦協定】で北緯17度線が暫定軍事境界線とされた。"},
  {"id": "whx231", "s": "wh", "lv": 2, "topic": "封じ込め政策", "q": "第二次世界大戦後にアメリカが進めた「封じ込め政策」の内容と、ソ連の対応を述べよ。", "a": "1947年にアメリカは【トルーマン=ドクトリン】でギリシア・トルコへの援助を表明し、【マーシャル=プラン】で西欧の経済復興を援助した。ソ連はこれに対抗して【コミンフォルム】を結成し、東欧諸国とコメコンを組織した。1949年には西側諸国が【NATO】を結成した。"},
  {"id": "whx232", "s": "wh", "lv": 2, "topic": "ドイツの東西分裂", "q": "第二次世界大戦後のドイツが、東西二つの国家に分裂した経緯を述べよ。", "a": "戦後のドイツは米英仏ソの4か国に分割占領された。西側占領地区での通貨改革にソ連が反発し、1948年に【ベルリン封鎖】をおこなった。1949年、西側に【ドイツ連邦共和国】、東側に【ドイツ民主共和国】が成立した。1961年には東ドイツが【ベルリンの壁】を築いた。"},
  {"id": "geox1", "s": "geo", "lv": 1, "topic": "西岸海洋性気候", "q": "西ヨーロッパは高緯度のわりに冬が温和である。その理由を説明せよ。", "a": "沖合を暖流の【北大西洋海流】が流れ、その上を通って暖められた空気を、一年中吹く【偏西風】が大陸西岸に運ぶため。その結果、気温の年較差が小さい【西岸海洋性気候】となる。"},
  {"id": "geox2", "s": "geo", "lv": 1, "topic": "赤道付近の多雨", "q": "赤道付近で一年中降水量が多くなるのはなぜか。", "a": "赤道付近は太陽からの熱を強く受けて地表の空気が暖められ、【上昇気流】が発達する。空気は上昇して冷えると雲をつくり、【熱帯収束帯（赤道低圧帯）】となって【スコール】などの多量の雨が降るため。"},
  {"id": "geox3", "s": "geo", "lv": 1, "topic": "回帰線付近の砂漠", "q": "南北の回帰線付近に大きな砂漠が分布するのはなぜか。", "a": "回帰線付近は赤道で上昇した空気が下降してくる【亜熱帯高圧帯】にあたる。【下降気流】のもとでは雲ができにくく、降水がきわめて少ないため、サハラ砂漠などの【砂漠気候】が広がる。"},
  {"id": "geox4", "s": "geo", "lv": 1, "topic": "海岸砂漠", "q": "ペルーやチリのアタカマ砂漠のように、海岸に砂漠ができるのはなぜか。", "a": "沖合を【寒流】（ペルー海流）が流れ、海面近くの空気が冷やされて下層が冷たく上層が暖かい【安定】した大気となる。そのため【上昇気流】が起こらず雨雲が発達しにくく、【海岸砂漠】が形成される。"},
  {"id": "geox5", "s": "geo", "lv": 1, "topic": "季節風", "q": "東アジアや南アジアで夏に雨が多いのはなぜか。季節風に着目して説明せよ。", "a": "夏は大陸が海洋より暖まりやすく大陸上が低圧になるため、海洋から大陸へ湿った【季節風（モンスーン）】が吹きこむ。この湿った風が【水蒸気】を運んで雨を降らせるため、夏に【雨季】となる。"},
  {"id": "geox6", "s": "geo", "lv": 1, "topic": "扇状地", "q": "扇状地の扇央が果樹園などに利用されることが多いのはなぜか。", "a": "扇央は【砂礫】が堆積してできており水はけがよく、河川が地下にもぐって【伏流】しやすいため水が得にくい。そのため水田には向かず、乾燥に強い【果樹園】や桑畑に利用されてきた。"},
  {"id": "geox7", "s": "geo", "lv": 1, "topic": "三角州", "q": "三角州はどのようにして形成されるか。また、その土地利用を説明せよ。", "a": "河川が海や湖に流れこむところで流速が落ち、運んできた細かい【砂や泥】が【堆積】して形成される。低平で水が得やすいため【水田】に利用され、大都市が発達することも多いが、【洪水】や高潮の被害を受けやすい。"},
  {"id": "geox8", "s": "geo", "lv": 1, "topic": "リアス海岸", "q": "リアス海岸はどのようにしてできたか。また、どのような産業に利用されているか。", "a": "山地の谷が【沈降】や海面上昇によって海に沈み、【溺れ谷】となって複雑な海岸線ができた。湾内は波がおだやかで水深があるため、【養殖業】や漁港に利用されるが、【津波】の被害を受けやすい。"},
  {"id": "geox9", "s": "geo", "lv": 1, "topic": "フィヨルド", "q": "ノルウェーなどに見られるフィヨルドの成因を説明せよ。", "a": "氷期に【氷河】が谷を削って断面が【U字谷】の深い谷をつくり、氷期が終わって氷河がとけ【海面上昇】が起こると、その谷に海水が入りこんで奥行きの長い細長い湾となった。"},
  {"id": "geox10", "s": "geo", "lv": 1, "topic": "日本海側の豪雪", "q": "冬に日本海側で雪が多くなる理由を説明せよ。", "a": "冬は【シベリア高気圧】から北西の【季節風】が吹き出す。この乾いた冷たい風が比較的暖かい【日本海】の上で水蒸気を補給され、山地にぶつかって上昇気流となり、日本海側に多量の雪を降らせるため。"},
  {"id": "geox11", "s": "geo", "lv": 1, "topic": "地中海式農業", "q": "地中海式農業ではどのような作物がつくられるか。気候と関連づけて説明せよ。", "a": "夏は高温で【乾燥】し、冬に雨が降る気候に合わせ、夏は乾燥に強い【オリーブ】やぶどう、柑橘類などの【樹木作物】を、降水のある冬には小麦などの穀物を栽培する。"},
  {"id": "geox12", "s": "geo", "lv": 1, "topic": "混合農業", "q": "ヨーロッパの混合農業とはどのような農業か説明せよ。", "a": "小麦などの【食用穀物】と、大麦・てんさいなどの【飼料作物】を【輪作】し、飼料で牛や豚などの【家畜】を飼育する農業。作物の栽培と家畜の飼育を組み合わせて地力を維持しながら経営する。"},
  {"id": "geox13", "s": "geo", "lv": 1, "topic": "酪農の立地", "q": "酪農が冷涼な地域や大都市の近郊で発達しやすい理由を説明せよ。", "a": "冷涼でやせた土地でも【牧草】はよく育つため、乳牛を飼う酪農に適している。また生乳は【鮮度】が重要で輸送しにくいため、消費地である【大都市】の近郊でも発達してきた。"},
  {"id": "geox14", "s": "geo", "lv": 1, "topic": "鉄鋼業の立地", "q": "日本の製鉄所が臨海部に立地している理由を説明せよ。", "a": "日本は【鉄鉱石】や【石炭】などの原料をほぼ輸入に頼っているため、大型船で原料を運びこみやすく、製品の輸出にも便利な【臨海部】の【港湾】付近に製鉄所が立地している。"},
  {"id": "geox15", "s": "geo", "lv": 1, "topic": "セメント工業", "q": "セメント工業が原料産地の近くに立地しやすいのはなぜか。", "a": "セメントの主原料である【石灰石】は、製品にすると重量が大きく減る【重量減損原料】で、原料の輸送費が大きいため。輸送費を節約できる【原料産地】（秩父など）に立地する【原料指向型】工業である。"},
  {"id": "geox16", "s": "geo", "lv": 1, "topic": "IC工業の立地", "q": "IC（集積回路）工場が空港や高速道路の近くに立地しやすいのはなぜか。", "a": "ICは小型・軽量で【付加価値】が高く、輸送費の負担が小さいため、【航空機】や高速道路のトラックで輸送しても採算がとれる。そのため地価が安く労働力も得やすい地方の【空港】や【高速道路】沿いに立地する。"},
  {"id": "geox17", "s": "geo", "lv": 1, "topic": "人口ピラミッド", "q": "日本の人口ピラミッドが富士山型からつぼ型へと変化した理由を説明せよ。", "a": "医療の発達などで【死亡率】が下がって平均寿命が延び、高齢者が増えた。一方、女性の社会進出や晩婚化などで【出生率】が低下したため、【少子高齢化】が進み、若い年齢層ほど人口の少ない【つぼ型】になった。"},
  {"id": "geox18", "s": "geo", "lv": 1, "topic": "ドーナツ化現象", "q": "大都市でみられたドーナツ化現象とはどのような現象か。", "a": "都心部の【地価】の高騰や環境悪化によって住民が【郊外】へ移り、都心部の【夜間人口】が減少して、周辺部の人口が増加する現象。都心は昼間人口が多く夜間人口が少なくなる。"},
  {"id": "geox19", "s": "geo", "lv": 1, "topic": "首位都市", "q": "発展途上国で首都などの一都市に人口が集中するのはなぜか。", "a": "農村では人口増加により仕事が不足し、多くの人が雇用や所得を求めて都市へ【人口流入】する。工業やサービス業、行政機能が一つの都市に集中しているため【首位都市（プライメートシティ）】が形成され、住環境の悪い【スラム】も生まれやすい。"},
  {"id": "geox20", "s": "geo", "lv": 1, "topic": "ヒートアイランド", "q": "大都市の気温が周辺より高くなるヒートアイランド現象の原因を説明せよ。", "a": "都市では地面が【アスファルト】やコンクリートに覆われて熱をため込み、緑地や水面が少ないため【蒸発】による冷却が弱い。さらにエアコンや自動車などの【人工排熱】が多いため、気温が周辺より高くなる。"},
  {"id": "geox21", "s": "geo", "lv": 1, "topic": "環太平洋造山帯", "q": "日本列島で地震や火山活動が多いのはなぜか。プレートの動きから説明せよ。", "a": "日本列島は【環太平洋造山帯】に位置し、太平洋プレートやフィリピン海プレートが大陸側のプレートの下に【沈み込む】【プレート境界】付近にあるため、地殻変動が活発で地震や火山活動が多い。"},
  {"id": "geox22", "s": "geo", "lv": 1, "topic": "安定陸塊", "q": "安定陸塊と新期造山帯では、地形にどのような違いがあるか。", "a": "【安定陸塊】は先カンブリア時代以降大きな造山運動を受けず、長い【侵食】で平坦な台地や平原が広がる。一方【新期造山帯】は現在も地殻変動が活発で、高く険しい山脈が連なり、地震や火山が多い。"},
  {"id": "geox23", "s": "geo", "lv": 1, "topic": "熱帯林の減少", "q": "アマゾンなどで熱帯林が減少している主な原因を説明せよ。", "a": "大規模な【牧場】や大豆畑の開発、木材を得るための【伐採】、道路建設にともなう入植、過度な【焼畑】などによって森林が切り開かれているため。熱帯林の減少は生物多様性の喪失や【地球温暖化】につながる。"},
  {"id": "geox24", "s": "geo", "lv": 1, "topic": "企業的穀物農業", "q": "アメリカやカナダで行われている企業的穀物農業の特色を説明せよ。", "a": "広大な土地で大型の【機械】を使い、小麦やとうもろこしなどを【大規模】に栽培する。少ない労働力で生産するため【労働生産性】が高く、生産物の多くを世界に【輸出】している。"},
  {"id": "geox25", "s": "geo", "lv": 2, "topic": "フェーン現象", "q": "山を越えて吹き降りる風が高温・乾燥になるフェーン現象のしくみを説明せよ。", "a": "湿った空気が山を上昇するとき、雲ができて雨を降らせ、水蒸気が凝結する際の【潜熱】で空気の温度低下がゆるやかになる（【湿潤断熱減率】）。山を越えて下降するときは【乾燥断熱減率】で大きく昇温するため、風下側は高温・乾燥になる。"},
  {"id": "geox26", "s": "geo", "lv": 2, "topic": "大陸東岸の気候", "q": "同じ緯度でも、ユーラシア大陸の東岸は西岸に比べて気温の年較差が大きい。その理由を説明せよ。", "a": "中緯度では【偏西風】が吹くため、東岸は大陸の影響を強く受ける。冬は大陸から寒冷な【季節風】が吹いて非常に寒く、夏は海洋からの季節風で高温になるため、【大陸性気候】の性格が強く【年較差】が大きくなる。"},
  {"id": "geox27", "s": "geo", "lv": 2, "topic": "河岸段丘", "q": "河岸段丘はどのようにして形成されるか説明せよ。", "a": "河川がつくった谷底平野が、土地の【隆起】や海面の低下によって河川の【下刻（侵食）】が再び強まると、川がより低い位置を流れるようになる。これがくり返されて、もとの谷底が【階段状】の平坦面（段丘面）として残る。"},
  {"id": "geox28", "s": "geo", "lv": 2, "topic": "カルスト地形", "q": "カルスト地形はどのようなしくみで形成されるか。", "a": "【石灰岩】の地域で、二酸化炭素を含む雨水や地下水が岩石を【溶食】することによって形成される。地表には【ドリーネ】などのくぼ地が、地下には【鍾乳洞】ができる。"},
  {"id": "geox29", "s": "geo", "lv": 2, "topic": "サンゴ礁", "q": "サンゴ礁が熱帯・亜熱帯の島の周りなどに分布する理由を説明せよ。", "a": "造礁サンゴは体内の褐虫藻が【光合成】を行うため、【水温】が高く、日光が届く【浅い】、濁りの少ない【澄んだ】海でしか生育できない。そのため河川からの土砂が流れこまない熱帯・亜熱帯の島の周りなどに発達する。"},
  {"id": "geox30", "s": "geo", "lv": 2, "topic": "永久凍土と高床", "q": "シベリアの建物が高床式になっていることが多い理由を説明せよ。", "a": "シベリアには一年中凍結した【永久凍土】が広がる。建物の暖房の熱が地面に伝わると凍土が【融解】して地盤が沈下し、建物が傾くおそれがあるため、【高床式】にして熱が地面に伝わらないようにしている。"},
  {"id": "geox31", "s": "geo", "lv": 2, "topic": "エルニーニョ現象", "q": "エルニーニョ現象とはどのような現象か。日本への影響もあわせて説明せよ。", "a": "太平洋赤道域で【貿易風】が弱まり、東部（ペルー沖）の【海面水温】が平年より高くなる現象。ペルー沖では寒流による湧昇が弱まって漁獲が減る。日本では【冷夏】や【暖冬】になりやすい。"},
  {"id": "geox32", "s": "geo", "lv": 2, "topic": "緑の革命", "q": "1960年代以降にアジアで進められた緑の革命の内容と、その課題を説明せよ。", "a": "米や小麦の【高収量品種】を導入し、【灌漑】設備や【化学肥料】・農薬を使って穀物の生産を大きく増やした。一方で、資金のある大規模農家が恩恵を受けやすく、【農民間の格差】の拡大や環境への負荷などの課題が生じた。"},
  {"id": "geox33", "s": "geo", "lv": 2, "topic": "センターピボット", "q": "アメリカのグレートプレーンズでは灌漑農業が地下水の問題を引き起こしている。その内容を説明せよ。", "a": "乾燥したグレートプレーンズでは【オガララ帯水層】の地下水をくみ上げ、回転式の【センターピボット】で散水して大規模に穀物を栽培している。しかし、くみ上げが補給量を上回っているため【地下水の枯渇】が懸念されている。"},
  {"id": "geox34", "s": "geo", "lv": 2, "topic": "適地適作", "q": "アメリカの農業における「適地適作」とはどのような考え方か。具体例をあげて説明せよ。", "a": "各地域の【気候】や土壌などの自然条件や市場との関係に最も適した作物を集中して栽培すること。例えば、冷涼な北部では【酪農】、中西部ではとうもろこしと大豆の【コーンベルト】、南部では【綿花】の栽培が行われる。"},
  {"id": "geox35", "s": "geo", "lv": 2, "topic": "プランテーション", "q": "プランテーション農業はどのようにして成立したか。その特色とあわせて説明せよ。", "a": "熱帯地域が欧米の【植民地】だった時代に、欧米の資本と現地の安い【労働力】を使い、輸出向けに天然ゴム・コーヒー・カカオなどの【商品作物】を大規模に【単一栽培】する農園として成立した。"},
  {"id": "geox36", "s": "geo", "lv": 2, "topic": "日本の食料自給率", "q": "日本の食料自給率（カロリーベース）が低下してきた理由を説明せよ。", "a": "食生活の【洋風化】で米の消費が減り、肉や油脂の消費が増えたが、それらや家畜の【飼料】の多くを輸入に頼っている。また【貿易自由化】で安い外国産の農産物が増え、農業の担い手の減少も進んだため。"},
  {"id": "geox37", "s": "geo", "lv": 2, "topic": "自動車工業", "q": "自動車工業の工場の周辺に多くの工場が集まる理由を説明せよ。", "a": "自動車は約3万点もの【部品】を組み立てて生産する【組立型工業】である。完成車工場が必要な部品を必要な時に受け取る【ジャストインタイム】方式をとるため、多くの【関連工場】が周辺に集まり【企業城下町】が形成される。"},
  {"id": "geox38", "s": "geo", "lv": 2, "topic": "産業の空洞化", "q": "1980年代後半以降、日本で産業の空洞化が問題となった理由を説明せよ。", "a": "【円高】の進行や国内の高い【人件費】を背景に、企業が生産拠点を安い労働力が得られるアジアなどの【海外】へ移した。その結果、国内の工場が減って雇用が失われ、地域の製造業が衰える【産業の空洞化】が起こった。"},
  {"id": "geox39", "s": "geo", "lv": 2, "topic": "輸出加工区", "q": "発展途上国が輸出加工区を設けて工業化をめざした理由を説明せよ。", "a": "関税の免除や税の優遇などで【外国企業】を誘致し、【資本】や技術を導入するため。豊富で安い【労働力】を生かして製品を輸出することで、外貨を獲得し【輸出指向型】の工業化を進めようとした。"},
  {"id": "geox40", "s": "geo", "lv": 2, "topic": "サンベルト", "q": "1970年代以降、アメリカで工業の中心がサンベルトへ移った理由を説明せよ。", "a": "北緯37度以南の【サンベルト】は温暖で、広い土地が安く、労働組合の組織率が低く【賃金】が安かった。州政府の誘致策もあり、【先端技術産業】や航空宇宙産業が進出し、【スノーベルト】に代わって工業の中心となった。"},
  {"id": "geox41", "s": "geo", "lv": 2, "topic": "人口転換", "q": "人口転換（人口革命）とはどのような過程か説明せよ。", "a": "経済発展にともない、人口動態が【多産多死】から、医療・衛生の改善で死亡率が下がる【多産少死】へ移り、人口が急増する。さらに教育の普及や都市化で出生率も下がり、【少産少死】へと移行する過程をいう。"},
  {"id": "geox42", "s": "geo", "lv": 2, "topic": "スプロール現象", "q": "大都市の郊外でみられるスプロール現象とはどのような現象で、何が問題か。", "a": "都市の拡大にともない、郊外で住宅や工場などが計画性なく【無秩序】に広がる現象。農地と住宅地が【虫食い】状に混在し、道路や下水道などの【都市基盤】の整備が追いつかないことが問題となる。"},
  {"id": "geox43", "s": "geo", "lv": 2, "topic": "インナーシティ問題", "q": "欧米の大都市でみられるインナーシティ問題について説明せよ。", "a": "都心周辺の古い市街地から、比較的豊かな層が【郊外】へ流出し、高齢者や低所得者、移民などが取り残される。その結果、建物の【老朽化】や治安の悪化、税収の減少が進み、地域が【スラム化】する問題。"},
  {"id": "geox44", "s": "geo", "lv": 2, "topic": "東南アジアの華人", "q": "東南アジアに華人が多く住み、経済的に大きな影響力をもつのはなぜか。", "a": "19世紀以降、中国の【福建】省や広東省などから、植民地での鉱山や農園の労働者、商人として多くの人々が移住した。彼らの子孫である【華人】は【商業】や金融業で成功し、各国の経済に大きな影響力をもつようになった。"},
  {"id": "geox45", "s": "geo", "lv": 2, "topic": "外来河川", "q": "エジプトでは砂漠気候にもかかわらず古くから農業が営まれてきた。その理由を説明せよ。", "a": "湿潤な地域に水源をもち、乾燥地域を貫いて流れる【外来河川】の【ナイル川】があるため。かつては定期的な【洪水】が肥沃な土を運び、現在はアスワンハイダムによる【灌漑】で農業が営まれている。"},
  {"id": "geox46", "s": "geo", "lv": 2, "topic": "乾燥地の塩害", "q": "乾燥地域の灌漑農業で塩害が起こるしくみを説明せよ。", "a": "乾燥地域では【蒸発】が盛んなため、過剰な【灌漑】で地下水位が上がると、土壌中の水が毛細管現象で地表に上がって蒸発し、水に溶けていた【塩分】が地表に集積する。こうして【土壌の塩性化】が進み、作物が育たなくなる。"},
  {"id": "geox47", "s": "geo", "lv": 2, "topic": "中国の経済特区", "q": "中国が1980年ごろから沿岸部に経済特区を設けた目的を説明せよ。", "a": "【改革開放政策】のもと、税の優遇などで【外国資本】や技術を導入し、輸出向けの工業化を進めるため。【シェンチェン（深圳）】など香港や台湾に近い南部の沿岸部に設けられ、その後の経済成長の起点となった。"},
  {"id": "geox48", "s": "geo", "lv": 2, "topic": "国際河川", "q": "ライン川がヨーロッパの経済にとって重要である理由を説明せよ。", "a": "ライン川は複数の国を流れ、条約で外国船の自由な航行が認められた【国際河川】である。流れが緩やかで水量が安定し【内陸水運】に適しているため、【ルール工業地域】などと河口の【ユーロポート】を結ぶ物流の大動脈となっている。"},
  {"id": "geox49", "s": "geo", "lv": 3, "topic": "地中海性気候の夏の乾燥", "q": "地中海性気候の地域で、夏に乾燥し冬に雨が多くなる理由を、大気大循環と関連づけて説明せよ。", "a": "大気の循環帯は太陽の【回帰】にともない季節によって南北に移動する。夏には【亜熱帯高圧帯】が高緯度側へ移動してその支配下に入るため乾燥し、冬には【偏西風】帯に入り、【温帯低気圧】や前線が通過して雨が多くなる。"},
  {"id": "geox50", "s": "geo", "lv": 3, "topic": "熱帯林の土壌", "q": "熱帯雨林は植物が非常に豊かだが、土壌はやせていることが多い。その理由を説明せよ。", "a": "高温多雨のため落葉などの有機物は微生物によってすぐに【分解】され、養分は植物にすぐ吸収されて【腐植層】が発達しにくい。さらに多量の雨で養分が【溶脱】され、鉄やアルミニウムの酸化物が残った赤色の【ラトソル】となるため。"},
  {"id": "geox51", "s": "geo", "lv": 3, "topic": "黒土地帯", "q": "ウクライナから黒海北岸にかけての地域が世界的な小麦の産地となっている理由を、土壌と気候から説明せよ。", "a": "この地域は【ステップ気候】の草原地帯で、草の根や枯れ草に由来する【腐植】が、降水が少なく流されにくいため厚く蓄積した、肥沃な黒色の【チェルノーゼム】が分布する。適度な降水と広大な平原もあり【小麦】の栽培に適している。"},
  {"id": "geox52", "s": "geo", "lv": 3, "topic": "モノカルチャー経済", "q": "アフリカの多くの国でみられるモノカルチャー経済の問題点を、その成立の背景とあわせて説明せよ。", "a": "【植民地】時代に宗主国向けの特定の農産物や鉱産資源の生産に特化させられたため成立した。少数の【一次産品】の輸出に依存するため、【国際価格】の変動や天候不順で国家収入が不安定になり、【交易条件】の悪化も受けやすい。"},
  {"id": "geox53", "s": "geo", "lv": 3, "topic": "青いバナナ", "q": "ヨーロッパで「青いバナナ（ブルーバナナ）」とよばれる地域に人口や産業が集中している理由を説明せよ。", "a": "イギリス南部からライン川流域を経て北イタリアに至る地域で、【ライン川】の水運や交通網に恵まれ、古くから商業・工業が発展してきた。【EU】の統合で国境を越えた移動が自由になり、ロンドンや【ルール】地方などの中心地が連なる経済の中核となっている。"},
  {"id": "geox54", "s": "geo", "lv": 3, "topic": "中国の地域格差", "q": "中国で沿海部と内陸部の経済格差が拡大した理由と、政府の対応を説明せよ。", "a": "【改革開放政策】で経済特区などの沿海部に外国資本が集中し、工業化と所得向上が急速に進んだ一方、内陸部は開発が遅れたため格差が拡大した。政府は【西部大開発】でインフラ整備などを進め、農村から都市への【出稼ぎ（農民工）】も多い。"},
  {"id": "geox55", "s": "geo", "lv": 3, "topic": "過疎と限界集落", "q": "日本の山間部などで過疎化が進むと、どのような問題が生じるか。", "a": "若者が都市へ流出して【高齢化】が進み、65歳以上が半数を超える【限界集落】が増える。地域の共同作業や祭りの維持が難しくなり、バスや病院、商店などの【生活サービス】が撤退し、【耕作放棄地】や荒廃した森林も増加する。"},
  {"id": "geox56", "s": "geo", "lv": 3, "topic": "仮想水", "q": "「仮想水（バーチャルウォーター）」の考え方から、日本の食料輸入の意味を説明せよ。", "a": "仮想水とは、輸入した農産物や畜産物を自国で生産したと仮定した場合に必要となる【水】の量のこと。日本は大量の食料を輸入することで、間接的に海外の【水資源】を大量に消費しており、輸出国の【水不足】の問題とも関わっている。"},
  {"id": "geox57", "s": "geo", "lv": 3, "topic": "オーストラリアの貿易", "q": "オーストラリアの主な貿易相手国がイギリスからアジア諸国へ変化した理由を説明せよ。", "a": "かつては【イギリス】の植民地として本国との結びつきが強かったが、イギリスの【EC加盟】で関係が弱まった。一方、日本や中国などアジアの工業化で【鉄鉱石】・石炭などの需要が高まり、白豪主義の撤廃と【多文化主義】もあってアジアとの結びつきが強まった。"},
  {"id": "geox58", "s": "geo", "lv": 3, "topic": "インドのICT産業", "q": "インドでICT（情報通信技術）産業が発展した理由を説明せよ。", "a": "理数系の教育水準が高い人材が豊富で、【英語】を話せる人が多く、【人件費】も比較的安い。またアメリカとの【時差】が約半日あるため、アメリカの夜間に業務を引き継げる。【ベンガルール】などに企業が集積している。"},
  {"id": "geox59", "s": "geo", "lv": 3, "topic": "ブラジルのバイオ燃料", "q": "ブラジルでさとうきびを原料とするバイオエタノールの生産が進められた理由と、その課題を説明せよ。", "a": "【石油危機】を機に、石油輸入への依存を減らすため、国内で豊富に栽培できる【さとうきび】から燃料をつくり、【フレックス燃料車】も普及した。一方で、農地の拡大による【森林破壊】や、食料との競合による価格上昇が課題となっている。"},
  {"id": "geox60", "s": "geo", "lv": 3, "topic": "熱帯低気圧の発達", "q": "熱帯低気圧が海面水温の高い海域で発達しやすく、上陸すると急速に衰える理由を説明せよ。", "a": "熱帯低気圧は、海面から蒸発した大量の【水蒸気】が上空で凝結するときに放出する【潜熱】をエネルギー源として発達する。上陸すると水蒸気の供給が絶たれ、地表との【摩擦】も大きくなるため衰える。"},
  {"id": "seikeix1", "s": "seikei", "lv": 1, "topic": "法の支配", "q": "「法の支配」とはどのような考え方か。「法治主義」との違いにもふれて説明せよ。", "a": "権力者も含めてすべての人が、【基本的人権】を保障する正しい内容の法に従うべきだという考え方で、【権力の濫用】を防ぐ。法の内容よりも法律に基づく手続きを重視した19世紀ドイツの【法治主義】（【形式的法治主義】）とは異なる。"},
  {"id": "seikeix2", "s": "seikei", "lv": 1, "topic": "三権分立", "q": "モンテスキューが唱えた三権分立とはどのような考え方か。", "a": "国家権力を【立法】・【行政】・【司法】の三つに分け、それぞれを別の機関に担当させて互いに【抑制と均衡】をはからせることで、権力の集中と濫用を防ぎ、国民の自由を守ろうとする考え方。『法の精神』で唱えられた。"},
  {"id": "seikeix3", "s": "seikei", "lv": 1, "topic": "ロックの社会契約説", "q": "ロックの社会契約説の内容を、抵抗権にふれて説明せよ。", "a": "人は生まれながらに生命・自由・財産を守る【自然権】をもつ。人々はその保障を確実にするため【社会契約】を結んで政府に権力を【信託】する。政府が自然権を侵害した場合、人民は【抵抗権（革命権）】によって政府を取りかえることができる。"},
  {"id": "seikeix4", "s": "seikei", "lv": 1, "topic": "日本国憲法の三大原理", "q": "日本国憲法の三大原理を挙げ、それぞれ簡潔に説明せよ。", "a": "政治のあり方を最終的に決める力が国民にあるとする【国民主権】、人が生まれながらにもつ権利を侵すことのできない永久の権利として保障する【基本的人権の尊重】、戦争を放棄し戦力をもたないとする【平和主義】の三つである。"},
  {"id": "seikeix5", "s": "seikei", "lv": 1, "topic": "違憲審査権", "q": "裁判所の違憲審査権とはどのような権限か。その意義も説明せよ。", "a": "法律や命令、処分などが【憲法】に適合するかどうかを判断する権限で、すべての裁判所がもつ。最終的な判断を下す最高裁判所は【憲法の番人】とよばれる。国会などによる【人権侵害】を防ぎ、【憲法の最高法規性】を守る意義がある。"},
  {"id": "seikeix6", "s": "seikei", "lv": 1, "topic": "衆議院の優越", "q": "衆議院に参議院より強い権限（衆議院の優越）が認められている理由を説明せよ。", "a": "衆議院は議員の【任期】が4年と参議院の6年より短く、任期途中の【解散】もあるため、選挙を通じて【民意】をより強く反映しやすいと考えられている。そのため【予算】の議決や首相の指名などで優越が認められている。"},
  {"id": "seikeix7", "s": "seikei", "lv": 1, "topic": "議院内閣制", "q": "日本の議院内閣制とはどのようなしくみか。内閣と国会の関係に着目して説明せよ。", "a": "内閣が【国会】の信任にもとづいて成立し、国会に対して【連帯責任】を負うしくみ。内閣総理大臣は国会議員の中から国会が指名し、衆議院が【内閣不信任】を決議すると、内閣は10日以内に衆議院を【解散】しない限り総辞職しなければならない。"},
  {"id": "seikeix8", "s": "seikei", "lv": 1, "topic": "アメリカの大統領制", "q": "アメリカの大統領制の特徴を、議院内閣制と比較して説明せよ。", "a": "大統領は国民が【間接選挙】で選び、議会から独立して行政権をもつ。議会は大統領を【不信任】できず、大統領も議会を解散できない。大統領は法案の提出権をもたないが、【教書】を送り、法案への【拒否権】をもつなど、【厳格な三権分立】がとられている。"},
  {"id": "seikeix9", "s": "seikei", "lv": 1, "topic": "生存権", "q": "日本国憲法第25条の生存権とはどのような権利か説明せよ。", "a": "すべての国民が「【健康で文化的な最低限度の生活】」を営む権利で、国に対して積極的な保障を求める【社会権】の一つである。国はこれを実現するため、【生活保護】などの【社会保障】制度を整備する責任を負う。"},
  {"id": "seikeix10", "s": "seikei", "lv": 1, "topic": "小選挙区制", "q": "衆議院議員選挙などで採用されている小選挙区制の長所と短所を説明せよ。", "a": "一つの選挙区から1人を選ぶ制度で、【二大政党制】になりやすく政局が安定しやすい。一方で、落選者に投じられた【死票】が多くなり、【少数意見】が議席に反映されにくい。"},
  {"id": "seikeix11", "s": "seikei", "lv": 1, "topic": "比例代表制", "q": "選挙制度のうち、比例代表制の長所と短所を小選挙区制と比べて説明せよ。", "a": "政党の【得票率】に応じて議席を配分する制度で、【死票】が少なく、多様な民意を議席に反映しやすい。一方で、【小党分立】になりやすく、【連立政権】となって政局が不安定になりやすい。"},
  {"id": "seikeix12", "s": "seikei", "lv": 1, "topic": "民主主義の学校", "q": "ブライスが「地方自治は民主主義の学校である」と述べたのはなぜか。", "a": "住民が身近な地域の問題に直接関わり、【住民自治】を実践することで、政治に参加する力や責任感が養われる。こうした経験が国の【民主主義】を支える基礎となると考えたため。日本では【直接請求権】などで住民の参加が保障されている。"},
  {"id": "seikeix13", "s": "seikei", "lv": 1, "topic": "市場メカニズム", "q": "市場で商品の価格はどのように決まるか。需要と供給の関係から説明せよ。", "a": "価格が高いと【需要】は減り【供給】は増え、売れ残りが生じて価格が下がる。逆に価格が低いと品不足になり価格が上がる。こうして需要量と供給量が一致する【均衡価格】に落ちつく。このはたらきを【価格の自動調節機能】という。"},
  {"id": "seikeix14", "s": "seikei", "lv": 1, "topic": "寡占と管理価格", "q": "寡占市場で価格が下がりにくくなる理由を説明せよ。", "a": "少数の企業が市場を支配する【寡占】市場では、有力企業が【プライス・リーダー】として価格を決め、他社が追随する【管理価格】が形成されやすい。企業は価格競争を避けて広告などの【非価格競争】を行うため、価格が下がりにくい（【価格の下方硬直性】）。"},
  {"id": "seikeix15", "s": "seikei", "lv": 1, "topic": "外部不経済", "q": "「外部不経済」とは何か。具体例をあげて説明せよ。", "a": "ある経済主体の活動が、【市場】での取引を通さずに第三者に不利益を与えること。例えば工場の排煙による【公害】で周辺住民が健康被害を受ける場合など。費用が価格に反映されないため、【市場の失敗】の一つとされる。"},
  {"id": "seikeix16", "s": "seikei", "lv": 1, "topic": "公共財", "q": "公共財が市場では十分に供給されないのはなぜか。", "a": "公共財は、多くの人が同時に利用できる【非競合性】と、対価を払わない人の利用を防げない【非排除性】をもつ。【フリーライダー】が生じて企業は利益を得にくいため市場では供給されず、【政府】が税金で供給する必要がある。"},
  {"id": "seikeix17", "s": "seikei", "lv": 1, "topic": "インフレーション", "q": "インフレーションは人々の生活にどのような影響を与えるか。", "a": "物価が継続的に上昇すると【貨幣価値】が下がるため、【預貯金】の実質的な価値が目減りし、賃金や年金など【定額所得者】の生活が苦しくなる。一方、借金の実質的な負担は軽くなるため、【債務者】には有利になる。"},
  {"id": "seikeix18", "s": "seikei", "lv": 1, "topic": "累進課税", "q": "所得税に累進課税制度が採用されている目的を説明せよ。", "a": "所得が多い人ほど高い【税率】を適用することで、負担能力に応じた【垂直的公平】を実現し、【所得の再分配】によって経済的な【格差】を縮小することを目的としている。景気を安定させる効果もある。"},
  {"id": "seikeix19", "s": "seikei", "lv": 1, "topic": "日本銀行の役割", "q": "日本の中央銀行である日本銀行が果たしている三つの役割を説明せよ。", "a": "日本銀行券を独占的に発行する【発券銀行】、市中の金融機関と取引し資金の貸し出しや預金の受け入れを行う【銀行の銀行】、国の資金を出し入れし国庫金を管理する【政府の銀行】という三つの役割をもつ。"},
  {"id": "seikeix20", "s": "seikei", "lv": 1, "topic": "比較生産費説", "q": "リカードの比較生産費説の内容を説明せよ。", "a": "各国が他国に比べて相対的に安く生産できる【比較優位】をもつ財の生産に【特化】し、互いに【貿易】すれば、両国全体の生産量が増えて双方が利益を得られるという説。【自由貿易】を支持する根拠となった。"},
  {"id": "seikeix21", "s": "seikei", "lv": 1, "topic": "円高の影響", "q": "円高は日本の輸出産業にどのような影響を与えるか説明せよ。", "a": "円高になると、外国から見た日本製品の【ドル建て価格】が上がるため、日本製品の価格競争力が落ちて【輸出】が不利になる。輸出企業の円に換算した売上が減るため、生産拠点を【海外】に移す動きも強まる。"},
  {"id": "seikeix22", "s": "seikei", "lv": 1, "topic": "社会保障制度", "q": "日本の社会保障制度の四つの柱を説明せよ。", "a": "保険料を出し合い病気や老齢などに備える【社会保険】、生活困窮者に最低限度の生活を保障する【公的扶助】、高齢者や障害者などを支援する【社会福祉】、感染症予防などで国民の健康を守る【公衆衛生】の四つである。"},
  {"id": "seikeix23", "s": "seikei", "lv": 1, "topic": "安保理の拒否権", "q": "国連安全保障理事会の拒否権とは何か。また、その問題点を説明せよ。", "a": "安保理の実質事項の決定には、【常任理事国】5か国すべての同意が必要とされ、1か国でも反対すれば決議できない。これを【拒否権】という。大国の利害が対立すると安保理が機能せず、【紛争】に有効に対処できないことがある。"},
  {"id": "seikeix24", "s": "seikei", "lv": 1, "topic": "汚染者負担の原則", "q": "公害対策における汚染者負担の原則（PPP）とはどのような考え方か。", "a": "公害の防止や被害の救済にかかる費用は、汚染を引き起こした【汚染者】が負担すべきだという考え方。費用を製品の価格に反映させて【外部不経済】を内部化させる。日本の公害健康被害補償法などにも取り入れられた。また故意・過失がなくても責任を負う【無過失責任】も導入された。"},
  {"id": "seikeix25", "s": "seikei", "lv": 2, "topic": "一票の格差", "q": "「一票の格差」とは何か。それが問題とされる理由を説明せよ。", "a": "選挙区によって議員1人あたりの有権者数が異なるため、有権者の一票の重みに差が生じること。憲法の【法の下の平等】に反するおそれがあり、最高裁は【違憲状態】や【違憲】の判決を出している。【議員定数】の是正が求められている。"},
  {"id": "seikeix26", "s": "seikei", "lv": 2, "topic": "プライバシーの権利", "q": "新しい人権としてのプライバシーの権利は、どのように変化してきたか。", "a": "当初は「私生活をみだりに公開されない権利」とされ、『宴のあと』事件などで認められた。情報化の進展にともない、自分の情報を自ら管理する【自己情報コントロール権】として捉えられるようになり、【個人情報保護法】が制定された。憲法第13条の【幸福追求権】が根拠とされる。"},
  {"id": "seikeix27", "s": "seikei", "lv": 2, "topic": "公共の福祉", "q": "日本国憲法における「公共の福祉」とはどのような考え方か。", "a": "人権どうしが衝突した場合にそれを【調整】するための原理であり、人権も無制限ではないことを示す。特に【経済の自由】は、社会的・経済的弱者を守るため、【精神の自由】よりも広い制約を受けるとされる（【二重の基準】）。"},
  {"id": "seikeix28", "s": "seikei", "lv": 2, "topic": "刑事手続の保障", "q": "日本国憲法が刑事手続について詳細な人権保障を定めている理由と、その内容を説明せよ。", "a": "戦前に特高警察などによる不当な逮捕や拷問が行われた反省から、法律の定める手続きによらなければ刑罰を科されない【法定手続きの保障】、法律がなければ罰せられない【罪刑法定主義】、裁判官の令状がなければ逮捕されない【令状主義】、【黙秘権】などを定めている。"},
  {"id": "seikeix29", "s": "seikei", "lv": 2, "topic": "内閣不信任と解散", "q": "衆議院の内閣不信任決議と衆議院の解散の関係を、憲法の規定にもとづいて説明せよ。", "a": "憲法第69条により、衆議院で【内閣不信任】案が可決されると、内閣は10日以内に衆議院を【解散】するか【総辞職】しなければならない。解散の場合、40日以内に【総選挙】が行われ、その後の特別国会で内閣は総辞職する。"},
  {"id": "seikeix30", "s": "seikei", "lv": 2, "topic": "司法権の独立", "q": "司法権の独立とは何か。それを保障するしくみを説明せよ。", "a": "裁判所が国会や内閣など他の権力から干渉を受けず、裁判官が【良心】に従い憲法と法律にのみ拘束されて裁判を行うこと。裁判官は【身分保障】され、【弾劾裁判】や心身の故障などの場合を除いて罷免されない。【大津事件】が先例とされる。"},
  {"id": "seikeix31", "s": "seikei", "lv": 2, "topic": "三位一体の改革", "q": "2000年代に行われた「三位一体の改革」の内容と、そのねらいを説明せよ。", "a": "国から地方への【補助金】の削減、【地方交付税】の見直し、国から地方への【税源移譲】の三つを一体的に行った改革。地方の財政的な自立を高め、【地方分権】を進めることがねらいだったが、地方の財源不足が問題となった。"},
  {"id": "seikeix32", "s": "seikei", "lv": 2, "topic": "55年体制", "q": "55年体制とはどのような政治体制であったか説明せよ。", "a": "1955年に左右の社会党が統一し、保守政党も合同して【自由民主党】が結成されたことで成立した体制。自民党が長期にわたり政権を担当し、野党第一党の【日本社会党】が改憲阻止に必要な3分の1程度の議席をもった。1993年の【非自民連立政権】の成立で崩壊した。"},
  {"id": "seikeix33", "s": "seikei", "lv": 2, "topic": "財政の三機能", "q": "政府が行う経済活動である財政には、どのような三つの機能があるか説明せよ。", "a": "道路や警察など市場では供給されにくい公共財を供給する【資源配分機能】、累進課税や社会保障で所得格差を縮める【所得再分配機能】、財政政策で景気の変動をやわらげる【経済安定化機能（景気調整機能）】の三つである。"},
  {"id": "seikeix34", "s": "seikei", "lv": 2, "topic": "ビルトイン・スタビライザー", "q": "ビルトイン・スタビライザー（自動安定化装置）のしくみを説明せよ。", "a": "財政に組み込まれた制度が景気を自動的に安定させるしくみ。好況期には【累進課税】によって税収が増え、失業者が減って【社会保障】の支出が減るため、景気の過熱が抑えられる。不況期にはその逆に作用して、【有効需要】の減少を和らげる。"},
  {"id": "seikeix35", "s": "seikei", "lv": 2, "topic": "国債の問題点", "q": "国債を大量に発行することの問題点を説明せよ。", "a": "国債の元利払いにあてる【国債費】が増えて、他の政策に使える予算が減る【財政の硬直化】が起こる。また、返済の負担を将来の世代に先送りする【世代間の不公平】や、民間の資金需要と競合して金利が上がる【クラウディング・アウト】などの問題がある。"},
  {"id": "seikeix36", "s": "seikei", "lv": 2, "topic": "公開市場操作", "q": "日本銀行の公開市場操作によって、景気はどのように調整されるか説明せよ。", "a": "不況時には日銀が金融機関から国債などを買う【買いオペレーション】で資金を供給し、市場金利を下げて企業の借り入れや投資を促す。景気過熱時には【売りオペレーション】で資金を吸収し、【金利】を上げて景気を抑える。"},
  {"id": "seikeix37", "s": "seikei", "lv": 2, "topic": "信用創造", "q": "銀行の信用創造とはどのようなしくみか説明せよ。", "a": "銀行が受け入れた預金の一部を【支払準備金】として残し、残りを貸し出す。貸し出された資金は再び別の銀行に【預金】され、さらに貸し出される。これがくり返されることで、最初の預金の何倍もの【預金通貨】が生み出されるしくみ。"},
  {"id": "seikeix38", "s": "seikei", "lv": 2, "topic": "デフレスパイラル", "q": "デフレスパイラルとはどのような状況か説明せよ。", "a": "物価の下落によって企業の【売上】や利益が減り、【賃金】の引き下げや雇用の削減が行われる。その結果、家計の所得が減って消費が落ち込み、さらに物価が下落する。このように物価下落と【景気後退】が悪循環を起こす状況をいう。"},
  {"id": "seikeix39", "s": "seikei", "lv": 2, "topic": "直接金融と間接金融", "q": "企業が資金を調達する方法としての直接金融と間接金融の違いを説明せよ。", "a": "【直接金融】は、企業が【株式】や社債を発行して、資金の出し手から直接資金を調達する方法。【間接金融】は、家計の預金などを【銀行】が仲立ちして企業に貸し出す方法で、戦後の日本では間接金融の比重が高かった。"},
  {"id": "seikeix40", "s": "seikei", "lv": 2, "topic": "経常収支", "q": "近年の日本の経常収支の特徴を、その内訳から説明せよ。", "a": "かつては【貿易収支】の大幅な黒字が経常収支の黒字を支えていたが、近年は燃料輸入の増加や生産拠点の海外移転で貿易収支の黒字が縮小し、赤字の年もある。一方、海外への投資から得る配当や利子などの【第一次所得収支】の黒字が大きく、【経常収支】の黒字を支えている。"},
  {"id": "seikeix41", "s": "seikei", "lv": 2, "topic": "ニクソン・ショック", "q": "ブレトン・ウッズ体制が崩壊し、変動相場制へ移行した経緯を説明せよ。", "a": "アメリカはベトナム戦争や貿易収支の悪化で【ドル】が大量に流出し、金の保有量が減少した。1971年、ニクソン大統領は【金とドルの交換停止】を発表した（【ニクソン・ショック】）。スミソニアン協定による調整も失敗し、1973年に主要国は【変動相場制】へ移行した。"},
  {"id": "seikeix42", "s": "seikei", "lv": 2, "topic": "GATTの原則", "q": "GATT（関税と貿易に関する一般協定）が掲げた三原則を説明せよ。", "a": "関税を引き下げ貿易制限を減らす【自由】、ある国に与えた最も有利な貿易条件をすべての加盟国に適用する【最恵国待遇】などの【無差別】、多国間の交渉（ラウンド）で貿易ルールを決める【多角】の三原則である。"},
  {"id": "seikeix43", "s": "seikei", "lv": 2, "topic": "南北問題", "q": "南北問題とは何か。発展途上国の経済構造にふれながら、その背景を説明せよ。", "a": "主に北半球に多い先進国と、南半球に多い発展途上国との間の【経済格差】の問題。途上国の多くは植民地時代から特定の【一次産品】の輸出に依存する【モノカルチャー経済】で、工業製品に比べて一次産品の価格が低迷しがちなため、格差が拡大した。"},
  {"id": "seikeix44", "s": "seikei", "lv": 2, "topic": "ケインズの有効需要", "q": "ケインズが唱えた有効需要の原理と、それにもとづく政策を説明せよ。", "a": "一国の生産量や雇用量は、貨幣の支出をともなう【有効需要】の大きさによって決まるとした。不況で失業が生じるのは有効需要が不足しているためであり、政府が【公共投資】などで積極的に市場に介入して需要を創出すべきだと主張し、【大きな政府】の理論的根拠となった。"},
  {"id": "seikeix45", "s": "seikei", "lv": 2, "topic": "労働三権", "q": "労働三権の内容と、それが保障されている理由を説明せよ。", "a": "労働者が労働組合をつくる【団結権】、使用者と労働条件について交渉する【団体交渉権】、ストライキなどを行う【団体行動権（争議権）】の三つ。個々の労働者は使用者に比べて弱い立場にあるため、団結して【対等】に交渉できるように保障されている。"},
  {"id": "seikeix46", "s": "seikei", "lv": 2, "topic": "消費税の逆進性", "q": "消費税にはしばしば「逆進性」があると指摘される。その意味を説明せよ。", "a": "消費税は所得に関係なく同じ【税率】で課されるが、低所得者ほど所得に占める【消費】の割合が高いため、所得に対する税負担の割合が重くなる。これを【逆進性】という。対策として食料品などに【軽減税率】が導入された。"},
  {"id": "seikeix47", "s": "seikei", "lv": 2, "topic": "情報の非対称性", "q": "「情報の非対称性」が市場の失敗をもたらす理由を、具体例をあげて説明せよ。", "a": "売り手と買い手の間で商品についての【情報】に差がある状態をいう。例えば中古車市場では、買い手が品質を見分けられないため良質な商品が適正に評価されず、粗悪な商品ばかりが出回る【逆選択】が起こり、市場がうまく機能しなくなる。そのため【市場の失敗】とされる。"},
  {"id": "seikeix48", "s": "seikei", "lv": 2, "topic": "集団安全保障", "q": "国際連合の集団安全保障は、勢力均衡とどのように異なるか説明せよ。", "a": "【勢力均衡】は対立する国家群が軍事力を均衡させて戦争を防ぐ方式だが、軍拡競争を招きやすい。【集団安全保障】は対立国も含めて国際機構に加盟し、侵略などを行った国に対して全加盟国が協力して【制裁】を加える方式で、国際連合では【安全保障理事会】が中心となる。"},
  {"id": "seikeix49", "s": "seikei", "lv": 3, "topic": "統治行為論", "q": "統治行為論とはどのような考え方か。それに対する批判もあわせて説明せよ。", "a": "国家の統治の基本に関わる【高度な政治性】をもつ国家行為については、裁判所は【司法審査】の対象外とすべきだとする考え方。【砂川事件】の最高裁判決などで用いられた。しかし、裁判所が【違憲審査権】の行使を回避し、憲法による統制を弱めるとの批判がある。"},
  {"id": "seikeix50", "s": "seikei", "lv": 3, "topic": "非伝統的金融政策", "q": "日本銀行が量的緩和政策などの非伝統的な金融政策をとった理由と、その限界を説明せよ。", "a": "デフレ下で政策金利がほぼゼロまで下がり、金利の引き下げという通常の手段が使えなくなったため、日銀は【量的緩和】で国債などを大量に買い入れ、【マネタリーベース】を増やした。しかし資金需要が弱いと貸出が増えず、【流動性の罠】のように効果が限られ、【物価上昇】目標の達成には時間がかかった。"},
  {"id": "seikeix51", "s": "seikei", "lv": 3, "topic": "国際金融のトリレンマ", "q": "国際金融のトリレンマとは何か説明せよ。", "a": "【為替相場の安定（固定相場制）】、【自由な資本移動】、【金融政策の独立性】の三つを同時に実現することはできず、いずれか二つしか選べないという理論。例えばユーロ圏の各国は固定相場と資本移動の自由を選び、独自の金融政策を放棄している。"},
  {"id": "seikeix52", "s": "seikei", "lv": 3, "topic": "プライマリーバランス", "q": "日本の財政健全化で、プライマリーバランスの黒字化が目標とされる理由を説明せよ。", "a": "【プライマリーバランス（基礎的財政収支）】は、国債費を除く歳出を、国債発行以外の税収などでまかなえているかを示す。これが黒字化すれば、政策的経費を借金に頼らずに済み、経済成長率が金利を上回れば【債務残高】の対【GDP】比を安定的に引き下げられるため。"},
  {"id": "seikeix53", "s": "seikei", "lv": 3, "topic": "リーマン・ショック", "q": "2008年の世界金融危機（リーマン・ショック）が世界的に広がった理由を説明せよ。", "a": "アメリカで信用力の低い人向けの【サブプライムローン】が、他の債権と組み合わせて【証券化】され、世界中の金融機関に販売されていた。住宅価格の下落で返済が滞ると、これらの証券の価値が暴落し、大手証券会社の【リーマン・ブラザーズ】が破綻。【金融のグローバル化】により危機が世界に波及した。"},
  {"id": "seikeix54", "s": "seikei", "lv": 3, "topic": "新自由主義", "q": "1980年代に広がった新自由主義の考え方と、その具体的な政策を説明せよ。", "a": "政府の市場介入や福祉を拡大した大きな政府が財政赤字や経済の停滞を招いたと批判し、市場の機能を重視して【小さな政府】を目指す考え方。イギリスの【サッチャー】政権やアメリカのレーガン政権が、【規制緩和】や国営企業の【民営化】、減税を進めた。"},
  {"id": "seikeix55", "s": "seikei", "lv": 3, "topic": "FTAの増加", "q": "WTO体制のもとで、二国間や地域間のFTA・EPAが増えている理由を説明せよ。", "a": "【WTO】は全会一致を原則とし、加盟国の増加で利害が対立して、【ドーハ・ラウンド】の交渉が停滞した。そのため各国は、合意しやすい特定の国や地域との間で関税を撤廃する【FTA】や、投資・人の移動なども含む【EPA】を結んで、貿易の自由化を進めている。"},
  {"id": "seikeix56", "s": "seikei", "lv": 3, "topic": "少子高齢化と年金", "q": "日本の公的年金制度が少子高齢化によって抱える課題を、財政方式に着目して説明せよ。", "a": "日本の公的年金は、現役世代の保険料で高齢者の年金をまかなう【賦課方式】を基本としている。少子高齢化で年金受給者が増え、支え手の【現役世代】が減ると、保険料負担が重くなる。そのため【マクロ経済スライド】で給付を抑制するなど、【世代間の公平】の確保が課題となっている。"},
  {"id": "seikeix57", "s": "seikei", "lv": 3, "topic": "立憲主義", "q": "立憲主義とはどのような考え方か。民主主義との関係にもふれて説明せよ。", "a": "【憲法】によって国家権力を制限し、国民の【基本的人権】を保障しようとする考え方。民主主義のもとでも、多数派が少数者の人権を侵害するおそれがあるため、憲法は【多数決】でも侵せない価値を定め、権力を縛る役割を果たす。改正に特別な手続きを求める【硬性憲法】もその表れである。"},
  {"id": "seikeix58", "s": "seikei", "lv": 3, "topic": "Jカーブ効果", "q": "円安になっても、すぐには日本の貿易収支が改善しないことがある。その理由を説明せよ。", "a": "円安直後は、すでに結ばれた契約にもとづいて取引が行われ、輸出入の【数量】がすぐには変化しない。そのため、外貨建ての輸入品の【円建て価格】が上昇する効果が先に表れ、貿易収支が一時的に悪化する。時間がたつと輸出数量が増えて改善に向かう。これを【Jカーブ効果】という。"},
  {"id": "seikeix59", "s": "seikei", "lv": 3, "topic": "バブル崩壊と不良債権", "q": "1990年代の日本で、バブル崩壊後に景気低迷が長期化した理由を説明せよ。", "a": "バブル期に土地や株を担保に行われた過剰な融資が、【地価】や株価の暴落で回収できなくなり、銀行は多額の【不良債権】を抱えた。銀行が【貸し渋り】を行い、企業も投資を控えたため経済が停滞し、【失われた10年】とよばれる長期不況となった。"},
  {"id": "seikeix60", "s": "seikei", "lv": 3, "topic": "集団的自衛権", "q": "集団的自衛権とは何か。日本政府の解釈の変化をふまえて説明せよ。", "a": "密接な関係にある他国への武力攻撃を、自国が攻撃されていなくても実力で阻止する権利で、【国連憲章】第51条で認められている。日本政府は従来、憲法上行使できないとしてきたが、2014年の【閣議決定】で【存立危機事態】に限り行使できると解釈を変更し、翌年【安全保障関連法】が成立した。"},
  {"id": "rinrix1", "s": "rinri", "lv": 1, "topic": "無知の知", "q": "ソクラテスの「無知の知」とはどのような考え方か説明せよ。", "a": "自分が大切な事柄について何も知らないことを自覚することこそが、真の知への出発点であるという考え方。ソクラテスは対話を通して相手に無知を自覚させる【問答法（助産術）】を用い、【魂への配慮】を説いて「【善く生きる】」ことを求めた。これを【無知の知】という。"},
  {"id": "rinrix2", "s": "rinri", "lv": 1, "topic": "イデア論", "q": "プラトンのイデア論とはどのような考え方か説明せよ。", "a": "感覚でとらえられる現実の世界は変化する不完全な【現象界】にすぎず、その背後に、理性によってのみとらえられる永遠不変の真の実在である【イデア】の世界（【イデア界】）があるとする考え方。最高のイデアは【善のイデア】とされた。"},
  {"id": "rinrix3", "s": "rinri", "lv": 1, "topic": "中庸", "q": "アリストテレスの説いた「中庸」とはどのようなものか説明せよ。", "a": "感情や行為において、過剰と不足の両極端を避けた適切な状態のこと。例えば勇気は無謀と臆病の【中庸】である。正しい行為をくり返して【習慣】づけることで身につく【習性的徳（倫理的徳）】とされた。"},
  {"id": "rinrix4", "s": "rinri", "lv": 1, "topic": "仁と礼", "q": "孔子が説いた「仁」と「礼」について、その関係を説明せよ。", "a": "【仁】は人を愛する心で、親子・兄弟間の自然な親愛の情である【孝悌】を基本とする内面的な徳である。【礼】は仁が外に表れた社会的な規範であり、孔子は自己の欲望を抑えて礼に従う【克己復礼】が仁であると説いた。"},
  {"id": "rinrix5", "s": "rinri", "lv": 1, "topic": "性善説", "q": "孟子の性善説の内容を、四端の説にふれて説明せよ。", "a": "人間は生まれつき善い性質をもつという考え方。人には他人の不幸を見過ごせない【惻隠の心】など四つの心の芽生え（【四端】）が備わっており、これを育てれば仁・義・礼・智の【四徳】が完成するとした。"},
  {"id": "rinrix6", "s": "rinri", "lv": 1, "topic": "性悪説", "q": "荀子の性悪説の内容と、そこから導かれる政治思想を説明せよ。", "a": "人間は生まれつき利益を好み欲望にまかせて争う【悪】の性質をもつとした。そのため、外から【礼】によって人間の性質を矯正する必要があると説き、礼による統治である【礼治主義】を主張した。後の【法家】の思想に影響を与えた。"},
  {"id": "rinrix7", "s": "rinri", "lv": 1, "topic": "無為自然", "q": "老子の「無為自然」とはどのような考え方か説明せよ。", "a": "万物を生み出す根源である【道（タオ）】に従い、人為的なはからいを捨てて、あるがままに生きるべきだという考え方。儒家の説く仁義などの道徳は、道が失われたことによる人為的なものだと批判し、【柔弱謙下】の生き方や、小さな共同体である【小国寡民】を理想とした。"},
  {"id": "rinrix8", "s": "rinri", "lv": 1, "topic": "四諦", "q": "ブッダ（ゴータマ・シッダッタ）が説いた四諦の内容を説明せよ。", "a": "人生は【苦】であるという苦諦、苦の原因は【煩悩】（渇愛）であるという集諦、煩悩を滅すれば苦のない【涅槃】の境地に至るという滅諦、そのための正しい修行の道である【八正道】を説く道諦の四つの真理である。"},
  {"id": "rinrix9", "s": "rinri", "lv": 1, "topic": "方法的懐疑", "q": "デカルトの「方法的懐疑」とはどのようなものか説明せよ。", "a": "確実な真理を見いだすために、少しでも疑わしいものはすべて疑ってみる方法。感覚や数学の真理さえも疑ったが、疑っている自分の存在だけは疑えないとして、「【われ思う、ゆえにわれあり】」を哲学の第一原理とした。そこから【演繹法】で知識を導いた。この方法を【方法的懐疑】という。"},
  {"id": "rinrix10", "s": "rinri", "lv": 1, "topic": "イドラ", "q": "ベーコンが説いた「イドラ」とは何か説明せよ。", "a": "正しい認識をさまたげる偏見や先入観のこと。人間という種族に共通する【種族のイドラ】、個人の性格や経験による洞窟のイドラ、言葉の不適切な使用による市場のイドラ、権威や学説の盲信による劇場のイドラの四つをあげ、これらを排して【経験】にもとづく【帰納法】による学問を説いた。"},
  {"id": "rinrix11", "s": "rinri", "lv": 1, "topic": "カントの道徳", "q": "カントは道徳的な行為をどのようなものと考えたか説明せよ。", "a": "道徳的な行為とは、結果ではなく、義務にもとづこうとする【善意志】から行われる行為であるとした。道徳法則は「〜せよ」と無条件に命じる【定言命法】の形をとり、人間は自ら立てた道徳法則に自ら従う【自律】によって自由な人格となる。"},
  {"id": "rinrix12", "s": "rinri", "lv": 1, "topic": "ベンサムの功利主義", "q": "ベンサムの功利主義では、行為の善悪をどのように判断するか説明せよ。", "a": "人間は快楽を求め苦痛を避ける存在であり、快楽をもたらす行為が善であるとした。快楽は量的に計算できるとして【快楽計算】を唱え、社会全体の快楽を最大にする「【最大多数の最大幸福】」を道徳と立法の原理とした。行為を外から規制する【制裁（サンクション）】も重視した。"},
  {"id": "rinrix13", "s": "rinri", "lv": 1, "topic": "労働の疎外", "q": "マルクスが説いた「労働の疎外」とはどのようなことか説明せよ。", "a": "本来、【労働】は人間が自らの能力を発揮し、他者とつながる本質的な活動である。しかし【資本主義】社会では、生産手段をもたない労働者が生産物や労働そのものを資本家に奪われ、労働が苦役となって人間らしさを失う。これを【疎外】という。"},
  {"id": "rinrix14", "s": "rinri", "lv": 1, "topic": "悪人正機", "q": "親鸞の「悪人正機」とはどのような考え方か説明せよ。", "a": "自力で善を積むことのできない、煩悩にまみれた【悪人】こそが、【阿弥陀仏】の救いの本来の対象であるという考え方。親鸞は念仏さえも阿弥陀仏のはからいによるものとし、すべてを仏にまかせる【絶対他力】を説いた。"},
  {"id": "rinrix15", "s": "rinri", "lv": 1, "topic": "もののあはれ", "q": "本居宣長の説いた「もののあはれ」と「真心」について説明せよ。", "a": "宣長は、物事にふれて素直に心が動く感情を【もののあはれ】とよび、それを知ることが人間の本来のあり方だとした。また、儒教や仏教の影響である【漢意】を排し、生まれながらのありのままの心である【真心】に従って生きることを説いた。彼は【国学】を大成した。"},
  {"id": "rinrix16", "s": "rinri", "lv": 1, "topic": "青年期", "q": "青年期を表す「マージナル・マン（境界人）」と「心理的離乳」について説明せよ。", "a": "レヴィンは、青年は子どもの集団にも大人の集団にも完全には属さない不安定な存在であるとして【マージナル・マン】とよんだ。ホリングワースは、青年期に親から精神的に自立しようとすることを【心理的離乳】とよんだ。青年期は【自我のめざめ】の時期でもある。"},
  {"id": "rinrix17", "s": "rinri", "lv": 2, "topic": "ミルの功利主義", "q": "ミルの功利主義は、ベンサムの功利主義をどのように修正したか説明せよ。", "a": "ベンサムが快楽を量的に計算できるとしたのに対し、ミルは快楽には【質】の違いがあり、精神的快楽は肉体的快楽よりも優れているとした（【質的功利主義】）。「満足した豚より不満足な人間がよい」と述べ、外的制裁よりも良心による【内的制裁】を重視した。"},
  {"id": "rinrix18", "s": "rinri", "lv": 2, "topic": "ヘーゲルの人倫", "q": "ヘーゲルが説いた「人倫」とはどのようなものか、その三段階をふまえて説明せよ。", "a": "人倫とは、外面的な【法】と内面的な【道徳】が【弁証法】的に統合されたものであり、自由が具体的に実現された共同体である。人倫は、愛で結ばれる【家族】、欲望の体系である市民社会を経て、両者を統合した国家において完成するとした。"},
  {"id": "rinrix19", "s": "rinri", "lv": 2, "topic": "実存の三段階", "q": "キルケゴールの説いた実存の三段階について説明せよ。", "a": "人は、快楽を求めて生きるがやがて【絶望】に陥る【美的実存】、良心に従い義務を果たそうとするが自らの無力さに挫折する【倫理的実存】を経て、単独者として神の前に立ち、信仰に生きる【宗教的実存】へと至るとした。"},
  {"id": "rinrix20", "s": "rinri", "lv": 2, "topic": "ニーチェの超人", "q": "ニーチェが「神は死んだ」と述べた意味と、彼が理想とした人間像を説明せよ。", "a": "キリスト教的な価値観が力を失い、最高の価値が無価値となる【ニヒリズム】の到来を宣言した。キリスト教道徳は弱者の強者へのねたみ（【ルサンチマン】）から生まれた奴隷道徳だと批判し、【力への意志】にもとづき、【永劫回帰】の運命を肯定して新たな価値を創造する【超人】を理想とした。"},
  {"id": "rinrix21", "s": "rinri", "lv": 2, "topic": "実存は本質に先立つ", "q": "サルトルの「実存は本質に先立つ」という言葉の意味を説明せよ。", "a": "人間は、あらかじめ本質が定められて生まれてくるのではなく、まず存在し、自らの【自由】な選択によって自分のあり方をつくっていく存在だという意味。人間は「【自由の刑】に処されている」とし、自らの選択が全人類に関わるため、社会に参加する【アンガージュマン】が大切だとした。"},
  {"id": "rinrix22", "s": "rinri", "lv": 2, "topic": "限界状況", "q": "ヤスパースの説いた「限界状況」と「実存的交わり」について説明せよ。", "a": "死・苦悩・争い・罪責など、人間の力では避けられない壁を【限界状況】とよんだ。人はそれに直面して挫折するとき、自己を超えた【超越者（包括者）】に出会い、真の実存に目覚める。また、他者と誠実に語り合う【実存的交わり（愛しながらの戦い）】を重視した。"},
  {"id": "rinrix23", "s": "rinri", "lv": 2, "topic": "朱子学と陽明学", "q": "朱子学と陽明学では、人間の心と理の関係についてどのように考えが異なるか説明せよ。", "a": "朱子は、人間の本来の性は理であるとする【性即理】を説き、事物の理を一つずつ窮める【格物致知】を重んじた。これに対して王陽明は、心そのものが理であるとする【心即理】を説き、生まれつきの良知を発揮することを重視し、知と行は一体であるという【知行合一】を唱えた。"},
  {"id": "rinrix24", "s": "rinri", "lv": 2, "topic": "大乗仏教", "q": "大乗仏教は上座部仏教とどのように異なるか説明せよ。", "a": "上座部仏教が出家者の厳しい修行による自己の解脱を重視し、【阿羅漢】を理想としたのに対し、大乗仏教は在家者も含めたすべての人々の救済をめざし、自らの悟りとともに他者の救済にも努める【菩薩】を理想とした。【六波羅蜜】の実践を説き、【空】の思想を展開した。"},
  {"id": "rinrix25", "s": "rinri", "lv": 2, "topic": "只管打坐", "q": "道元の「只管打坐」と「修証一等」について説明せよ。", "a": "道元は、ただひたすら坐禅に打ち込む【只管打坐】を説いた。坐禅によって身も心も一切の執着から離れる【身心脱落】の境地に至るとした。また、坐禅は悟りのための手段ではなく、修行そのものが悟りであるという【修証一等】を唱えた。彼は【曹洞宗】の開祖である。"},
  {"id": "rinrix26", "s": "rinri", "lv": 2, "topic": "古学", "q": "伊藤仁斎と荻生徂徠は、それぞれ朱子学をどのように批判したか説明せよ。", "a": "伊藤仁斎は、『論語』などの原典を直接読む【古義学】を唱え、朱子学の理を批判して、日常の人間関係における【誠】の心と仁愛を重視した。荻生徂徠は、古代の言葉の研究にもとづく【古文辞学】を唱え、道とは聖人が天下を安んじるために作った【礼楽刑政】であるとした。"},
  {"id": "rinrix27", "s": "rinri", "lv": 2, "topic": "独立自尊", "q": "福沢諭吉の「独立自尊」とはどのような考え方か説明せよ。", "a": "人は生まれながらに平等であるという【天賦人権】の考えにもとづき、各人が他に依存せず自らの判断と責任で生きる【独立自尊】の精神を説いた。そのためには日常に役立つ【実学】を学ぶことが必要とし、「一身独立して【一国独立】す」と述べた。"},
  {"id": "rinrix28", "s": "rinri", "lv": 2, "topic": "二つのJ", "q": "内村鑑三の「二つのJ」とはどのような考え方か説明せよ。", "a": "内村は【イエス（Jesus）】と【日本（Japan）】の二つに生涯をささげることを誓った。武士道の精神をキリスト教の土台とし、教会や儀式にとらわれず聖書に直接もとづいて信仰する【無教会主義】を唱えた。日露戦争に際しては【非戦論】を主張した。"},
  {"id": "rinrix29", "s": "rinri", "lv": 2, "topic": "自己本位", "q": "夏目漱石の「自己本位」とはどのような考え方か説明せよ。", "a": "漱石は、日本の近代化は西洋に迫られた【外発的開化】であり表面的だと批判した。そのうえで、他人に追随するのではなく、自己の内面に根ざして主体的に生きる【自己本位】を説いた。晩年には、私を去って天に従う【則天去私】の境地を求めたとされる。"},
  {"id": "rinrix30", "s": "rinri", "lv": 2, "topic": "アガペー", "q": "イエスが説いた「神の愛（アガペー）」とはどのような愛か説明せよ。", "a": "【アガペー】は、罪深い人間に対しても無差別・無償に注がれる神の愛である。イエスはこれにもとづき、形式的な【律法主義】を批判し、「【神への愛】」と、敵をも愛する「【隣人愛】」を最も重要な教えとした。"},
  {"id": "rinrix31", "s": "rinri", "lv": 2, "topic": "ストア派とエピクロス派", "q": "ストア派とエピクロス派は、幸福な生き方についてどのように考えたか比較して説明せよ。", "a": "ストア派のゼノンは、宇宙を貫く理性（ロゴス）に従い、情念に動かされない【アパテイア】の境地を理想とし、「【自然に従って生きよ】」と説いた。一方エピクロスは、快楽を善としつつも、身体の苦痛や魂の不安から解放された【アタラクシア】を理想とし、「【隠れて生きよ】」と説いた。"},
  {"id": "rinrix32", "s": "rinri", "lv": 2, "topic": "ロールズの正義論", "q": "ロールズの『正義論』の内容を、功利主義批判とあわせて説明せよ。", "a": "功利主義は全体の幸福のために個人の権利を犠牲にしうると批判した。自分の立場を知らない【無知のヴェール】のもとで人々が合意する原理として、各人に平等な基本的自由を保障する原理と、不平等は【公正な機会均等】と、最も恵まれない人の利益を最大にする【格差原理】を満たす場合に限り許されるという原理を示した。"},
  {"id": "rinrix33", "s": "rinri", "lv": 3, "topic": "間柄的存在", "q": "和辻哲郎は人間をどのような存在と考えたか。西洋近代の個人主義と比較して説明せよ。", "a": "和辻は、西洋近代の倫理学が孤立した【個人】を出発点とすることを批判した。人間は個人であると同時に社会的な存在でもあり、人と人との関係において成り立つ【間柄的存在】であるとした。倫理とは、個人と社会が互いに否定しあう【弁証法】的な運動の中で実現されるとした。"},
  {"id": "rinrix34", "s": "rinri", "lv": 3, "topic": "純粋経験", "q": "西田幾多郎の「純粋経験」とはどのようなものか説明せよ。", "a": "音楽に聴き入っているときのように、見る自己と見られる対象とが分かれる以前の、主観と客観が一体となった直接的な経験（【主客未分】）のこと。西田はこの【純粋経験】を真の実在とし、西洋哲学の【主客二元論】を乗り越えようとした。【禅】の体験が背景にあり、主著は『善の研究』である。"},
  {"id": "rinrix35", "s": "rinri", "lv": 3, "topic": "死への存在", "q": "ハイデガーは、人間が本来的な生き方を取り戻すにはどうすべきだと考えたか説明せよ。", "a": "人間（【現存在】）は、日常において世間に埋没し、自分を見失った【ダス・マン（世人）】として生きている。しかし、自らが【死への存在】であることを自覚し、死に向き合う【先駆的決意】をもつことによって、かけがえのない本来的な自己を取り戻すことができるとした。"},
  {"id": "rinrix36", "s": "rinri", "lv": 3, "topic": "フーコーの権力論", "q": "フーコーは近代社会における権力をどのようにとらえたか説明せよ。", "a": "近代の権力は、王のように上から暴力で支配するものではなく、学校・病院・軍隊などで人々を【規律・訓練】し、規範を内面化させて自発的に従わせるものだととらえた（【規律権力】）。その象徴として、常に監視されていると意識させる【パノプティコン】をあげた。また、正常と【狂気】を区別する近代理性のあり方も批判した。"},
  {"id": "rinrix37", "s": "rinri", "lv": 3, "topic": "コミュニケーション的合理性", "q": "ハーバーマスの「コミュニケーション的合理性」とはどのような考え方か説明せよ。", "a": "目的達成のための効率を重視する【道具的理性】に対し、人々が対等な立場で自由に討議し、相互理解と【合意】を形成する理性のはたらきを【コミュニケーション的合理性】とよんだ。行政や市場の論理が日常の【生活世界】を侵す「生活世界の植民地化」を批判した。"},
  {"id": "rinrix38", "s": "rinri", "lv": 3, "topic": "アーレントの活動", "q": "アーレントは人間の営みをどのように分類し、何を重視したか説明せよ。", "a": "人間の営みを、生命維持のための【労働】、道具や作品をつくる【仕事】、他者と言葉を交わして共同体に関わる【活動】の三つに分けた。近代では労働が優位となり公共性が失われたと批判し、多様な人々が【公共性】の場で語り合う活動を重視した。それが失われると全体主義を招くとした。"},
  {"id": "rinrix39", "s": "rinri", "lv": 3, "topic": "潜在能力", "q": "アマルティア・センの「潜在能力（ケイパビリティ）」の考え方を説明せよ。", "a": "センは、豊かさを所得や財の量だけでとらえるのではなく、人がその財を用いて実際に何ができるか、どのような状態でありうるかという【機能】の組み合わせ、すなわち【潜在能力】の大きさで評価すべきだとした。この考えは【人間の安全保障】や、国連の【人間開発指数】の基礎となった。"},
  {"id": "rinrix40", "s": "rinri", "lv": 3, "topic": "道具的理性批判", "q": "ホルクハイマーとアドルノは、近代の理性をどのように批判したか説明せよ。", "a": "彼らは『【啓蒙の弁証法】』で、人間を解放するはずの啓蒙的理性が、自然や人間を支配・管理するための効率性ばかりを追求する【道具的理性】に変質したと批判した。それが【ナチズム】などの全体主義や、大衆を画一化する文化産業を生んだとした。彼らは【フランクフルト学派】の思想家である。"},
  {"id": "physx1", "s": "phys", "lv": 1, "topic": "慣性の法則", "q": "走っているバスが急ブレーキをかけると、乗客が前のめりになる理由を説明せよ。", "a": "物体は外から力を受けなければ、その運動状態を保とうとする性質（【慣性】）をもつ。バスが急に減速しても、乗客の体は【慣性の法則】によってそれまでの【速度】で前に進み続けようとするため、前のめりになる。"},
  {"id": "physx2", "s": "phys", "lv": 1, "topic": "作用・反作用", "q": "ロケットが真空の宇宙空間でも加速できる理由を説明せよ。", "a": "ロケットは燃料を燃やしたガスを後方へ勢いよく噴き出す。このときロケットがガスを押す力の【反作用】として、ガスがロケットを前方へ押す力がはたらく（【作用・反作用の法則】）。空気を押す必要はないため、【真空】中でも加速できる。"},
  {"id": "physx3", "s": "phys", "lv": 1, "topic": "浮力", "q": "鉄でできた船が水に浮くことができる理由を説明せよ。", "a": "水中の物体は、押しのけた水の【重さ】に等しい大きさの上向きの【浮力】を受ける（【アルキメデスの原理】）。船は内部が空洞で体積が大きく、多くの水を押しのけるため、浮力が船の重力とつり合い、浮くことができる。"},
  {"id": "physx4", "s": "phys", "lv": 1, "topic": "光の屈折", "q": "水の入ったプールの底が、実際より浅く見えるのはなぜか説明せよ。", "a": "水中から空気中へ出る光は、水面で【屈折】し、【屈折角】が入射角より大きくなる。目は光が【直進】してきたと判断するため、屈折した光を延長した位置、つまり実際より浅い位置に底があるように見える。"},
  {"id": "physx5", "s": "phys", "lv": 1, "topic": "ドップラー効果", "q": "救急車が近づくときはサイレンの音が高く、遠ざかるときは低く聞こえる理由を説明せよ。", "a": "音源が近づくと、音源が進む向きの音波の【波長】が短く縮められ、観測者に届く音の【振動数】が大きくなるため高く聞こえる。遠ざかるときは波長が長くなり振動数が小さくなるため低く聞こえる。この現象を【ドップラー効果】という。"},
  {"id": "physx6", "s": "phys", "lv": 1, "topic": "静電誘導", "q": "こすって帯電させた下じきに、帯電していない小さな紙片が引きつけられる理由を説明せよ。", "a": "帯電した下じきを近づけると、紙片の中で【静電誘導】（誘電分極）が起こり、下じきに近い側に下じきと【異符号】の電荷が、遠い側に同符号の電荷が現れる。近い側の【引力】が遠い側の斥力より大きいため、紙片は引きつけられる。"},
  {"id": "physx7", "s": "phys", "lv": 1, "topic": "電磁誘導", "q": "コイルに磁石を出し入れすると電流が流れる理由を説明せよ。", "a": "磁石を動かすとコイルを貫く【磁束】が変化する。このときコイルには磁束の変化を妨げる向きに【誘導起電力】が生じ、電流が流れる。この現象を【電磁誘導】といい、発電機の原理となっている。"},
  {"id": "physx8", "s": "phys", "lv": 1, "topic": "比熱", "q": "晴れた日の昼、海岸では陸のほうが海より早く温まる。その理由を説明せよ。", "a": "水は陸の岩石や土に比べて【比熱】が大きく、同じ量の熱を受けても【温度】が上がりにくいため。陸は比熱が小さく温まりやすいので、昼は陸のほうが高温になり、海から陸へ向かう【海風】が吹く。"},
  {"id": "physx9", "s": "phys", "lv": 1, "topic": "光の分散", "q": "プリズムに白色光を通すと、光が虹のような色の帯に分かれる理由を説明せよ。", "a": "白色光はさまざまな【波長】の光が混ざったものである。ガラスの【屈折率】は光の波長によって異なり、波長の短い紫の光ほど大きく屈折する。そのため各色の光が異なる角度で屈折して分かれる。この現象を光の【分散】という。"},
  {"id": "physx10", "s": "phys", "lv": 1, "topic": "力学的エネルギー保存", "q": "空気抵抗や摩擦が無視できるとき、振り子のおもりは最初と同じ高さまで上がる。その理由を説明せよ。", "a": "おもりにはたらく糸の張力は運動の向きと常に垂直で【仕事】をしないため、重力だけが仕事をする。このとき【位置エネルギー】と【運動エネルギー】の和である【力学的エネルギー】が保存されるので、最初と同じ高さまで上がる。"},
  {"id": "physx11", "s": "phys", "lv": 2, "topic": "終端速度", "q": "雨粒は高いところから落ちてきても、ある一定の速さ以上にはならない。その理由を説明せよ。", "a": "雨粒には下向きの【重力】と、速さが増すほど大きくなる上向きの【空気抵抗】がはたらく。速さが増して空気抵抗が重力とつり合うと、【合力】が0になり加速しなくなるため、一定の速さ（【終端速度】）で落下する。"},
  {"id": "physx12", "s": "phys", "lv": 2, "topic": "人工衛星", "q": "地球のまわりを回る人工衛星が、地上に落ちてこない理由を説明せよ。", "a": "人工衛星は地球の【万有引力】を受けて常に地球に向かって落下しているが、同時に大きな速さで水平方向に進んでいる。万有引力が円運動の【向心力】となり、落下しても地表の曲がりに沿って進むため、地表に近づかずに【等速円運動】を続ける。"},
  {"id": "physx13", "s": "phys", "lv": 2, "topic": "うなり", "q": "振動数がわずかに異なる二つのおんさを同時に鳴らすと、音が強弱をくり返して聞こえる理由を説明せよ。", "a": "振動数がわずかに異なる二つの音波が【重ね合わせ】られると、二つの波の山どうしが重なって強めあう時と、山と谷が重なって弱めあう時が周期的にくり返される。これを【うなり】といい、1秒あたりのうなりの回数は二つの音の【振動数の差】に等しい。"},
  {"id": "physx14", "s": "phys", "lv": 2, "topic": "薄膜の干渉", "q": "シャボン玉の表面が色づいて見える理由を説明せよ。", "a": "膜の表面で反射した光と、膜の裏面で反射した光が重なり合って【干渉】する。二つの光の【光路差】は膜の【厚さ】によって変わり、強めあう光の【波長】も異なるため、場所によって特定の色の光が強めあって色づいて見える。"},
  {"id": "physx15", "s": "phys", "lv": 2, "topic": "回折", "q": "塀の向こう側にいる人の声は聞こえるのに、姿は見えない理由を説明せよ。", "a": "波が障害物の背後に回りこむ現象を【回折】といい、波長が障害物やすき間の大きさと同程度以上のときに顕著になる。音波の【波長】は数十cm〜数mと塀の大きさに近く回折しやすいが、光の波長は約0.4〜0.8μmと非常に【短い】ため、ほとんど回折しない。"},
  {"id": "physx16", "s": "phys", "lv": 2, "topic": "レンツの法則", "q": "銅やアルミニウムの管の中に強い磁石を落とすと、ゆっくり落ちる理由を説明せよ。", "a": "磁石が落下すると管を貫く磁束が変化し、管に【電磁誘導】による【渦電流】が流れる。【レンツの法則】により、この電流は磁束の変化を妨げる向きの磁場をつくるため、磁石には運動を妨げる向きの力がはたらき、ゆっくり落下する。"},
  {"id": "physx17", "s": "phys", "lv": 2, "topic": "高電圧送電", "q": "発電所から遠くへ電気を送るとき、高い電圧で送電する理由を説明せよ。", "a": "同じ【電力】を送る場合、電圧を高くすると電流を小さくできる。送電線の抵抗で失われる電力（【ジュール熱】）は電流の2乗に比例するため、高電圧にすると【送電損失】を大幅に減らせる。交流は【変圧器】で電圧を容易に変えられるので送電に用いられる。"},
  {"id": "physx18", "s": "phys", "lv": 2, "topic": "断熱圧縮", "q": "自転車の空気入れで空気を急に圧縮すると、空気入れが熱くなる理由を説明せよ。", "a": "急に圧縮すると、外部と熱をやりとりする時間がない【断熱変化】となる。【熱力学第一法則】より、外部からされた【仕事】がすべて気体の【内部エネルギー】の増加となるため、気体の温度が上昇する。"},
  {"id": "physx19", "s": "phys", "lv": 2, "topic": "光電効果", "q": "金属に光を当てたとき、強い赤色光では電子が飛び出さないのに、弱い紫外線では飛び出すことがある。その理由を説明せよ。", "a": "光は振動数に比例するエネルギーをもつ粒子（【光子】）の集まりである。電子は光子1個のエネルギーを受け取り、それが金属の【仕事関数】を超えたときだけ飛び出す。紫外線は【振動数】が大きく光子1個のエネルギーが大きいため電子が飛び出すが、赤色光は強くしても光子1個のエネルギーが足りない。これを【光電効果】という。"},
  {"id": "physx20", "s": "phys", "lv": 2, "topic": "金属の抵抗と温度", "q": "金属の電気抵抗が、温度が上がると大きくなる理由を説明せよ。", "a": "金属中の電流は【自由電子】の移動によるものである。温度が上がると金属の【陽イオン】の【熱振動】が激しくなり、自由電子が陽イオンに衝突して進みにくくなるため、【抵抗率】が大きくなる。"},
  {"id": "physx21", "s": "phys", "lv": 3, "topic": "空の色", "q": "昼間の空が青く見え、夕焼けが赤く見える理由を説明せよ。", "a": "太陽光が大気中の分子に当たると、波長より小さい粒子による【レイリー散乱】が起こり、波長の【短い】青い光ほど強く散乱される。昼は散乱された青い光が空全体から届くため青く見える。夕方は光が大気中を通る【距離】が長く、青い光は途中で散乱されて失われ、【波長の長い】赤い光が届くため赤く見える。"},
  {"id": "physx22", "s": "phys", "lv": 3, "topic": "核分裂のエネルギー", "q": "ウランの核分裂で大きなエネルギーが放出される理由を、質量とエネルギーの関係から説明せよ。", "a": "ウランのような重い原子核は、核子1個あたりの【結合エネルギー】が中程度の質量の原子核より小さい。核分裂で生じる原子核は結合エネルギーが大きく、分裂後の質量の和は分裂前より小さくなる。この【質量欠損】に相当するエネルギーが、【E=mc²】の関係にしたがって放出される。"},
  {"id": "physx23", "s": "phys", "lv": 3, "topic": "静電遮蔽", "q": "金属の箱で囲まれた内部には、外部の電場の影響が及ばない理由を説明せよ。", "a": "導体に外部電場がかかると、【自由電子】が移動して表面に電荷が現れ、外部電場を打ち消す電場をつくる。電子の移動は導体内部の電場が0になるまで続くため、静電平衡では導体は【等電位】となり、中空部分の電場も0になる。これを【静電遮蔽】という。"},
  {"id": "physx24", "s": "phys", "lv": 3, "topic": "熱機関の効率", "q": "熱機関の熱効率を100％にすることができない理由を説明せよ。", "a": "【熱力学第二法則】によれば、熱は高温から低温へ自然に移動するが、一つの熱源から得た熱をすべて【仕事】に変え続けることはできない。熱機関はサイクルを続けるために、受け取った熱の一部を必ず【低温熱源】へ捨てる必要があるため、熱効率は100％未満になる。【不可逆変化】の存在もその背景にある。"},
  {"id": "physx25", "s": "phys", "lv": 3, "topic": "線スペクトル", "q": "水素原子の出す光が、とびとびの波長だけをもつ線スペクトルになる理由を説明せよ。", "a": "ボーアの理論によれば、原子内の電子はとびとびの【エネルギー準位】の状態しかとれない。電子が高いエネルギー準位から低い準位へ移るとき、その【エネルギー差】に等しいエネルギーをもつ【光子】を放出する。エネルギー差がとびとびの値をとるため、光の波長もとびとびになり【線スペクトル】となる。"},
  {"id": "chemx1", "s": "chem", "lv": 1, "topic": "イオン結晶の性質", "q": "塩化ナトリウムの結晶は固体では電気を通さないが、融解すると電気を通す。その理由を説明せよ。", "a": "塩化ナトリウムは陽イオンと陰イオンが【イオン結合】で規則正しく並んだ【イオン結晶】である。固体ではイオンが固定されて動けないが、融解すると【イオン】が自由に動けるようになり、電荷を運ぶため【電気伝導性】を示す。"},
  {"id": "chemx2", "s": "chem", "lv": 1, "topic": "金属の性質", "q": "金属が電気や熱をよく通し、展性・延性をもつ理由を説明せよ。", "a": "金属では、原子の価電子が特定の原子に束縛されずに結晶全体を動き回る【自由電子】となり、【金属結合】をつくる。自由電子が電荷や熱を運ぶため電気や熱をよく通す。また原子の位置がずれても自由電子が結合を保つため、【展性・延性】を示す。"},
  {"id": "chemx3", "s": "chem", "lv": 1, "topic": "水の沸点", "q": "水の沸点が、分子量が同程度の他の水素化合物に比べて著しく高い理由を説明せよ。", "a": "水分子は【電気陰性度】の大きい酸素原子と水素原子からなり、強い【極性】をもつ。そのため分子間に【水素結合】が形成され、分子どうしが強く引き合っている。これを切るために大きなエネルギーが必要となるため、沸点が高い。"},
  {"id": "chemx4", "s": "chem", "lv": 1, "topic": "貴ガス", "q": "ヘリウムやネオンなどの貴ガスが、他の原子と化合物をつくりにくい理由を説明せよ。", "a": "貴ガスの原子は、最外殻の電子配置が非常に安定な【閉殻】（またはそれに準じる構造）になっている。そのため電子を失ったり受け取ったりして【イオン】になりにくく、【価電子】の数も0とみなされ、他の原子と結合しにくい。"},
  {"id": "chemx5", "s": "chem", "lv": 1, "topic": "酸性雨", "q": "酸性雨はどのようなしくみで発生するか。原因となる物質にふれて説明せよ。", "a": "化石燃料の燃焼によって発生する【硫黄酸化物】や【窒素酸化物】が、大気中で酸化され雨水に溶けると、【硫酸】や硝酸となって強い酸性を示す。こうして通常の雨（pH5.6程度）より酸性の強い【酸性雨】が降る。"},
  {"id": "chemx6", "s": "chem", "lv": 1, "topic": "トタン", "q": "鉄板に亜鉛をめっきしたトタンは、傷がついても鉄がさびにくい理由を説明せよ。", "a": "亜鉛は鉄よりも【イオン化傾向】が大きい。そのため傷がついて鉄が露出しても、亜鉛が先に【酸化】されて陽イオンとなって溶け出し、鉄の酸化を防ぐ。このように、亜鉛が【犠牲】となって鉄を守るはたらきをする。"},
  {"id": "chemx7", "s": "chem", "lv": 1, "topic": "ダイヤモンドと黒鉛", "q": "ダイヤモンドと黒鉛はどちらも炭素からなるが、硬さや電気伝導性が異なる。その理由を説明せよ。", "a": "両者は互いに【同素体】である。ダイヤモンドは各炭素原子が4個の原子と【共有結合】で正四面体状に結びつき、非常に硬く電気を通さない。黒鉛は3個の原子と結合した平面状の層が重なり、層間は弱い【分子間力】で結ばれるため軟らかく、残りの【価電子】が層内を動くので電気を通す。"},
  {"id": "chemx8", "s": "chem", "lv": 1, "topic": "圧力鍋", "q": "圧力鍋を使うと、食材が短時間で調理できる理由を説明せよ。", "a": "液体は【飽和蒸気圧】が外圧と等しくなる温度で沸騰する。圧力鍋では内部の【圧力】が大気圧より高くなるため、水の【沸点】が100℃より高くなる。より高温で加熱できるため、食材が短時間で調理できる。"},
  {"id": "chemx9", "s": "chem", "lv": 1, "topic": "中和", "q": "胃酸が出すぎたときに、炭酸水素ナトリウムを含む胃腸薬を飲むのはなぜか説明せよ。", "a": "胃酸の主成分は【塩酸】である。炭酸水素ナトリウムは水溶液中で弱い【塩基性】を示し、塩酸と【中和】反応を起こして塩化ナトリウム、水、【二酸化炭素】を生じる。これにより過剰な胃酸を打ち消すことができる。"},
  {"id": "chemx10", "s": "chem", "lv": 1, "topic": "電気分解", "q": "塩化銅(Ⅱ)水溶液を電気分解すると、陰極に銅が析出する理由を説明せよ。", "a": "水溶液中の銅(Ⅱ)イオンは【陽イオン】であるため、電源の負極につながれた【陰極】に引き寄せられる。陰極で電子を受け取る【還元】反応が起こり、【銅】が析出する。陽極では塩化物イオンが電子を失って塩素が発生する。"},
  {"id": "chemx11", "s": "chem", "lv": 2, "topic": "凝固点降下", "q": "冬に凍結防止のため道路に塩化カルシウムをまくのはなぜか説明せよ。", "a": "水に塩化カルシウムなどの不揮発性の物質が溶けると、溶液の【凝固点】は純粋な水より低くなる（【凝固点降下】）。塩化カルシウムは水中で電離して多くの【粒子】を生じ、さらに溶ける際に【溶解熱】を放出するため、凍結を効果的に防ぐことができる。"},
  {"id": "chemx12", "s": "chem", "lv": 2, "topic": "浸透圧", "q": "野菜に塩をふると、しばらくして水が出てくる理由を説明せよ。", "a": "細胞膜は水は通すが溶質を通しにくい【半透膜】の性質をもつ。細胞の外側の塩の濃度が内側より高くなると、濃度を等しくしようとして水が【濃度】の低い細胞内から高い外側へ移動する。この【浸透】によって細胞から水が出てくる。生じる圧力を【浸透圧】という。"},
  {"id": "chemx13", "s": "chem", "lv": 2, "topic": "ルシャトリエの原理", "q": "ハーバー・ボッシュ法でアンモニアを合成するとき、高圧にする理由を説明せよ。", "a": "N₂＋3H₂⇄2NH₃の反応では、正反応が進むと気体の【分子数】が減る。【ルシャトリエの原理】により、圧力を高くすると圧力を下げる向き、つまり分子数が減る正反応の向きに【平衡】が移動するため、アンモニアの生成量が増える。なお【触媒】は平衡に達する時間を短くする。"},
  {"id": "chemx14", "s": "chem", "lv": 2, "topic": "触媒", "q": "触媒が反応速度を大きくするしくみを説明せよ。また、平衡には影響するか。", "a": "触媒は反応の経路を変えて【活性化エネルギー】を小さくするため、そのエネルギーを超えられる分子の割合が増え、【反応速度】が大きくなる。正反応と逆反応の速度をともに大きくするので、平衡に達するまでの時間は短くなるが、【平衡】の位置や【反応熱】は変わらない。"},
  {"id": "chemx15", "s": "chem", "lv": 2, "topic": "温度と反応速度", "q": "温度を上げると反応速度が大きくなる理由を説明せよ。", "a": "温度が上がると分子の【熱運動】が激しくなり、【活性化エネルギー】以上のエネルギーをもつ分子の割合が急激に増える。そのため反応が起こる有効な【衝突】の回数が増え、【反応速度】が大きくなる。"},
  {"id": "chemx16", "s": "chem", "lv": 2, "topic": "緩衝液", "q": "酢酸と酢酸ナトリウムの混合水溶液に少量の酸を加えても、pHがほとんど変化しない理由を説明せよ。", "a": "この溶液には【酢酸イオン】と酢酸分子が多量に存在する。酸を加えるとH⁺は酢酸イオンと反応して弱酸の酢酸になり、塩基を加えるとOH⁻は酢酸と【中和】して水になる。そのため水素イオン濃度がほとんど変化しない。このような溶液を【緩衝液】といい、その作用を【緩衝作用】という。"},
  {"id": "chemx17", "s": "chem", "lv": 2, "topic": "不動態", "q": "鉄やアルミニウムは希硝酸には溶けるが、濃硝酸には溶けない。その理由を説明せよ。", "a": "鉄やアルミニウムを濃硝酸に入れると、強い【酸化】作用によって金属の表面にち密な【酸化被膜】が形成される。この被膜が内部を保護するため、それ以上反応が進まなくなる。このような状態を【不動態】という。"},
  {"id": "chemx18", "s": "chem", "lv": 2, "topic": "セッケン", "q": "セッケンが油汚れを落とすしくみを説明せよ。", "a": "セッケン分子は水になじむ【親水基】と、油になじむ【疎水基（親油基）】をもつ。水中では疎水基を内側に向けて油汚れを取り囲み、【ミセル】を形成して油を水中に分散させる（【乳化】作用）。こうして油汚れを水で洗い流すことができる。"},
  {"id": "chemx19", "s": "chem", "lv": 2, "topic": "塩の加水分解", "q": "酢酸ナトリウムの水溶液が塩基性を示す理由を説明せよ。", "a": "酢酸ナトリウムは【弱酸】の酢酸と強塩基の水酸化ナトリウムからなる塩である。水中で生じた酢酸イオンの一部が水と反応して酢酸分子となり、【水酸化物イオン】を生じる。この【加水分解】によって、水溶液が【塩基性】を示す。"},
  {"id": "chemx20", "s": "chem", "lv": 2, "topic": "ダニエル電池", "q": "ダニエル電池で電流が流れるしくみを説明せよ。", "a": "亜鉛は銅より【イオン化傾向】が大きい。そのため【負極】では亜鉛が電子を放出して亜鉛イオンとなって溶け出し（酸化）、電子は導線を通って【正極】へ流れる。正極では銅(Ⅱ)イオンが電子を受け取って銅が析出する（【還元】）。素焼き板はイオンを通して電気的なつりあいを保つ。"},
  {"id": "chemx21", "s": "chem", "lv": 3, "topic": "実在気体", "q": "実在気体が、高圧・低温の条件で理想気体の状態方程式からずれる理由を説明せよ。", "a": "理想気体は分子自身の【体積】と【分子間力】を無視している。高圧では気体の体積に対して分子自身の体積の割合が大きくなり、低温では分子の熱運動が弱まって分子間力の影響が大きくなるため、【理想気体】からのずれが大きくなる。"},
  {"id": "chemx22", "s": "chem", "lv": 3, "topic": "鏡像異性体", "q": "乳酸には、化学的性質はほぼ同じだが互いに重ね合わせられない2種類の分子が存在する。その理由を説明せよ。", "a": "乳酸は、4つの異なる原子または原子団が結合した【不斉炭素原子】をもつ。そのため、実物と鏡に映した像のように、互いに重ね合わせることのできない2種類の立体構造が存在する。これらを【鏡像異性体（光学異性体）】といい、【偏光】面を回転させる向きが異なる。"},
  {"id": "chemx23", "s": "chem", "lv": 3, "topic": "アルコールの溶解性", "q": "メタノールは水によく溶けるが、炭素数の多いアルコールは水に溶けにくい。その理由を説明せよ。", "a": "アルコールのヒドロキシ基は【親水性】で、水分子と【水素結合】をつくる。しかし炭素数が多くなると、【疎水性】の炭化水素基の部分が大きくなり、分子全体として水となじみにくくなるため、水に溶けにくくなる。"},
  {"id": "chemx24", "s": "chem", "lv": 3, "topic": "共通イオン効果", "q": "塩化ナトリウムの飽和水溶液に塩化水素を通じると、塩化ナトリウムの結晶が析出する理由を説明せよ。", "a": "飽和水溶液ではNaCl⇄Na⁺＋Cl⁻の【溶解平衡】が成り立っている。塩化水素を通じると【塩化物イオン】の濃度が増加し、【ルシャトリエの原理】により、その濃度を減らす方向に平衡が移動するため、NaClの結晶が析出する。これを【共通イオン効果】という。"},
  {"id": "chemx25", "s": "chem", "lv": 3, "topic": "タンパク質の変性", "q": "卵を加熱すると白く固まり、冷やしてももとに戻らない理由を説明せよ。", "a": "タンパク質は、ポリペプチド鎖が【水素結合】などによって特定の立体構造をとっている。加熱するとこれらの結合が切れて【立体構造】がくずれ、元に戻らなくなる。これを【変性】という。【ペプチド結合】による一次構造は保たれたままである。"},
  {"id": "biox1", "s": "bio", "lv": 1, "topic": "酵素と温度", "q": "ヒトの酵素の多くが、体温付近で最もよくはたらき、高温になるとはたらかなくなる理由を説明せよ。", "a": "酵素の主成分は【タンパク質】で、特定の立体構造をもつ【活性部位】で基質と結合する。温度が上がると反応速度は増すが、高温になると立体構造が壊れて【変性】し、【失活】する。そのため体温付近の【最適温度】で最もよくはたらく。"},
  {"id": "biox2", "s": "bio", "lv": 1, "topic": "血糖値の調節", "q": "食事のあとに上昇した血糖濃度が、もとの値に戻るしくみを説明せよ。", "a": "血糖濃度が上がると、すい臓の【ランゲルハンス島】のB細胞から【インスリン】が分泌される。インスリンは細胞へのグルコースの取りこみや、肝臓での【グリコーゲン】の合成を促進するため、血糖濃度が低下してもとに戻る。"},
  {"id": "biox3", "s": "bio", "lv": 1, "topic": "体温調節", "q": "寒い環境にいるとき、ヒトの体温が保たれるしくみを説明せよ。", "a": "皮膚で寒さを感じると、【間脳の視床下部】がはたらき、【交感神経】を通じて皮膚の血管を収縮させ、熱の放散を減らす。また、甲状腺ホルモンやアドレナリンの分泌を促して代謝を高め、【ふるえ】によって筋肉で熱を生産し、【体温】を保つ。"},
  {"id": "biox4", "s": "bio", "lv": 1, "topic": "半保存的複製", "q": "DNAの半保存的複製とはどのようなしくみか説明せよ。", "a": "DNAの2本鎖がほどけて、それぞれの鎖が【鋳型】となる。鋳型の塩基に対して【相補的】な塩基をもつヌクレオチドが結合して新しい鎖が合成される。新しくできたDNAは、もとの鎖1本と新しい鎖1本からなる。これを【半保存的複製】という。"},
  {"id": "biox5", "s": "bio", "lv": 1, "topic": "光合成と呼吸", "q": "光合成と呼吸の関係を、エネルギーの流れに着目して説明せよ。", "a": "【光合成】は、光エネルギーを用いて二酸化炭素と水から【有機物】を合成し、エネルギーを化学エネルギーとして蓄える反応である。【呼吸】は有機物を酸素を用いて分解し、蓄えられたエネルギーを取り出して【ATP】を合成する反応である。"},
  {"id": "biox6", "s": "bio", "lv": 1, "topic": "ワクチン", "q": "ワクチンを接種すると、感染症にかかりにくくなる理由を説明せよ。", "a": "ワクチンは、毒性を弱めたり無毒化したりした病原体やその成分である【抗原】を含む。接種すると【獲得免疫】がはたらき、その抗原に対応する【記憶細胞】がつくられる。実際に病原体が侵入したとき、すみやかに強い【二次応答】が起こるため、発症しにくくなる。"},
  {"id": "biox7", "s": "bio", "lv": 1, "topic": "生態系の物質循環", "q": "生態系における生産者と分解者のはたらきを説明せよ。", "a": "【生産者】である植物などは、光合成によって無機物から【有機物】をつくる。【分解者】である菌類や細菌は、生物の遺体や排出物に含まれる有機物を【無機物】に分解し、再び生産者が利用できるようにする。こうして生態系の中で物質が循環する。"},
  {"id": "biox8", "s": "bio", "lv": 1, "topic": "植生の遷移", "q": "日本で裸地から森林へと植生が移り変わる遷移の過程で、陽樹林が陰樹林に移り変わる理由を説明せよ。", "a": "陽樹林が発達すると、林床に届く【光】が少なくなる。陽樹の幼木は暗い林床では育ちにくいが、【陰樹】の幼木は弱い光でも生育できる。そのため次第に陰樹が増え、やがて陰樹林となって安定した【極相】に達する。これが【遷移】の過程である。"},
  {"id": "biox9", "s": "bio", "lv": 1, "topic": "体細胞分裂", "q": "体細胞分裂で生じた2つの娘細胞が、もとの細胞と同じ遺伝情報をもつ理由を説明せよ。", "a": "分裂の前の【間期】に、DNAが正確に【複製】されて2倍になる。分裂期には、複製されたそれぞれの【染色体】が縦に裂けるように分かれて両極に移動し、2つの娘細胞に均等に分配される。そのため娘細胞はもとの細胞と同じ【遺伝情報】をもつ。"},
  {"id": "biox10", "s": "bio", "lv": 1, "topic": "腎臓のはたらき", "q": "腎臓で尿がつくられるしくみを、ろ過と再吸収に着目して説明せよ。", "a": "糸球体で血液がろ過され、タンパク質や血球以外の成分が【ボーマンのう】へ出て【原尿】となる。原尿が細尿管を通る間に、グルコースなどの必要な物質や水が毛細血管へ【再吸収】され、残ったものが【尿】となる。"},
  {"id": "biox11", "s": "bio", "lv": 2, "topic": "アブシシン酸", "q": "植物が乾燥すると気孔を閉じるしくみと、その意義を説明せよ。", "a": "乾燥すると植物体内で【アブシシン酸】が合成され、孔辺細胞からカリウムイオンが流出して膨圧が低下し、【気孔】が閉じる。これにより【蒸散】による水の損失を防ぎ、乾燥に耐えることができる。ただし同時に【二酸化炭素】の取りこみも減る。"},
  {"id": "biox12", "s": "bio", "lv": 2, "topic": "光屈性", "q": "植物の茎が光の来る方向に曲がって伸びるしくみを説明せよ。", "a": "光が一方から当たると、植物ホルモンの【オーキシン】が光の当たらない【影側】へ移動する。茎ではオーキシンが細胞の【伸長】を促すため、影側の細胞がより大きく伸び、茎は光の来る方へ曲がる。これを正の【光屈性】という。"},
  {"id": "biox13", "s": "bio", "lv": 2, "topic": "工業暗化", "q": "イギリスで工業化の進行とともにオオシモフリエダシャクの暗色型が増えた理由を説明せよ。", "a": "工業化で【すす】により樹皮が黒くなると、明色型は目立って鳥に【捕食】されやすくなり、暗色型は目立たず生き残りやすくなった。暗色型が多く子を残した結果、集団中の暗色型の割合が増加した。これは【自然選択】による【適応】進化の例である。"},
  {"id": "biox14", "s": "bio", "lv": 2, "topic": "ヘモグロビン", "q": "ヘモグロビンが肺で酸素と結合し、組織で酸素を放出するしくみを説明せよ。", "a": "ヘモグロビンは【酸素分圧】が高く二酸化炭素分圧が低い肺胞では酸素と結合しやすい。組織では酸素分圧が低く、【二酸化炭素分圧】が高いため、酸素と解離しやすくなる。この性質は【酸素解離曲線】で示され、効率よく組織に【酸素】を供給できる。"},
  {"id": "biox15", "s": "bio", "lv": 2, "topic": "跳躍伝導", "q": "有髄神経繊維では、無髄神経繊維より興奮が速く伝わる理由を説明せよ。", "a": "有髄神経繊維の軸索は、電気を通しにくい【髄鞘】で覆われており、髄鞘の切れ目である【ランビエ絞輪】でのみ活動電位が生じる。興奮が絞輪から絞輪へととびとびに伝わる【跳躍伝導】が起こるため、【伝導速度】が大きくなる。"},
  {"id": "biox16", "s": "bio", "lv": 2, "topic": "減数分裂と多様性", "q": "減数分裂によって、遺伝的に多様な配偶子が生じる理由を説明せよ。", "a": "減数分裂の第一分裂では、【相同染色体】が対合し、それぞれがどちらの極に移動するかがランダムに決まる（【独立】した分配）。また、対合した相同染色体の間で【乗換え】が起こり【遺伝子の組換え】が生じる。これらにより、多様な遺伝子の組み合わせをもつ配偶子ができる。"},
  {"id": "biox17", "s": "bio", "lv": 2, "topic": "フィードバック調節", "q": "甲状腺から分泌されるチロキシンの量が一定に保たれるしくみを説明せよ。", "a": "血液中の【チロキシン】濃度が上がると、それが間脳の視床下部や【脳下垂体前葉】に作用し、甲状腺刺激ホルモン放出ホルモンや【甲状腺刺激ホルモン】の分泌が抑えられ、チロキシンの分泌が減る。このように最終産物が前の段階を調節するしくみを【負のフィードバック】という。"},
  {"id": "biox18", "s": "bio", "lv": 2, "topic": "アレルギー", "q": "アレルギーはどのようなしくみで起こるか説明せよ。", "a": "本来は無害な花粉などの物質が【抗原（アレルゲン）】となって、免疫が過剰に反応することで起こる。【抗体】が結合した【マスト細胞（肥満細胞）】に再び抗原が結合すると、ヒスタミンなどが放出され、くしゃみや炎症などの症状が生じる。急激で全身性の重い反応を【アナフィラキシー】という。"},
  {"id": "biox19", "s": "bio", "lv": 2, "topic": "キーストーン種", "q": "キーストーン種とはどのような生物か。具体例をあげて説明せよ。", "a": "生態系の中で、個体数は少なくても【生物群集】のバランスを保つうえで大きな影響を与える生物。例えば岩礁で【ヒトデ】を除去すると、ヒトデに捕食されていたイガイが増えて他の生物を排除し、【種の多様性】が低下する。このような生物を【キーストーン種】という。"},
  {"id": "biox20", "s": "bio", "lv": 2, "topic": "光周性", "q": "短日植物の花芽形成と、夜の長さとの関係を説明せよ。", "a": "短日植物は、連続した暗期の長さが一定の【限界暗期】以上になると花芽を形成する。暗期の途中に短時間光を当てる【光中断】を行うと、連続した暗期が短くなり花芽を形成しない。このように、植物は【昼の長さ】ではなく連続した暗期の長さを感知している。この性質を【光周性】という。"},
  {"id": "biox21", "s": "bio", "lv": 3, "topic": "遺伝的浮動", "q": "小さな集団で遺伝的浮動の影響が大きくなる理由を説明せよ。", "a": "【遺伝的浮動】は、次世代に伝わる遺伝子が【偶然】によって選ばれることで【遺伝子頻度】が変化する現象である。集団が小さいと、偶然による変動の影響が相対的に大きくなり、ある遺伝子が失われたり【固定】されたりしやすい。【びん首効果】はその一例である。"},
  {"id": "biox22", "s": "bio", "lv": 3, "topic": "ラクトースオペロン", "q": "大腸菌がラクトースのあるときだけラクトース分解酵素を合成するしくみを説明せよ。", "a": "ラクトースがないときは、【リプレッサー】が【オペレーター】に結合し、RNAポリメラーゼの転写を妨げている。ラクトースがあると、その代謝産物がリプレッサーに結合してオペレーターから離れさせるため、【転写】が始まり分解酵素が合成される。このような遺伝子群を【オペロン】という。"},
  {"id": "biox23", "s": "bio", "lv": 3, "topic": "ATP合成酵素", "q": "ミトコンドリアの電子伝達系でATPが合成されるしくみを説明せよ。", "a": "電子伝達系で電子が受け渡される際のエネルギーで、H⁺が内膜の外側（膜間腔）へくみ出され、内膜の内外でH⁺の【濃度勾配】が生じる。H⁺がこの勾配にしたがって【ATP合成酵素】を通ってマトリックスへ戻るときにATPが合成される。このしくみを【化学浸透】といい、最終的に電子は【酸素】に受け渡されて水ができる。"},
  {"id": "biox24", "s": "bio", "lv": 3, "topic": "遺伝子組換え", "q": "大腸菌を用いてヒトのインスリンを生産する遺伝子組換えの手順を説明せよ。", "a": "ヒトのインスリン遺伝子と、【ベクター】となる大腸菌の【プラスミド】を同じ【制限酵素】で切断し、【DNAリガーゼ】で連結して組換えプラスミドをつくる。これを大腸菌に導入して増殖させると、大腸菌が遺伝子を発現し、インスリンが生産される。"},
  {"id": "biox25", "s": "bio", "lv": 3, "topic": "C4植物", "q": "トウモロコシなどのC4植物が、高温・乾燥の環境で光合成を効率よく行える理由を説明せよ。", "a": "C4植物は、二酸化炭素との親和性が高い【PEPカルボキシラーゼ】で葉肉細胞においてCO₂を【C4化合物】として固定し、【維管束鞘細胞】へ送ってそこでCO₂を濃縮する。そのため気孔を閉じ気味にしても、【カルビン回路】に十分なCO₂を供給でき、光合成を効率よく行える。"},
  {"id": "earthx1", "s": "earth", "lv": 1, "topic": "日本の地震", "q": "日本付近で大きな地震が多く発生する理由を、プレートの動きから説明せよ。", "a": "日本付近では、海洋プレートである太平洋プレートやフィリピン海プレートが、大陸プレートの下に【沈み込んで】いる。その境界にある【海溝】付近で大陸プレートがひきずり込まれてひずみがたまり、それが解放されると【海溝型地震】が起こる。また内陸の【活断層】でも地震が起こる。"},
  {"id": "earthx2", "s": "earth", "lv": 1, "topic": "火山の形とマグマ", "q": "火山の形がマグマの性質によって異なる理由を説明せよ。", "a": "二酸化ケイ素（SiO₂）の多いマグマは【粘性】が大きく流れにくいため、盛り上がった【溶岩ドーム】をつくり、爆発的な噴火をしやすい。SiO₂の少ない玄武岩質マグマは粘性が小さく流れやすいため、傾斜のゆるやかな【盾状火山】をつくる。"},
  {"id": "earthx3", "s": "earth", "lv": 1, "topic": "季節の変化", "q": "日本で夏が暑く冬が寒くなる理由を、地球の運動から説明せよ。", "a": "地球は【地軸】を公転面に垂直な方向から約23.4°傾けたまま【公転】している。そのため夏は太陽の【南中高度】が高く昼の時間が長くなり、地面が受け取る太陽エネルギーが多くなる。冬はその逆になるため寒くなる。"},
  {"id": "earthx4", "s": "earth", "lv": 1, "topic": "月の満ち欠け", "q": "月が約1か月の周期で満ち欠けして見える理由を説明せよ。", "a": "月は自ら光を出さず、【太陽】の光を反射して輝いている。月が地球のまわりを【公転】するにつれて、太陽・地球・月の【位置関係】が変わり、地球から見える月の光っている部分の形が変化するため、満ち欠けして見える。"},
  {"id": "earthx5", "s": "earth", "lv": 1, "topic": "示準化石", "q": "示準化石は地層の年代を知るのに役立つ。示準化石として適した生物の条件を説明せよ。", "a": "示準化石に適した生物は、ある【限られた期間】だけ栄え、【広い範囲】に分布し、個体数が多かった生物である。そのため、離れた地域の地層でも同じ化石を含めば同時代と判断でき、【地質年代】の決定や地層の【対比】に役立つ。"},
  {"id": "earthx6", "s": "earth", "lv": 1, "topic": "海陸風", "q": "海岸地方で、昼は海から陸へ、夜は陸から海へ風が吹く理由を説明せよ。", "a": "陸は海より【比熱】が小さく、温まりやすく冷めやすい。昼は陸が海より高温になって陸上に【上昇気流】が生じ気圧が低くなるため、海から陸へ【海風】が吹く。夜は陸が海より低温になるため、陸から海へ【陸風】が吹く。"},
  {"id": "earthx7", "s": "earth", "lv": 1, "topic": "温室効果", "q": "大気中の二酸化炭素が増えると、地球の気温が上がる理由を説明せよ。", "a": "地表は太陽光で暖められ、【赤外線】を宇宙へ放射する。二酸化炭素などの【温室効果ガス】はこの赤外線を吸収し、その一部を再び地表へ放射して地表を暖める。温室効果ガスが増えるとこの【温室効果】が強まり、【地球温暖化】が進む。"},
  {"id": "earthx8", "s": "earth", "lv": 1, "topic": "雲のでき方", "q": "上昇する空気の中で雲ができるしくみを説明せよ。", "a": "空気が上昇すると、上空ほど気圧が低いため【断熱膨張】して温度が下がる。温度が【露点】に達すると、空気中の水蒸気が細かいちりなどを核として【凝結】し、水滴や氷の粒となる。これが集まって【雲】となる。"},
  {"id": "earthx9", "s": "earth", "lv": 1, "topic": "初期微動", "q": "地震のとき、はじめに小さなゆれがあり、その後に大きなゆれが来る理由を説明せよ。", "a": "地震が発生すると、速さの異なる2種類の地震波が同時に出る。速い【P波】が先に到着して小さなゆれの【初期微動】を起こし、遅れて到着した【S波】が大きなゆれの【主要動】を起こす。震源から遠いほど両者の到着時刻の差である【初期微動継続時間】が長くなる。"},
  {"id": "earthx10", "s": "earth", "lv": 1, "topic": "台風の発達", "q": "台風が暖かい海上で発達する理由を説明せよ。", "a": "台風は熱帯の海上で発生する【熱帯低気圧】が発達したものである。暖かい海面から大量の【水蒸気】が供給され、それが上昇して凝結するときに放出される【潜熱】がエネルギー源となるため、海面水温の高い海上で発達する。"},
  {"id": "earthx11", "s": "earth", "lv": 2, "topic": "外核とS波", "q": "地震のS波が地球の中心部を通過しないことから、地球内部についてどのようなことがわかるか説明せよ。", "a": "S波は【横波】であり、固体中は伝わるが【液体】中は伝わらない。震央から角距離103°以遠でS波が観測されない【シャドーゾーン】があることから、地球内部に液体の層があることがわかる。これが鉄を主成分とする【外核】である。"},
  {"id": "earthx12", "s": "earth", "lv": 2, "topic": "ホットスポット", "q": "ハワイ諸島で、島の年代が北西に向かうほど古くなっている理由を説明せよ。", "a": "マントル深部からの【プルーム】が上昇してくる【ホットスポット】の位置はほぼ固定されている。その上を【太平洋プレート】が北西方向へ移動しているため、ホットスポット上でできた火山島がプレートとともに北西へ運ばれ、北西ほど古い島が並ぶ。"},
  {"id": "earthx13", "s": "earth", "lv": 2, "topic": "天気の移り変わり", "q": "日本付近では天気が西から東へ移り変わることが多い。その理由を説明せよ。", "a": "日本は中緯度に位置し、上空に強い【偏西風】が吹いている。春や秋に日本付近を通る【温帯低気圧】や【移動性高気圧】は、偏西風に流されて西から東へ移動するため、天気も【西から東】へ移り変わることが多い。"},
  {"id": "earthx14", "s": "earth", "lv": 2, "topic": "ハドレー循環", "q": "低緯度の大気の大循環であるハドレー循環のしくみを説明せよ。", "a": "赤道付近では強く暖められた空気が上昇し、上空を高緯度側へ移動する。緯度30°付近で下降して【亜熱帯高圧帯】をつくり、地表付近を赤道へ向かって戻る。この地表付近の流れが【転向力（コリオリの力）】で西向きにそれたものが【貿易風】である。この循環を【ハドレー循環】という。"},
  {"id": "earthx15", "s": "earth", "lv": 2, "topic": "深層循環", "q": "海洋の深層循環はどのようにして起こるか説明せよ。", "a": "北大西洋のグリーンランド沖や南極周辺では、海水が冷却され、海氷ができる際に塩分が排出されるため、【低温】で【高塩分】の密度の大きい海水ができる。これが深層へ【沈み込み】、ゆっくりと世界の海洋の深層をめぐる。この循環を【熱塩循環】ともいう。"},
  {"id": "earthx16", "s": "earth", "lv": 2, "topic": "太陽の黒点", "q": "太陽の表面に見られる黒点が、周囲より黒く見える理由を説明せよ。", "a": "黒点は、太陽の内部からの強い【磁場】が光球面に現れた部分で、磁場によって内部からの熱の【対流】による輸送が妨げられている。そのため周囲の光球（約5800K）より【温度】が約1500〜2000K低く、相対的に暗く見える。黒点の数が多い時期は太陽の【活動】が活発である。"},
  {"id": "earthx17", "s": "earth", "lv": 2, "topic": "主系列星", "q": "恒星の多くがHR図上の主系列に分布する理由を説明せよ。", "a": "恒星は一生の大部分の期間、中心部で【水素】が【ヘリウム】に変わる【核融合】反応によってエネルギーを生み出し、安定して輝いている。この段階の恒星を【主系列星】といい、恒星はその一生の大部分をこの段階で過ごすため、多くの恒星が主系列に分布する。"},
  {"id": "earthx18", "s": "earth", "lv": 2, "topic": "金星の見え方", "q": "金星が明け方か夕方にしか見えず、真夜中には見えない理由を説明せよ。", "a": "金星は地球より内側を公転する【内惑星】であるため、地球から見て太陽から一定の角度（【最大離角】約47°）以上は離れない。そのため太陽が沈んだ直後の西の空（【宵の明星】）か、日の出前の東の空（明けの明星）にしか見えない。"},
  {"id": "earthx19", "s": "earth", "lv": 2, "topic": "津波", "q": "海溝型の巨大地震で大きな津波が発生しやすい理由を説明せよ。", "a": "海溝型地震では、プレート境界の【逆断層】がずれ動き、沈み込むプレートにひきずり込まれていた陸側のプレートが跳ね上がる。これにより広い範囲で【海底】が急激に隆起・沈降し、その上の大量の海水が持ち上げられて【津波】となる。津波は【水深】が浅くなる海岸で波高が高くなる。"},
  {"id": "earthx20", "s": "earth", "lv": 2, "topic": "示相化石", "q": "示相化石とは何か。具体例をあげて説明せよ。", "a": "地層が堆積した当時の【環境】を推定するのに役立つ化石。生息環境が限られた生物が適している。例えば【サンゴ】の化石が見つかれば、その地層は暖かくきれいな浅い海で堆積したと推定できる。このような化石を【示相化石】という。"},
  {"id": "earthx21", "s": "earth", "lv": 3, "topic": "アイソスタシー", "q": "氷河が融けたスカンジナビア半島で、現在も土地が隆起し続けている理由を説明せよ。", "a": "地殻はマントルの上に浮かんでつり合っている（【アイソスタシー】）。氷期には厚い【氷床】の重みで地殻が沈み込んだが、氷床が融けて荷重が取り除かれたため、つり合いを回復しようとしてゆっくり【隆起】している。マントルは長い時間では【流動】するためである。"},
  {"id": "earthx22", "s": "earth", "lv": 3, "topic": "宇宙の膨張", "q": "遠い銀河ほど速く遠ざかっていることから、宇宙についてどのようなことがわかるか説明せよ。", "a": "遠い銀河のスペクトルは波長が長い方へずれる【赤方偏移】を示し、その後退速度は距離に比例する（【ハッブル・ルメートルの法則】）。これは宇宙全体が一様に【膨張】していることを示し、過去にさかのぼると宇宙は高温・高密度の状態から始まったという【ビッグバン】の考えを支持する。"},
  {"id": "earthx23", "s": "earth", "lv": 3, "topic": "縞状鉄鉱層", "q": "約25億〜20億年前に縞状鉄鉱層が大量に形成された理由を説明せよ。", "a": "【シアノバクテリア】の【光合成】によって海中に酸素が放出されると、それまで海水中に溶けていた【鉄イオン】が酸化されて酸化鉄となり、海底に沈殿して【縞状鉄鉱層】ができた。海中の鉄が消費された後、酸素は大気中に蓄積していった。"},
  {"id": "earthx24", "s": "earth", "lv": 3, "topic": "偏西風の蛇行", "q": "偏西風が大きく蛇行すると、異常気象が起こりやすくなる理由を説明せよ。", "a": "偏西風が大きく南北に【蛇行】すると、高緯度側の寒気が南下し、低緯度側の暖気が北上する。蛇行した状態が長く続く【ブロッキング】が起こると、高気圧や低気圧が同じ場所に停滞するため、【熱波】や【寒波】、大雨などの異常気象が長く続きやすくなる。"},
  {"id": "earthx25", "s": "earth", "lv": 3, "topic": "恒星の寿命", "q": "質量の大きい恒星ほど寿命が短い理由を説明せよ。", "a": "質量の大きい恒星は、自身の重力が大きいため中心部が高温・高圧となり、【核融合】反応がきわめて激しく進む。燃料となる【水素】の量は質量に比例して多いが、【光度】は質量の約3乗以上に比例して大きくなるため燃料を急速に消費し、【主系列星】の段階の寿命が短くなる。"},
  {"id": "jhx210", "s": "jh", "lv": 1, "topic": "弥生時代の墓制", "q": "弥生時代の墓制にはどのような特徴がみられるか。社会の変化と関連づけて説明せよ。", "a": "集落の近くに共同墓地がつくられ、九州北部では【甕棺墓】、各地では溝で区画した【方形周溝墓】が広がった。後期には大型の【墳丘墓】が現れ、副葬品の差から集団内に【身分差】が生じ、有力な首長が出現したことがわかる。"},
  {"id": "jhx211", "s": "jh", "lv": 2, "topic": "古墳時代の祭祀", "q": "古墳時代の人々の信仰や祭祀にはどのようなものがあったか、具体例を挙げて説明せよ。", "a": "農耕にかかわる祭りとして、豊作を祈る春の【祈年祭】や収穫を感謝する秋の【新嘗祭】が行われた。山や巨岩などを神のやどる所として祀り、汚れをはらう【禊】や【祓】、鹿の骨を焼いて吉凶を占う【太占】、裁判で真偽を判定する【盟神探湯】なども行われた。"},
  {"id": "jhx212", "s": "jh", "lv": 2, "topic": "群集墳", "q": "古墳時代後期に群集墳が各地に多数つくられたことは、どのような社会の変化を示しているか説明せよ。", "a": "6世紀には【横穴式石室】をもつ小規模な円墳などが一定地域に密集してつくられた。これは古墳をつくる層が首長層から【有力農民層】にまで広がったことを示し、ヤマト政権が彼らを直接【支配】に組み込もうとしたことと関わると考えられる。"},
  {"id": "jhx213", "s": "jh", "lv": 2, "topic": "終末期古墳", "q": "7世紀の終末期古墳にはどのような特徴があるか。政治の動きと関連させて説明せよ。", "a": "前方後円墳の造営が終わり、各地の古墳は小型化した。一方、大王の墓として独自の【八角墳】がつくられ、大王が豪族を超えた存在であることを示した。【高松塚古墳】のような壁画古墳も現れ、古墳は【中央集権】化の進展とともに【薄葬】へと向かった。"},
  {"id": "jhx214", "s": "jh", "lv": 1, "topic": "埴輪", "q": "古墳に並べられた埴輪には、どのような種類と役割があったか説明せよ。", "a": "埴輪は古墳の墳丘に並べられた素焼きの焼き物である。初めは墳丘を区画する【円筒埴輪】が中心だったが、のちに家・器財をかたどったものや、人物・動物をかたどった【形象埴輪】がつくられた。首長の【葬送儀礼】や生前の姿を表したと考えられる。"},
  {"id": "jhx215", "s": "jh", "lv": 2, "topic": "高句麗と倭", "q": "4〜5世紀の倭と朝鮮半島の関係について、好太王碑の内容にふれながら説明せよ。", "a": "倭は鉄資源や先進技術を求めて朝鮮半島南部の【加耶】諸国とつながりをもち、【百済】と結んだ。【好太王碑】には、倭が4世紀末に半島に出兵し、北方の【高句麗】と戦ったことが記されている。この戦いを通じて騎馬技術などが倭に伝わったとされる。"},
  {"id": "jhx216", "s": "jh", "lv": 3, "topic": "加耶諸国と倭", "q": "加耶諸国は倭にとってどのような意味をもつ地域であったか。6世紀の情勢の変化とあわせて説明せよ。", "a": "朝鮮半島南部の加耶は【鉄資源】の産地であり、倭は早くから密接な関係をもち、【鉄】や技術者の確保に努めた。しかし6世紀になると加耶は【新羅】と【百済】に圧迫され、562年までに新羅に併合された。これにより倭の半島での足がかりは失われ、【対外政策】の見直しを迫られた。"},
  {"id": "jhx217", "s": "jh", "lv": 2, "topic": "屯倉と部民", "q": "ヤマト政権は、屯倉や部民を通じてどのように地方と人々を支配したか説明せよ。", "a": "ヤマト政権は各地に直轄地である【屯倉】を設け、【田部】に耕作させた。また人々を職能や奉仕の単位である【部】に組織し、王権に奉仕する【名代・子代】の部などを設けた。豪族も私有地の【田荘】と私有民の部曲をもち、政権はこれらを通じて地方を間接的に支配した。"},
  {"id": "jhx218", "s": "jh", "lv": 2, "topic": "国造制", "q": "ヤマト政権の地方支配における国造の役割について説明せよ。", "a": "6世紀ごろ、ヤマト政権は服属した地方豪族を【国造】に任じ、その地域の支配を認めた。国造は地方の支配権を保障される代わりに、子女を【舎人】や采女として出仕させ、特産物を【貢納】し、軍事行動にも参加した。こうして政権は豪族を通じた【間接支配】を進めた。"},
  {"id": "jhx219", "s": "jh", "lv": 2, "topic": "八色の姓", "q": "天武天皇が定めた八色の姓には、どのような目的があったか説明せよ。", "a": "684年の【八色の姓】は、豪族を新たな秩序のもとに位置づけ直すものであった。【真人】や朝臣などを上位に置き、【皇族】との近さによって序列を定めた。これにより豪族を天皇中心の【身分秩序】に組み込み、律令官人として再編しようとした。"},
  {"id": "jhx220", "s": "jh", "lv": 2, "topic": "戸籍の作成", "q": "庚午年籍と庚寅年籍は、律令国家の形成においてどのような意義をもったか説明せよ。", "a": "670年に天智天皇のもとでつくられた【庚午年籍】は、初の全国的な戸籍で、氏姓を正す根本台帳として永久保存とされた。690年の【庚寅年籍】以降は6年ごとの作成が定着し、人民を一人一人把握して【班田収授】や【課税】を行う【律令国家】の基礎となった。"},
  {"id": "jhx221", "s": "jh", "lv": 1, "topic": "二官八省", "q": "律令制の中央官制である二官八省のしくみについて説明せよ。", "a": "中央には祭祀を担当する【神祇官】と、国政全般を統括する【太政官】の二官が置かれた。太政官のもとに中務省・式部省・民部省など【八省】が分かれて実務を担った。重要な政務は太政大臣・左右大臣などの【公卿】が合議し、天皇の裁可を得て行われた。"},
  {"id": "jhx222", "s": "jh", "lv": 2, "topic": "律令制の地方行政", "q": "律令制の地方行政組織について、中央との関係もふまえて説明せよ。", "a": "全国は畿内と七道に分けられ、その下に【国・郡・里】が置かれた。国には中央から貴族が【国司】として派遣され、郡には地方豪族を任じた【郡司】が置かれて実務を担った。要地には九州の【大宰府】などが設けられ、地方豪族の伝統的支配力を利用しつつ中央集権を図った。"},
  {"id": "jhx223", "s": "jh", "lv": 3, "topic": "蔭位の制", "q": "律令制における蔭位の制とはどのような制度か。それが貴族社会に与えた影響とともに説明せよ。", "a": "【蔭位の制】は、五位以上の貴族の子や三位以上の孫が、成人すると父祖の位階に応じて一定の【位階】を自動的に与えられる制度である。高位の官人には【位田】や封戸などの経済的特権もあったため、上級貴族の地位が【世襲】的に維持され、旧来の有力豪族が【貴族】として存続した。"},
  {"id": "jhx224", "s": "jh", "lv": 1, "topic": "本朝十二銭", "q": "律令政府が和同開珎などの銭貨を発行した目的と、その流通の実態について説明せよ。", "a": "708年、唐にならって【和同開珎】を鋳造し、【平城京】造営の費用支払いなどに用いた。政府は711年に【蓄銭叙位令】を出して流通をうながしたが、京や畿内以外では稲や布による【物々交換】が中心で、銭貨の流通は限られた。以後10世紀まで計12種類の銭が鋳造された。"},
  {"id": "jhx225", "s": "jh", "lv": 1, "topic": "律令制の交通", "q": "律令国家は地方との連絡のためにどのような交通制度を整えたか説明せよ。", "a": "都と地方を結ぶ【七道】の官道を整備し、約16kmごとに【駅家】を置いて、公用の役人が馬を乗り継げるようにした（【駅制】）。地方からは【調・庸】などを都まで運ぶ運脚が人民の負担で行われ、往復の旅は大きな苦しみとなった。"},
  {"id": "jhx226", "s": "jh", "lv": 1, "topic": "万葉集", "q": "『万葉集』にはどのような特徴があるか説明せよ。", "a": "『万葉集』は奈良時代に成立した現存最古の【和歌集】で、約4500首を収める。天皇・貴族から【防人】や農民の歌まで幅広い身分の人々の歌が含まれ、漢字の音訓を用いて日本語を表記する【万葉仮名】で書かれた。柿本人麻呂や【山上憶良】らが知られる。"},
  {"id": "jhx227", "s": "jh", "lv": 2, "topic": "風土記", "q": "713年に編纂が命じられた風土記は、律令国家にとってどのような意味をもったか説明せよ。", "a": "朝廷は諸国に、郡郷の名の由来や【産物】、土地の肥えぐあい、【伝承】などをまとめさせた。これは地方の実情を把握して【地方支配】に役立てるとともに、各地の伝承を国家のもとに集める意味をもった。完全な形で残るのは【出雲国風土記】のみである。"},
  {"id": "jhx228", "s": "jh", "lv": 2, "topic": "渤海との交流", "q": "奈良時代に日本と渤海との間で交流が行われた背景とその内容を説明せよ。", "a": "中国東北部に建国した【渤海】は、【唐】や【新羅】と対立していたため日本に使節を送り、国交を求めた。日本も新羅との関係が悪化していたため友好関係を保ち、渤海使は【毛皮】などをもたらし、日本からは絹などが贈られた。交流は【日本海】を通じて約200年続いた。"},
  {"id": "jhx229", "s": "jh", "lv": 3, "topic": "奈良時代の対新羅関係", "q": "奈良時代の日本と新羅の関係はどのように推移したか。日本の対外意識とあわせて説明せよ。", "a": "朝鮮半島を統一した【新羅】に対し、日本は新羅を【従属国】とみなす姿勢をとった。これに対して新羅が対等の関係を求めたため、両国関係はしばしば【緊張】し、藤原仲麻呂は新羅攻撃を計画したこともあった。一方で新羅商人による【交易】は続き、8世紀末に公的な使節の往来は途絶えた。"},
  {"id": "jhx230", "s": "jh", "lv": 1, "topic": "神仏習合", "q": "神仏習合とはどのような考え方か。平安時代の本地垂迹説にふれて説明せよ。", "a": "日本古来の神々への信仰と仏教とが融合する考え方を【神仏習合】という。奈良時代から神社に【神宮寺】が建てられ、平安時代には、仏が人々を救うために仮に神の姿で現れたとする【本地垂迹説】が広まった。神前で経が読まれるなど、両者は深く結びついた。"},
  {"id": "jhx231", "s": "jh", "lv": 2, "topic": "三代格式", "q": "平安時代初期に格式が編纂された理由と、その意義について説明せよ。", "a": "律令制定後、社会の変化に応じて律令を補足・修正する【格】や施行細則である【式】が多数出されていた。嵯峨天皇は【弘仁格式】を編纂させ、のちに貞観格式・【延喜格式】と続いた。これにより実際の政務の基準が整理され、律令を現実に合わせて【運用】する体制が整った。"},
  {"id": "jhx232", "s": "jh", "lv": 3, "topic": "公営田と官田", "q": "9世紀に設けられた公営田や官田は、どのような目的で設けられたか説明せよ。", "a": "9世紀には戸籍の偽りや逃亡で【班田】が困難となり、調・庸の収入が減少した。そこで823年に大宰府管内に【公営田】、879年に畿内に【官田】を設け、有力農民を使って【直営】方式で耕作させ、その収穫で【財源】を確保しようとした。これは【律令制】の原則が崩れつつあることを示す。"},
  {"id": "jhx233", "s": "jh", "lv": 2, "topic": "延喜の荘園整理令", "q": "醍醐天皇の時代に出された延喜の荘園整理令は、どのような目的をもち、どのような結果となったか説明せよ。", "a": "902年の【延喜の荘園整理令】は、院宮王臣家が農民の土地を買い取ったり、農民が田地を寄進したりして生まれる不法な荘園を禁じ、【班田】を励行して【律令制】を立て直そうとするものであった。しかし効果は上がらず、班田はこの年が最後となり、政府は【受領】に徴税を任せる方向へ転換した。"},
  {"id": "jhx234", "s": "jh", "lv": 3, "topic": "負名体制", "q": "10世紀以降の地方の徴税のしくみである負名体制について説明せよ。", "a": "10世紀になると人を単位とする課税が困難となったため、国司は田地を【名】という単位に編成し、耕作と納税を【田堵】と呼ばれる有力農民に請け負わせた。請け負った者を【負名】という。課税の対象が人から【土地】へと移り、国司はこれを通じて【官物】や臨時雑役を徴収した。"},
  {"id": "jhx235", "s": "jh", "lv": 2, "topic": "刀伊の入寇", "q": "1019年の刀伊の入寇は、当時の国家と武士についてどのようなことを示しているか説明せよ。", "a": "沿海州の女真族とされる【刀伊】が対馬・壱岐を襲い、北九州に侵入した。中央政府はほとんど対応できず、【大宰権帥】の【藤原隆家】が九州の武士たちを指揮して撃退した。これは中央の軍事力が衰え、地方の【武士】が実際の防衛を担う存在となっていたことを示している。"},
  {"id": "jhx236", "s": "jh", "lv": 1, "topic": "武士団の形成", "q": "平安時代中期に武士団が形成された背景について説明せよ。", "a": "地方政治が乱れ、国司と地方豪族の対立や土地をめぐる争いが増えると、【地方豪族】や有力農民は土地を守るために武装した。彼らは一族の【家子】や従者の【郎党】を率いて武士団をつくり、やがて【清和源氏】や桓武平氏など、都から下った【軍事貴族】を棟梁として大きな武士団にまとまった。"},
  {"id": "jhx237", "s": "jh", "lv": 2, "topic": "奥州藤原氏", "q": "奥州藤原氏が東北地方で長く繁栄できた理由について説明せよ。", "a": "後三年合戦ののち、【藤原清衡】は陸奥・出羽の支配を確立し、平泉を拠点とした。奥州藤原氏は東北の【金】や馬などの豊かな産物を背景に、京都の文化を取り入れて【中尊寺金色堂】を建立するなど、約100年にわたり繁栄した。中央から離れた【平泉】を中心に独自の勢力を築いたが、1189年に源頼朝に滅ぼされた。"},
  {"id": "jhx238", "s": "jh", "lv": 1, "topic": "知行国制", "q": "院政期に広まった知行国制とはどのような制度か説明せよ。", "a": "【知行国】制は、上級貴族や寺社に一国の【支配権】を与え、その国からの【収益】を得させる制度である。知行国主は子弟や近親者を【国守】に任じ、実際の支配は目代に行わせた。院自身が収益を得る【院分国】もあり、院政の経済的基盤となった。"},
  {"id": "jhx239", "s": "jh", "lv": 3, "topic": "荘園公領制", "q": "院政期に成立した荘園公領制とはどのような体制か。その構造を説明せよ。", "a": "院政期には【荘園】が急増する一方、国司の支配する国衙領（【公領】）も郡・郷・保などに再編された。土地は荘園と公領とに大きく分かれ、いずれも在地では開発領主などが【荘官】や郡司・郷司として現地を管理した。上から本家・領家、下に現地の管理者と【名主】という重層的な【職】の体系で土地が支配される体制である。"},
  {"id": "jhx240", "s": "jh", "lv": 2, "topic": "僧兵の強訴", "q": "院政期に大寺院が行った強訴とはどのようなものか。それが武士の台頭とどう関わったか説明せよ。", "a": "興福寺や延暦寺などの大寺院は、【僧兵】を組織し、神木や神輿を押し立てて朝廷に要求を突きつける【強訴】をくり返した。朝廷はこれを抑えるため、【源平】の武士を警備に用いた。その結果、武士は中央政界に進出する足がかりを得、【武士の台頭】が進んだ。"},
  {"id": "jhx241", "s": "jh", "lv": 1, "topic": "保元・平治の乱", "q": "保元の乱と平治の乱は、政治の主導権の移り変わりにどのような影響を与えたか説明せよ。", "a": "1156年の【保元の乱】は、皇位継承や摂関家の内部対立が武士の力で決着した戦いであった。1159年の【平治の乱】では、院近臣の対立から源義朝が敗れ、【平清盛】が勢力を伸ばした。二つの乱により、貴族の争いも【武士】の力なしには解決できないことが明らかになり、【武家政権】成立への道が開かれた。"},
  {"id": "jhx242", "s": "jh", "lv": 1, "topic": "日宋貿易", "q": "平清盛が日宋貿易に力を入れた理由と、その影響について説明せよ。", "a": "清盛は瀬戸内海航路を整え、摂津の【大輪田泊】を修築して宋の商人を畿内に招いた。宋からは【宋銭】や陶磁器・書籍などが輸入され、日本からは金や硫黄などが輸出された。貿易の利益は【平氏政権】の経済基盤となり、宋銭の流入はのちの【貨幣経済】の発展をうながした。"},
  {"id": "jhx243", "s": "jh", "lv": 2, "topic": "治承・寿永の乱", "q": "治承・寿永の乱が全国的な内乱となった背景について説明せよ。", "a": "平氏による権力独占や、【後白河法皇】の幽閉への反発が強まる中、1180年に【以仁王】が平氏打倒の令旨を出し、源頼朝や源義仲らが挙兵した。各地の武士は、国司や荘園領主との対立を背景に、自らの【所領】の支配を確かなものにしようとして挙兵に加わったため、内乱は【全国】に広がった。"},
  {"id": "jhx244", "s": "jh", "lv": 3, "topic": "寿永二年十月宣旨", "q": "1183年の寿永二年十月宣旨は、鎌倉幕府の成立過程においてどのような意義をもつか説明せよ。", "a": "この宣旨で朝廷は、源頼朝に【東海道・東山道】の荘園・公領の年貢を領主に納めさせることを命じ、その実行のための【支配権】を認めた。これにより反乱軍であった頼朝の【東国支配】が朝廷から公的に承認された。のちの守護・地頭の設置とともに、幕府が【公権力】として成立する重要な段階となった。"},
  {"id": "jhx245", "s": "jh", "lv": 2, "topic": "鎌倉幕府の経済基盤", "q": "鎌倉幕府の経済的基盤にはどのようなものがあったか説明せよ。", "a": "幕府は、将軍が知行国主となる【関東知行国】（関東御分国）と、平家没官領などを中心とする将軍家の荘園である【関東御領】を経済基盤とした。また多数の【地頭職】をもち、【御家人】に与えて奉公の対価とした。これらにより幕府は朝廷と並ぶ大きな経済力を有した。"},
  {"id": "jhx246", "s": "jh", "lv": 3, "topic": "鎌倉時代の公武関係", "q": "鎌倉時代前期の朝廷と幕府の関係について、承久の乱の前後の変化にふれて説明せよ。", "a": "幕府成立当初、朝廷は国司を任命し、【荘園領主】も年貢を得るなど、朝廷と幕府が並立する【公武二元】的な支配が行われた。しかし【承久の乱】で幕府が勝利すると、【六波羅探題】が朝廷を監視し、皇位継承にも幕府が関与するようになった。これにより幕府の優位が確立し、支配は西国にも及んだ。"},
  {"id": "jhx247", "s": "jh", "lv": 2, "topic": "永仁の徳政令", "q": "1297年の永仁の徳政令は、どのような目的で出され、どのような結果となったか説明せよ。", "a": "分割相続による所領の細分化や【蒙古襲来】の負担、貨幣経済の浸透などで御家人は窮乏していた。幕府は【御家人】の救済のため、【永仁の徳政令】で御家人の所領の質入れ・売買を禁じ、すでに売却した所領を【無償】で取り戻させた。しかし金融の停滞などを招いて効果は一時的で、御家人の幕府への【不満】は高まった。"},
  {"id": "jhx248", "s": "jh", "lv": 2, "topic": "悪党", "q": "鎌倉時代後期に各地で活動した悪党とはどのような存在か説明せよ。", "a": "鎌倉時代後期、畿内やその周辺で、荘園領主や幕府の支配に反抗して武力で年貢を奪ったり所領を侵したりする者たちが現れ、【悪党】と呼ばれた。彼らは【非御家人】の武士や商人なども含み、流通や【商業】の発達を背景に力をつけた。悪党の動きは幕府の【支配】の動揺を示している。"},
  {"id": "jhx249", "s": "jh", "lv": 2, "topic": "日元間の交流", "q": "元寇の後も日本と元の間で民間の交流が続いたことについて、具体例を挙げて説明せよ。", "a": "蒙古襲来後も両国の間に正式な国交はなかったが、民間の【貿易】や僧侶の往来は盛んだった。幕府は【建長寺】の修造費用を得るため貿易船を派遣し、足利尊氏・直義も【後醍醐天皇】の冥福を祈る寺の造営費用を得るため【天龍寺船】を送った。禅僧の往来を通じて【禅宗】の文化も伝わった。"},
  {"id": "jhx250", "s": "jh", "lv": 2, "topic": "鎌倉時代の女性", "q": "鎌倉時代の武士の家における女性の地位について説明せよ。", "a": "鎌倉時代の武士の家では【分割相続】が行われ、女性も財産の分配を受けた。女性が【地頭】や御家人になる例もみられた。しかし後期になると、所領の細分化を防ぐために女性の相続分は本人一代限りとする【一期分】が多くなり、やがて【単独相続】が広まって女性の地位は低下していった。"},
  {"id": "jhx251", "s": "jh", "lv": 2, "topic": "神国思想", "q": "蒙古襲来は、日本人の意識にどのような影響を与えたか。神国思想に着目して説明せよ。", "a": "【蒙古襲来】の際に暴風雨が元軍に大きな損害を与えたことなどから、日本は神々に守られた国であるという【神国思想】が強まった。寺社は異国降伏の【祈祷】の功績を主張して幕府に恩賞を求めた。この思想はその後も対外的な危機のたびに強調され、日本の【自国意識】に影響を与えた。"},
  {"id": "jhx252", "s": "jh", "lv": 2, "topic": "観応の擾乱", "q": "観応の擾乱とはどのような争いか。それが南北朝の動乱を長期化させた理由とあわせて説明せよ。", "a": "室町幕府の内部で、足利尊氏の執事【高師直】と尊氏の弟【足利直義】が対立し、1350年に武力衝突に発展した。尊氏・直義も争い、各勢力が有利になるよう時に【南朝】と結んだため、南朝は勢力を保った。武士の【惣領制】の解体による一族内の対立も重なり、動乱は【長期化】した。"},
  {"id": "jhx253", "s": "jh", "lv": 1, "topic": "半済令", "q": "室町幕府が出した半済令とはどのようなもので、守護にどのような影響を与えたか説明せよ。", "a": "1352年に出された【半済令】は、近江・美濃・尾張の3国に限り、1年間、荘園・公領の年貢の【半分】を守護が【兵粮米】として徴収することを認めたものである。のちに全国化・恒常化し、守護は年貢の半分を配下の【武士】に分け与えて統制を強め、【守護大名】へと成長した。"},
  {"id": "jhx254", "s": "jh", "lv": 2, "topic": "鎌倉府", "q": "室町幕府が設けた鎌倉府の役割と、幕府との関係の変化について説明せよ。", "a": "【鎌倉府】は東国支配のために置かれ、足利尊氏の子基氏の子孫が長官の【鎌倉公方】を世襲し、上杉氏が補佐役の【関東管領】を務めた。鎌倉府は大きな権限をもち、しだいに京都の幕府と【対立】するようになった。1438年の【永享の乱】で公方足利持氏が討たれ、関東は混乱に向かった。"},
  {"id": "jhx255", "s": "jh", "lv": 1, "topic": "倭寇", "q": "14世紀と16世紀の倭寇には、どのような違いがあるか説明せよ。", "a": "14世紀の【前期倭寇】は、対馬・壱岐・肥前松浦地方の人々が中心で、朝鮮半島や中国沿岸で米や人を略奪した。16世紀の【後期倭寇】は、【明】の海禁政策に反発して密貿易を行った【中国人】が多くを占めた。後期倭寇は豊臣秀吉の【海賊取締令】などで終息した。"},
  {"id": "jhx256", "s": "jh", "lv": 3, "topic": "寧波の乱", "q": "1523年の寧波の乱は、日明貿易の担い手の変化をどのように示しているか説明せよ。", "a": "応仁の乱後、幕府が衰えると日明貿易の実権は、堺商人と結ぶ【細川氏】と博多商人と結ぶ【大内氏】に移った。両者は【寧波】で勘合をめぐって衝突し、この【寧波の乱】ののち大内氏が貿易を独占した。貿易の主体が幕府から有力【守護大名】と商人へ移ったことを示している。"},
  {"id": "jhx257", "s": "jh", "lv": 2, "topic": "中世の座", "q": "中世の商工業者がつくった座とはどのようなものか。その特権と後の変化を説明せよ。", "a": "【座】は商工業者の同業者団体で、天皇家や貴族・寺社を【本所】としてあおぎ、奉仕や座役を納める代わりに【販売】や製造の独占権、関銭の免除などの特権を認められた。大山崎の【油座】が有名である。戦国時代になると新興商人の台頭で特権は動揺し、戦国大名や織田信長の【楽市】政策で否定された。"},
  {"id": "jhx258", "s": "jh", "lv": 3, "topic": "撰銭令", "q": "室町時代から戦国時代にかけて撰銭令が出された背景と目的を説明せよ。", "a": "室町時代には【明銭】などの輸入銭が流通したが、民間で鋳造された粗悪な【私鋳銭】も多く、取引の際に悪銭を嫌って良銭を選ぶ【撰銭】が行われた。このため取引が円滑に進まなくなった。幕府や戦国大名は【撰銭令】を出し、悪銭と良銭の交換比率を定めたり一部の撰銭を禁じたりして、【流通】の円滑化を図った。"},
  {"id": "jhx259", "s": "jh", "lv": 2, "topic": "嘉吉の徳政一揆", "q": "1441年の嘉吉の徳政一揆の結果、幕府はどのような対応をとったか。その背景もあわせて説明せよ。", "a": "将軍【足利義教】が殺害された嘉吉の変の直後、新将軍の代始めを理由に、京都周辺の農民らが【徳政】を求めて大規模に蜂起した。幕府は一揆の要求を受け入れ、初めて【徳政令】を出した。その後幕府は債務額の一部を納めさせて徳政を認める【分一銭】を徴収するなど、徳政令を財源確保にも利用した。"},
  {"id": "jhx260", "s": "jh", "lv": 2, "topic": "蓮如と一向宗", "q": "浄土真宗（一向宗）が戦国時代に北陸や東海・近畿で勢力を伸ばした理由を説明せよ。", "a": "本願寺の【蓮如】は、平易な文章で教えを説いた【御文】を用いて布教し、門徒を【講】に組織した。この組織は惣村の結びつきと結合し、農民や武士、商工業者に広まった。門徒は強い団結力をもち、【一向一揆】を起こして加賀では守護を倒し、約100年にわたって【自治】を行った。"},
  {"id": "jhx261", "s": "jh", "lv": 3, "topic": "法華一揆", "q": "16世紀前半の京都における法華一揆の展開について説明せよ。", "a": "京都では、【日親】の布教などにより日蓮宗（法華宗）が商工業者の【町衆】に広まった。1532年に法華一揆を結んで一向一揆と対決し、京都の【自治】的な運営を行った。しかし1536年に【延暦寺】の僧兵と衝突して敗れ、法華宗の寺院は京都から追われた（【天文法華の乱】）。"},
  {"id": "jhx262", "s": "jh", "lv": 2, "topic": "五山・十刹の制", "q": "室町幕府が臨済宗を保護して整えた五山・十刹の制について、その意義を説明せよ。", "a": "幕府は【臨済宗】を保護し、南宋の制度にならって【五山・十刹の制】を整え、寺格を定めて官寺とした。五山の禅僧は中国の文化や学問に通じ、【外交文書】の作成や政治顧問として幕府に仕えた。また漢詩文の【五山文学】や朱子学の研究も行われ、【水墨画】など禅の文化が広がった。"},
  {"id": "jhx263", "s": "jh", "lv": 1, "topic": "能と狂言", "q": "室町時代に能が大成された経緯と、狂言との違いについて説明せよ。", "a": "能は田楽・【猿楽】などの芸能から発展し、足利義満の保護を受けた【観阿弥】・【世阿弥】父子によって大成された。世阿弥は【風姿花伝】で能の理論を記した。能が歌や舞を中心とする幽玄な芸能であるのに対し、【狂言】は能の合間に演じられ、日常の会話を用いて庶民を描く喜劇であった。"},
  {"id": "jhx264", "s": "jh", "lv": 2, "topic": "連歌", "q": "室町時代に連歌が広く流行した理由について説明せよ。", "a": "連歌は、和歌の上の句と下の句を複数の人が交互につないでいく文芸で、集まった人々が共同で作る【寄合】の文芸であった。南北朝期に【二条良基】が規則を定め、地位を高めた。のちに【宗祇】が正風連歌を確立し、諸国を旅して広めたため、【地方武士】や庶民にまで広がった。山崎宗鑑は俗語を用いた【俳諧連歌】をはじめた。"},
  {"id": "jhx265", "s": "jh", "lv": 3, "topic": "貫高制", "q": "戦国大名が採用した貫高制とはどのような制度か。その目的を説明せよ。", "a": "【貫高制】は、家臣や農民の所領・田畑の収入を銭に換算した【貫高】で表示する制度である。戦国大名は【検地】で把握した貫高を基準に、農民には【年貢】を負担させ、家臣には貫高に応じた【軍役】を負担させた。これにより大名は家臣団と領国を統一的な基準で支配できた。"},
  {"id": "jhx266", "s": "jh", "lv": 2, "topic": "指出検地", "q": "戦国大名の指出検地と豊臣秀吉の太閤検地の違いについて説明せよ。", "a": "戦国大名や織田信長が行った【指出検地】は、家臣や寺社などに土地の面積や収入を【自己申告】させる方式であった。これに対して太閤検地は、役人を派遣して統一した【ものさし】で田畑を実地に測量し、【石高】で表示した。これにより土地の直接把握が進み、【中間搾取】が排除された。"},
  {"id": "jhx267", "s": "jh", "lv": 1, "topic": "南蛮貿易", "q": "16世紀後半の南蛮貿易の特徴について、その担い手と取引品にふれて説明せよ。", "a": "【ポルトガル】人やスペイン人との貿易を南蛮貿易という。ポルトガル人は【マカオ】を拠点に、中国産の【生糸】や鉄砲・火薬などをもたらし、日本からは主に【銀】が輸出された。貿易は【キリスト教】の布教と一体で行われたため、九州の大名には貿易の利益を求めてキリスト教を保護する者も現れた。"},
  {"id": "jhx268", "s": "jh", "lv": 2, "topic": "天正遣欧使節", "q": "天正遣欧使節が派遣された背景と、帰国後の状況について説明せよ。", "a": "1582年、イエズス会宣教師【ヴァリニャーニ】のすすめにより、【キリシタン大名】の大友義鎮・有馬晴信・大村純忠が4人の少年をローマ教皇のもとに派遣した。使節はヨーロッパで歓迎されたが、1590年の帰国時にはすでに【バテレン追放令】が出されており、その後の【禁教】で苦難をたどった。"},
  {"id": "jhx269", "s": "jh", "lv": 3, "topic": "惣無事令", "q": "豊臣秀吉が出した惣無事令とはどのようなものか。その全国統一における意義を説明せよ。", "a": "秀吉は【関白】の地位につき、天皇の権威を背景に全国の大名に【停戦】を命じ、領地の確定を秀吉の裁定に委ねさせた。これを【惣無事令】という。これに違反した島津氏や【北条氏】を討伐することで、大名間の私戦を否定し、【全国統一】を正当化した。"},
  {"id": "jhx270", "s": "jh", "lv": 2, "topic": "石高制", "q": "太閤検地によって成立した石高制は、近世社会のしくみの中でどのような役割を果たしたか説明せよ。", "a": "太閤検地で土地の生産力は米の量である【石高】で表示されるようになった。大名の領地の大きさは石高で示され、大名は石高に応じて【軍役】を負担した。また村の石高（村高）を基準に【年貢】が課された。このように石高は、【大名】の格付けや負担、農民の負担を統一的に定める近世社会の基本となった。"},
  {"id": "jhx271", "s": "jh", "lv": 2, "topic": "兵農分離", "q": "兵農分離とはどのようなことか。それを進めた豊臣政権の政策を挙げて説明せよ。", "a": "兵農分離とは、武士と農民の身分を分けることである。豊臣秀吉は【太閤検地】で耕作者を検地帳に登録して土地に結びつけ、【刀狩】で農民から武器を取り上げた。さらに【人掃令】で武士が町人・百姓になることなどを禁じた。こうして武士は【城下町】に集住し、農民は村で耕作に専念する体制がつくられた。"},
  {"id": "jhx272", "s": "jh", "lv": 3, "topic": "豊臣政権の財政基盤", "q": "豊臣政権の財政基盤について、蔵入地と鉱山・都市の支配に着目して説明せよ。", "a": "豊臣政権は約200万石の直轄地（【蔵入地】）をもち、年貢を財源とした。さらに【佐渡金山】や石見大森銀山などの主要な鉱山を直轄して金銀を得て、天正大判などの【貨幣】を鋳造した。また京都・大坂・堺・【長崎】などの重要都市を直轄し、豪商の経済力を利用した。"},
  {"id": "jhx273", "s": "jh", "lv": 2, "topic": "豊臣政権の政治機構", "q": "豊臣政権の政治機構にはどのような特徴と弱点があったか説明せよ。", "a": "豊臣政権では、腹心の家臣を【五奉行】として政務を分担させ、有力大名を【五大老】として重要政務を合議させた。しかし整った【官僚機構】は十分に発達せず、政権は秀吉個人の力に依存していた。秀吉の死後、五大老の筆頭【徳川家康】が勢力を伸ばし、【関ヶ原の戦い】を経て政権を握った。"},
  {"id": "jhx274", "s": "jh", "lv": 1, "topic": "関ヶ原の戦い", "q": "関ヶ原の戦いは、その後の政治にどのような影響を与えたか説明せよ。", "a": "秀吉の死後、【徳川家康】と石田三成の対立から、1600年に【関ヶ原の戦い】が起こった。家康の東軍が勝利し、西軍の大名を【改易】・減封してその所領を没収した。これにより家康の覇権が確立し、1603年に家康は【征夷大将軍】となって江戸幕府を開いた。"},
  {"id": "jhx275", "s": "jh", "lv": 2, "topic": "一国一城令", "q": "1615年に出された一国一城令の目的について説明せよ。", "a": "【大坂の陣】で豊臣氏を滅ぼした後、幕府は【一国一城令】を出し、大名の居城を一つに限り、その他の城を破却させた。これは大名の【軍事力】を削減するとともに、家臣を城下に集めて大名の【家臣統制】を強めることにもつながった。同年には武家諸法度も出され、幕府による大名統制が本格化した。"},
  {"id": "jhx276", "s": "jh", "lv": 3, "topic": "幕藩体制の構造", "q": "幕藩体制とはどのような支配体制か説明せよ。", "a": "幕藩体制とは、将軍（【幕府】）と大名（【藩】）が、それぞれ土地と人民を支配する体制である。将軍は大名に【領知】を与え、大名は将軍に【軍役】などで奉仕する主従関係を結んだ。幕府は約400万石の直轄地と主要都市・鉱山をもち、大名を統制したが、藩内の政治は各大名に任された。強力な【将軍権力】と大名の領国支配が結びついた体制である。"},
  {"id": "jhx277", "s": "jh", "lv": 3, "topic": "知行制の変化", "q": "江戸時代の藩における家臣への知行のあり方は、どのように変化したか。その意味とあわせて説明せよ。", "a": "当初、多くの藩では家臣に領地を与え、その領民を直接支配させる【地方知行制】がとられた。しかし17世紀後半にかけて、藩が年貢を一括して徴収し、家臣には蔵米を支給する【俸禄制度】へ移行する藩が増えた。これにより家臣は領民との結びつきを失って【城下町】の官僚的な存在となり、【藩主】の権力が強化された。"},
  {"id": "jhx278", "s": "jh", "lv": 1, "topic": "朱印船貿易", "q": "江戸時代初期の朱印船貿易について、その特徴と影響を説明せよ。", "a": "徳川家康は、大名や商人に海外渡航を許可する【朱印状】を与えて貿易を保護した。朱印船は主に【東南アジア】各地に渡り、中国産の生糸などを求めた。日本からは【銀】が輸出された。東南アジアには日本人が移住して【日本町】がつくられたが、鎖国政策の進行で衰退した。"},
  {"id": "jhx279", "s": "jh", "lv": 2, "topic": "糸割符制度", "q": "1604年に始まった糸割符制度とはどのような制度か。その目的を説明せよ。", "a": "【糸割符制度】は、京都・堺・長崎（のちに江戸・大坂も加わる）の特定の商人に【糸割符仲間】をつくらせ、【ポルトガル】船が運んでくる中国産【生糸】を一括購入させ、仲間に配分させる制度である。これにより輸入価格の主導権をポルトガル商人から奪い、利益を独占させないことが目的であった。"},
  {"id": "jhx280", "s": "jh", "lv": 2, "topic": "薩摩藩の琉球支配", "q": "1609年以降、琉球王国はどのような立場に置かれたか説明せよ。", "a": "1609年、【薩摩藩】の島津氏が琉球王国を征服し、検地を行って石高を定め、年貢を納めさせた。一方で琉球は【中国】への朝貢を続けたため、薩摩藩は朝貢を通じた貿易の利益を得た。琉球は将軍の代替わりごとに【慶賀使】、国王の代替わりごとに【謝恩使】を江戸に送り、日中両属の状態に置かれた。"},
  {"id": "jhx281", "s": "jh", "lv": 2, "topic": "シャクシャインの戦い", "q": "1669年のシャクシャインの戦いが起こった背景と、その結果について説明せよ。", "a": "蝦夷地では【松前藩】がアイヌとの交易独占権を幕府から認められ、家臣に交易場（【商場】）を与えていた。交易条件がアイヌに不利になると、首長【シャクシャイン】を中心にアイヌが蜂起した。松前藩は津軽藩の協力も得て鎮圧し、その後アイヌは松前藩に従属を強いられ、のちに商人が交易を請け負う【場所請負制度】に移行した。"},
  {"id": "jhx282", "s": "jh", "lv": 1, "topic": "朝鮮通信使", "q": "江戸時代の日朝関係について、朝鮮通信使と対馬藩の役割にふれて説明せよ。", "a": "豊臣秀吉の朝鮮侵略で断絶した国交は、【対馬藩】の宗氏の努力で回復し、1609年に【己酉約条】が結ばれた。対馬藩は【釜山】の倭館で貿易を独占した。朝鮮からは将軍の代替わりなどに【朝鮮通信使】が来日し、各地で文化交流が行われた。"},
  {"id": "jhx283", "s": "jh", "lv": 2, "topic": "オランダ風説書", "q": "江戸幕府がオランダ風説書を提出させた目的と、その意義について説明せよ。", "a": "鎖国体制のもとで、幕府は【長崎】の【出島】に来航するオランダ船に、海外の情勢を記した【オランダ風説書】を提出させた。幕府はこれによって海外の動きを把握し、【情報】を独占した。アヘン戦争やペリー来航の予告なども伝えられ、幕府の【対外政策】に影響を与えた。"},
  {"id": "jhx284", "s": "jh", "lv": 2, "topic": "慶安の変と牢人問題", "q": "慶安の変ののち、幕府の大名政策はどのように変化したか説明せよ。", "a": "17世紀前半、大名の【改易】が相次いで多数の【牢人】が生まれ、社会不安が高まった。1651年、牢人の由井正雪らが幕府転覆を図る【慶安の変】が起こった。これをきっかけに幕府は【末期養子の禁】を緩和して大名家の断絶を減らし、武力による統制から秩序を重んじる【文治政治】へと転換した。"},
  {"id": "jhx285", "s": "jh", "lv": 2, "topic": "田畑永代売買禁止令", "q": "17世紀に幕府が田畑永代売買禁止令や分地制限令を出した目的を説明せよ。", "a": "幕府や藩の財政は、【本百姓】が納める年貢に依存していた。1643年の【田畑永代売買の禁止令】は、田畑の売買によって本百姓が没落し、土地が一部の者に集中することを防ぐためのものであった。また1673年の【分地制限令】は、相続による耕地の細分化を防ぐものであった。いずれも本百姓の【経営】を維持し、【年貢】を確保することがねらいであった。"},
  {"id": "jhx286", "s": "jh", "lv": 1, "topic": "新田開発", "q": "17世紀に新田開発が進んだ背景と、その結果について説明せよ。", "a": "17世紀には幕府や大名が年貢の増収を図って大規模な【治水】・灌漑工事を行い、【新田開発】を進めた。18世紀には商人の資金による【町人請負新田】も現れた。その結果、全国の【耕地面積】は江戸時代初めの約2倍に増え、【人口】も増加した。"},
  {"id": "jhx287", "s": "jh", "lv": 2, "topic": "株仲間", "q": "江戸時代の株仲間とはどのようなものか。幕府の政策との関係を説明せよ。", "a": "【株仲間】は都市の商工業者の同業者組合で、営業の【独占】を幕府や藩から公認された。享保の改革では物価統制のために公認され、【田沼意次】は営業税である【運上・冥加】の増収のため積極的に公認した。天保の改革では物価高騰の原因とされて【解散】を命じられたが、効果がなく、のちに再興された。"},
  {"id": "jhx288", "s": "jh", "lv": 2, "topic": "蔵物と納屋物", "q": "江戸時代の大坂に集まった蔵物と納屋物の違いと、大坂が「天下の台所」と呼ばれた理由を説明せよ。", "a": "諸藩は【蔵屋敷】を大坂に置き、年貢米や特産物である【蔵物】を運び込んで販売し、貨幣を得た。一方、民間の商人が扱う商品を【納屋物】という。大坂には全国から物資が集まり、【堂島米市場】などで取引された。このように全国の物資の集散地であったため、大坂は【天下の台所】と呼ばれた。"},
  {"id": "jhx289", "s": "jh", "lv": 3, "topic": "村方騒動", "q": "18世紀後半以降に増加した村方騒動の背景を、農村の変化にふれて説明せよ。", "a": "18世紀になると【貨幣経済】が農村に浸透し、商品作物の生産が広がる一方、農民の階層分化が進んだ。土地を集めて【地主】となる富農と、土地を失って【小作人】となる貧農とに分かれた。村役人を兼ねる富農の不正や村の運営に対して一般の百姓が抗議する【村方騒動】が増加し、【村落共同体】の変質を示した。"},
  {"id": "jhx290", "s": "jh", "lv": 2, "topic": "明暦の大火", "q": "1657年の明暦の大火は、江戸の都市と幕府財政にどのような影響を与えたか説明せよ。", "a": "【明暦の大火】で江戸城の天守を含む市街の大半が焼失した。幕府は大名屋敷や寺社の移転、【火除地】や広小路の設置などで都市を改造し、江戸の市街は拡大した。一方、復興費用は【幕府財政】を圧迫し、鉱山の産出量減少とあわせて財政が悪化し、のちの【元禄】期の財政難の一因となった。"},
  {"id": "jhx291", "s": "jh", "lv": 2, "topic": "石門心学", "q": "石田梅岩が説いた心学の内容と、それが広まった理由について説明せよ。", "a": "京都の商人出身の【石田梅岩】は、儒教・仏教・神道を融合して、庶民に生活倫理を説いた【心学】を開いた。商人の【利潤】追求は正当な行為であると認め、正直・倹約などの徳目を重視した。商業を卑しむ風潮の中で【町人】の自覚を高める教えとして受け入れられ、弟子の手島堵庵らによって各地に広まった。"},
  {"id": "jhx292", "s": "jh", "lv": 3, "topic": "江戸時代の社会批判思想", "q": "安藤昌益の思想の特徴と、その歴史的意義を説明せよ。", "a": "八戸の医師【安藤昌益】は『自然真営道』を著し、すべての人が自ら耕作して生活する【万人直耕】の【自然世】を理想とした。そして武士が農民から年貢を取り立てて生活する身分制社会を【法世】として批判した。封建的な【身分制度】を根本から否定した点で、江戸時代の思想として特異な意義をもつ。"},
  {"id": "jhx293", "s": "jh", "lv": 2, "topic": "江戸時代の経世論", "q": "18世紀後半から19世紀にかけて現れた経世論には、どのような主張があったか説明せよ。", "a": "社会の変化に対応して、経世済民を論じる経世論が盛んになった。【本多利明】は開国による【貿易】振興を説き、【海保青陵】は藩の専売など商業の利益を積極的に認めた。【佐藤信淵】は産業の国営化や貿易を主張した。これらは身分制や農業中心の考えにとらわれない【富国】策を提示した。"},
  {"id": "jhx294", "s": "jh", "lv": 2, "topic": "海防論", "q": "18世紀末に林子平が唱えた海防論と、それに対する幕府の対応を説明せよ。", "a": "ロシアの南下が知られるようになると、【林子平】は『海国兵談』で、日本は四方を海に囲まれているため【海防】の強化が必要だと説いた。しかし【松平定信】の幕府は、政治を批判し人心を惑わすものとして【出版】を禁じ、子平を処罰した。その直後の1792年に【ラクスマン】が根室に来航し、海防の重要性が現実のものとなった。"},
  {"id": "jhx295", "s": "jh", "lv": 1, "topic": "浮世絵", "q": "江戸時代の浮世絵の発展について説明せよ。", "a": "浮世絵は庶民の生活や風俗を描いた絵画で、元禄期に【菱川師宣】が版画として普及させた。18世紀半ばには【鈴木春信】が多色刷りの【錦絵】を始め、美人画の喜多川歌麿や役者絵の東洲斎写楽が活躍した。19世紀には【葛飾北斎】や歌川広重の風景画が人気を集め、のちにヨーロッパの【印象派】にも影響を与えた。"},
  {"id": "jhx296", "s": "jh", "lv": 1, "topic": "歌舞伎と人形浄瑠璃", "q": "元禄期の歌舞伎と人形浄瑠璃の発展について説明せよ。", "a": "元禄期には上方を中心に町人の文化が栄えた。人形浄瑠璃では【近松門左衛門】が脚本を書き、義理と人情の葛藤を描いた【世話物】などが人気を集め、【竹本義太夫】が語った。歌舞伎では江戸の【市川団十郎】の荒事、上方の坂田藤十郎の和事が評判となり、芝居小屋は【町人】の娯楽となった。"},
  {"id": "jhx297", "s": "jh", "lv": 2, "topic": "水戸学", "q": "水戸学の思想の特徴と、幕末の政治に与えた影響を説明せよ。", "a": "水戸藩では【徳川光圀】が『大日本史』の編纂を始め、そこから【水戸学】が形成された。19世紀には【会沢安】（正志斎）や藤田東湖らが、天皇を尊ぶ【尊王論】と外国を排斥する攘夷論を結びつけた。この【尊王攘夷】の思想は、幕末の志士たちに大きな影響を与えた。"},
  {"id": "jhx298", "s": "jh", "lv": 2, "topic": "農村復興", "q": "19世紀前半、荒廃した農村を復興させるためにどのような取り組みが行われたか説明せよ。", "a": "天明のききん以後、関東などでは人口の減少や耕地の荒廃が進んだ。【二宮尊徳】（金次郎）は勤労・倹約を重んじる【報徳仕法】を説き、各地の農村の復興を指導した。また【大原幽学】は下総で【性学】を説き、農民の生活改善や協同組合的な組織づくりを進めた。こうした取り組みは村の【自力】による再建をめざすものであった。"},
  {"id": "jhx299", "s": "jh", "lv": 3, "topic": "江戸後期の朝廷", "q": "江戸時代後期に朝廷の権威が高まった背景について説明せよ。", "a": "18世紀後半以降、【国学】や水戸学の広まりとともに、天皇を尊ぶ【尊王論】が強まった。幕府も将軍の支配は天皇から【委任】されたものであるという大政委任論を唱え、朝廷の権威を支配の正統性の根拠とした。光格天皇の【尊号一件】では幕府と朝廷が対立し、幕末には朝廷が【条約勅許】問題などで政治的な発言力を強めた。"},
  {"id": "jhx300", "s": "jh", "lv": 2, "topic": "蛮社の獄", "q": "1839年の蛮社の獄はなぜ起こったか。モリソン号事件との関係にふれて説明せよ。", "a": "1837年、日本人漂流民を送り届けに来たアメリカ商船【モリソン号】が、異国船打払令に基づいて砲撃された。蘭学者の【渡辺崋山】は『慎機論』、【高野長英】は『戊戌夢物語』を著し、幕府の対外政策を批判した。幕府はこれを処罰した（【蛮社の獄】）。これは幕府の【言論統制】と洋学者への警戒を示す事件であった。"},
  {"id": "jhx301", "s": "jh", "lv": 2, "topic": "将軍継嗣問題", "q": "13代将軍徳川家定の後継をめぐる将軍継嗣問題について説明せよ。", "a": "病弱な将軍家定の後継をめぐり、越前藩主松平慶永ら有力大名は、賢明とされた一橋家の【徳川慶喜】を推した（【一橋派】）。一方、譜代大名らは血統の近い紀伊藩主【徳川慶福】を推した（南紀派）。南紀派の【井伊直弼】が大老に就任して慶福（家茂）を後継に決め、条約調印とあわせて反対派を弾圧する【安政の大獄】につながった。"},
  {"id": "jhx302", "s": "jh", "lv": 2, "topic": "文久の改革", "q": "1862年の文久の改革はどのような経緯で行われ、どのような内容であったか説明せよ。", "a": "薩摩藩の【島津久光】が勅使とともに江戸に下り、幕政改革を要求した。幕府はこれに応じ、【徳川慶喜】を将軍後見職、【松平慶永】を政事総裁職、松平容保を【京都守護職】に任じた。また【参勤交代】を緩和し、大名の妻子の帰国を認めた。これにより幕府の権威は低下した。"},
  {"id": "jhx303", "s": "jh", "lv": 2, "topic": "薩英戦争", "q": "生麦事件と薩英戦争は、薩摩藩の方針にどのような変化をもたらしたか説明せよ。", "a": "1862年、島津久光の行列を横切ったイギリス人が殺傷される【生麦事件】が起こった。翌年、報復のためイギリス艦隊が鹿児島を攻撃する【薩英戦争】となった。薩摩藩は欧米の【軍事力】の強さを実感し、攘夷が不可能であることを悟って、かえって【イギリス】に接近し、軍備の近代化を進めた。"},
  {"id": "jhx304", "s": "jh", "lv": 3, "topic": "改税約書", "q": "1866年の改税約書は、日本の経済にどのような影響を与えたか説明せよ。", "a": "四国艦隊下関砲撃事件の後、列強は兵庫開港の延期などと引き換えに、幕府に【改税約書】を結ばせた。これにより輸入関税は従価約20%から一律に【従量税】で約5%に引き下げられた。その結果、安価な外国製品の輸入が急増して【貿易収支】は輸入超過となり、国内産業は打撃を受けた。この不利な【関税】は条約改正まで日本を苦しめた。"},
  {"id": "jhx305", "s": "jh", "lv": 3, "topic": "幕府の軍制改革", "q": "幕末に幕府はどのような軍制改革を行ったか。その背景とあわせて説明せよ。", "a": "長州征討の失敗などを受け、幕府は【フランス】の援助のもとで軍制改革を進めた。徳川慶喜は公使【ロッシュ】の助言を受けて、フランス式の陸軍の訓練を行い、【横須賀製鉄所】を建設した。一方、薩長は【イギリス】と結びついており、英仏の対立が幕府と雄藩の対立に重なった。"},
  {"id": "jhx306", "s": "jh", "lv": 1, "topic": "戊辰戦争", "q": "戊辰戦争の経過と、その結果について説明せよ。", "a": "1868年の鳥羽・伏見の戦いで旧幕府軍が敗れ、【戊辰戦争】が始まった。新政府軍は江戸に進み、【勝海舟】と西郷隆盛の会談で江戸城は無血開城した。東北諸藩は【奥羽越列藩同盟】を結んで抵抗したが敗れ、1869年に【五稜郭】の戦いで旧幕府勢力が降伏し、新政府による国内統一が完成した。"},
  {"id": "jhx307", "s": "jh", "lv": 2, "topic": "五榜の掲示", "q": "五箇条の誓文と五榜の掲示の内容を比較し、新政府の姿勢について説明せよ。", "a": "1868年、新政府は【五箇条の誓文】で公議世論の尊重や開国和親などの基本方針を示した。一方、翌日に民衆向けに掲げた【五榜の掲示】では、儒教道徳の遵守や【徒党】・強訴の禁止、【キリスト教】の禁止など、江戸幕府の政策をほぼ受け継いだ。新政府は開明的な方針を示しつつ、民衆に対しては【統制】的な姿勢をとった。"},
  {"id": "jhx308", "s": "jh", "lv": 2, "topic": "政体書", "q": "1868年の政体書で定められた政治の仕組みについて説明せよ。", "a": "【政体書】は、新政府の政治組織を定めたもので、【アメリカ】の制度などを参考にした。国家権力を【太政官】に集め、その中で立法・行政・司法の【三権分立】の形をとった。また官吏の【互選】による交代制も定めた。ただし実際には、新政府の要職は薩長土肥などの出身者が占めた。"},
  {"id": "jhx309", "s": "jh", "lv": 1, "topic": "四民平等", "q": "明治政府が進めた四民平等とはどのような政策か。その限界とあわせて説明せよ。", "a": "明治政府は封建的身分制度を廃止し、公家・大名を【華族】、武士を【士族】、農工商を【平民】とした。平民にも苗字を名乗ることや【職業選択】・移住の自由を認め、1871年にはえた・ひにんの呼称を廃止した（いわゆる【解放令】）。しかし、職業・結婚・居住などでの【差別】は根強く残った。"},
  {"id": "jhx310", "s": "jh", "lv": 2, "topic": "壬申戸籍", "q": "1872年に作成された壬申戸籍は、どのような意味をもったか説明せよ。", "a": "1871年の戸籍法に基づき、翌1872年に全国統一の【壬申戸籍】が作成された。これは【華族・士族・平民】の新しい族籍にもとづいて国民を把握するもので、【徴兵令】や学制、地租改正などの【近代的】な諸政策を実施する基礎となった。一方で旧身分の記載が残り、差別の原因ともなった。"},
  {"id": "jhx311", "s": "jh", "lv": 2, "topic": "国立銀行条例", "q": "1872年の国立銀行条例の目的と、その後の改正の意味について説明せよ。", "a": "明治政府は【渋沢栄一】が中心となり、アメリカの制度にならった【国立銀行条例】を定めた。民間の銀行に【兌換】銀行券を発行させ、不換紙幣の整理を図ったが、正貨兌換の義務のため設立は進まなかった。1876年の改正で兌換義務を廃止すると設立が進み、【秩禄処分】で交付された【金禄公債】を資本とする銀行も多く生まれた。"},
  {"id": "jhx312", "s": "jh", "lv": 2, "topic": "日清修好条規", "q": "1871年の日清修好条規はどのような特徴をもつ条約か説明せよ。", "a": "【日清修好条規】は、日本が清と結んだ最初の条約である。互いに【領事裁判権】を認め合い、関税率も協定するなど、両国が対等な立場で結んだ【対等条約】であった。欧米と結んだ不平等条約とは異なる点に特徴がある。しかしその後、【琉球】の帰属や【朝鮮】をめぐって両国は対立していった。"},
  {"id": "jhx313", "s": "jh", "lv": 2, "topic": "台湾出兵", "q": "1874年の台湾出兵が行われた経緯と、その結果について説明せよ。", "a": "1871年に【琉球】の漂流民が台湾で殺害された事件を理由に、1874年、日本は台湾に出兵した。清は当初、台湾の住民を「化外の民」としたが、イギリスの調停により清は日本の出兵を【義挙】と認め、事実上の【賠償金】を支払った。これにより、琉球の人々が【日本国民】であることを清に認めさせたと日本は主張した。"},
  {"id": "jhx314", "s": "jh", "lv": 1, "topic": "日朝修好条規", "q": "1876年の日朝修好条規の内容と、その特徴について説明せよ。", "a": "1875年の【江華島事件】をきっかけに、日本は朝鮮に開国を迫り、翌年【日朝修好条規】を結んだ。条約は朝鮮を【自主の国】と規定して清の宗主権を否定し、釜山など3港の開港と、日本の【領事裁判権】を認めさせた。これは日本が欧米から押しつけられたのと同様の【不平等条約】であった。"},
  {"id": "jhx315", "s": "jh", "lv": 2, "topic": "琉球処分", "q": "明治政府が琉球を日本の領土に組み入れた過程について説明せよ。", "a": "1872年、政府は琉球王国を【琉球藩】とし、国王尚泰を藩王とした。清との冊封関係を断つよう求めたが琉球側は応じなかった。1879年、政府は軍隊と警察を派遣して琉球藩を廃止し、【沖縄県】を設置した（【琉球処分】）。清はこれに抗議し、帰属問題は【日清戦争】まで未解決のまま残った。"},
  {"id": "jhx316", "s": "jh", "lv": 2, "topic": "大阪会議", "q": "1875年の大阪会議と、その後に出された漸次立憲政体樹立の詔について説明せよ。", "a": "征韓論争や台湾出兵で政府が分裂すると、【大久保利通】は政府を強化するため、大阪で板垣退助・木戸孝允と会談した（【大阪会議】）。その結果、漸次立憲政体樹立の詔が出され、立法機関の【元老院】、司法機関の【大審院】、府県知事を集める地方官会議が設置された。一方で政府は讒謗律などで言論を取り締まった。"},
  {"id": "jhx317", "s": "jh", "lv": 2, "topic": "讒謗律と新聞紙条例", "q": "1875年に政府が讒謗律と新聞紙条例を定めた目的について説明せよ。", "a": "【民撰議院設立建白書】の提出以降、新聞や雑誌を通じて政府への批判が強まった。政府は【讒謗律】で官吏などを批判する言論を罰し、【新聞紙条例】で新聞・雑誌の言論を取り締まった。これらは高まりつつある【自由民権運動】を抑えるための【言論統制】であった。"},
  {"id": "jhx318", "s": "jh", "lv": 2, "topic": "私擬憲法", "q": "自由民権運動の中で作成された私擬憲法には、どのような特徴があったか説明せよ。", "a": "国会開設の勅諭の前後から、民権派は国民の立場に立った憲法草案である【私擬憲法】を多く作成した。立志社の『日本憲法見込案』や植木枝盛の【東洋大日本国国憲按】は、人民の【抵抗権】や革命権まで認めるなど急進的な内容を含んだ。また東京近郊の農村の人々がつくった【五日市憲法】のように、民衆の【政治参加】の意識の高まりを示すものもあった。"},
  {"id": "jhx319", "s": "jh", "lv": 2, "topic": "秩父事件", "q": "1884年の秩父事件が起こった背景について、松方財政との関連から説明せよ。", "a": "【松方財政】によるデフレ政策で米や【生糸】の価格が暴落し、養蚕地帯である秩父の農民は困窮して借金に苦しんだ。農民は【困民党】を組織し、自由党員の一部とともに負債の減免などを求めて蜂起したが、軍隊によって鎮圧された。この【秩父事件】などの激化事件は、自由党の【解党】の一因となった。"},
  {"id": "jhx320", "s": "jh", "lv": 3, "topic": "三大事件建白運動", "q": "1887年の三大事件建白運動の内容と、政府の対応を説明せよ。", "a": "国会開設を前に、民権派は【大同団結】を唱えて再結集を図った。井上馨の条約改正交渉の失敗をきっかけに、【言論・集会の自由】、【地租軽減】、外交失策の挽回（対等条約の締結）を求める三大事件建白運動が起こった。政府は【保安条例】を出し、民権派を東京から追放して運動を抑えた。"},
  {"id": "jhx321", "s": "jh", "lv": 2, "topic": "華族令", "q": "1884年の華族令は、どのような目的で制定されたか説明せよ。", "a": "【伊藤博文】は憲法制定・国会開設に備え、【華族令】を定めた。これにより従来の公家・大名に加え、国家に功績のあった【維新の功臣】も華族とし、公・侯・伯・子・男の五爵を設けた。これは将来設置される【貴族院】の基盤をつくり、【皇室】を守る勢力を形成するためであった。"},
  {"id": "jhx322", "s": "jh", "lv": 1, "topic": "内閣制度の創設", "q": "1885年の内閣制度の創設は、それまでの太政官制と比べてどのような点に特徴があったか説明せよ。", "a": "1885年、【太政官制】を廃止して【内閣制度】が創設され、【伊藤博文】が初代内閣総理大臣となった。各省の長官である国務大臣が内閣を構成し、行政の責任を負うようになった。家柄にとらわれず【能力】のある人物を登用できるようになり、宮中と【府中】（政府）の区別も明確化された。"},
  {"id": "jhx323", "s": "jh", "lv": 3, "topic": "地方制度の整備", "q": "明治政府が1880年代末から1890年にかけて整えた地方制度の特徴を説明せよ。", "a": "ドイツ人顧問【モッセ】の助言を受け、【山県有朋】が中心となって1888年に市制・町村制、1890年に【府県制・郡制】が公布された。地方自治の形をとったが、選挙権は一定以上の税を納める者に限られ、町村長は地元の【名望家】が中心となった。また知事は政府が任命し、地方は【中央集権】的な統制の下に置かれた。"},
  {"id": "jhx324", "s": "jh", "lv": 2, "topic": "超然主義", "q": "大日本帝国憲法発布直後に政府が表明した超然主義とはどのような考え方か。初期議会との関係とあわせて説明せよ。", "a": "憲法発布の直後、黒田清隆首相は、政府は政党の意向に左右されず、【超然】として公正な政治を行うと表明した（【超然主義】）。しかし初期議会では【民党】が衆議院の多数を占め、【政費節減・民力休養】を掲げて予算案を削減しようとしたため、政府は民党の協力なしに政治を進めることが困難になった。"},
  {"id": "jhx325", "s": "jh", "lv": 2, "topic": "大津事件", "q": "1891年の大津事件は、日本の司法にとってどのような意義をもったか説明せよ。", "a": "来日中の【ロシア皇太子】が大津で警備の巡査に切りつけられ負傷した。政府はロシアとの関係悪化を恐れ、犯人を死刑にするよう求めたが、大審院長の【児島惟謙】は、刑法に従って通常の謀殺未遂罪を適用するよう担当裁判官を説き、【無期徒刑】の判決となった。これは【司法権の独立】を守った事件とされる。"},
  {"id": "jhx326", "s": "jh", "lv": 2, "topic": "台湾統治", "q": "日清戦争後の日本による台湾統治の特徴について説明せよ。", "a": "【下関条約】で日本は台湾を獲得し、【台湾総督府】を置いた。住民の激しい抵抗を軍事力で鎮圧し、総督には軍人が任じられた。民政長官【後藤新平】のもとで土地調査や鉄道・港湾の整備が進められ、【製糖業】などの産業が育成された。台湾は日本の【植民地】として食料などの供給地となった。"},
  {"id": "jhx327", "s": "jh", "lv": 2, "topic": "隈板内閣", "q": "1898年に成立した隈板内閣の意義と、その短命に終わった理由を説明せよ。", "a": "自由党と進歩党が合同して【憲政党】が結成されると、伊藤博文は政権を譲り、大隈重信を首相、板垣退助を内相とする【隈板内閣】が成立した。これは日本初の【政党内閣】であった。しかし旧自由党系と旧進歩党系の対立が激しく、尾崎行雄の【共和演説事件】をきっかけに分裂し、約4か月で退陣した。"},
  {"id": "jhx328", "s": "jh", "lv": 3, "topic": "軍部大臣現役武官制", "q": "第2次山県有朋内閣が定めた軍部大臣現役武官制は、のちの政治にどのような影響を与えたか説明せよ。", "a": "1900年、【山県有朋】は政党の勢力が軍部に及ぶのを防ぐため、陸・海軍大臣を【現役】の大将・中将に限る制度を定めた。これにより軍部が大臣を出さなければ【内閣】は組閣・存続できなくなった。実際、1912年には陸軍が大臣を出さず【第2次西園寺内閣】が倒れ、軍部の【政治的発言力】が強まった。"},
  {"id": "jhx329", "s": "jh", "lv": 1, "topic": "立憲政友会の結成", "q": "1900年に伊藤博文が立憲政友会を結成したことは、どのような意味をもったか説明せよ。", "a": "政府と政党の対立が続く中、【伊藤博文】は、政党の力を政権に取り込む必要があると考え、【憲政党】（旧自由党系）を中心に【立憲政友会】を結成した。これは、超然主義をとってきた【藩閥】の指導者みずからが政党を組織したもので、政党が政治の担い手として重要な位置を占めるようになったことを示した。"},
  {"id": "jhx330", "s": "jh", "lv": 2, "topic": "桂園時代", "q": "日露戦争前後から大正初期にかけての桂園時代とはどのような政治状況か説明せよ。", "a": "1901年から1913年まで、長州閥で陸軍出身の【桂太郎】と、【立憲政友会】総裁の【西園寺公望】が交互に首相となった時期を【桂園時代】という。藩閥・官僚勢力と政党勢力が【妥協】・提携しながら政権を担当し、政友会は政権に協力することで勢力を拡大した。"},
  {"id": "jhx331", "s": "jh", "lv": 2, "topic": "日露戦争と国内世論", "q": "日露戦争の開戦前後の国内世論について、主戦論と非戦論の両面から説明せよ。", "a": "ロシアが満州を占領し続けると、対露同志会や東京帝大の七博士などが開戦を主張し、新聞の多くも【主戦論】に傾いた。一方、キリスト教徒の【内村鑑三】や、平民社の【幸徳秋水】・堺利彦らは【非戦論】を唱え、歌人の【与謝野晶子】も反戦的な詩を発表した。しかし世論の大勢は開戦を支持した。"},
  {"id": "jhx332", "s": "jh", "lv": 3, "topic": "日露戦争の戦費", "q": "日露戦争の戦費はどのように調達され、戦後の日本にどのような影響を残したか説明せよ。", "a": "日露戦争の戦費は約17億円にのぼり、その多くを【内外債】に頼った。特に【外債】はイギリス・アメリカで募集された。さらに【増税】も行われ、国民の負担は大きかった。しかし【ポーツマス条約】で賠償金が得られなかったため、戦後も【財政難】が続き、外債の利払いなどが経済を圧迫した。"},
  {"id": "jhx333", "s": "jh", "lv": 2, "topic": "満鉄と関東都督府", "q": "日露戦争後、日本は南満州でどのような権益を得て、どのように経営したか説明せよ。", "a": "【ポーツマス条約】で日本は旅順・大連の租借権と、長春以南の鉄道とその付属の権利を得た。1906年、旅順に【関東都督府】を置いて関東州を統治し、大連に【南満州鉄道株式会社】（満鉄）を設立して鉄道や沿線の炭鉱などを経営した。これに対し門戸開放を求める【アメリカ】は反発し、日米関係は【悪化】した。"},
  {"id": "jhx334", "s": "jh", "lv": 3, "topic": "日露協約", "q": "日露戦争後に日本とロシアが結んだ日露協約の意義を説明せよ。", "a": "日露戦争後、日本とロシアは満州への進出を図る【アメリカ】に対抗するため、1907年から4次にわたって【日露協約】を結んだ。両国は満州における【勢力範囲】を南北に分割して互いの権益を承認し、日本の【韓国】支配とロシアの【外蒙古】での利益も認め合った。かつての敵国が協調関係に転じた点が重要である。"},
  {"id": "jhx335", "s": "jh", "lv": 2, "topic": "日本人移民排斥問題", "q": "日露戦争後、アメリカで日本人移民排斥運動が起こった背景と、それが日米関係に与えた影響を説明せよ。", "a": "日露戦争後、【カリフォルニア州】などで日本人移民が増えると、低賃金で働く日本人に仕事を奪われるという反発や人種的偏見から【移民排斥】運動が起こった。1906年にはサンフランシスコで【日本人学童隔離】問題が起こった。満州問題での対立と重なって日米関係は悪化し、1924年には日本人移民を事実上禁じる【移民法】が成立した。"},
  {"id": "jhx336", "s": "jh", "lv": 2, "topic": "地方改良運動", "q": "日露戦争後に政府が進めた地方改良運動の目的と内容について説明せよ。", "a": "日露戦争後、戦争の負担で町村の財政は窮乏し、国民の間には個人主義や享楽的な風潮も広がった。第2次桂内閣は【戊申詔書】を出して勤倹節約を説き、内務省を中心に【地方改良運動】を進めた。町村財政の再建や、旧村落の神社の統合、【青年会】の組織化などを行い、国家を支える【町村】の基盤を強化しようとした。"},
  {"id": "jhx337", "s": "jh", "lv": 2, "topic": "大逆事件", "q": "1910年の大逆事件はどのような事件か。その後の社会運動への影響とあわせて説明せよ。", "a": "1910年、明治天皇の暗殺を計画したとして多数の社会主義者・無政府主義者が検挙され、翌年【幸徳秋水】ら12名が処刑された（【大逆事件】）。計画に無関係な人も多く含まれていた。事件後、警視庁に【特別高等課】が置かれて取り締まりが強化され、社会主義運動はしばらく【冬の時代】を迎えた。"},
  {"id": "jhx338", "s": "jh", "lv": 2, "topic": "工場法", "q": "1911年に制定された工場法の内容と、その限界について説明せよ。", "a": "産業革命の進展にともない、劣悪な労働環境が社会問題となった。政府は1911年に日本初の労働者保護法である【工場法】を制定し、【少年・女性】の就業時間の制限や深夜業の禁止などを定めた。しかし、適用は【15人以上】の工場に限られ、製糸業などでは例外も認められた。資本家の反対で施行は【1916年】まで遅れた。"},
  {"id": "jhx339", "s": "jh", "lv": 2, "topic": "シーメンス事件", "q": "1914年のシーメンス事件とはどのような事件で、どのような政治的結果をもたらしたか説明せよ。", "a": "1914年、ドイツのシーメンス社などからの軍艦・兵器購入をめぐる海軍高官の【汚職】が発覚した（【シーメンス事件】）。海軍出身の首相【山本権兵衛】の内閣は世論の批判を受けて総辞職した。後継には国民に人気のあった【大隈重信】が選ばれ、立憲同志会を与党とする内閣が成立した。"},
  {"id": "jhx340", "s": "jh", "lv": 1, "topic": "二十一カ条の要求", "q": "1915年に日本が中国に出した二十一カ条の要求の内容と、その影響を説明せよ。", "a": "第一次世界大戦中、大隈内閣は中国の【袁世凱】政府に対して二十一カ条の要求を突きつけた。その内容は、ドイツが持っていた【山東省】の権益の継承や、旅順・大連の租借期限の延長などであった。日本は最後通牒を発してその大部分を認めさせたが、中国では受諾した5月9日を【国恥記念日】とし、【反日】感情が高まった。"},
  {"id": "jhx341", "s": "jh", "lv": 2, "topic": "シベリア出兵", "q": "シベリア出兵の目的と経過、その結果について説明せよ。", "a": "ロシア革命が起こると、1918年に連合国は【チェコスロヴァキア軍】の救出を名目に【シベリア出兵】を行い、日本も大軍を派遣した。日本は他国の撤兵後も駐留を続けて内外の批判を受け、1922年に撤兵した。多くの戦費と犠牲を払いながら成果はなく、出兵を見こした米の買い占めは【米騒動】の一因ともなった。"},
  {"id": "jhx342", "s": "jh", "lv": 3, "topic": "石井・ランシング協定", "q": "1917年の石井・ランシング協定の内容と、その後の経過を説明せよ。", "a": "第一次世界大戦中、日本とアメリカは中国問題について【石井・ランシング協定】を結んだ。アメリカは中国における日本の【特殊権益】を認め、日本は中国の【門戸開放】・機会均等を認め合った。しかし両国の解釈には違いがあり、【ワシントン会議】で九カ国条約が結ばれたことにより、1923年に協定は【廃棄】された。"},
  {"id": "jhx343", "s": "jh", "lv": 2, "topic": "パリ講和会議と日本", "q": "パリ講和会議で日本はどのような主張をし、どのような結果を得たか説明せよ。", "a": "日本は五大国の一員としてパリ講和会議に参加し、ドイツが持っていた【山東省】の権益の継承と、赤道以北のドイツ領【南洋諸島】の委任統治権を認められた。一方、日本が提案した【人種差別撤廃】条項は否決された。山東問題に反発した中国では【五・四運動】が起こった。"},
  {"id": "jhx344", "s": "jh", "lv": 2, "topic": "三・一独立運動", "q": "1919年の三・一独立運動の背景と、その後の日本の朝鮮統治の変化を説明せよ。", "a": "第一次世界大戦後の【民族自決】の思想の広まりを背景に、1919年3月1日、ソウルで独立宣言が発表され、【独立運動】が朝鮮全土に広がった。日本はこれを軍隊・警察で鎮圧した。その後、【原敬】内閣は朝鮮総督を文官からも任用できるようにし、【憲兵警察】を廃止するなど、【文化政治】と呼ばれる統治に転換した。"},
  {"id": "jhx345", "s": "jh", "lv": 3, "topic": "戦後恐慌", "q": "第一次世界大戦後の1920年代の日本経済が「慢性的な不況」と言われた理由を説明せよ。", "a": "大戦が終わってヨーロッパの生産が回復すると、日本の輸出は減少し、1920年に株価が暴落して【戦後恐慌】が起こった。さらに1923年の【関東大震災】で大きな打撃を受け、政府は日銀の特別融資で救済したが、【震災手形】の処理が遅れた。不良債権を抱えた企業や銀行の【整理】が進まず、輸入超過も続いて、【慢性的】な不況となった。"},
  {"id": "jhx346", "s": "jh", "lv": 1, "topic": "関東大震災", "q": "1923年の関東大震災が社会に与えた影響について説明せよ。", "a": "1923年9月1日の【関東大震災】では、東京・横浜が大火災に見舞われ、多くの死者を出した。混乱の中で「朝鮮人が暴動を起こす」などの流言が広まり、自警団などにより多くの【朝鮮人】や中国人が殺害された。また社会主義者の大杉栄らが憲兵に殺された。経済的には【震災手形】の処理が後の【金融恐慌】の原因となった。"},
  {"id": "jhx347", "s": "jh", "lv": 2, "topic": "大正期の軍縮", "q": "1920年代に日本で行われた陸海軍の軍縮について説明せよ。", "a": "第一次世界大戦後の国際協調と財政難を背景に、海軍では【ワシントン海軍軍縮条約】で主力艦の保有比率が定められ、建造が中止された。陸軍では加藤友三郎内閣以降の軍縮に続き、1925年に陸相【宇垣一成】が4個師団を削減した（宇垣軍縮）。ただし浮いた予算は戦車などの【装備】の近代化に回され、また学校に【配属将校】を置いて軍事教練を始めた。"},
  {"id": "jhx348", "s": "jh", "lv": 2, "topic": "全国水平社", "q": "1922年に結成された全国水平社の目的と意義について説明せよ。", "a": "1871年の解放令後も、被差別部落の人々に対する【差別】は根強く残っていた。政府の融和政策に頼らず、自らの力で差別からの解放をめざして、1922年に【全国水平社】が結成された。【西光万吉】らが起草した宣言（【水平社宣言】）は「人の世に熱あれ、人間に光あれ」と結ばれ、日本初の人権宣言ともいわれる。"},
  {"id": "jhx349", "s": "jh", "lv": 2, "topic": "大正期の女性運動", "q": "明治末から大正期にかけて、女性の地位向上をめざしてどのような運動が行われたか説明せよ。", "a": "1911年、【平塚らいてう】らは【青鞜社】を結成し、女性の自我の解放を訴えた。1920年には平塚らいてうや【市川房枝】らが【新婦人協会】を設立し、女性の政治活動を禁じた治安警察法第5条の改正を求めた。その結果、1922年に女性の政治集会への参加が認められた。その後も【婦人参政権】獲得の運動が続けられた。"},
  {"id": "jhx350", "s": "jh", "lv": 2, "topic": "治安維持法", "q": "1925年に制定された治安維持法の目的と、その後の改正による変化について説明せよ。", "a": "1925年、【加藤高明】内閣は普通選挙法と同時に【治安維持法】を制定した。【日ソ基本条約】で国交が成立したことや、普選による労働者の政治進出を背景に、【国体】の変革や私有財産制度の否認をめざす結社を取り締まった。1928年の改正で最高刑が【死刑】に引き上げられ、対象も広がり、自由主義者なども弾圧された。"},
  {"id": "jhx351", "s": "jh", "lv": 2, "topic": "憲政の常道", "q": "1924年から1932年までの「憲政の常道」とは、どのような政治慣行か説明せよ。", "a": "1924年の【護憲三派】内閣の成立から、1932年の【五・一五事件】で犬養毅首相が殺害されるまで、衆議院で多数を占める【政党】の総裁が内閣を組織する【政党内閣】が続いた。内閣が失政で倒れると野党第一党に政権が移るこの慣行は「【憲政の常道】」と呼ばれ、元老の西園寺公望がこれを支えた。"},
  {"id": "jhx352", "s": "jh", "lv": 2, "topic": "山東出兵", "q": "田中義一内閣が行った山東出兵の目的と、その後の展開について説明せよ。", "a": "中国で【蔣介石】の国民革命軍が【北伐】を進めると、田中義一内閣は日本人居留民の保護を名目に3次にわたり【山東出兵】を行い、1928年には済南で国民革命軍と衝突した（済南事件）。これは対中【強硬外交】の現れであり、中国の反日感情を高めた。"},
  {"id": "jhx353", "s": "jh", "lv": 3, "topic": "張作霖爆殺事件", "q": "1928年の張作霖爆殺事件は、日本の政治にどのような影響を与えたか説明せよ。", "a": "北伐軍に敗れて奉天に引き上げる途中の【張作霖】を、満州の直接支配をねらう【関東軍】の一部が列車ごと爆殺した。しかし子の張学良は国民政府に合流し、満州支配のねらいは失敗した。田中義一首相は首謀者を厳しく処分できず、【昭和天皇】の不興を買って内閣は総辞職した。事件は軍の【独走】の始まりを示している。"},
  {"id": "jhx354", "s": "jh", "lv": 3, "topic": "統帥権干犯問題", "q": "1930年のロンドン海軍軍縮条約の調印をめぐって起こった統帥権干犯問題について説明せよ。", "a": "【浜口雄幸】内閣は、【ロンドン海軍軍縮条約】に調印し、補助艦の保有量を制限した。これに対し海軍軍令部や野党の【立憲政友会】、右翼などは、兵力量の決定は天皇の統帥権に属し、軍令部の同意なく調印したのは【統帥権の干犯】であると攻撃した。浜口首相は右翼青年に狙撃されて重傷を負い、のちに退陣した。"},
  {"id": "jhx355", "s": "jh", "lv": 3, "topic": "農山漁村経済更生運動", "q": "昭和恐慌期に政府が農村に対して行った救済策について説明せよ。", "a": "昭和恐慌で農産物価格が暴落し、特に【東北地方】では冷害も重なって、欠食児童や娘の身売りが問題となった（【農業恐慌】）。政府は公共土木事業である【時局匡救事業】を行って農民に現金収入の機会を与え、また【農山漁村経済更生運動】を進めて、【産業組合】の拡充などによる農民の自力更生を図った。"},
  {"id": "jhx356", "s": "jh", "lv": 3, "topic": "社会主義者の転向", "q": "1930年代に社会主義者の転向が相次いだ背景について説明せよ。", "a": "1933年、獄中にあった日本共産党の最高指導者【佐野学】・鍋山貞親が、コミンテルンの方針を批判し、天皇制のもとでの社会主義を主張する【転向】声明を発表した。満州事変を機にナショナリズムが高まり、治安維持法による弾圧も強まる中、これをきっかけに多くの共産主義者が転向した。社会主義運動は大きく後退し、【国家社会主義】に傾く者も現れた。"},
  {"id": "jhx357", "s": "jh", "lv": 2, "topic": "新興財閥", "q": "1930年代に新興財閥が台頭した背景について説明せよ。", "a": "【高橋是清】の財政のもとで、【金輸出再禁止】による円安と軍事費の増大が重化学工業の発展をうながした。【日産】（鮎川義介）や【日窒】（野口遵）などの新興財閥は、【軍部】と結びついて満州や朝鮮に進出し、重化学工業部門を中心に急成長した。"},
  {"id": "jhx358", "s": "jh", "lv": 2, "topic": "天皇機関説事件", "q": "1935年の天皇機関説事件と、それに対する政府の対応を説明せよ。", "a": "憲法学者【美濃部達吉】の天皇機関説は、統治権は国家にあり、天皇は国家の最高機関として統治権を行使するという学説で、長く学界の通説だった。しかし1935年、貴族院で反国体的として攻撃され、軍部や右翼が排撃運動を起こした。【岡田啓介】内閣は【国体明徴声明】を出して天皇機関説を否定し、美濃部の著書は発禁となった。【政党政治】を支えた理論が否定された。"},
  {"id": "jhx359", "s": "jh", "lv": 2, "topic": "日独伊三国同盟", "q": "1940年に日独伊三国同盟が結ばれた背景と、その影響について説明せよ。", "a": "日本は1936年に【日独防共協定】を結び、翌年イタリアも加わった。第二次世界大戦でドイツが西ヨーロッパを席巻すると、日本は南方進出を図り、1940年に【日独伊三国同盟】を締結した。この同盟は【アメリカ】を仮想敵国とするものであったため、アメリカは【対日経済制裁】を強化し、日米関係は決定的に悪化した。"},
  {"id": "jhx360", "s": "jh", "lv": 1, "topic": "日ソ中立条約", "q": "1941年に日本が日ソ中立条約を結んだ目的と、その後の経過を説明せよ。", "a": "日本は【南進】政策を進めるにあたり、北方の安全を確保するため、1941年4月に【松岡洋右】外相のもとで【日ソ中立条約】を結んだ。しかし同年6月に独ソ戦が始まると、日本は関東軍特種演習を行った。条約の有効期間中であったが、ソ連は【ヤルタ会談】の密約に基づき、1945年8月に日本に【宣戦布告】した。"},
  {"id": "jhx361", "s": "jh", "lv": 1, "topic": "新体制運動", "q": "近衛文麿が進めた新体制運動の目的と、その結果成立した大政翼賛会について説明せよ。", "a": "1940年、【近衛文麿】は、ドイツのナチ党のような強力な一国一党の組織をつくり、国民を戦争に動員する【新体制運動】を進めた。多くの政党は自ら解散して参加し、同年【大政翼賛会】が結成された。しかし政党のような政治組織にはならず、【部落会・町内会】や【隣組】を末端組織とする、上意下達の国民統制組織となった。"},
  {"id": "jhx362", "s": "jh", "lv": 2, "topic": "皇民化政策", "q": "日中戦争期以降、朝鮮や台湾で行われた皇民化政策について説明せよ。", "a": "日中戦争が始まると、日本は植民地の人々を戦争に動員するため、【皇民化政策】を進めた。朝鮮や台湾では日本語の使用や【神社参拝】が強制され、朝鮮では日本式の氏名に改めさせる【創氏改名】が行われた。さらに戦争末期には朝鮮・台湾でも【徴兵制】が施行された。"},
  {"id": "jhx363", "s": "jh", "lv": 1, "topic": "太平洋戦争の戦局", "q": "太平洋戦争の戦局はどのように推移したか。ミッドウェー海戦を転機として説明せよ。", "a": "日本は開戦後、【真珠湾攻撃】やマレー半島上陸により、約半年で東南アジアから西太平洋の広い地域を占領した。しかし1942年6月の【ミッドウェー海戦】で主力空母4隻を失い、以後は守勢に転じた。1944年に【サイパン島】が陥落すると、日本本土への空襲が本格化した。"},
  {"id": "jhx364", "s": "jh", "lv": 2, "topic": "大東亜共栄圏", "q": "「大東亜共栄圏」の理念と、日本による占領地支配の実態について説明せよ。", "a": "日本は欧米の植民地支配からアジアを解放し、日本を盟主とする共存共栄の【大東亜共栄圏】の建設を掲げた。1943年には占領地の代表を集めて【大東亜会議】を開いた。しかし実際には、占領地で【資源】の収奪や労働力の徴発を行い、日本語教育や【神社参拝】を強制したため、各地で【抗日運動】が起こった。"},
  {"id": "jhx365", "s": "jh", "lv": 1, "topic": "沖縄戦", "q": "1945年の沖縄戦の特徴について説明せよ。", "a": "1945年4月、アメリカ軍が【沖縄本島】に上陸し、約3か月にわたって地上戦が行われた。日本軍は本土決戦までの時間をかせぐため持久戦をとり、多くの【住民】が戦闘に巻き込まれた。中学生などが動員された【鉄血勤皇隊】や女子学生の【ひめゆり学徒隊】の犠牲も出て、県民の約4分の1が死亡したとされる。"},
  {"id": "jhx366", "s": "jh", "lv": 2, "topic": "満蒙開拓団", "q": "満州への農業移民（満蒙開拓団）が送り出された背景と、その結末について説明せよ。", "a": "昭和恐慌で【農村】が困窮すると、政府は過剰な人口の解消と満州の支配強化のため、【満蒙開拓団】を送り出した。1936年には大量移民計画が国策とされ、青少年義勇軍も送られた。しかし1945年の【ソ連】の侵攻で多くの犠牲者が出て、【中国残留孤児】の問題も生じた。"},
  {"id": "jhx367", "s": "jh", "lv": 2, "topic": "近衛声明", "q": "日中戦争中に出された近衛声明の内容と、その結果について説明せよ。", "a": "1938年1月、近衛文麿首相は「【国民政府】を対手とせず」と声明し、和平の道を自ら閉ざした。同年11月には戦争の目的を日満華による【東亜新秩序】の建設であると声明した。そして国民党の【汪兆銘】を重慶から脱出させ、1940年に南京に新国民政府を樹立させたが、戦争は【長期化】した。"},
  {"id": "jhx368", "s": "jh", "lv": 2, "topic": "ノモンハン事件", "q": "1939年のノモンハン事件は、日本の対外政策にどのような影響を与えたか説明せよ。", "a": "1939年、満州国とモンゴルの国境地帯で【関東軍】とソ連・モンゴル軍が衝突し、日本軍は【ソ連】の機械化部隊に大敗した（【ノモンハン事件】）。同じ頃、ドイツがソ連と【独ソ不可侵条約】を結び、平沼騏一郎内閣は「欧州情勢は複雑怪奇」と声明して総辞職した。日本はその後北進よりも【南進】へと傾いた。"},
  {"id": "jhx369", "s": "jh", "lv": 1, "topic": "極東国際軍事裁判", "q": "極東国際軍事裁判（東京裁判）について、その内容と問題点を説明せよ。", "a": "GHQは戦争指導者を戦争犯罪人として逮捕し、1946年から【極東国際軍事裁判】で【A級戦犯】を審理した。1948年、【東条英機】ら7名が死刑となった。一方、【昭和天皇】は占領統治への影響などから訴追されなかった。戦勝国のみが裁いたことや、事後法による処罰ではないかという点が問題とされた。"},
  {"id": "jhx370", "s": "jh", "lv": 2, "topic": "公職追放", "q": "GHQによる公職追放の目的と、その後の変化について説明せよ。", "a": "1946年、GHQは戦争に協力した軍人・政治家・官僚・言論人などを公職から追放する【公職追放】を指令した。これは戦争指導者を排除し、日本の【民主化】を進めるためであった。しかし冷戦の進展による【占領政策の転換】で、1950年ごろから追放は解除され、代わって共産党員らを職場から追放する【レッド=パージ】が行われた。"},
  {"id": "jhx371", "s": "jh", "lv": 2, "topic": "戦後政党の復活", "q": "終戦直後に成立した政党と、1946年の総選挙の意義について説明せよ。", "a": "敗戦後、政党が相次いで復活・結成され、旧政友会系の【日本自由党】、旧民政党系の日本進歩党、日本社会党などが成立し、【日本共産党】も合法化された。1946年4月の総選挙は、【女性参政権】を認めた新選挙法による初の選挙で、【39名】の女性議員が誕生した。選挙後、【吉田茂】内閣が成立した。"},
  {"id": "jhx372", "s": "jh", "lv": 1, "topic": "引揚げと復員", "q": "敗戦直後の日本で、引揚げと復員はどのような社会問題をもたらしたか説明せよ。", "a": "敗戦時、海外にいた軍人や民間人は合わせて600万人以上にのぼった。軍人の【復員】や民間人の【引揚げ】によって国内の人口は急増し、【失業者】があふれた。都市は空襲で焼け野原となっており、深刻な【食料不足】や住宅不足が生じた。人々は【闇市】や農村への買い出しで食料を手に入れた。"},
  {"id": "jhx373", "s": "jh", "lv": 2, "topic": "金融緊急措置令", "q": "敗戦直後のインフレーションに対して政府はどのような政策をとったか説明せよ。", "a": "敗戦直後、物資不足と通貨の増発によって激しい【インフレーション】が起こった。1946年、幣原喜重郎内閣は【金融緊急措置令】を出し、預金を【封鎖】して旧円の流通を禁じ、【新円】への切り替えを行って通貨量を減らそうとした。しかし効果は一時的で、その後の【傾斜生産方式】による資金供給でインフレは再び進んだ。"},
  {"id": "jhx374", "s": "jh", "lv": 2, "topic": "傾斜生産方式", "q": "第1次吉田茂内閣が採用した傾斜生産方式について、その内容と影響を説明せよ。", "a": "【傾斜生産方式】は、資材や資金を【石炭】・【鉄鋼】などの基幹産業に重点的に投入し、生産を回復させる政策である。1947年に設立された【復興金融金庫】が巨額の資金を融資し、生産は回復に向かった。しかし資金の多くは日銀からの借り入れに頼ったため、【インフレーション】を加速させた（復金インフレ）。"},
  {"id": "jhx375", "s": "jh", "lv": 1, "topic": "ドッジ=ライン", "q": "1949年のドッジ=ラインはどのような政策で、日本経済にどのような影響を与えたか説明せよ。", "a": "GHQは経済安定九原則を指令し、銀行家【ドッジ】が来日して経済政策を指導した（ドッジ=ライン）。赤字を許さない【超均衡予算】を組ませ、1ドル＝【360円】の単一為替レートを設定して日本経済を国際経済に結びつけた。その結果インフレは収まったが、深刻な【不況】となり、多くの失業者が出た。"},
  {"id": "jhx376", "s": "jh", "lv": 2, "topic": "シャウプ勧告", "q": "1949年のシャウプ勧告による税制改革の特徴について説明せよ。", "a": "コロンビア大学教授【シャウプ】を団長とする税制使節団は、日本の税制について勧告を行った。【直接税】中心主義をとり、【所得税】を中心とする税制が確立した。累進所得税制や地方財政の強化が図られた。これは【ドッジ=ライン】とともに、戦後日本の財政・税制の基礎となった。"},
  {"id": "jhx377", "s": "jh", "lv": 1, "topic": "再軍備", "q": "朝鮮戦争をきっかけに、日本の再軍備はどのように進められたか説明せよ。", "a": "1950年に【朝鮮戦争】が始まると、在日アメリカ軍が朝鮮に出動したため、GHQの指令で【警察予備隊】が新設された。独立後の1952年に保安隊に改組され、1954年には【MSA協定】でアメリカから経済・軍事援助を受ける代わりに防衛力の増強を義務づけられ、陸・海・空の【自衛隊】が発足した。"},
  {"id": "jhx378", "s": "jh", "lv": 2, "topic": "原水爆禁止運動", "q": "1950年代に原水爆禁止運動が高まった背景と、その経過について説明せよ。", "a": "1954年、アメリカのビキニ環礁での【水爆実験】により、日本の漁船【第五福竜丸】が被ばくした。これをきっかけに、東京の主婦などから原水爆禁止の署名運動が全国に広がり、1955年に広島で第1回【原水爆禁止世界大会】が開かれた。しかし運動はのちに政党間の対立から【分裂】した。"},
  {"id": "jhx379", "s": "jh", "lv": 1, "topic": "所得倍増計画", "q": "池田勇人内閣の所得倍増計画とはどのような政策か説明せよ。", "a": "安保闘争ののちに成立した【池田勇人】内閣は、「寛容と忍耐」を掲げて政治的対立を避け、経済成長を重視した。1960年に【国民所得倍増計画】を発表し、10年間で国民所得を2倍にすることを目標に、公共投資や減税などを進めた。実際には目標を上回る【高度経済成長】が実現した。"},
  {"id": "jhx380", "s": "jh", "lv": 2, "topic": "開放経済体制への移行", "q": "1960年代に日本が開放経済体制に移行した過程を説明せよ。", "a": "1960年代、日本は国際的な求めに応じて貿易や資本の自由化を進めた。1963年に【GATT11条国】に移行して国際収支を理由とする輸入制限ができなくなり、1964年には【IMF8条国】に移行して為替制限を撤廃した。同年には先進国の組織である【OECD】にも加盟し、さらに【資本の自由化】も段階的に進めた。"},
  {"id": "jhx381", "s": "jh", "lv": 1, "topic": "公害問題", "q": "高度経済成長期の公害問題と、それに対する国の対応について説明せよ。", "a": "高度経済成長期には産業優先の政策のもとで公害が深刻化した。熊本県の【水俣病】、新潟水俣病、富山県の【イタイイタイ病】、三重県の【四日市ぜんそく】は、四大公害訴訟でいずれも被害者側が勝訴した。国は1967年に【公害対策基本法】を制定し、1971年に【環境庁】を設置した。"},
  {"id": "jhx382", "s": "jh", "lv": 2, "topic": "革新自治体", "q": "1960年代後半から1970年代にかけて各地で革新自治体が成立した背景について説明せよ。", "a": "高度経済成長にともなって、【公害】や都市の過密、住宅不足などの問題が深刻になった。こうした問題に対応する住民運動が高まり、【社会党】や【共産党】などが支持する首長が大都市を中心に当選した。1967年の東京都の【美濃部亮吉】知事がその代表である。革新自治体は【福祉】の充実や公害規制に取り組んだ。"},
  {"id": "jhx383", "s": "jh", "lv": 1, "topic": "ドル=ショック", "q": "1971年のドル=ショックは、日本経済にどのような影響を与えたか説明せよ。", "a": "1971年、アメリカの【ニクソン】大統領は、ドルと【金】の交換停止を発表した（ドル=ショック）。同年末の【スミソニアン協定】で1ドル＝308円に円が切り上げられたが、1973年には主要国が【変動相場制】に移行した。円高は輸出に依存する日本経済に打撃を与えた。"},
  {"id": "jhx384", "s": "jh", "lv": 2, "topic": "減量経営", "q": "石油危機後、日本企業はどのように不況を乗り切ったか説明せよ。", "a": "第1次石油危機ののち、日本企業は人員削減や【省エネルギー】、【ME（マイクロエレクトロニクス）技術】を用いた工場・事務の自動化などの【減量経営】を進めた。産業構造も鉄鋼・石油化学などの素材産業から自動車・電気機械などの【加工組立型】産業へと移り、日本は他の先進国より早く不況を脱し、【安定成長】を実現した。"},
  {"id": "jhx385", "s": "jh", "lv": 1, "topic": "プラザ合意", "q": "1985年のプラザ合意は、日本経済にどのような影響を与えたか説明せよ。", "a": "1985年、G5の蔵相・中央銀行総裁会議で、ドル高を是正するための協調介入が合意された（【プラザ合意】）。その結果、急激な【円高】が進んで輸出産業が打撃を受け、【円高不況】となった。政府・日銀は【低金利】政策をとり、あふれた資金が株式や土地に流れて【バブル経済】が発生した。"},
  {"id": "jhx386", "s": "jh", "lv": 2, "topic": "日米貿易摩擦", "q": "1970〜80年代の日米貿易摩擦の展開について説明せよ。", "a": "日本の対米輸出が急増すると、繊維・【鉄鋼】・カラーテレビ、さらに【自動車】や半導体をめぐって日米間に貿易摩擦が起こった。日本は自動車の【輸出自主規制】を行った。アメリカは日本市場の閉鎖性を批判して【牛肉・オレンジ】の輸入自由化を求め、1989年からは日米【構造協議】で日本の経済構造の改善を要求した。"},
  {"id": "jhx387", "s": "jh", "lv": 2, "topic": "中曽根内閣の行財政改革", "q": "1980年代の中曽根康弘内閣が進めた行財政改革の内容を説明せよ。", "a": "中曽根康弘内閣は、「【戦後政治の総決算】」を掲げ、財政赤字の削減のため【行財政改革】を進めた。その中で、電電公社・専売公社・国鉄の【民営化】が行われ、NTT・JT・JRが発足した。これは、政府の役割を縮小し民間の活力を重視する【新自由主義】の考え方に基づく改革であった。"},
  {"id": "jhx388", "s": "jh", "lv": 1, "topic": "平成不況", "q": "1990年代の日本経済の停滞（平成不況）が長期化した理由について説明せよ。", "a": "1990年代初め、株価と地価が暴落して【バブル経済】が崩壊した。金融機関は回収できない【不良債権】を大量に抱え、1997年には大手の金融機関も相次いで破綻した（【金融危機】）。企業は【リストラ】を進めて雇用が不安定になり、消費も低迷したため、不況は長期化し「【失われた10年】」と呼ばれた。"},
  {"id": "jhx389", "s": "jh", "lv": 2, "topic": "政治改革と選挙制度改革", "q": "1990年代の政治改革によって衆議院の選挙制度はどのように変わったか、その背景とともに説明せよ。", "a": "【リクルート事件】や佐川急便事件など、政治家と企業の癒着による汚職事件が相次ぎ、政治改革が求められた。1994年、【細川護熙】内閣のもとで、衆議院の選挙制度は中選挙区制から【小選挙区比例代表並立制】に改められた。あわせて【政党交付金】制度が導入され、政治資金規正も強化された。"},
  {"id": "jhx390", "s": "jh", "lv": 1, "topic": "六国史", "q": "古代の朝廷が編纂した六国史について、その特徴を説明せよ。", "a": "六国史は、朝廷が編纂した6つの【正史】の総称で、【日本書紀】に始まり【日本三代実録】で終わる。いずれも【漢文】の編年体で書かれ、天皇の権威と国家の歴史を示すことを目的とした。10世紀初めに編纂が途絶えたのは、【律令国家】の体制が変化したことと関係している。"},
  {"id": "jhx391", "s": "jh", "lv": 2, "topic": "律令制下の教育", "q": "律令制のもとで設けられた教育機関とその目的について説明せよ。", "a": "律令制のもとで、中央には官吏養成機関として【大学】が、地方には国ごとに【国学】が置かれた。大学では主に貴族の子弟が儒教の経典を学ぶ【明経道】などを学んだ。平安時代には漢文学や歴史を学ぶ【紀伝道】が重視され、有力貴族は一族の子弟のために【大学別曹】を設けた。"},
  {"id": "jhx392", "s": "jh", "lv": 3, "topic": "院宮王臣家", "q": "9世紀に台頭した院宮王臣家と呼ばれる勢力は、律令国家の支配にどのような影響を与えたか説明せよ。", "a": "9世紀には、天皇と結びつく少数の皇族や貴族が【院宮王臣家】と呼ばれる有力な勢力となった。彼らは地方の【富豪層】と結び、私的に土地を集積したり、富豪層を家人として保護したりした。その結果、国司の徴税は妨げられ、律令制に基づく国家の【財政】が圧迫され、【公地公民】の原則はさらに崩れた。"},
  {"id": "jhx393", "s": "jh", "lv": 3, "topic": "成功と重任", "q": "平安時代中期に広まった成功や重任とはどのようなものか。その背景と影響を説明せよ。", "a": "10世紀以降、受領の地位は大きな利益をもたらすものとなった。朝廷の儀式や寺社の造営などに私財を出して官職を得ることを【成功】、同じ官職に再任されることを【重任】という。これらは朝廷の財政難を補うものであったが、官職が【利権】化し、受領が任国に赴かずに【目代】を派遣する【遙任】も広まって、地方政治はいっそう乱れた。"},
  {"id": "jhx394", "s": "jh", "lv": 3, "topic": "不輸・不入の権", "q": "荘園が不輸の権・不入の権を獲得していった過程と、その意味を説明せよ。", "a": "荘園は本来課税の対象であったが、貴族や寺社は政府に申請し、太政官符や民部省符によって租税の免除を認めさせた（【官省符荘】）。また国司の認めた【国免荘】もあった。のちに荘園に国司の使者である【検田使】の立ち入りを拒否する【不入の権】も得るようになり、荘園は【国家】の支配から独立性を強めた。"},
  {"id": "jhx395", "s": "jh", "lv": 1, "topic": "絵巻物", "q": "院政期から鎌倉時代にかけて盛んになった絵巻物にはどのようなものがあるか、特徴とともに説明せよ。", "a": "絵巻物は、詞書と絵を交互に描いて物語を表現した作品である。院政期には貴族社会を描いた【源氏物語絵巻】、庶民の姿もいきいきと描いた【信貴山縁起絵巻】や伴大納言絵巻、動物を擬人化した【鳥獣戯画】がつくられた。鎌倉時代には合戦や寺社の縁起、高僧の伝記などを描いた作品が多く生まれ、蒙古襲来絵詞はその代表例である。"},
  {"id": "jhx396", "s": "jh", "lv": 1, "topic": "鎌倉幕府の成立", "q": "源頼朝が鎌倉幕府を築いていった過程を説明せよ。", "a": "1180年に挙兵した源頼朝は、【鎌倉】を拠点とし、御家人を統率する【侍所】を設けて東国の武士を組織した。1183年には東国の支配権を朝廷に認められ、1185年には平氏を滅ぼした後、【守護・地頭】の設置を認められた。1192年に【征夷大将軍】に任じられ、武家政権としての体制が整った。"},
  {"id": "jhx397", "s": "jh", "lv": 2, "topic": "旧仏教の革新", "q": "鎌倉時代に新仏教が広がる中で、旧仏教の側にはどのような動きがみられたか説明せよ。", "a": "新仏教の台頭に刺激されて、旧仏教の側でも【戒律】を重んじる改革の動きが起こった。法相宗の【貞慶】や華厳宗の【明恵】（高弁）は法然の専修念仏を批判した。また律宗の【叡尊】や【忍性】は戒律を広めるとともに、貧しい人や病人の救済など【社会事業】にも力を尽くした。"},
  {"id": "jhx398", "s": "jh", "lv": 3, "topic": "守護在京制", "q": "室町幕府のもとで多くの守護が京都に住んだこと（守護在京制）は、地方の支配にどのような影響を与えたか説明せよ。", "a": "室町幕府は、遠国を除く守護に【在京】を原則とさせ、幕政に参加させるとともに統制した。守護は領国の支配を【守護代】に任せたため、守護代や現地の【国人】が力を強めた。応仁の乱後に守護が領国に下っても、すでに実権を守護代らに奪われている例が多く、【下剋上】の一因となった。"},
  {"id": "jhx399", "s": "jh", "lv": 3, "topic": "明応の政変", "q": "1493年の明応の政変は、室町幕府の権力にどのような変化をもたらしたか説明せよ。", "a": "1493年、管領【細川政元】は将軍【足利義材】（義稙）を廃し、足利義澄を将軍に立てた（【明応の政変】）。これにより将軍は管領家の意向で擁立・廃位される存在となり、幕府の実権は細川氏が握った。将軍権力の【形骸化】が決定的となったことから、この政変を【戦国時代】の始まりとみる考え方もある。"},
  {"id": "jhx400", "s": "jh", "lv": 3, "topic": "国人一揆", "q": "室町時代の国人一揆とはどのようなものか。その目的とあわせて説明せよ。", "a": "【国人】は地方に根を張った在地の武士である。彼らは守護の支配に対抗し、また農民の抵抗を抑えて自らの所領支配を安定させるため、互いに【契約】を結んで【一揆】を形成した。紛争を一揆内部の話し合いで解決するなど、地域的な秩序を自ら維持した。山城の国一揆は、国人と農民が結んで【守護】の軍勢を退けた例である。"},
  {"id": "jhx401", "s": "jh", "lv": 1, "topic": "城下町の形成", "q": "近世の城下町はどのような構造をもっていたか説明せよ。", "a": "兵農分離によって武士は【城下町】に集住させられた。城下町は大名の居城を中心に、【武家地】・【寺社地】・【町人地】などに身分ごとに区分された。町人地には商人や職人が住み、領国の【政治・経済】の中心となった。"},
  {"id": "jhx402", "s": "jh", "lv": 1, "topic": "南蛮文化", "q": "16世紀後半に伝わった南蛮文化にはどのようなものがあったか説明せよ。", "a": "ポルトガル人などとの交流により、【南蛮文化】が生まれた。宣教師は学校の【コレジオ】や神学校のセミナリオを設け、【ヴァリニャーニ】が伝えた【活字印刷術】で、キリスト教の書物や日本の古典などを出版した（キリシタン版）。天文学・医学・地理学などの知識や、日本人を描いた【南蛮屛風】もつくられた。"},
  {"id": "jhx403", "s": "jh", "lv": 1, "topic": "茶の湯", "q": "茶の湯が室町時代から桃山時代にかけてどのように発展したか説明せよ。", "a": "室町時代には茶の味を飲み分けて賭けをする【闘茶】が流行したが、15世紀後半に【村田珠光】が簡素さと精神性を重んじる侘茶を始めた。これを堺の武野紹鷗が受け継ぎ、【千利休】が大成した。茶の湯は【織田信長】や豊臣秀吉にも保護され、大名や豪商の間に広まった。"},
  {"id": "jhx404", "s": "jh", "lv": 2, "topic": "寛永文化", "q": "17世紀前半の寛永期の文化にはどのような特徴があったか説明せよ。", "a": "寛永期の文化は桃山文化を受け継ぎつつ、新しい傾向がみられた。建築では、家康をまつる【日光東照宮】に豪華な権現造が用いられた一方、【桂離宮】には書院造に茶室風を取り入れた【数寄屋造】が用いられた。絵画では【俵屋宗達】が『風神雷神図屛風』を描き、陶芸でも朝鮮の技術による有田焼などが生まれた。"},
  {"id": "jhx405", "s": "jh", "lv": 1, "topic": "江戸時代の実学", "q": "元禄期を中心とする江戸時代の実用的な学問の発達について説明せよ。", "a": "儒学の合理的な考え方の影響もあって、実用的な学問が発達した。【貝原益軒】は本草学で『大和本草』を著し、農学では【宮崎安貞】が『農業全書』を著した。数学では【関孝和】が独自の【和算】を発展させ、天文学では渋川春海が【貞享暦】をつくった。"},
  {"id": "jhx406", "s": "jh", "lv": 3, "topic": "近世の家制度", "q": "近世の武士や百姓の「家」にはどのような特徴があったか説明せよ。", "a": "近世には、家名・家業・家産を【世襲】によって代々受け継ぐ「家」が、社会の基本単位として広く成立した。武士の家では主君から与えられる【家禄】を家として継承し、相続は原則として【長子】の単独相続であった。家長である戸主の権限は強く、女性は家督を継げないなど、【男性優位】のしくみであった。"},
  {"id": "jhx407", "s": "jh", "lv": 1, "topic": "世直し一揆とええじゃないか", "q": "幕末の社会不安の中で民衆が起こした世直し一揆とええじゃないかについて説明せよ。", "a": "開港による物価の高騰や政治の混乱で民衆の生活は苦しくなり、1866年には全国で【百姓一揆】や打ちこわしが多発した。社会の根本的な変革を求める【世直し一揆】も起こった。1867年には東海・近畿地方を中心に、伊勢神宮のお札が降ったとして民衆が「【ええじゃないか】」と熱狂的に踊り歩く騒ぎが広がり、幕府の【権威】の失墜を示した。"},
  {"id": "jhx408", "s": "jh", "lv": 3, "topic": "大久保政権", "q": "明治六年の政変後に成立した大久保政権の特徴について説明せよ。", "a": "明治六年の政変で西郷隆盛らが下野すると、【大久保利通】が政府の実権を握った。大久保は1873年に新設された【内務省】の長官（内務卿）となり、地方行政や警察、【殖産興業】を管轄して強力に近代化を推し進めた。一方で【有司専制】との批判を受け、自由民権運動や【士族反乱】と対立した。"},
  {"id": "jhx409", "s": "jh", "lv": 1, "topic": "お雇い外国人", "q": "明治政府がお雇い外国人を招いた目的と、彼らが果たした役割について説明せよ。", "a": "明治政府は欧米の進んだ【技術】や制度を取り入れるため、多くの外国人を高い給料で雇った（お雇い外国人）。医学の【ベルツ】、札幌農学校の【クラーク】、憲法制定に助言した【ロエスレル】、美術のフェノロサなどが知られる。彼らは日本の【近代化】に大きく貢献した。"},
  {"id": "jhx410", "s": "jh", "lv": 2, "topic": "明六社", "q": "明六社の設立とその活動が、明治初期の社会に与えた影響を説明せよ。", "a": "1873年、【森有礼】の発議で、福沢諭吉・中村正直・西周らの洋学者が【明六社】を設立した。翌年から機関誌『【明六雑誌】』を発行し、【功利主義】や天賦人権の思想などを紹介して、国民の【啓蒙】に努めた。しかし政府の讒謗律・新聞紙条例による言論統制を受けて、1875年に雑誌は廃刊となった。"},
  {"id": "jhx411", "s": "jh", "lv": 1, "topic": "軍人勅諭", "q": "1882年に出された軍人勅諭の内容と、その目的について説明せよ。", "a": "1882年に出された【軍人勅諭】は、軍人に【天皇】への忠節や礼儀・武勇などの徳目を説いた。また、軍人が【政治】に関与することを禁じた。自由民権運動の影響が軍隊に及ぶことを防ぎ、【天皇の軍隊】としての精神を確立することが目的であった。"},
  {"id": "jhx412", "s": "jh", "lv": 3, "topic": "統帥権の独立", "q": "明治期に確立した統帥権の独立とはどのようなものか。その制度的な背景とともに説明せよ。", "a": "1878年、陸軍の作戦・用兵を担当する【参謀本部】が設置され、天皇に直属した。大日本帝国憲法では、軍隊の指揮命令権である【統帥権】は天皇の大権とされ、内閣や議会の関与が及ばないとされた（【統帥権の独立】）。のちに海軍にも軍令部が置かれた。これにより軍部は政府から独立した地位を持ち、昭和期の軍の【独走】の制度的な背景となった。"},
  {"id": "jhx413", "s": "jh", "lv": 1, "topic": "金本位制の確立", "q": "日本が金本位制を確立した経緯について説明せよ。", "a": "松方財政のもとで1882年に【日本銀行】が設立され、銀兌換の銀行券が発行されて【銀本位制】が確立した。その後、【日清戦争】の賠償金を準備金として、1897年に【貨幣法】が制定され、【金本位制】が確立した。これにより欧米の金本位制諸国との貿易や資本の取引が安定した。"},
  {"id": "jhx414", "s": "jh", "lv": 2, "topic": "鉄道の発達", "q": "明治期の鉄道網の発達について、官営と民営の動きにふれて説明せよ。", "a": "1872年に【新橋・横浜】間に官営鉄道が開通した。1880年代には華族を中心に設立された【日本鉄道会社】が成功したことをきっかけに民営鉄道の設立ブームが起こり、民営鉄道の営業距離が官営を上回った。1906年には軍事・経済上の理由から【鉄道国有法】が公布され、主要な【民営鉄道】が国有化された。"},
  {"id": "jhx415", "s": "jh", "lv": 1, "topic": "財閥の形成", "q": "明治期に財閥がどのように形成されたか説明せよ。", "a": "三井・三菱などの政商は、政府と結んで特権的な利益を得た。1880年代には官営事業の【払下げ】を受けて鉱山などの経営を拡大し、銀行・貿易・鉱業など多角的な事業を展開した。【持株会社】を中心に多くの企業を傘下におさめる【コンツェルン】の形態をとり、日本経済に大きな力をもった。"},
  {"id": "jhx416", "s": "jh", "lv": 2, "topic": "寄生地主制", "q": "明治期に寄生地主制が発展した理由について説明せよ。", "a": "地租改正で地租は【定額金納】となったが、小作料は【現物】で納められた。【松方デフレ】で自作農が困窮して土地を手放すと、土地は地主に集中した。地主は自ら耕作せず高額な小作料を得て、その資金を株式などに【投資】した。こうして地主が小作料に依存する【寄生地主制】が発展した。"},
  {"id": "jhx417", "s": "jh", "lv": 1, "topic": "明治の美術", "q": "明治期の美術はどのように展開したか説明せよ。", "a": "明治初期には工部美術学校で【西洋画】が教えられたが、のちに伝統美術を見直す動きが起こった。アメリカ人【フェノロサ】と【岡倉天心】は日本美術の復興に努め、1887年に【東京美術学校】が設立された。その後、黒田清輝らが外光派の西洋画を伝え、1907年に文部省美術展覧会（文展）が開かれた。"},
  {"id": "jhx418", "s": "jh", "lv": 1, "topic": "明治の文学", "q": "明治期の文学の展開について、言文一致体の確立を中心に説明せよ。", "a": "坪内逍遙は『小説神髄』で、人間の心理をありのままに描く【写実主義】を主張した。【二葉亭四迷】は『浮雲』で話し言葉と書き言葉を一致させる【言文一致体】で書いた。日清・日露戦争のころには、感情や個性を重んじる【ロマン主義】や、社会の現実を描く自然主義が展開した。"},
  {"id": "jhx419", "s": "jh", "lv": 1, "topic": "戦後の文化", "q": "戦後の日本の文化の特徴について、具体例を挙げて説明せよ。", "a": "戦後、思想や言論の自由が回復し、新しい文化が生まれた。1949年に【湯川秀樹】が日本人初の【ノーベル賞】を受賞し、国民に希望を与えた。映画では【黒澤明】が国際的な評価を得た。また1953年に【テレビ放送】が始まり、高度経済成長期には大衆文化が広く普及した。"},
  {"id": "jhx420", "s": "jh", "lv": 1, "topic": "寺社参詣の流行", "q": "江戸時代後期に庶民の寺社参詣や旅が盛んになった背景について説明せよ。", "a": "江戸時代には【五街道】などの交通網が整備され、宿場も発達した。経済的なゆとりができた庶民は、信仰と娯楽をかねて【伊勢神宮】などへの寺社参詣に出かけ、数百万人が伊勢へ向かう【御蔭参り】も起こった。村では費用を出し合う【講】がつくられた。また寺社の秘仏を公開する【開帳】も人々を集めた。"},
  {"id": "jhx421", "s": "jh", "lv": 1, "topic": "江戸の出版文化", "q": "江戸時代後期に出版文化が庶民に広がった理由について説明せよ。", "a": "【寺子屋】の普及で庶民の識字率が高まり、出版物の需要が増えた。木版印刷による本が大量につくられ、【貸本屋】を通じて安く読むことができた。【滑稽本】の十返舎一九『東海道中膝栗毛』や、読本の【曲亭馬琴】『南総里見八犬伝』などが人気を集めた。一方、幕府は寛政・天保の改革で風俗を乱すとして【出版統制】を行った。"},
  {"id": "jhx422", "s": "jh", "lv": 3, "topic": "日清戦後経営", "q": "日清戦争後、政府はどのような戦後経営を行ったか。その財源と目的に着目して説明せよ。", "a": "日清戦争後、【三国干渉】を受けた政府は、ロシアに対抗するため【軍備拡張】を中心とする戦後経営を進めた。また八幡製鉄所の設立など産業の振興も図った。財源には清からの【賠償金】をあてたほか、地租などの【増税】を行った。地租増徴をめぐって政府は政党と対立し、のちに【政党との提携】が進むきっかけとなった。"},
  {"id": "jhx423", "s": "jh", "lv": 2, "topic": "大学令と高等教育の拡充", "q": "1918年の大学令は、日本の教育と社会にどのような影響を与えたか説明せよ。", "a": "原敬内閣は【高等教育】の拡充を図り、1918年に【大学令】を制定した。これにより、それまで帝国大学に限られていた大学として、【公立・私立大学】や単科大学の設立が認められた。高等教育を受ける人が増え、都市の【サラリーマン】などの【新中間層】が広がり、大正期の大衆文化の担い手となった。"},
  {"id": "jhx424", "s": "jh", "lv": 3, "topic": "金輸出解禁", "q": "浜口雄幸内閣が金輸出解禁を行った目的と、それが失敗に終わった理由を説明せよ。", "a": "浜口内閣の井上準之助蔵相は、緊縮財政と産業合理化を進め、1930年に【金輸出解禁】を行った。為替相場を安定させて【貿易】を振興し、国際競争力の弱い企業を整理して経済の体質を改善することがねらいであった。しかし実勢より円高の【旧平価】で解禁したうえ、前年に起こった【世界恐慌】が波及し、正貨が大量に流出して深刻な【昭和恐慌】となった。"},
  {"id": "jhx425", "s": "jh", "lv": 3, "topic": "戦時統制経済", "q": "日中戦争期に日本の経済はどのように統制されたか説明せよ。", "a": "日中戦争が始まると、政府は軍需産業に資金や輸入資材を集中させるため、【臨時資金調整法】などで経済への直接統制を始めた。1937年に設置された【企画院】が【物資動員計画】を作成し、1938年の国家総動員法で政府は議会の承認なしに物資や労働力を動員できるようになった。また価格等統制令や【配給制】によって国民生活も統制された。"},
  {"id": "jhx426", "s": "jh", "lv": 3, "topic": "間接統治", "q": "連合国による日本占領が間接統治の方式で行われたことの意味を説明せよ。", "a": "日本の占領は事実上アメリカ軍が行い、マッカーサーを最高司令官とする【GHQ】が指令・勧告を出し、それを【日本政府】が実施する【間接統治】の方式がとられた。このため天皇制や政府・官僚機構は維持され、ポツダム勅令などによって改革が行われた。ドイツの【直接統治】とは異なり、戦前からの官僚機構が存続したことは戦後政治にも影響を与えた。"},
  {"id": "jhx427", "s": "jh", "lv": 3, "topic": "講和論争", "q": "サンフランシスコ平和条約の締結にあたって国内で起こった講和論争について説明せよ。", "a": "講和をめぐって、国内では、社会主義国を含むすべての交戦国と講和すべきだとする【全面講和論】と、アメリカなど西側諸国とだけでも講和して早期独立を図るべきだとする【単独講和論】とが対立した。南原繁らは全面講和を主張したが、【吉田茂】内閣は【西側陣営】の一員としての独立を選び、同時に日米安全保障条約を結んだ。"},
  {"id": "jhx428", "s": "jh", "lv": 2, "topic": "日米行政協定", "q": "1952年の日米行政協定の内容と、それがもたらした問題について説明せよ。", "a": "【日米安全保障条約】に基づき、1952年に【日米行政協定】が結ばれた。日本は駐留アメリカ軍に【基地】を提供し、その費用を分担することになった。また米兵の犯罪について日本の裁判権が制限されるなど不平等な面があった。各地で基地の拡張に反対する【基地反対闘争】が起こり、【内灘】や砂川の闘争が知られる。"},
  {"id": "jhx429", "s": "jh", "lv": 3, "topic": "赤字国債の発行", "q": "1970年代半ば以降、日本の財政で赤字国債の発行が続いた理由と、その影響を説明せよ。", "a": "石油危機後の不況で税収が落ち込む一方、【景気対策】としての公共事業や、社会保障の拡充による支出が増えた。政府は1975年度から本格的に【赤字国債】（特例国債）を発行した。その後も発行が続いて国債残高が増大し、【財政再建】が課題となった。1989年の【消費税】導入も財政の立て直しをねらいの一つとしていた。"},
  {"id": "jhx430", "s": "jh", "lv": 1, "topic": "社会保障制度の整備", "q": "高度経済成長期に日本の社会保障制度はどのように整備されたか説明せよ。", "a": "高度経済成長期には、すべての国民が公的な医療保険と年金に加入する【国民皆保険】・【国民皆年金】の体制が1961年に実現した。さらに1973年は「【福祉元年】」と呼ばれ、70歳以上の【老人医療費】の無料化や年金の給付水準の引き上げが行われた。しかしその直後の石油危機で財政は厳しくなった。"},
  {"id": "jhx431", "s": "jh", "lv": 1, "topic": "農業基本法", "q": "1961年の農業基本法の目的と、高度経済成長期の農業・農村の変化について説明せよ。", "a": "農業と工業の所得格差を是正するため、【農業基本法】が制定され、【機械化】や経営規模の拡大による自立経営農家の育成がめざされた。しかし農業以外の収入が多い【兼業農家】が増え、農村から都市への人口流出が進んだ。米が余るようになると、1970年から米の作付けを減らす【減反政策】が始まった。"},
  {"id": "jhx432", "s": "jh", "lv": 1, "topic": "過疎と過密", "q": "高度経済成長期に起こった過疎と過密の問題について説明せよ。", "a": "高度経済成長期には、若者を中心に農村から【太平洋ベルト】地帯の大都市へ人口が大量に流出した。都市では人口が集中して住宅不足や交通渋滞などの【過密】問題が起こり、郊外には大規模な住宅団地や【ニュータウン】が建設された。一方、農村や山村では人口が減って地域社会の維持が難しくなる【過疎】問題が深刻化した。"},
  {"id": "jhx433", "s": "jh", "lv": 1, "topic": "高度成長期の交通網", "q": "高度経済成長期に交通網がどのように整備されたか説明せよ。", "a": "1964年の【東京オリンピック】に合わせて、東京・新大阪間に【東海道新幹線】が開通し、首都高速道路も整備された。1965年には名神高速道路が全線開通し、のちに東名高速道路も開通した。こうして【高速道路】網が広がり、自動車が普及する【モータリゼーション】が進んだ。"},
  {"id": "jhx434", "s": "jh", "lv": 1, "topic": "金権政治批判", "q": "1970年代のロッキード事件は、日本の政治にどのような影響を与えたか説明せよ。", "a": "【田中角栄】首相は日本列島改造論を掲げたが、自らの金脈問題で退陣した。1976年には、アメリカの航空機会社からの収賄の容疑で田中前首相が逮捕される【ロッキード事件】が発覚した。【金権政治】への批判が高まり、同年の総選挙で【自由民主党】は議席を大きく減らした。"},
  {"id": "jhx435", "s": "jh", "lv": 1, "topic": "消費税の導入", "q": "1989年の消費税の導入について、その背景と政治への影響を説明せよ。", "a": "【財政赤字】の拡大と高齢化社会の到来に備えるため、【竹下登】内閣は1989年に税率3%の【消費税】を導入した。国民の反発は強く、【リクルート事件】も重なって竹下内閣は退陣した。同年の参議院議員選挙で自由民主党は大敗し、参議院で【過半数】を失った。"},
  {"id": "jhx436", "s": "jh", "lv": 1, "topic": "構造改革", "q": "2000年代の小泉純一郎内閣が進めた構造改革の内容と、その影響を説明せよ。", "a": "【小泉純一郎】内閣は「聖域なき構造改革」を掲げ、【規制緩和】や公共事業の削減、【郵政民営化】などを進めた。これは市場競争を重視する【新自由主義】的な政策であった。景気は回復に向かったが、非正規雇用の増加などにより所得の【格差】が拡大したとの批判もある。"},
  {"id": "jhx437", "s": "jh", "lv": 2, "topic": "保革伯仲", "q": "1970年代後半の保革伯仲とはどのような政治状況か。その背景とあわせて説明せよ。", "a": "【ロッキード事件】などで自由民主党への批判が強まり、1976年の総選挙で自民党は過半数を割り込み、追加公認でようやく過半数を確保した。国会では与党と野党の議席がほぼ拮抗する【保革伯仲】の状況となった。自民党内でも【三木武夫】おろしや福田・大平の対立など【派閥】抗争が激しく、新自由クラブが結成されるなど、政権運営は不安定になった。"},
  {"id": "jhx438", "s": "jh", "lv": 1, "topic": "郵便と通信の発達", "q": "明治初期に整備された郵便・電信の制度について説明せよ。", "a": "1871年、【前島密】の建議により、飛脚に代わる官営の【郵便制度】が始まり、全国均一料金制がとられた。また1869年には東京・横浜間に【電信】が開通し、1870年代には長崎と上海を結ぶ海底電線で【海外】とも結ばれた。これらは中央集権的な【近代国家】の情報網を支えた。"},
  {"id": "jhx439", "s": "jh", "lv": 2, "topic": "江戸時代の伝馬制度", "q": "江戸幕府が整えた街道の宿駅と伝馬の制度について、その目的と農村への負担を説明せよ。", "a": "幕府は【五街道】に【宿駅】を置き、公用の人や荷物を運ぶため、一定数の人馬を常備させた（伝馬制度）。宿駅には【問屋場】が置かれ、継ぎ立ての事務を扱った。人馬が不足すると、周辺の村々が【助郷】として人馬を提供させられ、交通量が増えると重い【負担】となった。"},
  {"id": "jhx440", "s": "jh", "lv": 3, "topic": "御家人制の変質", "q": "鎌倉時代後期、御家人制はどのように変質していったか。その原因とあわせて説明せよ。", "a": "鎌倉時代後期には【分割相続】の繰り返しによって所領が細分化し、【貨幣経済】の浸透で御家人は窮乏して所領を手放す者が多くなった。一方で【得宗】の家臣である【御内人】が勢力を強め、得宗専制のもとで一般の御家人は幕府政治から疎外された。こうして将軍と御家人の【御恩と奉公】の関係は揺らいだ。"},
  {"id": "jhx441", "s": "jh", "lv": 1, "topic": "日本列島改造論", "q": "田中角栄内閣の日本列島改造論はどのような政策で、どのような結果をもたらしたか説明せよ。", "a": "1972年に成立した【田中角栄】内閣は、【日本列島改造論】を掲げ、新幹線や【高速道路】の全国的な整備、工業の地方分散などを進めようとした。しかし開発予定地を中心に土地の買い占めが起こって【地価】が高騰し、1973年の【石油危機】も重なって激しいインフレ（狂乱物価）を招いた。"},
  {"id": "jhx442", "s": "jh", "lv": 2, "topic": "院政期の武士の中央進出", "q": "院政期に武士が中央政界に進出していった過程を説明せよ。", "a": "白河上皇は院の御所を警備する【北面の武士】を置き、武士を院の武力として用いた。【平正盛】・忠盛父子は、源義親の乱の鎮圧や瀬戸内海の海賊追討で功を立て、院の信任を得た。忠盛は武士として初めて【昇殿】を許され、【平清盛】の代には保元・平治の乱を経て、平氏が政権を握るに至った。"},
  {"id": "whx233", "s": "wh", "lv": 1, "topic": "シュメール人の都市国家", "q": "メソポタミア南部でシュメール人が築いた都市国家の特徴について説明せよ。", "a": "前3000年ごろ、シュメール人はメソポタミア南部に【ウル】やウルクなどの都市国家を築いた。灌漑農業による余剰生産物を背景に、王を中心とする【神権政治】が行われ、都市の中心には守護神をまつる【ジッグラト】が建てられた。粘土板に刻む【楔形文字】や六十進法も用いられた。"},
  {"id": "whx234", "s": "wh", "lv": 1, "topic": "ヒッタイト", "q": "ヒッタイトは、オリエントの歴史にどのような影響を与えたか説明せよ。", "a": "インド=ヨーロッパ語系の【ヒッタイト】は、前17世紀ごろ【アナトリア】に王国を建て、早くから【鉄器】を使用した。馬と戦車を用いて強大になり、【バビロン第1王朝】を滅ぼし、エジプトとも争った。ヒッタイトの滅亡後、製鉄技術がオリエント各地に広まった。"},
  {"id": "whx235", "s": "wh", "lv": 2, "topic": "アメンホテプ4世の改革", "q": "古代エジプトのアメンホテプ4世が行った宗教改革とその背景について説明せよ。", "a": "新王国時代、テーベの守護神【アメン】の神官団が強大な力をもち、王権を脅かしていた。【アメンホテプ4世】は唯一神【アトン】の信仰を強制し、自らもイクナートンと名乗り、都を【テル=エル=アマルナ】に移した。この時期には写実的な【アマルナ美術】が生まれたが、改革は王の死後に放棄された。"},
  {"id": "whx236", "s": "wh", "lv": 2, "topic": "アラム人", "q": "アラム人が古代オリエントで果たした役割について説明せよ。", "a": "セム語系の【アラム人】は、【ダマスクス】を中心に、ラクダを用いた【内陸交易】で活躍した。その結果、アラム語はオリエントの共通語（国際語）として広く用いられ、【アラム文字】は後にヘブライ文字やソグド文字、【ウイグル文字】など多くの文字の起源となった。"},
  {"id": "whx237", "s": "wh", "lv": 1, "topic": "ペルシア戦争", "q": "ペルシア戦争の経過と、それがギリシア世界に与えた影響について説明せよ。", "a": "前5世紀初め、アケメネス朝の支配に対するイオニア地方のギリシア人の反乱をきっかけに【ペルシア戦争】が起こった。アテネはマラトンの戦いや【サラミスの海戦】で勝利した。サラミスで軍船の漕ぎ手として活躍した【無産市民】の発言力が高まり、アテネの【民主政】が完成に向かった。"},
  {"id": "whx238", "s": "wh", "lv": 2, "topic": "デロス同盟", "q": "デロス同盟はどのように成立し、アテネとの関係はどのように変化したか説明せよ。", "a": "ペルシアの再来に備え、前478年ごろ、アテネを盟主として多くのポリスが【デロス同盟】を結んだ。しかしアテネは同盟の【資金】をアテネに移し、自国の建設事業にも流用するなど、加盟市に対する支配を強めた（アテネ帝国）。これに反発する【スパルタ】中心のペロポネソス同盟との対立が、【ペロポネソス戦争】を招いた。"},
  {"id": "whx239", "s": "wh", "lv": 1, "topic": "アレクサンドロスの東方遠征", "q": "アレクサンドロス大王の東方遠征は、どのような結果をもたらしたか説明せよ。", "a": "マケドニアの【アレクサンドロス】は、前334年に東方遠征を開始し、【アケメネス朝】を滅ぼしてインド北西部に至る大帝国を築いた。各地に【アレクサンドリア】と名づけた都市を建設した。彼の死後、帝国は分裂したが、ギリシア文化とオリエント文化が融合した【ヘレニズム】時代が始まった。"},
  {"id": "whx240", "s": "wh", "lv": 1, "topic": "ギリシア哲学", "q": "古代ギリシアにおける哲学の発展について説明せよ。", "a": "前6世紀のイオニア地方で、万物の根源を神話によらず合理的に探究する【自然哲学】が生まれた。前5世紀のアテネでは、弁論術を教えるソフィストの相対主義に対し、【ソクラテス】が普遍的な真理と徳を探究した。その弟子の【プラトン】はイデア論を説き、【アリストテレス】は諸学問を体系化した。"},
  {"id": "whx241", "s": "wh", "lv": 2, "topic": "ローマのイタリア半島統一", "q": "ローマはイタリア半島を統一した後、征服した諸都市をどのように支配したか説明せよ。", "a": "ローマは前3世紀前半に【イタリア半島】を統一した。征服した都市には、ローマ市民権を与える植民市、一部の権利のみ与える自治市、自治を認めるが義務を負わせる【同盟市】などと、異なる待遇を与えた。こうして都市どうしの団結を防ぐ【分割統治】を行い、反乱を防いだ。のちに同盟市は【市民権】を求めて反乱を起こした。"},
  {"id": "whx242", "s": "wh", "lv": 1, "topic": "ポエニ戦争", "q": "ポエニ戦争の結果、ローマの社会はどのように変化したか説明せよ。", "a": "ローマは、西地中海の覇権をめぐって【カルタゴ】と3次にわたる【ポエニ戦争】を戦い、勝利した。海外に属州を得たローマでは、属州から安い穀物が流入し、長期の従軍で中小農民が没落した。一方、有力者は奴隷を使った大土地所有制である【ラティフンディア】を経営して富を蓄え、【貧富の差】が拡大した。"},
  {"id": "whx243", "s": "wh", "lv": 2, "topic": "元首政", "q": "アウグストゥスが始めた元首政とはどのような政治体制か説明せよ。", "a": "カエサルの養子【オクタウィアヌス】は、内乱を終わらせ、元老院から【アウグストゥス】の称号を受けた。彼は共和政の制度を尊重し、自らを【市民の第一人者】（プリンケプス）と称した。しかし実際には軍隊の指揮権など多くの権力を握り、事実上の【皇帝】として統治した。この体制を【元首政】という。"},
  {"id": "whx244", "s": "wh", "lv": 2, "topic": "専制君主政", "q": "ディオクレティアヌス帝の専制君主政は、元首政とどのように異なるか説明せよ。", "a": "3世紀の危機を収拾した【ディオクレティアヌス】帝は、皇帝を神のように崇拝させる【専制君主政】（ドミナトゥス）を始めた。元首政が共和政の形式を残していたのに対し、皇帝は元老院を無視して【官僚制】と軍隊によって統治した。また帝国を4分割して統治する【四帝分治制】をしき、皇帝崇拝を拒む【キリスト教徒】を迫害した。"},
  {"id": "whx245", "s": "wh", "lv": 2, "topic": "ササン朝ペルシア", "q": "ササン朝ペルシアの政治と文化の特徴について説明せよ。", "a": "3世紀に【パルティア】を倒して成立したササン朝は、アケメネス朝の後継者を称し、【ゾロアスター教】を国教とした。シャープール1世はローマ皇帝を捕虜とし、6世紀の【ホスロー1世】は突厥と結んでエフタルを滅ぼした。工芸品は東西に広まり、日本の正倉院にもその影響がみられる。7世紀に【イスラーム】勢力に滅ぼされた。"},
  {"id": "whx246", "s": "wh", "lv": 2, "topic": "クシャーナ朝と大乗仏教", "q": "クシャーナ朝のもとで広まった大乗仏教は、それ以前の仏教とどのように異なるか説明せよ。", "a": "従来の仏教では出家者が自らの悟りを目指す修行を重視した。これに対し紀元前後に起こった【大乗仏教】は、自らの悟りよりも広く【衆生の救済】を重視し、その実践者を【菩薩】として信仰した。【カニシカ王】の保護を受けたクシャーナ朝のもとで広まり、ナーガールジュナが理論を体系化して、中央アジアから【中国】・日本に伝わった。"},
  {"id": "whx247", "s": "wh", "lv": 3, "topic": "季節風貿易", "q": "1世紀ごろのインド洋における季節風貿易の展開と、それが南インドに与えた影響を説明せよ。", "a": "1世紀ごろ、ギリシア系の商人が【季節風】（ヒッパロスの風）を利用して、エジプトからインドに直行する航路を開いた。その様子は『【エリュトゥラー海案内記】』に記されている。インドの【香辛料】などがローマに運ばれ、大量の【ローマの金貨】が南インドにもたらされた。南インドの【サータヴァーハナ朝】などはこの交易で栄えた。"},
  {"id": "whx248", "s": "wh", "lv": 1, "topic": "ヒンドゥー教の成立", "q": "ヒンドゥー教はどのように成立し、インド社会に定着したか説明せよ。", "a": "【バラモン教】に民間信仰が融合して【ヒンドゥー教】が成立した。シヴァ神やヴィシュヌ神などを信仰する多神教で、【グプタ朝】の時代に社会に定着した。ヴァルナ制にもとづく生活規範を定めた『【マヌ法典】』が成立し、人々の日常生活に深く根をおろした。一方、仏教は【衰退】に向かった。"},
  {"id": "whx249", "s": "wh", "lv": 3, "topic": "チョーラ朝", "q": "南インドのチョーラ朝が東南アジアに進出した背景について説明せよ。", "a": "10〜13世紀に南インドで栄えた【チョーラ朝】は、ヒンドゥー教を保護し、強力な海軍をもった。【海上交易】の利益を求めてセイロン島の一部を支配し、11世紀には東南アジアの【シュリーヴィジャヤ】に遠征した。また【宋】に使節を送るなど、インド洋から東アジアに至る交易ネットワークの中で勢力を広げた。"},
  {"id": "whx250", "s": "wh", "lv": 1, "topic": "殷の神権政治", "q": "殷王朝ではどのような政治が行われていたか説明せよ。", "a": "殷では、王が神意を占い、その結果に基づいて政治を行う【神権政治】が行われた。占いには亀の甲羅や獣の骨が用いられ、その内容を記した【甲骨文字】は漢字の起源となった。祭祀には精巧な【青銅器】が用いられた。殷墟からは大規模な王墓が発見されている。"},
  {"id": "whx251", "s": "wh", "lv": 2, "topic": "春秋・戦国時代の社会変化", "q": "春秋・戦国時代に中国の社会と経済はどのように変化したか説明せよ。", "a": "春秋時代末から【鉄製農具】や【牛耕】が普及して農業生産力が高まり、小家族による農業経営が可能となった。氏族的な結合はくずれ、諸侯は君主に権力を集中して官僚を用いる中央集権化を進めた。商工業も発達して【青銅貨幣】が流通し、各地に都市が栄えた。こうした変革の中で【諸子百家】が現れた。"},
  {"id": "whx252", "s": "wh", "lv": 1, "topic": "秦の滅亡", "q": "秦が統一後わずか15年で滅亡した理由について説明せよ。", "a": "秦の始皇帝は、【法家】の思想にもとづく厳しい法による統治を行い、万里の長城の修築や宮殿の造営などの大土木工事に人々を動員し、重い負担を課した。また【焚書・坑儒】で思想を弾圧した。始皇帝の死後、【陳勝・呉広の乱】をきっかけに各地で反乱が起こり、【劉邦】らが台頭して秦は滅亡した。"},
  {"id": "whx253", "s": "wh", "lv": 2, "topic": "後漢の豪族", "q": "後漢の時代に豪族が勢力を強めた背景と、それが政治に与えた影響を説明せよ。", "a": "前漢末から地方では大土地所有者である【豪族】が成長し、貧しい農民を【小作人】として支配した。後漢を建てた【光武帝】は豪族の支持を受けたため、豪族の力は大きく、官吏の推薦制度である【郷挙里選】を通じて官僚にも進出した。後漢後期には宦官と官僚が対立する【党錮の禁】が起こり、政治は混乱した。"},
  {"id": "whx254", "s": "wh", "lv": 1, "topic": "黄巾の乱", "q": "184年に起こった黄巾の乱の背景と、その結果について説明せよ。", "a": "後漢末には宦官の専横による政治の混乱や、豪族による土地の集積で、農民の生活は困窮した。こうした中、宗教結社【太平道】の指導者【張角】が農民を率いて【黄巾の乱】を起こした。乱は鎮圧されたが、各地の豪族や武将が自立して勢力を争い、後漢は滅亡に向かい、やがて【三国時代】となった。"},
  {"id": "whx255", "s": "wh", "lv": 2, "topic": "六朝文化", "q": "魏晋南北朝時代の江南を中心とする六朝文化の特徴について説明せよ。", "a": "建康を都とした南朝では、門閥貴族を担い手とする優雅な【貴族文化】が栄えた。俗世を離れて老荘思想を論じる【清談】が流行し、文学では田園詩人の【陶淵明】、四六駢儷体による華麗な文章が好まれた。書道の【王羲之】や、絵画の【顧愷之】も活躍した。"},
  {"id": "whx256", "s": "wh", "lv": 2, "topic": "五胡十六国", "q": "4世紀の華北で五胡十六国の時代が始まった背景と、その後の展開を説明せよ。", "a": "西晋で皇族の争いである【八王の乱】が起こると、その兵力として動員された匈奴などの【遊牧民】が自立した。匈奴は西晋を滅ぼし、華北では遊牧民と漢人が多くの国を建てる【五胡十六国】時代となった。晋の一族は江南に逃れて【東晋】を建てた。5世紀前半には鮮卑の【北魏】が華北を統一した。"},
  {"id": "whx257", "s": "wh", "lv": 2, "topic": "府兵制", "q": "西魏に始まり唐に受け継がれた府兵制とはどのような兵制か。その衰退の理由とあわせて説明せよ。", "a": "【府兵制】は、均田制で土地を与えた農民から兵士を選び、自費で武器や食料を用意させて、都の警備や辺境の防衛にあたらせる【兵農一致】の制度であった。しかし兵役の負担が重く、農民の逃亡が増えて均田制が崩れると維持できなくなり、8世紀には傭兵を用いる【募兵制】に切り替えられ、【節度使】が辺境防衛を担った。"},
  {"id": "whx258", "s": "wh", "lv": 1, "topic": "租調庸制", "q": "唐の租調庸制とはどのような税制か。均田制との関係とあわせて説明せよ。", "a": "唐では、【均田制】によって成年男子に土地を与え、その代わりに税を課した。穀物を納める【租】、絹や麻などの布を納める【調】、労役またはその代わりに絹などを納める【庸】があり、これを【租調庸制】という。成年男子に一律に課す人頭税であったため、均田制が崩れると機能しなくなり、【両税法】に代わった。"},
  {"id": "whx259", "s": "wh", "lv": 2, "topic": "羈縻政策", "q": "唐が周辺民族に対してとった羈縻政策について説明せよ。", "a": "唐は東突厥などを服属させて大領土を築き、征服地には【都護府】を置いた。周辺民族の居住地には州や県を設けたが、統治はその民族の【首長】に任せ、唐はその上から監督した。このような間接統治を【羈縻政策】という。これにより唐は少ない負担で広大な領域を支配し、多様な民族を取り込む【世界帝国】となった。"},
  {"id": "whx260", "s": "wh", "lv": 2, "topic": "節度使の台頭", "q": "唐の後半に節度使が強大化した背景と、その政治的影響を説明せよ。", "a": "府兵制が崩れると、唐は辺境に募兵による軍団を置き、その指揮官として【節度使】を任じた。節度使はやがて民政や財政の権限も持つようになり、【安史の乱】の後は内地にも置かれた。彼らは任地で自立した勢力（【藩鎮】）となって中央の統制から離れ、唐の滅亡後は【五代十国】の分裂時代につながった。"},
  {"id": "whx261", "s": "wh", "lv": 1, "topic": "黄巣の乱", "q": "黄巣の乱が起こった背景と、それが唐に与えた影響について説明せよ。", "a": "唐の後半、財政難を補うため政府は【塩】を専売制にして高値で売った。これに対し、塩の密売人の【王仙芝】や【黄巣】が875年に反乱を起こした。乱は全国に広がり、黄巣は一時長安を占領した。反乱軍を離脱した【朱全忠】は節度使となり、907年に唐を滅ぼして後梁を建てた。"},
  {"id": "whx262", "s": "wh", "lv": 2, "topic": "ジャムチ", "q": "モンゴル帝国のジャムチ（駅伝制）は、ユーラシアの交流にどのような役割を果たしたか説明せよ。", "a": "モンゴル帝国は、首都の【カラコルム】や大都を中心に幹線道路を整備し、一定の間隔で駅を設けて馬や食料を用意させる【ジャムチ】（駅伝制）を整えた。使者は通行証の【牌符】を持って駅を利用した。これにより帝国の広大な領域の統治が可能になり、商人や宣教師の往来が活発化して、【東西交流】が盛んになった。"},
  {"id": "whx263", "s": "wh", "lv": 1, "topic": "永楽帝の政策", "q": "明の永楽帝の積極的な対外政策について説明せよ。", "a": "【靖難の役】で甥の建文帝から帝位を奪った永楽帝は、都を南京から【北京】に移した。自らモンゴル高原に遠征し、ベトナムを一時支配した。また宦官の【鄭和】に命じて南海遠征を行わせ、多くの国に【朝貢】をうながした。この時期、明の国際的な影響力は最大となった。"},
  {"id": "whx264", "s": "wh", "lv": 3, "topic": "張居正の改革", "q": "16世紀後半の張居正の改革の内容と、その後の明の政治について説明せよ。", "a": "万暦帝の初期、内閣大学士の【張居正】は、北虜南倭による財政難を立て直すため、全国の土地を調査し、【一条鞭法】を全国に広げた。また官僚の綱紀を正し、国家財政を一時的に再建した。しかし強引な手法は官僚の反発を招き、彼の死後は【万暦帝】の浪費や朝鮮出兵などで財政が再び悪化し、官僚の派閥争い（【東林派】と非東林派）が激化した。"},
  {"id": "whx265", "s": "wh", "lv": 2, "topic": "一条鞭法", "q": "明代後半に一条鞭法が広まった背景と、その内容を説明せよ。", "a": "16世紀、日本や【アメリカ大陸】から大量の【銀】が中国に流入し、銀が主要な貨幣として流通するようになった。これを背景に、複雑だった土地税（田賦）と人頭税・労役（丁税）をそれぞれ【銀】で一括して納める【一条鞭法】が広まった。これは税制を簡素化するもので、清代の【地丁銀制】につながった。"},
  {"id": "whx266", "s": "wh", "lv": 2, "topic": "里甲制", "q": "明の洪武帝が農村支配のために設けた里甲制について説明せよ。", "a": "洪武帝は、農村を110戸で1里とし、そのうち富裕な10戸を【里長戸】、残り100戸を10甲に分ける【里甲制】を設けた。里長と甲首が【租税】の徴収や治安維持にあたった。また戸籍・租税台帳の【賦役黄冊】と、土地台帳の【魚鱗図冊】を作成し、【六諭】を定めて儒教道徳を教えるなど、民衆を統制した。"},
  {"id": "whx267", "s": "wh", "lv": 3, "topic": "東林派", "q": "明末に東林派と非東林派の対立が激化したことは、明の滅亡とどのように関わったか説明せよ。", "a": "明末、【顧憲成】らが無錫の東林書院を拠点に、宦官の専横や政治の腐敗を批判した。彼らは【東林派】と呼ばれ、宦官【魏忠賢】と結ぶ非東林派と激しく争い、弾圧を受けた。この【党争】によって政治は麻痺し、重税への不満から各地で反乱が起こって、1644年に【李自成】の反乱軍が北京を占領し、明は滅亡した。"},
  {"id": "whx268", "s": "wh", "lv": 2, "topic": "典礼問題", "q": "清代の典礼問題とはどのようなもので、清のキリスト教政策にどのような影響を与えたか説明せよ。", "a": "【イエズス会】は、中国人信者が孔子の祭祀や祖先崇拝などの【典礼】に参加することを容認して布教を進めた。これに対し、ドミニコ会などが教皇に訴えて批判し、教皇は典礼を禁止した。これに反発した【康熙帝】はイエズス会以外の布教を禁じ、【雍正帝】は1724年にキリスト教の布教を全面的に【禁止】した。"},
  {"id": "whx269", "s": "wh", "lv": 2, "topic": "軍機処", "q": "清の雍正帝が設置した軍機処の役割について説明せよ。", "a": "雍正帝は、ジュンガルとの戦争に際して機密を保つため、【軍機処】を設置した。皇帝が少数の信任する大臣を選んで、重要な政務や【軍事】を処理させた。軍機処は皇帝の【独裁】を支える最高の政務機関となり、明以来の内閣に代わって政治の中枢となった。これにより皇帝の権力はいっそう強化された。"},
  {"id": "whx270", "s": "wh", "lv": 2, "topic": "マカートニー使節団", "q": "18世紀末にイギリスがマカートニーを清に派遣した目的と、その結果について説明せよ。", "a": "清は1757年に西洋との貿易を【広州】一港に限定し、特許商人の【公行】に貿易を独占させていた。イギリスはこうした貿易制限の撤廃と自由貿易を求めて、1793年に【マカートニー】を派遣し、【乾隆帝】に謁見した。しかし清は朝貢の形式にこだわり、要求を拒否した。その後のアマースト派遣も失敗し、のちの【アヘン戦争】につながった。"},
  {"id": "whx271", "s": "wh", "lv": 3, "topic": "清代の人口増加", "q": "18世紀の清で人口が急増した理由と、それが社会に与えた影響について説明せよ。", "a": "18世紀、清の平和と【地丁銀制】による人頭税の廃止、さらにアメリカ大陸原産の【トウモロコシ】やサツマイモなど、山地でも栽培できる作物の普及により、人口は約3億人に急増した。人口の増加は耕地の不足を招き、人々は山間部や辺境に移住した。生活が苦しい移住民の間では【白蓮教】などが広まり、【白蓮教徒の乱】などの社会不安が起こった。"},
  {"id": "whx272", "s": "wh", "lv": 1, "topic": "朝鮮の三国時代", "q": "朝鮮半島の三国時代とその統一について説明せよ。", "a": "4世紀ごろ、朝鮮半島北部の【高句麗】に加え、南部に【百済】と【新羅】が成立し、三国が争った。7世紀、新羅は唐と結んで百済と高句麗を滅ぼし、その後唐の勢力を追い出して676年に半島を統一した。新羅は【骨品制】と呼ばれる身分制度をもち、都の【金城】（慶州）を中心に仏教文化が栄えた。"},
  {"id": "whx273", "s": "wh", "lv": 2, "topic": "両班", "q": "朝鮮王朝の両班とはどのような階層か。その特徴を説明せよ。", "a": "【両班】は、もともと文官（文班）と武官（武班）を指したが、朝鮮王朝では【科挙】に合格して官僚となる特権的な支配階層を意味するようになった。両班は【朱子学】を学び、土地を所有して地方社会でも大きな力をもった。彼らは学派などに分かれて激しい【党争】を繰り返した。"},
  {"id": "whx274", "s": "wh", "lv": 1, "topic": "訓民正音", "q": "15世紀に朝鮮でつくられた訓民正音について、その意義を説明せよ。", "a": "朝鮮王朝第4代の【世宗】は、学者を集めて朝鮮語を表記するための独自の文字を作らせ、1446年に【訓民正音】として公布した。のちに【ハングル】と呼ばれる。それまでの漢字では表しにくかった朝鮮語を、民衆でも書き表せるようにした点に意義がある。この時代には【金属活字】による印刷も盛んであった。"},
  {"id": "whx275", "s": "wh", "lv": 2, "topic": "壬辰・丁酉倭乱", "q": "豊臣秀吉の朝鮮侵攻（壬辰・丁酉倭乱）は、東アジアにどのような影響を与えたか説明せよ。", "a": "16世紀末、豊臣秀吉が朝鮮に出兵すると、朝鮮では【李舜臣】が率いる水軍や民衆の【義兵】が抵抗し、【明】も援軍を送った。戦争によって朝鮮の国土は荒廃した。明は援軍の派遣で財政が悪化し、その衰退が早まった。この間に中国東北部では【女真】（満州人）が勢力を伸ばし、のちの清の興隆につながった。"},
  {"id": "whx276", "s": "wh", "lv": 1, "topic": "ウマイヤ朝", "q": "ウマイヤ朝の統治の特徴と、それに対する不満について説明せよ。", "a": "661年、シリア総督の【ムアーウィヤ】は【ダマスクス】を都としてウマイヤ朝を開き、カリフ位を世襲とした。ウマイヤ朝はアラブ人が支配者として特権をもち、イスラームに改宗した非アラブ人（【マワーリー】）にも【ジズヤ】（人頭税）や地租を課した。このようなアラブ人優遇に対する不満が高まり、750年にアッバース朝に倒された。"},
  {"id": "whx277", "s": "wh", "lv": 2, "topic": "後ウマイヤ朝", "q": "後ウマイヤ朝の成立と、その文化的な役割について説明せよ。", "a": "アッバース朝が成立すると、ウマイヤ家の一族はイベリア半島に逃れ、756年に【コルドバ】を都として【後ウマイヤ朝】を建てた。10世紀にはカリフを称した。コルドバは西方イスラーム世界の学問と文化の中心として栄え、のちにここなどで蓄積された古典の知識が【ラテン語】に翻訳され、ヨーロッパの【12世紀ルネサンス】に影響を与えた。"},
  {"id": "whx278", "s": "wh", "lv": 2, "topic": "シャリーアとウラマー", "q": "イスラーム社会におけるシャリーア（イスラーム法）とウラマーの役割について説明せよ。", "a": "【シャリーア】は、『コーラン』と預言者ムハンマドの言行（【ハディース】）をもとに体系化されたイスラーム法である。信仰儀礼だけでなく、結婚・相続・商取引など社会生活全般を規定した。イスラーム諸学を修めた知識人である【ウラマー】が、法学者や裁判官（カーディー）としてシャリーアを解釈・適用し、社会秩序を支えた。"},
  {"id": "whx279", "s": "wh", "lv": 2, "topic": "スーフィズム", "q": "スーフィズム（イスラーム神秘主義）とはどのようなものか。それがイスラームの拡大に果たした役割とあわせて説明せよ。", "a": "形式化した法や学問を重視する傾向に対し、修行によって神との一体感を求める【神秘主義】が生まれた。これを【スーフィズム】といい、12世紀以降、聖者を中心とする【教団】が組織されて民衆に広まった。スーフィーは各地の民間信仰とも融合しながら布教し、【東南アジア】やアフリカ、中央アジアへのイスラームの拡大に大きな役割を果たした。"},
  {"id": "whx280", "s": "wh", "lv": 3, "topic": "ワクフ", "q": "イスラーム都市の発展においてワクフ（寄進制度）が果たした役割を説明せよ。", "a": "【ワクフ】は、私有財産の所有者がその収益を宗教や公共の目的のために永久に寄進する制度である。支配者や富裕な商人は、店舗や農地などをワクフとし、その収益で【モスク】や学院の【マドラサ】、病院、隊商宿などを建設・運営した。これにより都市の宗教・教育・福祉の施設が維持され、【スーク】（市場）とともに【イスラーム都市】の発展を支えた。"},
  {"id": "whx281", "s": "wh", "lv": 2, "topic": "イル=ハン国", "q": "イル=ハン国の成立と、その統治の変化について説明せよ。", "a": "チンギス=ハンの孫【フレグ】は西アジアに遠征し、1258年に【アッバース朝】を滅ぼして、イラン高原を中心にイル=ハン国を建てた。当初は少数のモンゴル人がイラン人を支配したが、13世紀末の【ガザン=ハン】は【イスラーム】に改宗して国教とし、イラン人の宰相【ラシード=アッディーン】を登用して税制改革を行った。"},
  {"id": "whx282", "s": "wh", "lv": 1, "topic": "イブン=バットゥータ", "q": "イブン=バットゥータの旅行は、当時のイスラーム世界についてどのようなことを示しているか説明せよ。", "a": "モロッコ出身の【イブン=バットゥータ】は、14世紀にアフリカからインド、中国（【元】）にまで旅行し、その見聞を『【三大陸周遊記】』にまとめた。彼は各地のムスリム社会で歓迎され、法学者として仕えることもあった。これは広大な地域にイスラーム世界の【ネットワーク】が形成されていたことを示している。"},
  {"id": "whx283", "s": "wh", "lv": 1, "topic": "インド洋交易", "q": "8世紀以降のインド洋交易で活躍したムスリム商人について説明せよ。", "a": "アッバース朝の成立以降、ムスリム商人は三角帆の【ダウ船】を用い、【季節風】を利用してインド洋で活発な交易を行った。彼らは東アフリカ沿岸や東南アジア、中国の【広州】などに居留地をつくり、香辛料や陶磁器、絹などを取引した。こうした交易を通じて、各地に【イスラーム】が広まった。"},
  {"id": "whx284", "s": "wh", "lv": 3, "topic": "ムラービト朝とムワッヒド朝", "q": "北アフリカのムラービト朝とムワッヒド朝が、西アフリカやイベリア半島に与えた影響を説明せよ。", "a": "11世紀、ベルベル人の【ムラービト朝】は【マラケシュ】を都とし、南に進んで西アフリカの【ガーナ王国】を攻撃し、この地域のイスラーム化をうながした。また北のイベリア半島に進出し、キリスト教勢力のレコンキスタに対抗した。12世紀にこれに代わった【ムワッヒド朝】も半島に進出したが、13世紀前半に【キリスト教】勢力に敗れて衰退した。"},
  {"id": "whx285", "s": "wh", "lv": 2, "topic": "カピチュレーション", "q": "オスマン帝国のカピチュレーションは、当初の意味と後の意味とでどのように変化したか説明せよ。", "a": "【カピチュレーション】は、オスマン帝国がフランスなどの外国人に、帝国内での居住や通商の自由、【領事裁判権】などを恩恵として認めた特権である。16世紀の【スレイマン1世】の時代に拡大したとされ、当初は強大な帝国からの恩恵であった。しかし帝国が衰えると、ヨーロッパ諸国の経済的な【進出】と内政干渉の足場となり、【不平等条約】の性格を強めた。"},
  {"id": "whx286", "s": "wh", "lv": 3, "topic": "マラーター同盟", "q": "18世紀のインドにおけるマラーター同盟の台頭と、イギリスとの関係について説明せよ。", "a": "17世紀後半、【アウラングゼーブ】の厳格なイスラーム政策に反発して、西インドのヒンドゥー教徒が【シヴァージー】のもとで王国を建てた。18世紀には諸侯の連合体である【マラーター同盟】となり、ムガル帝国に代わって勢力を広げた。しかし【マラーター戦争】でイギリスに敗れ、1818年に事実上解体した。"},
  {"id": "whx287", "s": "wh", "lv": 2, "topic": "シク教", "q": "シク教の教えの特徴と、シク教徒が政治的勢力となった経緯について説明せよ。", "a": "16世紀初め、【ナーナク】はイスラーム教の影響を受け、ヒンドゥー教の偶像崇拝や【カースト】による差別を否定して、唯一神への信仰を説く【シク教】を開いた。パンジャーブ地方で信者を広げ、ムガル帝国の弾圧に対抗して武装化した。19世紀前半に王国を建てたが、【シク戦争】でイギリスに敗れて併合された。"},
  {"id": "whx288", "s": "wh", "lv": 1, "topic": "フランク王国の発展", "q": "ゲルマン人の国家の中で、フランク王国が発展した理由について説明せよ。", "a": "5世紀末、メロヴィング家の【クローヴィス】がフランク人を統一した。彼は他のゲルマン人が信仰していた異端の【アリウス派】ではなく、正統派の【アタナシウス派】に改宗した。そのため、ローマ系の住民やローマ教会の支持を得ることができ、フランク王国は西ヨーロッパの【有力国家】として発展した。"},
  {"id": "whx289", "s": "wh", "lv": 2, "topic": "カロリング朝の成立", "q": "カロリング朝の成立と、ローマ教皇との結びつきについて説明せよ。", "a": "8世紀、メロヴィング朝の【宮宰】カール=マルテルは、【トゥール・ポワティエ間の戦い】でイスラーム勢力を撃退した。その子【ピピン】は教皇の支持を得て王位につき、カロリング朝を開いた。ピピンはその見返りにランゴバルド王国から奪った【ラヴェンナ】地方を教皇に寄進し、これが【教皇領】の始まりとなった。"},
  {"id": "whx290", "s": "wh", "lv": 1, "topic": "神聖ローマ帝国の成立", "q": "神聖ローマ帝国の成立と、その後の皇帝のイタリア政策について説明せよ。", "a": "東フランク王国の【オットー1世】は、マジャール人を撃退し、962年に教皇から【ローマ皇帝】の冠を受けた。これが【神聖ローマ帝国】の始まりとされる。歴代の皇帝は【イタリア政策】に力を注いでイタリアに出兵を繰り返したため、ドイツ本国の統治はおろそかになり、諸侯の自立が進んだ。"},
  {"id": "whx291", "s": "wh", "lv": 2, "topic": "領邦の分立", "q": "中世後期のドイツで領邦が分立した理由を、神聖ローマ帝国の政治から説明せよ。", "a": "神聖ローマ皇帝は【イタリア政策】に力を注ぎ、国内の統治を怠ったため、諸侯が自立して【領邦】を形成した。13世紀には事実上皇帝のいない【大空位時代】も生じた。1356年に皇帝カール4世が出した【金印勅書】は、皇帝選出権を7人の【選帝侯】に認め、諸侯の権限を確認したため、ドイツの分裂はいっそう固定化した。"},
  {"id": "whx292", "s": "wh", "lv": 2, "topic": "修道院運動", "q": "中世ヨーロッパの修道院が果たした役割と、クリュニー修道院による改革について説明せよ。", "a": "6世紀に【ベネディクトゥス】がモンテ=カシノに修道院を開き、「祈り、働け」をモットーに規律ある生活を定めた。修道院は開墾や学問の保存に貢献した。10世紀に創設された【クリュニー修道院】は、聖職売買や聖職者の妻帯などの【教会の腐敗】を批判して改革運動を進め、のちの【叙任権闘争】につながる教皇の改革に影響を与えた。"},
  {"id": "whx293", "s": "wh", "lv": 2, "topic": "托鉢修道会", "q": "13世紀に生まれた托鉢修道会の特徴と役割について説明せよ。", "a": "13世紀、都市の発達とともに、清貧を重んじ、財産をもたずに【托鉢】によって生活しながら民衆の中で布教する修道会が生まれた。イタリアの【フランチェスコ修道会】やスペイン出身者が創設した【ドミニコ修道会】が代表的である。彼らは【都市】の民衆に説教して信仰を広め、異端の論駁や、大学での【神学】の研究にも力を尽くした。"},
  {"id": "whx294", "s": "wh", "lv": 1, "topic": "スコラ学", "q": "中世ヨーロッパのスコラ学とはどのような学問か説明せよ。", "a": "【スコラ学】は、キリスト教の信仰を理性によって体系的に説明しようとした学問である。12世紀以降、イスラーム世界を経由して【アリストテレス】哲学が伝わると、これを取り入れて発展した。13世紀に【トマス=アクィナス】が『【神学大全】』を著し、信仰と理性の調和を図ってスコラ学を大成した。"},
  {"id": "whx295", "s": "wh", "lv": 1, "topic": "中世の大学", "q": "中世ヨーロッパで大学が生まれた背景と、その特徴を説明せよ。", "a": "12世紀以降、都市の発達やイスラーム世界からの学問の流入を背景に、学生や教師の【組合】として大学が生まれた。法学で知られる【ボローニャ大学】、神学で知られる【パリ大学】、医学のサレルノ大学などが有名である。大学では共通語の【ラテン語】が用いられ、教会や国王から【自治権】を認められた。"},
  {"id": "whx296", "s": "wh", "lv": 1, "topic": "中世の教会建築", "q": "中世ヨーロッパの教会建築の様式の変化について説明せよ。", "a": "11〜12世紀には、厚い石の壁と小さな窓、半円アーチを特徴とする重厚な【ロマネスク様式】が広まった。代表例はイタリアの【ピサ大聖堂】である。12世紀後半からは、尖頭アーチと高い尖塔、大きな窓を飾る【ステンドグラス】を特徴とする【ゴシック様式】が都市で盛んになり、フランスのノートルダム大聖堂などが建てられた。"},
  {"id": "whx297", "s": "wh", "lv": 1, "topic": "ハンザ同盟", "q": "北ドイツの都市が結んだハンザ同盟の目的と活動について説明せよ。", "a": "中世後期、【リューベック】を盟主とする北ドイツの諸都市は【ハンザ同盟】を結んだ。共通の利益を守るため、【北海・バルト海】の交易を独占し、ロンドンやノヴゴロドなどに商館を置いた。同盟は独自の軍隊をもち、【デンマーク】と戦って勝利するなど、大きな政治力をもった。"},
  {"id": "whx298", "s": "wh", "lv": 1, "topic": "地中海商業圏", "q": "中世ヨーロッパの地中海商業圏の特徴について説明せよ。", "a": "十字軍をきっかけに地中海の交易が活発化し、【ヴェネツィア】や【ジェノヴァ】などの北イタリア諸都市が、東方から香辛料や絹織物などを輸入する【東方貿易】（レヴァント貿易）で繁栄した。この地中海商業圏と北海・バルト海の北ヨーロッパ商業圏は、フランスの【シャンパーニュ地方】の定期市などで結ばれた。"},
  {"id": "whx299", "s": "wh", "lv": 3, "topic": "アルビジョワ十字軍", "q": "13世紀のアルビジョワ十字軍は、フランス王権の伸長にどのような意味をもったか説明せよ。", "a": "南フランスでは、教会の権威を否定する異端の【カタリ派】（アルビジョワ派）が広まった。教皇【インノケンティウス3世】の呼びかけでアルビジョワ十字軍が組織され、北フランスの諸侯が参加した。最終的にフランス王【ルイ9世】の時代に南フランスは王権の支配下に入り、カペー朝の【王領】の拡大と王権の強化につながった。"},
  {"id": "whx300", "s": "wh", "lv": 2, "topic": "フィリップ4世と三部会", "q": "フランス王フィリップ4世が三部会を召集した経緯と、その意義について説明せよ。", "a": "カペー朝の【フィリップ4世】は、戦費調達のため聖職者への【課税】を図り、教皇ボニファティウス8世と対立した。1302年、彼は聖職者・貴族・平民の代表からなる【三部会】を召集し、国内の支持を固めた。その後、教皇を捕らえる【アナーニ事件】を起こし、教皇庁を【アヴィニョン】に移した。これは王権が教皇権を上回ったことを示している。"},
  {"id": "whx301", "s": "wh", "lv": 2, "topic": "ばら戦争", "q": "ばら戦争はイギリスの政治にどのような変化をもたらしたか説明せよ。", "a": "百年戦争の終結後、イギリスでは王位継承をめぐって【ランカスター家】と【ヨーク家】が争い、ばら戦争が起こった。多くの諸侯・騎士が戦いで没落した。1485年、ランカスター家につながるヘンリ7世が王位について【テューダー朝】を開き、【星室庁裁判所】を活用して貴族を抑え、【絶対王政】の基礎を築いた。"},
  {"id": "whx302", "s": "wh", "lv": 1, "topic": "中世末の農民反乱", "q": "14世紀にフランスとイギリスで起こった農民反乱の背景について説明せよ。", "a": "14世紀には【黒死病】の流行で人口が激減し、労働力不足から農民の地位が向上していた。これに対して領主が再び【封建反動】を強めたため、農民の不満が高まった。フランスでは【ジャックリーの乱】、イギリスでは人頭税を契機に【ワット=タイラーの乱】が起こった。乱は鎮圧されたが、【荘園制】の解体は進んだ。"},
  {"id": "whx303", "s": "wh", "lv": 2, "topic": "ウィクリフとフス", "q": "14〜15世紀のウィクリフとフスの教会批判は、のちの宗教改革とどのように関わるか説明せよ。", "a": "イギリスの【ウィクリフ】は、【聖書】こそが信仰の唯一の拠り所であると主張して教会の世俗化を批判し、聖書を英訳した。その影響を受けたベーメンの【フス】も教会を批判したが、【コンスタンツ公会議】で異端とされて処刑された。その後ベーメンでは【フス戦争】が起こった。聖書中心主義などの主張は、16世紀の【宗教改革】の先駆となった。"},
  {"id": "whx304", "s": "wh", "lv": 2, "topic": "モスクワ大公国", "q": "モスクワ大公国がロシアの統一を進めた過程について説明せよ。", "a": "13世紀以来、ロシアは【キプチャク=ハン国】の支配下にあった（タタールのくびき）。モスクワ大公国はしだいに勢力を伸ばし、15世紀後半の【イヴァン3世】は1480年にキプチャク=ハン国の支配から自立した。彼はビザンツ皇帝の姪と結婚して【ツァーリ】の称号を用い、モスクワは【ギリシア正教】の中心とされた。"},
  {"id": "whx305", "s": "wh", "lv": 2, "topic": "スラヴ人の改宗", "q": "東ヨーロッパのスラヴ人の宗教について、東西の教会の影響の違いに着目して説明せよ。", "a": "スラヴ人のうち、ロシア人やセルビア人などの【東スラヴ人】・南スラヴ人の多くは、ビザンツ帝国の影響を受けて【ギリシア正教】を受け入れ、キリル文字を用いた。一方、ポーランド人やチェック人などの【西スラヴ人】は、【ローマ=カトリック】を受け入れ、ラテン文字を用いた。この違いは、東ヨーロッパの【文化圏】の分かれ目となった。"},
  {"id": "whx306", "s": "wh", "lv": 3, "topic": "ヤゲウォ朝", "q": "14世紀後半に成立したポーランドのヤゲウォ朝の意義について説明せよ。", "a": "ドイツ騎士団の圧迫に対抗するため、1386年、【リトアニア大公】ヤゲウォとポーランド女王が結婚し、両国が連合して【ヤゲウォ朝】が成立した。1410年には【ドイツ騎士団】を破った。ヤゲウォ朝は16世紀に最盛期を迎え、東ヨーロッパの大国となった。ヤゲウォ朝断絶後は貴族が国王を選ぶ【選挙王制】となった。"},
  {"id": "whx307", "s": "wh", "lv": 2, "topic": "東方植民", "q": "12世紀以降のドイツ人の東方植民について、その背景と結果を説明せよ。", "a": "中世の農業生産の向上や人口の増加を背景に、12世紀以降ドイツ人は【エルベ川】以東のスラヴ人居住地域へ大規模に移住した（【東方植民】）。その結果、【ブランデンブルク辺境伯領】やドイツ騎士団領が成立した。この地域では、のちに領主が直営地で農民を使役する【農場領主制】（グーツヘルシャフト）が展開した。"},
  {"id": "whx308", "s": "wh", "lv": 3, "topic": "12世紀ルネサンス", "q": "12世紀ルネサンスとはどのような動きか。その背景とともに説明せよ。", "a": "12世紀、【レコンキスタ】が進んだイベリア半島の【トレド】や、シチリア島などで、イスラーム世界に伝わっていたギリシア古典やアラビア語の学術書が【ラテン語】に翻訳された。これにより【アリストテレス】哲学や医学・数学・天文学が西ヨーロッパに流入し、【スコラ学】や大学の発展をうながした。この学問の復興を12世紀ルネサンスという。"},
  {"id": "whx309", "s": "wh", "lv": 2, "topic": "イタリア戦争", "q": "イタリア戦争の原因と、それがヨーロッパの国際関係に与えた影響について説明せよ。", "a": "15世紀末、フランス王シャルル8世がイタリアに侵入し、【イタリア戦争】が始まった。のちにフランスの【ヴァロワ家】と神聖ローマ皇帝を出す【ハプスブルク家】が、イタリアの支配をめぐって長く争った。この戦争の中で、各国が常備軍や外交使節を整え、勢力均衡を図る【主権国家】体制が形成された。また戦乱によってイタリアの【ルネサンス】は衰退に向かった。"},
  {"id": "whx310", "s": "wh", "lv": 2, "topic": "カール5世", "q": "神聖ローマ皇帝カール5世が直面した課題について説明せよ。", "a": "ハプスブルク家の【カール5世】は、スペイン王と神聖ローマ皇帝を兼ね、ネーデルラントやアメリカ大陸にも領土をもつ大帝国を支配した。しかし外では【フランソワ1世】とのイタリア戦争や【オスマン帝国】の脅威（第1次ウィーン包囲）、内では【ルター派】の諸侯との対立に苦しんだ。退位後、領土はスペイン系とオーストリア系に分かれた。"},
  {"id": "whx311", "s": "wh", "lv": 1, "topic": "フェリペ2世", "q": "16世紀後半のスペインの繁栄と、その衰退の始まりについて説明せよ。", "a": "【フェリペ2世】の時代、スペインはアメリカ大陸の【銀】を背景に繁栄した。1571年の【レパントの海戦】でオスマン帝国を破り、1580年には【ポルトガル】を併合して「太陽の沈まぬ国」となった。しかしオランダの独立戦争や、1588年の【無敵艦隊】のイギリスへの敗北などで、衰退に向かった。"},
  {"id": "whx312", "s": "wh", "lv": 2, "topic": "価格革命", "q": "16世紀のヨーロッパで起こった価格革命とはどのようなものか。その社会的な影響を説明せよ。", "a": "16世紀、【アメリカ大陸】から大量の【銀】がヨーロッパに流入し、物価が2〜3倍に上昇した。これを【価格革命】という。定額の地代収入に頼っていた【封建領主】は打撃を受けて没落が進んだ。一方、商工業者は利益を得て力を伸ばした。また西ヨーロッパの商工業の発達は、穀物を輸出する東ヨーロッパの【農場領主制】を強める結果となった。"},
  {"id": "whx313", "s": "wh", "lv": 2, "topic": "商業革命", "q": "大航海時代以降のヨーロッパで起こった商業革命について説明せよ。", "a": "大航海時代以降、アジアやアメリカ大陸との交易がさかんになり、ヨーロッパの商業の中心は【地中海】沿岸から【大西洋】沿岸へと移った。これを【商業革命】という。その結果、イタリア諸都市や南ドイツは衰え、スペイン・ポルトガルの【リスボン】や、のちに【アントウェルペン】、さらにアムステルダムが国際商業の中心となった。"},
  {"id": "whx314", "s": "wh", "lv": 1, "topic": "イギリスの宗教改革", "q": "イギリスの宗教改革は、ドイツの宗教改革とどのように異なっていたか説明せよ。", "a": "ドイツの宗教改革がルターの信仰上の主張から始まったのに対し、イギリスでは国王【ヘンリ8世】が王妃との離婚を教皇に認められなかったことをきっかけに、1534年に【国王至上法】を出してローマ教会から独立した。こうして国王を首長とする【イギリス国教会】が成立した。その後【エリザベス1世】の統一法で国教会体制が確立した。"},
  {"id": "whx315", "s": "wh", "lv": 2, "topic": "主権国家体制", "q": "16〜17世紀のヨーロッパで形成された主権国家体制とはどのようなものか説明せよ。", "a": "【主権国家】とは、明確な国境をもつ領域を、他の権力に干渉されずに統治する国家である。イタリア戦争などを通じて、各国は【常備軍】や官僚制を整え、国家間では常駐の外交使節を置き、【勢力均衡】を図った。1648年の【ウェストファリア条約】はこの主権国家体制を確立したとされる。"},
  {"id": "whx316", "s": "wh", "lv": 1, "topic": "東インド会社", "q": "17世紀にイギリスやオランダが設立した東インド会社の特徴について説明せよ。", "a": "1600年にイギリス、1602年にオランダが【東インド会社】を設立し、アジアとの貿易を独占する【特許状】を国家から与えられた。オランダ東インド会社は【株式会社】の先駆とされ、ジャワ島の【バタヴィア】を拠点に香辛料貿易を支配した。東インド会社は条約の締結や軍隊の保持などの国家的な権限ももった。"},
  {"id": "whx317", "s": "wh", "lv": 2, "topic": "アンボイナ事件", "q": "1623年のアンボイナ事件は、イギリスのアジア進出にどのような影響を与えたか説明せよ。", "a": "モルッカ諸島の【アンボイナ島】で、オランダがイギリス商館員らを殺害した事件である。これにより、イギリスは香辛料の産地である【東南アジア】の島々から後退し、【インド】経営に重点を移した。オランダは香辛料貿易を独占し、イギリスは綿織物の取引などで勢力を伸ばし、のちのイギリスの【インド支配】につながった。"},
  {"id": "whx318", "s": "wh", "lv": 2, "topic": "英蘭戦争", "q": "17世紀の英蘭戦争の原因と、その結果について説明せよ。", "a": "イギリスは1651年に【航海法】を制定し、イギリスとの貿易からオランダの【中継貿易】を排除しようとした。これをきっかけに3次にわたる【英蘭戦争】が起こった。イギリスは北アメリカのオランダ領ニューアムステルダムを奪い、【ニューヨーク】と改称した。オランダは海上覇権を失い、イギリスが【海洋覇権】を握る道が開かれた。"},
  {"id": "whx319", "s": "wh", "lv": 1, "topic": "プロイセンの台頭", "q": "18世紀にプロイセンが強国へと成長した理由について説明せよ。", "a": "プロイセンは、【ユンカー】と呼ばれる地主貴族を将校や官僚に登用し、強力な【常備軍】と官僚制を整えた。【フリードリヒ2世】は啓蒙専制君主として改革を進め、【オーストリア継承戦争】と七年戦争で【シュレジエン】を獲得・確保して、ヨーロッパの強国となった。"},
  {"id": "whx320", "s": "wh", "lv": 3, "topic": "外交革命", "q": "18世紀半ばの外交革命とは何か。その背景とあわせて説明せよ。", "a": "【オーストリア継承戦争】でシュレジエンをプロイセンに奪われたオーストリアの【マリア=テレジア】は、その奪還をめざした。そこで、長年敵対してきた【フランス】と同盟を結んだ。これを【外交革命】という。これに対しプロイセンはイギリスと結び、1756年に【七年戦争】が始まった。"},
  {"id": "whx321", "s": "wh", "lv": 1, "topic": "ポーランド分割", "q": "18世紀後半のポーランド分割について、その経過と背景を説明せよ。", "a": "ポーランドは【選挙王制】のもとで貴族が対立し、国力が弱まっていた。1772年、【ロシア】・プロイセン・オーストリアの3国が第1回ポーランド分割を行った。ポーランドでは【コシューシコ】らが抵抗したが、1795年の第3回分割で国家は【消滅】した。"},
  {"id": "whx322", "s": "wh", "lv": 2, "topic": "ネルチンスク条約", "q": "1689年のネルチンスク条約の内容と、その意義について説明せよ。", "a": "17世紀、ロシアはシベリアに進出し、【黒竜江】（アムール川）流域で清と衝突した。1689年、ロシアの【ピョートル1世】と清の【康熙帝】のもとで【ネルチンスク条約】が結ばれ、両国の国境が定められ、通商も規定された。これは清が外国と【対等】な形式で結んだ最初の条約とされ、【イエズス会】士が通訳として関わった。"},
  {"id": "whx323", "s": "wh", "lv": 1, "topic": "議院内閣制の成立", "q": "18世紀前半のイギリスで議院内閣制が成立した経緯について説明せよ。", "a": "1714年、【ハノーヴァー朝】が成立すると、ドイツ出身の国王ジョージ1世は英語が話せず、政治を内閣に任せた。【ウォルポール】は首相として、議会の多数党が内閣を組織し、内閣が国王ではなく【議会】に対して責任を負う慣行をつくった（【責任内閣制】）。こうして「国王は君臨すれども統治せず」の原則が確立した。"},
  {"id": "whx324", "s": "wh", "lv": 2, "topic": "社会契約説と市民革命", "q": "17〜18世紀の社会契約説について、ホッブズ・ロック・ルソーの主張を比較して説明せよ。", "a": "【ホッブズ】は、自然状態は「万人の万人に対する闘争」であるとし、人々は契約により絶対的な主権者に権利をゆだねるべきだとした。【ロック】は、人民が政府に信託した自然権を政府が侵害する場合には【抵抗権】を行使できると説き、名誉革命やアメリカ独立に影響を与えた。【ルソー】は【人民主権】を唱え、フランス革命に影響を与えた。"},
  {"id": "whx325", "s": "wh", "lv": 1, "topic": "古典派経済学", "q": "アダム=スミスの経済思想の特徴について説明せよ。", "a": "18世紀、イギリスの【アダム=スミス】は『【諸国民の富】』（国富論）を著し、国家の富は労働によって生み出されると考えた。そして、個人の自由な経済活動にまかせれば、「見えざる手」によって社会全体の富が増大すると説き、国家の介入を批判する【自由放任主義】を主張した。これは【重商主義】の批判であり、古典派経済学の基礎となった。"},
  {"id": "whx326", "s": "wh", "lv": 3, "topic": "財政革命", "q": "名誉革命後のイギリスで進んだ財政革命は、イギリスが覇権を握るうえでどのような意味をもったか説明せよ。", "a": "名誉革命後のイギリスでは、1694年に【イングランド銀行】が設立され、議会が保証する【国債】制度が整えられた。議会の承認による課税と国債の発行によって、政府は低い利率で巨額の資金を調達できるようになった。これを【財政革命】という。これによりイギリスは、【フランス】との一連の戦争に必要な【戦費】をまかない、勝利を収めることができた。"},
  {"id": "whx327", "s": "wh", "lv": 3, "topic": "ジェントリ", "q": "イギリスのジェントリとはどのような階層か。近世イギリスの政治と社会における役割を説明せよ。", "a": "【ジェントリ】は、貴族の下に位置する地主層で、【郷紳】とも呼ばれる。修道院解散などを機に土地を拡大し、【治安判事】として地方行政を無給で担った。また【下院】の議員として議会で大きな力をもち、ピューリタン革命や名誉革命でも重要な役割を果たした。彼らは【農業革命】の担い手ともなった。"},
  {"id": "whx328", "s": "wh", "lv": 2, "topic": "アムステルダムの繁栄", "q": "17世紀にオランダのアムステルダムが国際経済の中心となった理由について説明せよ。", "a": "独立したオランダは、【バルト海】貿易での穀物・木材の取引や、ニシン漁業、造船業で繁栄した。さらに【東インド会社】を通じてアジアとの貿易を握った。【アムステルダム】には各地の商品と資本が集まり、為替銀行や取引所が整えられて、国際的な【金融】の中心となった。また宗教的な【寛容】も商人や学者を引き寄せた。"},
  {"id": "whx329", "s": "wh", "lv": 2, "topic": "合衆国憲法", "q": "1787年に制定されたアメリカ合衆国憲法の特徴について説明せよ。", "a": "独立後の13州は緩やかな連合にとどまっていたが、1787年の憲法制定会議で【合衆国憲法】が制定された。【人民主権】を基本とし、州に自治を認めつつ中央政府の権限を強める【連邦主義】をとった。また立法・行政・司法の【三権分立】を明確に定め、初代大統領には【ワシントン】が選ばれた。"},
  {"id": "whx330", "s": "wh", "lv": 2, "topic": "ジャクソニアン=デモクラシー", "q": "ジャクソン大統領の時代のアメリカの民主主義の特徴と、その限界について説明せよ。", "a": "西部出身の【ジャクソン】大統領の時代、多くの州で財産による選挙権の制限が撤廃され、白人男性の【普通選挙】が広まった。民主主義の進展は【ジャクソニアン=デモクラシー】と呼ばれた。しかし一方で、1830年の【先住民強制移住法】によって先住民はミシシッピ川以西に移住させられ、【黒人奴隷制】も維持された。"},
  {"id": "whx331", "s": "wh", "lv": 1, "topic": "七月革命", "q": "1830年の七月革命の原因と、その影響について説明せよ。", "a": "王政復古後のフランスで、国王【シャルル10世】は議会を解散するなど反動的な政治を行った。これに対しパリの民衆が蜂起して【七月革命】が起こり、自由主義者の【ルイ=フィリップ】が国王となって七月王政が成立した。この影響で【ベルギー】がオランダから独立し、ポーランドなどでも反乱が起こり、ウィーン体制は動揺した。"},
  {"id": "whx332", "s": "wh", "lv": 2, "topic": "ギリシア独立戦争", "q": "ギリシア独立戦争にヨーロッパ列強が介入した理由と、その結果について説明せよ。", "a": "1821年、ギリシアは【オスマン帝国】からの独立戦争を起こした。ヨーロッパでは古代ギリシアへのあこがれから支援の声が高まり、詩人の【バイロン】も参加した。イギリス・フランス・【ロシア】は、オスマン帝国の弱体化と自国の勢力拡大をねらって介入し、1830年にギリシアの独立が承認された。これは【ウィーン体制】の動揺を示した。"},
  {"id": "whx333", "s": "wh", "lv": 1, "topic": "チャーティスト運動", "q": "イギリスのチャーティスト運動の目的と、その意義について説明せよ。", "a": "1832年の第1回【選挙法改正】で選挙権を得たのは主に産業資本家で、【労働者】は選挙権を得られなかった。そこで労働者は男性普通選挙や【秘密投票】などを求める【人民憲章】を掲げてチャーティスト運動を展開した。運動自体は失敗したが、その要求の多くはのちの【選挙法改正】で実現した。"},
  {"id": "whx334", "s": "wh", "lv": 2, "topic": "ナポレオン3世の第二帝政", "q": "ナポレオン3世の第二帝政の政治の特徴と、その崩壊について説明せよ。", "a": "二月革命後、大統領となったルイ=ナポレオンは、1852年に皇帝【ナポレオン3世】となった。彼は資本家・農民・労働者の対立の上に立ち、【人気取り政策】で支持を集めた。パリの改造を行い、クリミア戦争や【メキシコ出兵】など対外的な威信を求めたが、メキシコ出兵は失敗した。1870年の【プロイセン=フランス戦争】で捕虜となり、帝政は崩壊した。"},
  {"id": "whx335", "s": "wh", "lv": 2, "topic": "パリ=コミューン", "q": "1871年のパリ=コミューンとはどのようなものか説明せよ。", "a": "プロイセン=フランス戦争に敗れた後、臨時政府がドイツと屈辱的な講和を結ぼうとしたことに反発し、パリの民衆が蜂起して【パリ=コミューン】を樹立した。これは【労働者】を中心とする世界初の自治政府とされる。しかし臨時政府の【ティエール】の軍隊によって約2か月で鎮圧され、多くの犠牲者を出した。その後【第三共和政】が確立した。"},
  {"id": "whx336", "s": "wh", "lv": 2, "topic": "ドイツ関税同盟", "q": "1834年に発足したドイツ関税同盟は、ドイツ統一にどのような役割を果たしたか説明せよ。", "a": "ウィーン会議後のドイツは、多くの領邦に分かれ、関税が経済発展の妨げとなっていた。【プロイセン】を中心に1834年、【ドイツ関税同盟】が発足し、加盟国間の関税を撤廃した。これにより経済的な統一が進み、【オーストリア】を除いたプロイセン主導の【小ドイツ主義】的な統一の経済的基盤となった。経済学者【リスト】は保護関税を主張した。"},
  {"id": "whx337", "s": "wh", "lv": 2, "topic": "オーストリア=ハンガリー帝国", "q": "1867年にオーストリア=ハンガリー帝国が成立した背景と、その特徴について説明せよ。", "a": "1866年の【プロイセン=オーストリア戦争】に敗れたオーストリアは、ドイツ統一から排除された。帝国内の民族運動に対処するため、オーストリアは【マジャール人】と妥協し、ハンガリー王国を認めて同君連合の【オーストリア=ハンガリー帝国】（二重帝国）を成立させた。しかしスラヴ系の民族は不満を強め、【民族問題】は解決されなかった。"},
  {"id": "whx338", "s": "wh", "lv": 2, "topic": "ナロードニキ", "q": "19世紀後半のロシアのナロードニキ運動について、その主張と結末を説明せよ。", "a": "農奴解放後も農民の生活は改善されず、都市の【インテリゲンツィア】（知識人）は、農村共同体（【ミール】）を基礎に社会主義を実現しようと「【ヴ=ナロード】」（人民の中へ）を唱えて農村に入った。しかし農民の支持を得られずに挫折し、一部は【テロリズム】に走って、1881年に皇帝【アレクサンドル2世】を暗殺した。"},
  {"id": "whx339", "s": "wh", "lv": 2, "topic": "再建期", "q": "南北戦争後のアメリカ南部の再建期について、黒人の地位の変化に着目して説明せよ。", "a": "南北戦争後、憲法修正によって【奴隷制】は廃止され、黒人に市民権と選挙権が認められた。しかし南部では土地を得られなかった黒人の多くが【シェアクロッパー】（分益小作人）となった。再建期が終わると、南部諸州は【人種隔離】を定める州法などで黒人を差別し、投票権も事実上奪った。また【KKK】などの白人至上主義団体が黒人を迫害した。"},
  {"id": "whx340", "s": "wh", "lv": 2, "topic": "フロンティアの消滅", "q": "19世紀後半のアメリカ西部開拓の進展と、フロンティアの消滅が持つ意味を説明せよ。", "a": "1862年の【ホームステッド法】は西部の公有地を開拓者に無償で与え、1869年には【大陸横断鉄道】が開通して西部開拓が進んだ。その過程で先住民は土地を奪われ、居留地に追いやられた。1890年に国勢調査局は【フロンティア】の消滅を宣言した。その後アメリカは、市場を求めて【海外進出】へと向かった。"},
  {"id": "whx341", "s": "wh", "lv": 2, "topic": "新移民", "q": "19世紀末以降のアメリカの「新移民」とはどのような人々か。アメリカ社会に与えた影響とあわせて説明せよ。", "a": "19世紀末から、【東欧】や【南欧】からの移民が急増し、それ以前の西欧・北欧系の移民と区別して【新移民】と呼ばれた。彼らはカトリック教徒やユダヤ教徒が多く、都市で低賃金の【労働者】として工業化を支えたが、差別も受けた。また中国人や日本人などアジア系の移民に対しては【移民排斥】の動きが強まった。"},
  {"id": "whx342", "s": "wh", "lv": 1, "topic": "第2次産業革命", "q": "19世紀後半の第2次産業革命の特徴について説明せよ。", "a": "19世紀後半、【石油】と【電力】を新たな動力源とし、重化学工業を中心とする第2次産業革命が進んだ。この技術革新は大規模な設備と資金を必要としたため、【独占資本】が形成された。【アメリカ】と【ドイツ】がその中心となって急速に工業化し、イギリスの地位は相対的に低下した。"},
  {"id": "whx343", "s": "wh", "lv": 2, "topic": "インターナショナル", "q": "19世紀の国際的な労働運動組織である第1インターナショナルと第2インターナショナルについて説明せよ。", "a": "1864年、【マルクス】の指導のもとロンドンで【第1インターナショナル】が結成されたが、内部対立とパリ=コミューン後の弾圧で解散した。1889年には【パリ】で第2インターナショナルが結成され、ドイツ社会民主党が中心となった。しかし第一次世界大戦が起こると、各国の社会主義政党が自国の戦争を支持したため、【崩壊】した。"},
  {"id": "whx344", "s": "wh", "lv": 1, "topic": "進化論", "q": "ダーウィンの進化論は、19世紀の社会や思想にどのような影響を与えたか説明せよ。", "a": "1859年、【ダーウィン】は『【種の起源】』を著し、生物は【自然選択】（自然淘汰）によって進化すると主張した。これはキリスト教の神による創造説と対立し、大きな論争を引き起こした。また進化論を人間社会に当てはめた【社会進化論】が広まり、帝国主義や人種主義を正当化する根拠ともされた。"},
  {"id": "whx345", "s": "wh", "lv": 1, "topic": "ロマン主義", "q": "19世紀前半のヨーロッパで広まったロマン主義の特徴について説明せよ。", "a": "19世紀前半、理性を重んじる【啓蒙思想】や古典主義への反発から、人間の【感情】や個性、想像力を重んじるロマン主義が広まった。ロマン主義は各民族の歴史や伝統、【民族文化】を重視したため、【ナショナリズム】の高まりとも結びついた。ドイツの【グリム兄弟】による民話の収集などはその例である。"},
  {"id": "whx346", "s": "wh", "lv": 2, "topic": "スエズ運河株買収", "q": "イギリスがスエズ運河会社の株を買収した経緯と、その後のエジプトとの関係について説明せよ。", "a": "1869年にフランス人【レセップス】によってスエズ運河が開通した。1875年、財政難に陥ったエジプトが運河会社の株を売りに出すと、イギリス首相【ディズレーリ】は【ロスチャイルド】家の融資を得てこれを買収した。これによりイギリスは【インド】への最短ルートを確保し、エジプトの財政に介入して、のちのエジプトの【保護国化】につながった。"},
  {"id": "whx347", "s": "wh", "lv": 2, "topic": "ウラービー運動", "q": "1881年にエジプトで起こったウラービー運動の背景と、その結果について説明せよ。", "a": "エジプトは運河建設などで巨額の債務を負い、財政は【イギリス】・フランスに管理された。これに反発した軍人【ウラービー】は「エジプト人のためのエジプト」を掲げ、立憲制の樹立と外国支配からの脱却を求めて運動を起こした。しかしイギリスが軍事介入してこれを鎮圧し、エジプトを事実上の【保護国】とした。"},
  {"id": "whx348", "s": "wh", "lv": 1, "topic": "ファショダ事件", "q": "1898年のファショダ事件の背景と、その結果について説明せよ。", "a": "イギリスはエジプトのカイロと南アフリカの【ケープタウン】を結ぶ【縦断政策】を、フランスはアルジェリアからサハラ砂漠を経てジブチ・マダガスカルを結ぶ【横断政策】を進めた。1898年、両国軍がスーダンの【ファショダ】で衝突しそうになったが、フランスが譲歩した。その後両国は接近し、1904年に【英仏協商】を結んだ。"},
  {"id": "whx349", "s": "wh", "lv": 2, "topic": "モロッコ事件", "q": "20世紀初めの二度のモロッコ事件は、ヨーロッパの国際関係にどのような影響を与えたか説明せよ。", "a": "【英仏協商】でフランスのモロッコでの優越が認められると、ドイツの【ヴィルヘルム2世】は1905年にタンジールを訪問してこれに挑戦し、1911年にはアガディールに軍艦を派遣した。しかしいずれもドイツは国際的に孤立し、フランスはモロッコを【保護国】化した。この事件は【英仏】の結束を強め、ドイツの孤立を深めた。"},
  {"id": "whx350", "s": "wh", "lv": 1, "topic": "3B政策と3C政策", "q": "ドイツの3B政策とイギリスの3C政策の内容と、両国の対立について説明せよ。", "a": "ドイツは、ベルリン・【ビザンティウム】（イスタンブル）・バグダードを結ぶ【バグダード鉄道】の建設をめざし、西アジアへの進出を図った（3B政策）。これはカイロ・ケープタウン・【カルカッタ】を結ぶイギリスの【3C政策】と対立した。この対立は、両国の建艦競争とともに、第一次世界大戦の一因となった。"},
  {"id": "whx351", "s": "wh", "lv": 1, "topic": "三国協商の成立", "q": "20世紀初めに三国協商が成立した経緯を説明せよ。", "a": "ドイツの積極的な世界政策に対抗するため、イギリスは「光栄ある孤立」を捨てて1902年に【日英同盟】を結び、1904年にフランスと【英仏協商】を結んだ。1907年には、日露戦争で敗れたロシアと【英露協商】を結んだ。すでに1890年代に成立していた【露仏同盟】とあわせて三国協商が成立し、ドイツ・オーストリア・イタリアの三国同盟と対立した。"},
  {"id": "whx352", "s": "wh", "lv": 2, "topic": "バルカン問題", "q": "20世紀初めのバルカン半島が「ヨーロッパの火薬庫」と呼ばれた理由を説明せよ。", "a": "1908年、オーストリアが【ボスニア・ヘルツェゴヴィナ】を併合し、スラヴ系の【セルビア】が強く反発した。ロシアは【パン=スラヴ主義】を掲げてセルビアを支援し、ドイツとオーストリアは【パン=ゲルマン主義】をとって対立した。さらに2度の【バルカン戦争】でバルカン諸国間の対立も深まり、大国の利害が絡み合う一触即発の状態となった。"},
  {"id": "whx353", "s": "wh", "lv": 1, "topic": "アメリカ=スペイン戦争", "q": "1898年のアメリカ=スペイン戦争の結果、アメリカの対外政策はどのように変化したか説明せよ。", "a": "キューバの独立運動を機に、アメリカは【スペイン】と戦って勝利した。アメリカは【フィリピン】・グアム・プエルトリコを獲得し、キューバを事実上の保護国とした。同年には【ハワイ】も併合した。これによりアメリカは太平洋・カリブ海に進出し、本格的な【帝国主義】政策へと転じた。"},
  {"id": "whx354", "s": "wh", "lv": 1, "topic": "門戸開放宣言", "q": "アメリカが中国について門戸開放宣言を出した背景と、その内容を説明せよ。", "a": "列強が中国で租借地や【勢力範囲】を設定して中国分割を進める中、中国進出に出遅れたアメリカは、1899年と1900年に国務長官【ジョン=ヘイ】の名で宣言を出した。中国の【門戸開放】・【機会均等】・領土保全を主張し、列強の独占的な支配を牽制して、アメリカの中国市場への進出を図った。"},
  {"id": "whx355", "s": "wh", "lv": 3, "topic": "太平洋分割", "q": "19世紀後半から20世紀初めにかけての太平洋地域の分割について説明せよ。", "a": "19世紀後半から列強は太平洋の島々の領有を進めた。【イギリス】はオーストラリアやニュージーランド、フィジーなどを支配した。【ドイツ】は一部のニューギニアやビスマルク諸島、マーシャル諸島などを得た。【アメリカ】はハワイを併合し、米西戦争でグアムなどを得た。フランスはタヒチなどを支配した。島々は【捕鯨】や貿易・海軍の拠点として重視された。"},
  {"id": "whx356", "s": "wh", "lv": 2, "topic": "インド国民会議", "q": "インド国民会議の性格は、成立当初からどのように変化したか説明せよ。", "a": "1885年、イギリスはインド人の不満をそらすため、エリート層を集めて【インド国民会議】を開いた。当初は【親英的】な性格であった。しかし1905年の【ベンガル分割令】に反発し、1906年のカルカッタ大会では【ティラク】らが主導して、英貨排斥・【スワデーシ】・スワラージ・民族教育の4綱領を採択し、反英的な民族運動の中心となった。"},
  {"id": "whx357", "s": "wh", "lv": 2, "topic": "清仏戦争", "q": "清仏戦争の原因と、その結果について説明せよ。", "a": "フランスはベトナムへの進出を進め、ベトナムの宗主国である清と対立した。ベトナムでは【劉永福】の【黒旗軍】がフランスに抵抗した。1884年に清仏戦争が起こり、1885年の【天津条約】で清はベトナムに対する宗主権を放棄した。フランスは1887年に、ベトナムとカンボジアをあわせて【フランス領インドシナ連邦】を成立させた。"},
  {"id": "whx358", "s": "wh", "lv": 3, "topic": "ワッハーブ派", "q": "18世紀のアラビア半島で起こったワッハーブ派の運動の特徴とその意義について説明せよ。", "a": "18世紀半ば、【イブン=アブドゥル=ワッハーブ】は、イスラームが神秘主義などで本来の姿を失ったと批判し、ムハンマドの時代の【純粋なイスラーム】への回帰を説いた。この運動は豪族【サウード家】と結んで【ワッハーブ王国】を建て、オスマン帝国の支配に挑戦した。アラブ人の民族的自覚をうながし、のちの【サウジアラビア】につながった。"},
  {"id": "whx359", "s": "wh", "lv": 2, "topic": "ミドハト憲法", "q": "1876年のオスマン帝国憲法（ミドハト憲法）の制定と、その停止について説明せよ。", "a": "タンジマートの後、オスマン帝国では立憲制を求める動きが高まり、1876年に宰相【ミドハト=パシャ】が起草した憲法が発布された。アジアで最初の憲法とされ、【議会】の開設などを定めた。しかしスルタン【アブデュルハミト2世】は、1877年の【ロシア=トルコ戦争】の勃発を理由に議会を閉鎖し、憲法を停止して専制政治を行った。"},
  {"id": "whx360", "s": "wh", "lv": 3, "topic": "グレート=ゲーム", "q": "19世紀の中央アジアにおけるイギリスとロシアの対立（グレート=ゲーム）について説明せよ。", "a": "19世紀、ロシアは南下政策を進め、中央アジアの【ブハラ=ハン国】やヒヴァ=ハン国を保護国化し、コーカンド=ハン国を併合した。これに対し、【インド】を支配するイギリスは警戒を強め、2次にわたる【アフガン戦争】でアフガニスタンを保護国とした。この英露の勢力争いは、1907年の【英露協商】で、イラン・アフガニスタンなどの【勢力範囲】を定めることで一応の決着をみた。"},
  {"id": "whx361", "s": "wh", "lv": 1, "topic": "総力戦", "q": "第一次世界大戦が総力戦となったことは、各国の社会にどのような変化をもたらしたか説明せよ。", "a": "第一次世界大戦は長期化し、各国は軍隊だけでなく、経済や国民生活のすべてを戦争に動員する【総力戦】体制をとった。政府は経済を統制し、【挙国一致】体制をつくった。男性が戦場に行くと【女性】が工場などで働き、戦後に女性の地位が向上して多くの国で【女性参政権】が認められた。"},
  {"id": "whx362", "s": "wh", "lv": 1, "topic": "十四か条", "q": "アメリカのウィルソン大統領が発表した十四か条の平和原則の内容と、その影響を説明せよ。", "a": "1918年、アメリカ大統領【ウィルソン】は【十四か条】の平和原則を発表した。秘密外交の廃止、海洋の自由、軍備縮小、【民族自決】、【国際平和機構】の設立などを掲げた。これは戦後の講和の基礎となったが、民族自決は主に【東ヨーロッパ】に適用され、アジア・アフリカの植民地には適用されなかった。"},
  {"id": "whx363", "s": "wh", "lv": 2, "topic": "ドイツ革命", "q": "1918年のドイツ革命の経過と、その結果について説明せよ。", "a": "第一次世界大戦末期の1918年11月、【キール軍港】の水兵の反乱をきっかけに革命が全国に広がった。皇帝【ヴィルヘルム2世】は退位してオランダに亡命し、社会民主党を中心とする臨時政府が成立して【休戦協定】に調印した。翌年には共産党の【スパルタクス団】の蜂起が鎮圧され、ヴァイマル憲法が制定された。"},
  {"id": "whx364", "s": "wh", "lv": 2, "topic": "ドイツ賠償問題", "q": "第一次世界大戦後のドイツの賠償問題はどのように推移したか説明せよ。", "a": "ドイツは巨額の賠償金を課されたが、支払いが滞ったため、1923年にフランスとベルギーが【ルール地方】を占領した。ドイツでは激しい【インフレーション】が起こった。1924年の【ドーズ案】でアメリカの資本がドイツに貸し付けられ、賠償の支払いが緩和された。1929年の【ヤング案】で賠償額はさらに減額されたが、世界恐慌でその支払いは事実上停止された。"},
  {"id": "whx365", "s": "wh", "lv": 2, "topic": "ロカルノ条約", "q": "1925年のロカルノ条約の内容と、その意義について説明せよ。", "a": "ドイツの外相【シュトレーゼマン】やフランスの外相【ブリアン】らの協調外交によって、1925年に【ロカルノ条約】が結ばれた。ドイツと周辺諸国の国境の現状維持や、ラインラントの非武装化などが確認された。これにより西ヨーロッパの緊張が緩和され、翌1926年にはドイツの【国際連盟】加盟が実現した。"},
  {"id": "whx366", "s": "wh", "lv": 1, "topic": "不戦条約", "q": "1928年の不戦条約の内容と、その限界について説明せよ。", "a": "1928年、アメリカ国務長官の【ケロッグ】とフランス外相の【ブリアン】の提唱により、パリで【不戦条約】が結ばれた。国際紛争を解決する手段としての【戦争】を放棄することを約束し、のちに多くの国が参加した。しかし違反した場合の【制裁】規定がなく、自衛のための戦争は認められるとされたため、実効性は乏しかった。"},
  {"id": "whx367", "s": "wh", "lv": 1, "topic": "1920年代のアメリカ", "q": "1920年代のアメリカで大衆消費社会が成立した背景と、その特徴を説明せよ。", "a": "第一次世界大戦後、アメリカは【債権国】となり、世界経済の中心となった。自動車の【大量生産】方式が確立し、自動車や家庭電化製品が普及し、ラジオや映画などの【大衆文化】が広まった。一方で、【禁酒法】の施行や移民の制限など、保守的な傾向もみられた。1929年の株価暴落で繁栄は終わりを告げた。"},
  {"id": "whx368", "s": "wh", "lv": 1, "topic": "世界恐慌", "q": "1929年に始まった世界恐慌が世界に広がった理由と、その影響を説明せよ。", "a": "1929年10月、ニューヨークの【ウォール街】で株価が大暴落し、アメリカで恐慌が起こった。アメリカは世界経済の中心であり、ヨーロッパに貸し付けていた【資本】を引き上げたため、恐慌は【世界】に広がった。各国では工業生産の減少と大量の【失業者】が生まれ、【ファシズム】の台頭など国際政治に大きな影響を与えた。"},
  {"id": "whx369", "s": "wh", "lv": 2, "topic": "人民戦線", "q": "1930年代に各国で人民戦線が結成された背景と、フランスの例について説明せよ。", "a": "ドイツでナチスが政権を握ると、ファシズムの脅威に対抗するため、1935年に【コミンテルン】は社会民主主義者などとの協力をよびかけた。これに応じて各国で反ファシズムの【人民戦線】が結成された。フランスでは1936年に社会党の【ブルム】を首相とする人民戦線内閣が成立し、週40時間労働制や【有給休暇】などを実現した。"},
  {"id": "whx370", "s": "wh", "lv": 1, "topic": "スペイン内戦", "q": "1936年に始まったスペイン内戦の経過と、その国際的な意味について説明せよ。", "a": "1936年、スペインで人民戦線政府が成立すると、【フランコ】将軍が反乱を起こし、【スペイン内戦】が始まった。【ドイツ】とイタリアはフランコを支援し、ソ連は政府側を支援した。イギリス・フランスは【不干渉政策】をとったが、各国から【国際義勇軍】が政府側に参加した。1939年にフランコ側が勝利した。"},
  {"id": "whx371", "s": "wh", "lv": 2, "topic": "独ソ不可侵条約", "q": "1939年の独ソ不可侵条約が結ばれた背景と、その結果について説明せよ。", "a": "【ミュンヘン会談】でイギリス・フランスがドイツに譲歩すると、ソ連は英仏への不信を強めた。一方、ドイツは東西二正面作戦を避けたかった。1939年8月、敵対していた両国は【独ソ不可侵条約】を結び、世界を驚かせた。その秘密議定書でポーランドなどの分割が定められ、同年9月にドイツが【ポーランド】に侵攻して【第二次世界大戦】が始まった。"},
  {"id": "whx372", "s": "wh", "lv": 2, "topic": "ホロコースト", "q": "ナチス=ドイツによるユダヤ人迫害（ホロコースト）はどのように進められたか説明せよ。", "a": "ナチ党は【人種主義】的な思想に基づき、政権獲得後ユダヤ人の公職追放を進め、1935年の【ニュルンベルク法】でユダヤ人の市民権を奪った。第二次世界大戦が始まると、占領地のユダヤ人を各地に隔離し、【アウシュヴィッツ】などの【強制収容所】に送って大量に殺害した。犠牲者は約600万人にのぼったとされる。"},
  {"id": "whx373", "s": "wh", "lv": 2, "topic": "ウェストミンスター憲章", "q": "1931年のウェストミンスター憲章によって、イギリス帝国はどのように変化したか説明せよ。", "a": "第一次世界大戦に協力したカナダや【オーストラリア】などの自治領は、本国と対等な地位を求めるようになった。1931年の【ウェストミンスター憲章】で、自治領は本国と対等な地位を認められ、イギリス国王への忠誠で結ばれた【イギリス連邦】が成立した。世界恐慌後には連邦内で【スターリング=ブロック】が形成された。"},
  {"id": "whx374", "s": "wh", "lv": 2, "topic": "北伐", "q": "1926年に始まった国民革命軍の北伐の経過と、その結果について説明せよ。", "a": "孫文の死後、国民党の【蔣介石】は1926年に国民革命軍を率いて北方の【軍閥】の打倒をめざし、【北伐】を開始した。北伐中の1927年、蔣介石は上海で共産党を弾圧する【上海クーデタ】を起こし、南京に国民政府を建てた。1928年には北京に入り、張作霖の子の張学良も国民政府に合流して、【中国統一】がほぼ達成された。"},
  {"id": "whx375", "s": "wh", "lv": 2, "topic": "西安事件", "q": "1936年の西安事件は、中国の抗日戦争にどのような影響を与えたか説明せよ。", "a": "蔣介石は満州事変後も「安内攘外」を掲げて共産党の打倒を優先し、共産党は【長征】を行って延安に拠点を移した。共産党は1935年に【八・一宣言】で内戦停止と抗日を呼びかけた。1936年、【張学良】は西安で蔣介石を監禁して内戦停止を要求した（【西安事件】）。これをきっかけに翌年【第2次国共合作】が成立し、抗日民族統一戦線が形成された。"},
  {"id": "whx376", "s": "wh", "lv": 3, "topic": "エジプトの独立", "q": "第一次世界大戦後のエジプトの独立は、どのような点で不完全なものであったか説明せよ。", "a": "第一次世界大戦中、エジプトはイギリスの正式な【保護国】とされた。戦後、【ワフド党】を中心とする独立運動が高まり、1922年にイギリスはエジプトの独立を認めた。しかし、イギリスは【スエズ運河】の支配権や軍隊の駐留権を保持したため、独立は形式的なものであった。完全な独立は、1952年の【エジプト革命】を経て実現に向かった。"},
  {"id": "whx377", "s": "wh", "lv": 2, "topic": "パフレヴィー朝", "q": "1925年にイランで成立したパフレヴィー朝の政策について説明せよ。", "a": "第一次世界大戦後、イランでは軍人の【レザー=ハーン】がクーデタで実権を握り、1925年に【カージャール朝】を廃して【パフレヴィー朝】を開いた。彼はトルコの改革にならって、近代化政策を進め、1935年に国号をペルシアから【イラン】に改めた。しかし石油利権はイギリスに握られたままであった。"},
  {"id": "whx378", "s": "wh", "lv": 2, "topic": "インドネシアの民族運動", "q": "20世紀前半のインドネシアにおける民族運動の展開について説明せよ。", "a": "オランダの支配に対し、20世紀初めにイスラーム同盟（【サレカット=イスラーム】）が結成され、民族運動が大衆化した。1920年には【インドネシア共産党】が結成されたが、蜂起に失敗して弾圧された。1927年には【スカルノ】が【インドネシア国民党】を結成し、完全独立を掲げたが、オランダに弾圧された。"},
  {"id": "whx379", "s": "wh", "lv": 2, "topic": "ベトナムの民族運動", "q": "20世紀前半のベトナムにおける民族運動の展開を、ホー=チ=ミンの活動を中心に説明せよ。", "a": "フランスの支配下で、20世紀初めには日本への留学をすすめる【ドンズー運動】が起こったが、弾圧された。第一次世界大戦後、【ホー=チ=ミン】は1925年にベトナム青年革命同志会を結成し、1930年にはこれを母体に【インドシナ共産党】を結成した。第二次世界大戦中の1941年には【ベトナム独立同盟】（ベトミン）を組織して、日本とフランスに抵抗した。"},
  {"id": "whx380", "s": "wh", "lv": 2, "topic": "善隣外交", "q": "1930年代にアメリカのフランクリン=ローズヴェルト大統領が進めた善隣外交について説明せよ。", "a": "それまでアメリカは、ラテンアメリカ諸国に対して武力干渉を伴う【カリブ海政策】をとっていた。【フランクリン=ローズヴェルト】大統領は【善隣外交】を掲げ、キューバの保護国化を定めた【プラット条項】を廃止するなど、内政干渉を控えた。これはラテンアメリカとの関係を改善し、【経済】的な結びつきを強めるためであった。"},
  {"id": "whx381", "s": "wh", "lv": 2, "topic": "ブレスト=リトフスク条約", "q": "1918年のブレスト=リトフスク条約の内容と、その意味について説明せよ。", "a": "十月革命で成立したソヴィエト政権は、【平和に関する布告】で無併合・無賠償・民族自決による講和を呼びかけた。1918年3月、ソヴィエト政権はドイツと【ブレスト=リトフスク条約】を結び、【ポーランド】やバルト地方などの広大な領土を放棄して、第一次世界大戦から離脱した。これに対し連合国は【対ソ干渉戦争】を始めた。"},
  {"id": "whx382", "s": "wh", "lv": 2, "topic": "アメリカの孤立主義", "q": "第一次世界大戦後のアメリカの外交が孤立主義に傾いた理由について説明せよ。", "a": "ウィルソン大統領は国際連盟の設立を提唱したが、アメリカ議会の【上院】は、ヨーロッパの問題に巻き込まれることを恐れて【ヴェルサイユ条約】の批准を拒否した。そのためアメリカは【国際連盟】に参加しなかった。これは【モンロー主義】以来の伝統的な孤立主義によるものであったが、ワシントン会議の開催などアジア・太平洋では積極的な外交も行った。"},
  {"id": "whx383", "s": "wh", "lv": 3, "topic": "ラテンアメリカのポピュリズム", "q": "20世紀半ばのラテンアメリカで現れたポピュリズムの特徴について、アルゼンチンの例を挙げて説明せよ。", "a": "世界恐慌で一次産品の輸出が打撃を受けたラテンアメリカでは、工業化をめざす【輸入代替工業化】が進められた。アルゼンチンの【ペロン】は、【労働者】の支持を基盤に政権を握り、賃金の引き上げや社会保障の充実、外国資本の企業の【国有化】を進めた。このような大衆の支持を基盤とする指導者による政治を【ポピュリズム】という。"},
  {"id": "whx384", "s": "wh", "lv": 3, "topic": "東欧の新興国家", "q": "第一次世界大戦後に東ヨーロッパで成立した新興国家と、それらが抱えた問題について説明せよ。", "a": "大戦後、【民族自決】の原則により、ポーランド、【チェコスロヴァキア】、セルブ=クロアート=スロヴェーン王国（のちのユーゴスラヴィア）、バルト3国などが独立した。しかし多くの国は国内に【少数民族】を抱え、国境をめぐる対立もあった。経済的にも弱く、世界恐慌後は多くの国で【権威主義】体制が成立し、やがてドイツの【膨張】の対象となった。"},
  {"id": "whx385", "s": "wh", "lv": 3, "topic": "委任統治制度", "q": "第一次世界大戦後に導入された委任統治制度とはどのようなものか。その実態とあわせて説明せよ。", "a": "大戦後、敗戦国ドイツの植民地や【オスマン帝国】のアラブ地域は、【国際連盟】から委任を受けた国が統治することになった（【委任統治】）。例えばシリアは【フランス】、イラク・パレスチナはイギリスの委任統治領となった。名目上は住民の自立を助けるためとされたが、実態は戦勝国による植民地支配の継続であり、【民族自決】は適用されなかった。"},
  {"id": "whx386", "s": "wh", "lv": 3, "topic": "第二次世界大戦の性格", "q": "第二次世界大戦は、第一次世界大戦と比べてどのような特徴をもった戦争であったか説明せよ。", "a": "第二次世界大戦は、連合国側が自らを【ファシズム】に対する民主主義の戦いと位置づけた戦争であった。航空機による【無差別爆撃】で都市が攻撃され、戦場と銃後の区別がなくなり、【民間人】の犠牲が軍人を上回った。また【ホロコースト】などの大量虐殺や、戦争末期の【原子爆弾】の使用など、人類に大きな被害をもたらした。"},
  {"id": "whx387", "s": "wh", "lv": 1, "topic": "マーシャル=プラン", "q": "1947年に発表されたマーシャル=プランの目的と、それがヨーロッパに与えた影響について説明せよ。", "a": "アメリカの国務長官【マーシャル】は、戦争で荒廃したヨーロッパの【経済復興】を援助する計画を発表した。これは西ヨーロッパの経済を立て直し、【共産主義】の拡大を防ぐことを目的としていた。ソ連と東欧諸国はこれを拒否し、対抗して【コミンフォルム】を結成したため、ヨーロッパの【東西分断】が深まった。"},
  {"id": "whx388", "s": "wh", "lv": 1, "topic": "NATOとワルシャワ条約機構", "q": "冷戦期の二つの軍事同盟、NATOとワルシャワ条約機構の成立について説明せよ。", "a": "ベルリン封鎖などで東西の緊張が高まると、1949年にアメリカと西ヨーロッパ諸国は集団防衛のため【北大西洋条約機構】（NATO）を結成した。1955年に【西ドイツ】がNATOに加盟すると、ソ連と東欧諸国は【ワルシャワ条約機構】を結成した。こうしてヨーロッパは二つの軍事ブロックに【分断】された。"},
  {"id": "whx389", "s": "wh", "lv": 1, "topic": "スターリン批判", "q": "1956年のスターリン批判の内容と、それが東欧諸国に与えた影響について説明せよ。", "a": "1956年、ソ連共産党第20回大会で【フルシチョフ】はスターリンの【個人崇拝】や粛清を批判し、資本主義国との【平和共存】を唱えた。これをきっかけに東欧諸国では自由化を求める動きが起こり、【ポーランド】では暴動が起こり、【ハンガリー】では大規模な反ソ暴動が起こった。"},
  {"id": "whx390", "s": "wh", "lv": 2, "topic": "ハンガリー事件", "q": "1956年のハンガリー事件の経過と、その意味について説明せよ。", "a": "スターリン批判をきっかけに、ハンガリーでは自由化を求める民衆の運動が起こった。首相となった【ナジ=イムレ】は複数政党制の導入や【ワルシャワ条約機構】からの脱退を表明した。これに対し【ソ連】は軍事介入して運動を鎮圧し、ナジはのちに処刑された。これはソ連が東欧に対する【支配】を維持する姿勢を示すものであった。"},
  {"id": "whx391", "s": "wh", "lv": 2, "topic": "プラハの春", "q": "1968年の「プラハの春」とはどのような動きで、どのような結末を迎えたか説明せよ。", "a": "1968年、チェコスロヴァキアで【ドプチェク】が共産党第一書記となり、言論の自由化などを進める「【人間の顔をした社会主義】」を掲げた改革を行った（プラハの春）。しかし【ソ連】はワルシャワ条約機構軍を率いて軍事介入し、改革を弾圧した。ソ連は社会主義圏全体の利益のためには一国の主権は制限されるとする【制限主権論】（ブレジネフ=ドクトリン）でこれを正当化した。"},
  {"id": "whx392", "s": "wh", "lv": 2, "topic": "中ソ対立", "q": "1950年代末から始まった中ソ対立の原因と、その展開について説明せよ。", "a": "中国は、ソ連の【スターリン批判】と平和共存政策を修正主義として批判した。1959年にソ連は中国との【国防新技術協定】を破棄し、翌年には技術者を引き揚げた。対立は社会主義の路線をめぐる論争から国家間の対立へと発展し、1969年には国境の【珍宝島】（ダマンスキー島）で武力衝突が起こった。この対立は、のちの【米中接近】の背景となった。"},
  {"id": "whx393", "s": "wh", "lv": 1, "topic": "核軍備管理", "q": "1960年代の核軍備管理の動きについて、具体的な条約を挙げて説明せよ。", "a": "【キューバ危機】で核戦争の危険が現実化したことを受け、米ソは直通通信回線（ホットライン）を設けた。1963年には米英ソが大気圏内・宇宙空間・水中での核実験を禁止する【部分的核実験禁止条約】を結んだ。1968年には核兵器保有国の増加を防ぐ【核拡散防止条約】（NPT）が調印された。しかし地下核実験は禁止されず、【フランス】・中国は当初これに加わらなかった。"},
  {"id": "whx394", "s": "wh", "lv": 2, "topic": "非同盟諸国首脳会議", "q": "1961年に始まった非同盟諸国首脳会議の目的と意義を説明せよ。", "a": "1961年、ユーゴスラヴィアの【ティトー】、エジプトの【ナセル】、インドの【ネルー】らの呼びかけで、【ベオグラード】で第1回【非同盟諸国首脳会議】が開かれた。東西いずれの陣営にも属さない国々が集まり、平和共存や反植民地主義、軍事ブロックへの不参加などを訴えた。こうした国々は【第三世界】と呼ばれ、国際政治で一定の発言力をもった。"},
  {"id": "whx395", "s": "wh", "lv": 2, "topic": "アルジェリア戦争", "q": "アルジェリア戦争はフランスの政治にどのような影響を与えたか説明せよ。", "a": "1954年、アルジェリアで【民族解放戦線】（FLN）が武装闘争を開始した。アルジェリアには多くのフランス人入植者がおり、フランスは独立を認めず戦争は泥沼化した。この混乱の中で【第四共和政】は崩壊し、1958年に【ド=ゴール】が政権に復帰して【第五共和政】が成立した。ド=ゴールは1962年に【エヴィアン協定】でアルジェリアの独立を認めた。"},
  {"id": "whx396", "s": "wh", "lv": 3, "topic": "コンゴ動乱", "q": "1960年に独立したコンゴで起こったコンゴ動乱の背景と経過を説明せよ。", "a": "1960年、コンゴは【ベルギー】から独立したが、直後に、銅などの【鉱物資源】が豊富な【カタンガ州】が旧宗主国の支援を受けて分離を宣言し、内乱となった。首相の【ルムンバ】は国連に支援を求めたが、のちに殺害された。国連は平和維持軍を派遣した。この動乱には米ソの【冷戦】や旧宗主国の利権が絡み、独立後のアフリカの困難を象徴するものとなった。"},
  {"id": "whx397", "s": "wh", "lv": 1, "topic": "公民権運動", "q": "1950〜60年代のアメリカにおける公民権運動の展開と、その成果について説明せよ。", "a": "南部では黒人に対する【人種隔離】が続いていた。1955年のバス=ボイコット運動をきっかけに、【キング牧師】の指導による非暴力の【公民権運動】が広がり、1963年にはワシントン大行進が行われた。その結果、1964年に【ジョンソン】大統領のもとで【公民権法】が成立し、人種差別が法的に禁止された。"},
  {"id": "whx398", "s": "wh", "lv": 3, "topic": "1968年の世界", "q": "1968年前後に世界各地で起こった異議申し立ての動きについて説明せよ。", "a": "1960年代後半、【ベトナム戦争】への反対を背景に、先進国では既存の体制や価値観に異議を唱える【学生運動】が高まった。フランスでは学生・労働者が大規模なストを行う【五月危機】（五月革命）が起こり、ド=ゴール退陣の一因となった。アメリカでは反戦運動や【公民権運動】が高揚し、社会主義圏でも【プラハの春】が起こるなど、各地で既存の秩序が揺らいだ。"},
  {"id": "whx399", "s": "wh", "lv": 2, "topic": "ニクソン訪中", "q": "1972年のニクソン大統領の訪中の背景と、それが国際関係に与えた影響を説明せよ。", "a": "アメリカは【ベトナム戦争】の泥沼化で行き詰まり、中国は【中ソ対立】の激化でソ連を脅威と感じていた。両国の利害が一致し、1972年に【ニクソン】大統領が訪中して米中関係は改善に向かった。前年には中華人民共和国が【国連】の代表権を獲得していた。日本も同年に【日中国交正常化】を果たし、1979年に米中は国交を樹立した。"},
  {"id": "whx400", "s": "wh", "lv": 2, "topic": "サッチャリズムとレーガノミクス", "q": "1980年代にイギリスやアメリカで進められた新自由主義的な政策について説明せよ。", "a": "1970年代の石油危機以後の不況と財政赤字を背景に、福祉国家を見直す動きが強まった。イギリスの【サッチャー】政権やアメリカの【レーガン】政権は、政府の役割を縮小する「【小さな政府】」をめざし、【規制緩和】や国営企業の【民営化】、減税などを進めた。経済の活性化に一定の成果を上げたが、所得格差の拡大などの問題も生じた。"},
  {"id": "whx401", "s": "wh", "lv": 1, "topic": "ペレストロイカ", "q": "ゴルバチョフが進めたペレストロイカの内容と、その結果について説明せよ。", "a": "1985年にソ連共産党書記長となった【ゴルバチョフ】は、経済の停滞を打開するため【ペレストロイカ】（改革）を進めた。【グラスノスチ】（情報公開）による言論の自由化も行い、外交では【新思考外交】を展開して冷戦の終結に貢献した。しかし改革は経済の混乱を招き、民族運動も高まって、1991年にソ連は【解体】した。"},
  {"id": "whx402", "s": "wh", "lv": 2, "topic": "天安門事件", "q": "1989年の天安門事件の背景と、その後の中国の政治・経済の方向性について説明せよ。", "a": "【改革開放】政策で経済は成長したが、インフレや官僚の腐敗への不満も高まった。1989年、民主化に理解を示した【胡耀邦】の死をきっかけに、北京の天安門広場で学生や市民が【民主化】を求める運動を起こした。政府は軍隊を出動させてこれを武力で鎮圧した（【天安門事件】）。その後、中国は共産党の一党支配を維持しつつ、【社会主義市場経済】のもとで経済発展を進めた。"},
  {"id": "whx403", "s": "wh", "lv": 1, "topic": "湾岸戦争", "q": "1991年の湾岸戦争の原因と経過について説明せよ。", "a": "1990年、イラクの【サダム=フセイン】政権は隣国の【クウェート】に侵攻し、併合を宣言した。国連安全保障理事会はイラクに撤退を求め、武力行使を容認した。1991年、【アメリカ】を中心とする【多国籍軍】がイラクを攻撃し、クウェートを解放した。冷戦の終結によって米ソが協調したことが、国連の機能を高めた。"},
  {"id": "whx404", "s": "wh", "lv": 2, "topic": "ユーゴスラヴィア紛争", "q": "1990年代のユーゴスラヴィア紛争の背景と経過について説明せよ。", "a": "ユーゴスラヴィアは多民族国家で、【ティトー】の指導のもとで統合が保たれていた。しかし彼の死後、冷戦終結とともに民族対立が表面化し、1991年に【スロヴェニア】と【クロアティア】が独立を宣言して内戦となった。【ボスニア=ヘルツェゴヴィナ】では激しい内戦が続き、のちにコソヴォ紛争ではNATOがセルビアを空爆した。"},
  {"id": "whx405", "s": "wh", "lv": 1, "topic": "イラン革命", "q": "1979年のイラン革命の背景と、その結果について説明せよ。", "a": "イランの国王【パフレヴィー2世】は、アメリカの支援のもとで【白色革命】と呼ばれる上からの近代化を進めたが、貧富の差の拡大や独裁に対する不満が高まった。1979年、宗教指導者【ホメイニ】を中心とする革命が起こり、国王は亡命し、【イスラーム】の教えに基づく共和国が成立した。この革命は【第2次石油危機】の原因となった。"},
  {"id": "whx406", "s": "wh", "lv": 2, "topic": "ソ連のアフガニスタン侵攻", "q": "1979年のソ連のアフガニスタン侵攻は、国際関係にどのような影響を与えたか説明せよ。", "a": "1979年、ソ連はアフガニスタンの親ソ政権を支援するため軍事介入した。これに対し【アメリカ】など西側諸国は強く反発し、1980年の【モスクワオリンピック】をボイコットした。米ソの【デタント】は終わり、「新冷戦」と呼ばれる緊張が再び高まった。ソ連軍はイスラーム勢力の激しい抵抗に苦しみ、1989年に【撤退】を完了した。"},
  {"id": "whx407", "s": "wh", "lv": 1, "topic": "同時多発テロ", "q": "2001年の同時多発テロと、その後のアメリカの対応について説明せよ。", "a": "2001年9月11日、イスラーム急進派組織【アル=カーイダ】が、ハイジャックした旅客機でニューヨークの世界貿易センタービルなどを攻撃した。アメリカの【ブッシュ】（子）政権は「テロとの戦い」を掲げ、同年【アフガニスタン】を攻撃して【ターリバーン】政権を倒し、2003年には【イラク戦争】を起こしてフセイン政権を倒した。"},
  {"id": "whx408", "s": "wh", "lv": 3, "topic": "グローバリゼーション", "q": "冷戦終結後に進んだグローバリゼーションの特徴と、それがもたらした問題について説明せよ。", "a": "冷戦の終結で旧社会主義国が市場経済に参加し、情報通信技術の発達によって、ヒト・モノ・カネ・情報が国境を越えて移動する【グローバリゼーション】が急速に進んだ。1995年には【世界貿易機関】（WTO）が発足した。一方で、1997年の【アジア通貨危機】や2008年の【世界金融危機】のように危機が瞬時に世界に波及するようになり、国内外の【経済格差】も拡大した。"},
  {"id": "whx409", "s": "wh", "lv": 2, "topic": "韓国の民主化", "q": "韓国における開発独裁から民主化への歩みについて説明せよ。", "a": "1961年のクーデタで実権を握った【朴正煕】は、開発独裁体制のもとで経済成長を進め、「【漢江の奇跡】」と呼ばれる発展をもたらした。1979年に彼が暗殺された後も軍事政権が続き、1980年の【光州事件】では民主化運動が武力で弾圧された。しかし1987年に民主化宣言が出され、大統領の直接選挙制が実現し、1993年には【金泳三】の文民政権が成立した。"},
  {"id": "whx410", "s": "wh", "lv": 2, "topic": "台湾の民主化", "q": "戦後の台湾における政治体制の変化について説明せよ。", "a": "国共内戦に敗れた国民党は台湾に逃れ、【蔣介石】のもとで【戒厳令】をしき、一党独裁体制をとった。経済的には輸出主導の工業化で成長した。1987年に戒厳令が解除され、【李登輝】総統のもとで民主化が進み、1996年には総統の【直接選挙】が実施された。2000年には野党の【民主進歩党】の陳水扁が総統に当選した。"},
  {"id": "whx411", "s": "wh", "lv": 3, "topic": "カンボジア内戦", "q": "1970年代以降のカンボジアの内戦と、その国際的な背景について説明せよ。", "a": "1975年、ベトナム戦争の終結とともに【ポル=ポト】派（赤色クメール）が政権を握り、極端な共産主義政策を進め、多くの国民を虐殺した。1978年、ポル=ポト派と対立した【ベトナム】がカンボジアに侵攻し、親ベトナム政権を樹立した。ポル=ポト派を支援していた【中国】は1979年にベトナムに侵攻した（【中越戦争】）。内戦は1991年の和平協定と国連の暫定統治を経て終結した。"},
  {"id": "whx412", "s": "wh", "lv": 2, "topic": "NIEs", "q": "1970〜80年代に経済成長をとげたNIEsについて説明せよ。", "a": "1970年代以降、【韓国】・台湾・香港・シンガポールなどは、外国資本と技術を導入し、輸出向けの工業製品を生産する【輸出指向型工業化】を進めて急速に経済成長した。これらの国・地域は【新興工業経済地域】（NIEs）と呼ばれた。多くは強力な政府が経済開発を主導する【開発独裁】体制のもとで成長を実現した。"},
  {"id": "whx413", "s": "wh", "lv": 2, "topic": "インドシナ戦争", "q": "第二次世界大戦後のインドシナ戦争の経過と、その結果について説明せよ。", "a": "1945年、【ホー=チ=ミン】はベトナム民主共和国の独立を宣言したが、フランスはこれを認めず、【インドシナ戦争】が始まった。1954年、フランスは【ディエンビエンフー】の戦いで大敗し、【ジュネーヴ休戦協定】が結ばれた。北緯17度線を暫定的な軍事境界線とし、統一選挙を予定したが、アメリカはこれに調印せず、南にベトナム共和国を支援した。"},
  {"id": "whx414", "s": "wh", "lv": 2, "topic": "ド=ゴールの外交", "q": "フランス第五共和政のド=ゴール大統領が進めた外交の特徴を説明せよ。", "a": "【ド=ゴール】は、アメリカに依存しない「フランスの栄光」を掲げた独自の外交を進めた。1960年に【核実験】を行って核保有国となり、1964年には【中華人民共和国】を承認した。また1966年には【NATO】の軍事機構から脱退した。ヨーロッパ統合では、【イギリス】のEEC加盟に反対した。"},
  {"id": "whx415", "s": "wh", "lv": 3, "topic": "東方外交", "q": "西ドイツのブラント政権が進めた東方外交の内容と、その意義を説明せよ。", "a": "1969年に西ドイツ首相となった社会民主党の【ブラント】は、ソ連・東欧諸国との関係改善をめざす【東方外交】を進めた。ソ連やポーランドと条約を結んで、【オーデル=ナイセ線】を事実上の国境として承認し、1972年には【東ドイツ】と東西ドイツ基本条約を結んで相互に承認した。翌年には東西ドイツが【国連】に同時加盟し、ヨーロッパの緊張緩和が進んだ。"},
  {"id": "whx416", "s": "wh", "lv": 3, "topic": "イランの石油国有化", "q": "1951年のイランの石油国有化の試みとその結末は、どのような意味をもっていたか説明せよ。", "a": "イランの石油は、イギリス系の【アングロ=イラニアン石油会社】に握られていた。1951年、首相【モサッデグ】は石油の【国有化】を断行した。しかしイギリスは国際的な石油市場からイランを締め出し、1953年に【アメリカ】とイギリスが支援したクーデタでモサッデグは失脚した。これは、のちの【資源ナショナリズム】の先駆的な動きであった。"},
  {"id": "whx417", "s": "wh", "lv": 3, "topic": "資源ナショナリズム", "q": "1960〜70年代に高まった資源ナショナリズムとは何か。OPECの活動とあわせて説明せよ。", "a": "自国の天然資源は自国で管理し、開発の利益を自国のために用いようとする考え方を【資源ナショナリズム】という。1960年に産油国は【石油輸出国機構】（OPEC）を結成し、国際石油資本（【メジャー】）に対抗した。1973年の第4次中東戦争では、アラブの産油国が【石油戦略】をとり、原油価格が大幅に引き上げられて【石油危機】が起こった。"},
  {"id": "whx418", "s": "wh", "lv": 1, "topic": "地球環境問題", "q": "地球環境問題に対する国際的な取り組みについて説明せよ。", "a": "1972年、ストックホルムで【国連人間環境会議】が開かれ、「かけがえのない地球」をスローガンに環境問題が国際的な課題とされた。1992年にはリオデジャネイロで【地球サミット】（国連環境開発会議）が開かれ、「【持続可能な開発】」の理念が示された。1997年には温室効果ガスの削減目標を定めた【京都議定書】が採択された。"},
  {"id": "whx419", "s": "wh", "lv": 1, "topic": "キューバ革命", "q": "1959年のキューバ革命の経過と、その後のキューバとアメリカの関係について説明せよ。", "a": "キューバでは、アメリカの支援を受けた【バティスタ】政権が独裁を行っていた。1959年、【カストロ】らがこれを打倒した（キューバ革命）。新政権はアメリカ系企業の土地や資産を接収したため、アメリカは1961年にキューバと【断交】した。キューバは社会主義を宣言して【ソ連】に接近し、1962年のキューバ危機につながった。"},
  {"id": "whx420", "s": "wh", "lv": 1, "topic": "三国の分立", "q": "後漢の滅亡後に成立した三国時代について説明せよ。", "a": "後漢末の混乱の中、華北では【曹操】が勢力を伸ばし、220年にその子曹丕が後漢の皇帝から帝位を譲られて【魏】を建てた。これに対し、四川では劉備が【蜀】を、江南では孫権が【呉】を建てて三国が分立した。魏は【九品中正】を定めた。三国は最終的に魏を継いだ【晋】（西晋）によって統一された。"},
  {"id": "whx421", "s": "wh", "lv": 1, "topic": "中国の三大発明", "q": "宋代に実用化が進んだ火薬・羅針盤・印刷術は、のちの世界史にどのような影響を与えたか説明せよ。", "a": "宋代には【火薬】・【羅針盤】・【木版印刷】が実用化され、活字印刷も考案された。これらはイスラーム世界を経てヨーロッパに伝わった。火薬は火器を生み、騎士の没落をうながす【軍事革命】につながった。羅針盤は遠洋航海を可能にし【大航海時代】を支えた。印刷術はグーテンベルクの改良を経て宗教改革などの思想の普及に役立った。"},
  {"id": "whx422", "s": "wh", "lv": 1, "topic": "プラッシーの戦い", "q": "1757年のプラッシーの戦いは、イギリスのインド支配にどのような意味をもったか説明せよ。", "a": "1757年、イギリス東インド会社の【クライヴ】は、ベンガル太守とそれを支援する【フランス】の連合軍をプラッシーで破った。これによりフランスのインドでの勢力は後退した。イギリス東インド会社は1765年に【ベンガル】などの【徴税権】（ディーワーニー）を獲得し、商業会社からインドの【領域支配者】へと性格を変えていった。"},
  {"id": "whx423", "s": "wh", "lv": 1, "topic": "マラッカ王国", "q": "15世紀のマラッカ王国が繁栄した理由について説明せよ。", "a": "マラッカ王国は、マレー半島の【マラッカ海峡】に面した港市国家である。明の【鄭和】の遠征を受け入れて明の後ろ盾を得、中継貿易の拠点として発展した。15世紀に国王が【イスラーム】に改宗すると、ムスリム商人が集まり、東南アジアのイスラーム化の拠点となった。1511年に【ポルトガル】に占領された。"},
  {"id": "whx424", "s": "wh", "lv": 1, "topic": "モンゴル時代の東西交流", "q": "モンゴル帝国の時代に、ユーラシアの東西交流が活発になった理由と、その具体例を説明せよ。", "a": "モンゴル帝国はユーラシアの大部分を支配し、【ジャムチ】を整備して交通の安全を確保した。そのため商人や宣教師の往来が盛んになった。ローマ教皇の使節【プラノ=カルピニ】やフランス王の使節ルブルックがカラコルムを訪れ、【マルコ=ポーロ】は元に仕えたとされ、『世界の記述』（東方見聞録）を残した。イスラーム世界からは【授時暦】のもとになった天文学なども伝わった。"},
  {"id": "whx425", "s": "wh", "lv": 1, "topic": "ラダイト運動", "q": "19世紀初めのイギリスで起こったラダイト運動の背景について説明せよ。", "a": "産業革命によって【機械制工場】が普及すると、手工業の職人は仕事を失い、生活が苦しくなった。1810年代、イギリス中部や北部の手工業者らは、失業や賃金低下の原因は【機械】にあるとして、機械を打ち壊す【ラダイト運動】を起こした。これは産業革命がもたらした社会の変化に対する【労働者】の反発を示している。"},
  {"id": "whx426", "s": "wh", "lv": 1, "topic": "ローマの実用文化", "q": "古代ローマの文化の特徴について、ギリシア文化と比較して説明せよ。", "a": "ローマ人はギリシア文化を受け継いだが、独創的な哲学や芸術よりも、【実用的】な分野で優れた業績を残した。法律の分野では【ローマ法】を発達させ、土木・建築では道路や【水道橋】、円形闘技場の【コロッセウム】などを建設した。また暦では【ユリウス暦】をつくり、のちのヨーロッパ文化の基礎となった。"},
  {"id": "whx427", "s": "wh", "lv": 1, "topic": "キリスト教の成立", "q": "キリスト教はどのように成立し、ローマ帝国内に広まったか説明せよ。", "a": "1世紀初め、パレスチナで【イエス】は、ユダヤ教の形式的な律法主義を批判し、神の愛と隣人愛を説いた。イエスが処刑された後、弟子たちはイエスを救世主（キリスト）と信じ、キリスト教が成立した。【ペテロ】や【パウロ】が異邦人にも布教し、キリスト教は帝国の下層民を中心に広まった。キリスト教徒は皇帝崇拝を拒んだため【迫害】を受けた。"},
  {"id": "whx428", "s": "wh", "lv": 1, "topic": "ゾロアスター教", "q": "ゾロアスター教の教えの特徴と、他の宗教への影響について説明せよ。", "a": "ゾロアスター教は古代イランで成立した宗教で、世界を善の神【アフラ=マズダ】と悪の神アーリマンとの闘争ととらえる【善悪二元論】を説いた。最後の審判の考えも説かれ、ユダヤ教やキリスト教に影響を与えた。ササン朝で【国教】とされ、経典『【アヴェスター】』が編纂された。中国には祆教として伝わった。"},
  {"id": "whx429", "s": "wh", "lv": 1, "topic": "新文化運動", "q": "1910年代の中国で起こった新文化運動の内容と、その意義について説明せよ。", "a": "辛亥革命後も政治の混乱が続く中、【陳独秀】は雑誌『【新青年】』を発行して、儒教道徳を批判し、民主と科学を唱えた。【胡適】は口語による文学を提唱する白話運動を進め、【魯迅】は『狂人日記』や『阿Q正伝』を発表した。この運動は民衆の意識を変革し、のちの【五・四運動】の思想的な基盤となった。"},
  {"id": "whx430", "s": "wh", "lv": 1, "topic": "三民主義", "q": "孫文が唱えた三民主義の内容について説明せよ。", "a": "【孫文】は1905年に東京で【中国同盟会】を結成し、【三民主義】を革命の指導理念とした。民族主義は満州人の清朝を打倒して漢民族の国家を建設すること、【民権主義】は共和政を樹立すること、民生主義は地権の平均などで民衆の生活を安定させることを意味した。のちの国民党の基本理念となった。"},
  {"id": "whx431", "s": "wh", "lv": 1, "topic": "香港返還", "q": "香港がイギリスから中国に返還された経緯と、その後の統治のしくみを説明せよ。", "a": "香港島は【南京条約】でイギリスに割譲され、のちに九竜半島の一部も割譲され、新界は99年間の租借地とされた。1984年の中英共同声明で返還が決まり、1997年に香港は中国に返還された。返還後は【一国二制度】のもとで【特別行政区】とされ、50年間は資本主義制度と高度な【自治】が保障されるとされた。"},
  {"id": "whx432", "s": "wh", "lv": 1, "topic": "アラブの春", "q": "2010年末から始まった「アラブの春」の背景と、その結果について説明せよ。", "a": "2010年末、【チュニジア】で起こった民衆の抗議運動が長期独裁政権を倒すと、運動は【インターネット】などを通じてアラブ諸国に広がった。エジプトでは【ムバーラク】政権が倒れた。しかし多くの国では民主化は定着せず、【シリア】では内戦となり、多くの難民が発生した。"},
  {"id": "whx433", "s": "wh", "lv": 1, "topic": "朝鮮の南北分断", "q": "第二次世界大戦後、朝鮮半島が南北に分断された経緯を説明せよ。", "a": "日本の敗戦後、朝鮮半島は北緯【38度線】を境に、北を【ソ連】、南をアメリカが占領した。米ソの対立で統一政府の樹立は実現せず、1948年に南に【李承晩】を大統領とする大韓民国、北に【金日成】を首相とする朝鮮民主主義人民共和国が成立した。1950年の朝鮮戦争で分断は固定化した。"},
  {"id": "whx434", "s": "wh", "lv": 1, "topic": "活版印刷術", "q": "グーテンベルクが改良した活版印刷術は、ヨーロッパの社会にどのような影響を与えたか説明せよ。", "a": "15世紀半ば、ドイツの【グーテンベルク】は金属活字を用いた【活版印刷術】を改良・実用化した。これにより書物が安価に大量に生産されるようになり、知識が広く普及した。ルネサンスの人文主義の思想の広まりや、ルターのドイツ語訳【聖書】などの普及を通じて【宗教改革】の拡大を支えた。"},
  {"id": "whx435", "s": "wh", "lv": 2, "topic": "アユタヤ朝", "q": "タイのアユタヤ朝が繁栄した理由について説明せよ。", "a": "14世紀半ばに成立したアユタヤ朝は、【上座部仏教】を保護し、【スコータイ朝】を併合して勢力を広げた。チャオプラヤ川の水運と豊かな【米】の生産を背景に、明への朝貢や、中国・日本・ヨーロッパとの交易で栄えた。17世紀には【日本町】もつくられ、山田長政が活躍した。18世紀にビルマの【コンバウン朝】に滅ぼされた。"},
  {"id": "whx436", "s": "wh", "lv": 2, "topic": "タラス河畔の戦い", "q": "751年のタラス河畔の戦いは、どのような歴史的意義をもつか説明せよ。", "a": "751年、中央アジアのタラス河畔で【唐】と【アッバース朝】の軍が戦い、アッバース朝が勝利した。この戦いで捕虜となった唐の紙すき職人を通じて、【製紙法】がイスラーム世界に伝わり、【サマルカンド】などで紙が生産されたとされる。製紙法はのちにヨーロッパに伝わった。また中央アジアの【イスラーム化】が進むきっかけともなった。"},
  {"id": "whx437", "s": "wh", "lv": 2, "topic": "コロンブス交換", "q": "大航海時代以降の新大陸と旧大陸の間の動植物の移動は、世界にどのような影響を与えたか説明せよ。", "a": "アメリカ大陸から【ジャガイモ】・トウモロコシ・トマト・タバコなどがヨーロッパやアジアに伝わり、ヨーロッパや中国の【人口増加】を支えた。一方、旧大陸からは馬・牛や小麦、サトウキビなどがもたらされた。しかし同時に【天然痘】などの感染症も持ち込まれ、免疫をもたない【先住民】の人口が激減した。"},
  {"id": "whx438", "s": "wh", "lv": 2, "topic": "ヘレニズム諸国", "q": "アレクサンドロス大王の死後に成立したヘレニズム諸国について説明せよ。", "a": "アレクサンドロスの死後、その部下の将軍たち（【ディアドコイ】）の争いの結果、帝国はエジプトの【プトレマイオス朝】、シリアを中心とする【セレウコス朝】、マケドニアのアンティゴノス朝などに分裂した。これらの国ではギリシア人が支配層となった。プトレマイオス朝の都【アレクサンドリア】はヘレニズム文化の中心として栄え、前30年に【ローマ】に滅ぼされた。"},
  {"id": "whx439", "s": "wh", "lv": 2, "topic": "デカブリストの乱", "q": "1825年のロシアのデカブリストの乱の背景と意義について説明せよ。", "a": "ナポレオン戦争でヨーロッパに遠征したロシアの青年貴族将校たちは、西欧の自由主義思想に触れ、ロシアの専制政治や【農奴制】の遅れを痛感した。1825年、皇帝【ニコライ1世】の即位に際して、立憲制などを求めて蜂起したが、すぐに鎮圧された。これを【デカブリストの乱】という。失敗したが、ロシアにおける【自由主義】運動の始まりとされる。"},
  {"id": "whx440", "s": "wh", "lv": 2, "topic": "イギリスの工場法", "q": "19世紀のイギリスで工場法が制定された背景と、その内容について説明せよ。", "a": "産業革命期の工場では、【女性】や子どもが劣悪な環境で長時間働かされていた。社会主義者の【ロバート=オーウェン】らは労働条件の改善を訴えた。1833年の【工場法】では、9歳未満の児童労働の禁止や18歳未満の労働時間の制限が定められ、違反を監督するために【工場監督官】が置かれた。その後も改正が重ねられ、労働者保護が進んだ。"},
  {"id": "whx441", "s": "wh", "lv": 2, "topic": "アフリカ統一機構", "q": "1963年に結成されたアフリカ統一機構の目的と、その後の変化について説明せよ。", "a": "1960年の「アフリカの年」を経て多くの国が独立すると、1963年、エチオピアの【アディスアベバ】でアフリカ独立諸国の首脳会議が開かれ、【アフリカ統一機構】（OAU）が結成された。アフリカ諸国の連帯や、残る【植民地主義】の一掃をめざした。2002年には、より強い統合をめざして【アフリカ連合】（AU）に発展した。"},
  {"id": "whx442", "s": "wh", "lv": 2, "topic": "21世紀の中国の台頭", "q": "21世紀に入って中国が国際社会で存在感を高めた理由を説明せよ。", "a": "中国は【改革開放】政策以来、外国資本を導入して高い経済成長を続け、2001年には【世界貿易機関】（WTO）に加盟して「世界の工場」となった。2010年には国内総生産（GDP）で【日本】を抜いて世界第2位となった。さらに【一帯一路】構想を掲げて、アジアからヨーロッパ・アフリカに至る地域で経済的な影響力を強めている。"},
  {"id": "whx443", "s": "wh", "lv": 2, "topic": "袁世凱の政治", "q": "辛亥革命後に袁世凱が行った政治と、その結末について説明せよ。", "a": "【袁世凱】は清の宣統帝を退位させる代わりに、孫文から臨時大総統の地位を譲り受けた。彼は議会で多数を占めた【国民党】を弾圧し、反対派の【第二革命】を鎮圧して正式な大総統に就任した。さらに【帝政】の復活を図ったが、国内外の反対と【第三革命】によって断念し、まもなく病死した。その後中国は【軍閥】が割拠する状態となった。"},
  {"id": "whx444", "s": "wh", "lv": 2, "topic": "バングラデシュの独立", "q": "1971年にバングラデシュが独立した経緯について説明せよ。", "a": "1947年、パキスタンはインドをはさんで東西に分かれる国家として独立した。政治・経済の実権を握る西パキスタンに対し、ベンガル語を話す【東パキスタン】では不満が高まった。1971年、東パキスタンは独立を宣言し、【インド】が軍事介入して第3次【インド=パキスタン戦争】となった。その結果、東パキスタンは【バングラデシュ】として独立した。"},
  {"id": "whx445", "s": "wh", "lv": 3, "topic": "宋代の市舶司", "q": "宋代の海上交易の発展と、市舶司の役割について説明せよ。", "a": "宋代には【ジャンク船】による海上交易が発展し、【泉州】や広州・明州などの港が栄えた。政府はこれらの港に【市舶司】を置き、海上交易を管理して【関税】を徴収し、重要な財源とした。中国からは陶磁器や絹織物、銅銭が輸出され、東南アジアやインド洋から香辛料などが輸入された。【ムスリム商人】も多く来航し、港には外国人居留地もつくられた。"},
  {"id": "whx446", "s": "wh", "lv": 3, "topic": "交鈔", "q": "元代に紙幣である交鈔が広く使われた背景と、その結末について説明せよ。", "a": "元は宋代の紙幣制度を受け継ぎ、【交鈔】を発行して主要な通貨とした。ユーラシア規模の交易では【銀】が決済手段となり、交鈔は銀との交換が保証されて流通した。また【塩】の専売とも結びついて財政を支えた。しかし元末には財政難から交鈔が【乱発】されて価値が暴落し、経済が混乱した。これは元の滅亡の一因となった。"},
  {"id": "whx447", "s": "wh", "lv": 3, "topic": "宦官の政治関与", "q": "中国の歴代王朝で宦官が政治に関与し、しばしば混乱を招いた理由を、具体例を挙げて説明せよ。", "a": "宦官は皇帝の身辺に仕えたため、皇帝の信任を得て権力を握ることがあった。後漢では宦官が官僚と対立して【党錮の禁】を起こし、唐の後半には宦官が皇帝の廃立にも関与した。明では【永楽帝】が宦官を重用し、鄭和の遠征にも用いたが、のちに【魏忠賢】らが専横をきわめた。皇帝の【独裁】体制のもとで、皇帝に近い宦官が力をもちやすかった。"},
  {"id": "whx448", "s": "wh", "lv": 3, "topic": "郷紳", "q": "明清時代の郷紳とはどのような人々か。地方社会における役割を説明せよ。", "a": "【郷紳】は、科挙の合格者や退職した【官僚】などで、出身地の地方社会に住む有力者である。彼らは【徭役】の免除などの特権をもち、多くの土地を所有した。地方官は数年で交代するため、地方の行政や治安の維持、水利、【慈善事業】などには郷紳の協力が欠かせなかった。一方で郷紳の特権はしばしば民衆の反発を招いた。"},
  {"id": "whx449", "s": "wh", "lv": 3, "topic": "華僑", "q": "華僑が東南アジアに広がった歴史的背景を説明せよ。", "a": "宋代以降、海上交易の発展とともに中国人の東南アジアへの移住が始まった。明清時代には【福建】や広東などの出身者を中心に移住が増え、東南アジアの港市で商業活動を担った。19世紀には、ヨーロッパ諸国の植民地開発のための労働力として、【苦力】と呼ばれる中国人労働者が大量に移住した。彼らは【同郷】・同族の結びつきを基盤にネットワークを築き、【東南アジア】の経済に大きな影響力をもった。"},
  {"id": "whx450", "s": "wh", "lv": 3, "topic": "イギリスの奴隷貿易廃止", "q": "19世紀前半にイギリスで奴隷貿易と奴隷制が廃止された背景について説明せよ。", "a": "18世紀末から、キリスト教的な人道主義の立場から【ウィルバーフォース】らが奴隷貿易の廃止を訴えた。また産業革命の進展によって、産業資本家が【自由貿易】を求め、奴隷制に基づく西インド諸島の【砂糖プランテーション】の経済的重要性は相対的に低下した。こうして1807年に【奴隷貿易】が、1833年に植民地での【奴隷制】が廃止された。"},
  {"id": "whx451", "s": "wh", "lv": 3, "topic": "アメリカの革新主義", "q": "20世紀初めのアメリカで展開した革新主義の背景と、その内容を説明せよ。", "a": "19世紀末のアメリカでは、【独占資本】の形成や政治の腐敗、都市の貧困などの問題が深刻化した。これに対して、政府が社会や経済に介入して問題を解決しようとする【革新主義】が広まった。【セオドア=ローズヴェルト】や【ウィルソン】大統領は、反トラスト法による独占の規制や、労働者の保護、上院議員の直接選挙などの改革を進めた。"},
  {"id": "whx452", "s": "wh", "lv": 3, "topic": "ルワンダ内戦", "q": "1990年代のルワンダ内戦と大量虐殺の背景について説明せよ。", "a": "ルワンダでは、植民地支配の時代に宗主国の【ベルギー】が少数派の【ツチ】を優遇し、多数派の【フツ】との区別を固定化した。独立後、両者の対立が続き、1990年に内戦となった。1994年には、フツの過激派がツチや穏健派フツの人々を大量に殺害する【ジェノサイド】が起こり、短期間に数十万人が犠牲となった。国際社会の介入の遅れも批判された。"},
  {"id": "whx453", "s": "wh", "lv": 3, "topic": "ヴィジャヤナガル王国", "q": "南インドのヴィジャヤナガル王国の特徴と、その繁栄の理由について説明せよ。", "a": "14世紀前半、南インドに【ヒンドゥー教】の王国であるヴィジャヤナガル王国が成立し、北方の【イスラーム】勢力に対抗した。インド洋交易を通じて【馬】や香辛料などを取引して繁栄し、都は国際都市として栄えた。16世紀後半にデカンのイスラーム諸国の連合軍に敗れて衰退した。"},
  {"id": "whx454", "s": "wh", "lv": 1, "topic": "エジプト=イスラエル平和条約", "q": "1979年のエジプト=イスラエル平和条約が結ばれた経緯と、その影響を説明せよ。", "a": "第4次中東戦争の後、エジプトの【サダト】大統領はイスラエルとの和平に転じた。1978年、アメリカの【カーター】大統領の仲介で【キャンプ=デーヴィッド合意】が成立し、翌年平和条約が結ばれ、イスラエルは【シナイ半島】をエジプトに返還した。しかしアラブ諸国はエジプトを非難し、サダトは1981年に暗殺された。"},
  {"id": "whx455", "s": "wh", "lv": 1, "topic": "ポーランドの「連帯」", "q": "1980年代のポーランドにおける「連帯」の運動とその意義について説明せよ。", "a": "1980年、ポーランドで物価の値上げに反対するストライキが広がり、【ワレサ】を指導者とする自主管理労働組合「【連帯】」が結成された。翌年政府は戒厳令をしいて連帯を非合法化したが、運動は続いた。1989年、自由選挙で連帯が圧勝して非共産党政権が成立し、【東欧革命】の先駆けとなった。"},
  {"id": "whx456", "s": "wh", "lv": 2, "topic": "クレタ文明とミケーネ文明", "q": "エーゲ文明のうち、クレタ文明とミケーネ文明の特徴を比較して説明せよ。", "a": "前2000年ごろに栄えたクレタ文明は、【クノッソス】宮殿に代表され、城壁をもたない開放的な文明であった。これに対し、ギリシア人が築いた【ミケーネ文明】は、巨石の城壁をもつ堅固な城塞を中心とする戦闘的な文明であった。ミケーネ文明では【線文字B】が用いられ、のちに【ヴェントリス】によって解読され、ギリシア語であることがわかった。"},
  {"id": "whx457", "s": "wh", "lv": 2, "topic": "則天武后", "q": "唐の則天武后の政治の特徴と、その歴史的な意味を説明せよ。", "a": "【則天武后】は高宗の皇后として実権を握り、690年には自ら皇帝となって国号を【周】と改めた。彼女は【科挙】出身の新しい官僚を積極的に登用し、旧来の門閥貴族の勢力を抑えた。また【仏教】を保護した。彼女の死後唐は復活し、その後の政治の混乱は「【武韋の禍】」と呼ばれた。"},
  {"id": "whx458", "s": "wh", "lv": 2, "topic": "唐代の文化", "q": "唐代の文化の特徴について、具体例を挙げて説明せよ。", "a": "唐代の文化は、貴族的で国際色豊かな文化であった。詩では【李白】・【杜甫】が、散文では韓愈・柳宗元が活躍し、書では【顔真卿】が力強い書風を確立した。儒学では孔穎達らが『五経正義』を編纂した。仏教では玄奘や義浄がインドから経典をもち帰り、【景教】（ネストリウス派キリスト教）やマニ教なども伝来した。"},
  {"id": "whx459", "s": "wh", "lv": 2, "topic": "清朝の編纂事業", "q": "清朝が行った大規模な編纂事業の目的について説明せよ。", "a": "清朝は、康熙帝の『【康熙字典】』、雍正帝の『古今図書集成』、乾隆帝の『【四庫全書】』など、大規模な編纂事業を行った。これらは学問を奨励し、多くの【漢人知識人】を動員して懐柔するとともに、その過程で清朝に不都合な書物を【禁書】とする思想統制の意味ももっていた。こうした政策は【考証学】の発達とも関わった。"},
  {"id": "whx460", "s": "wh", "lv": 2, "topic": "カルロヴィッツ条約", "q": "1699年のカルロヴィッツ条約は、オスマン帝国の歴史においてどのような意味をもつか説明せよ。", "a": "1683年、オスマン帝国は【第2次ウィーン包囲】に失敗し、その後の戦争にも敗れた。1699年の【カルロヴィッツ条約】で、オスマン帝国は【オーストリア】に【ハンガリー】などを割譲した。これはオスマン帝国が初めて大規模な領土を失った条約であり、ヨーロッパに対する【劣勢】への転換点となった。"},
  {"id": "whx461", "s": "wh", "lv": 2, "topic": "ムガル帝国の成立", "q": "ムガル帝国はどのように成立したか説明せよ。", "a": "ティムールの子孫である【バーブル】は、中央アジアから北インドに進出し、1526年の【パーニーパットの戦い】で【ロディー朝】を破って【デリー】を拠点にムガル帝国を建てた。ムガルとはモンゴルを意味する。第3代の【アクバル】の時代に統治体制が整えられた。"},
  {"id": "whx462", "s": "wh", "lv": 2, "topic": "ガレオン貿易", "q": "16世紀後半から始まったガレオン貿易の内容と、その世界史的な意義について説明せよ。", "a": "スペインは1571年にフィリピンの【マニラ】を拠点とし、メキシコの【アカプルコ】との間でガレオン船による貿易を行った。アメリカ大陸の【銀】がマニラに運ばれ、中国商人がもたらす【絹】や陶磁器と交換された。これにより太平洋を横断する交易路が成立し、アメリカ大陸の銀が直接中国に流入して、【世界的な交易網】が形成された。"},
  {"id": "whx463", "s": "wh", "lv": 2, "topic": "ロシア第一革命", "q": "1905年のロシア第一革命の背景と、その結果について説明せよ。", "a": "【日露戦争】の戦況が悪化する中、1905年1月、首都で請願行進をした民衆に軍隊が発砲する【血の日曜日事件】が起こった。これをきっかけに各地でストライキや農民反乱が起こり、労働者は【ソヴィエト】を組織した。皇帝【ニコライ2世】は【十月宣言】を出して国会（ドゥーマ）の開設を約束したが、のちに再び専制を強めた。"},
  {"id": "whx464", "s": "wh", "lv": 2, "topic": "ストルイピンの改革", "q": "ロシア第一革命後のストルイピンの改革の内容と、その結果を説明せよ。", "a": "首相【ストルイピン】は、革命運動を弾圧する一方、農村共同体である【ミール】を解体し、農民に土地を与えて【自作農】を育成しようとした。これは皇帝を支える保守的な農民層をつくり、社会を安定させるためであった。しかし改革は十分な成果を上げず、農村では【貧富の差】が拡大し、ストルイピンは1911年に暗殺された。"},
  {"id": "whx465", "s": "wh", "lv": 2, "topic": "イギリス労働党の成立", "q": "イギリスで労働党が成立し、政権を担うようになった過程を説明せよ。", "a": "19世紀末、労働組合や【フェビアン協会】などの社会主義団体が結集し、1900年に労働代表委員会が結成され、1906年に【労働党】と改称した。労働党は【議会】を通じて社会改革を進めようとした。第一次世界大戦後に【自由党】に代わって二大政党の一つとなり、1924年に【マクドナルド】を首相とする初の労働党内閣が成立した。"},
  {"id": "whx466", "s": "wh", "lv": 2, "topic": "ドイモイ", "q": "ベトナムのドイモイ（刷新）政策の内容と、その背景について説明せよ。", "a": "ベトナム戦争後に南北を統一したベトナムは、【カンボジア】への侵攻や中越戦争で国際的に孤立し、計画経済のもとで経済も停滞した。1986年、共産党は【ドイモイ】（刷新）政策を採用し、共産党の一党体制を維持しつつ【市場経済】を導入し、【外国資本】の誘致や対外開放を進めた。1995年には【ASEAN】に加盟した。"},
  {"id": "whx467", "s": "wh", "lv": 2, "topic": "インドの経済自由化", "q": "独立後のインドの経済政策は、1990年代にどのように変化したか説明せよ。", "a": "独立後のインドは、【ネルー】のもとで国家主導の混合経済をとり、輸入代替工業化と【計画経済】を進めた。しかし経済成長は伸び悩み、1991年に外貨危機に陥ると、【規制緩和】や外国資本の導入など経済の【自由化】に転換した。その後、【情報技術】（IT）産業などが発展し、高い経済成長を実現した。"},
  {"id": "whx468", "s": "wh", "lv": 2, "topic": "ソ連の国際的承認", "q": "1920年代にソ連が国際的に承認されていった過程を説明せよ。", "a": "成立当初のソヴィエト政権は、対ソ干渉戦争などで国際的に孤立していた。1922年、ドイツと【ラパロ条約】を結んで国交を樹立した。1924年にはイギリスやフランス、イタリアが承認し、1925年には日本も【日ソ基本条約】で国交を結んだ。【アメリカ】の承認は1933年となり、翌1934年にソ連は【国際連盟】に加盟した。"},
  {"id": "whx469", "s": "wh", "lv": 2, "topic": "シベリア鉄道", "q": "シベリア鉄道の建設は、東アジアの国際関係にどのような影響を与えたか説明せよ。", "a": "ロシアは【フランス】の資本を導入して、1891年にシベリア鉄道の建設を始めた。日清戦争後には清から【東清鉄道】の敷設権を得て、満州を横断する路線を建設した。これによりロシアの【極東】進出が強化され、満州や朝鮮をめぐって【日本】との対立が深まり、【日露戦争】の背景となった。"},
  {"id": "whx470", "s": "wh", "lv": 2, "topic": "景教とマニ教", "q": "唐代の中国に伝わった外来宗教について、その伝来の背景とともに説明せよ。", "a": "唐は国際的な帝国であり、【シルクロード】を通じて多くの外国人が長安を訪れた。ネストリウス派キリスト教は【景教】と呼ばれ、長安には【大秦景教流行中国碑】が建てられた。ゾロアスター教（祆教）や、ウイグルで国教とされた【マニ教】も伝わった。しかしこれらは9世紀の【会昌の廃仏】の際に弾圧を受けて衰えた。"},
  {"id": "whx471", "s": "wh", "lv": 2, "topic": "19世紀の国際組織", "q": "19世紀後半に国際的な協力組織が生まれた背景と、その具体例を説明せよ。", "a": "19世紀後半、交通・通信の発達により人や物、情報の国際的な移動が増えると、国境を越えた協力の必要が高まった。1864年に【国際赤十字】が組織され、戦時の負傷者の救護を国際的に行うことになった。1865年に【万国電信連合】、1874年に【万国郵便連合】が設立された。また【国際オリンピック大会】も1896年に始まった。"},
  {"id": "whx472", "s": "wh", "lv": 2, "topic": "全インド=ムスリム連盟", "q": "1906年に結成された全インド=ムスリム連盟は、インドの民族運動にどのような影響を与えたか説明せよ。", "a": "イギリスは【ベンガル分割令】などで、ヒンドゥー教徒とイスラーム教徒の対立をあおる【分割統治】を行った。1906年、イギリスの支援を受けて親英的な【全インド=ムスリム連盟】が結成された。のちに連盟は【ジンナー】の指導のもとでイスラーム教徒の国家の建設を主張し、1947年のインドと【パキスタン】の分離独立につながった。"},
  {"id": "whx473", "s": "wh", "lv": 2, "topic": "イギリスの福祉国家", "q": "第二次世界大戦後、イギリスで福祉国家が建設された経緯と、その内容を説明せよ。", "a": "1945年の総選挙で【労働党】が勝利し、【アトリー】内閣が成立した。戦時中の【ベヴァリッジ報告】をもとに、「ゆりかごから墓場まで」と呼ばれる社会保障制度を整え、国民保健サービスによる医療の無料化などを行った。また石炭・鉄道などの【重要産業】を国有化した。インドなどの独立も認めた。"},
  {"id": "whx474", "s": "wh", "lv": 3, "topic": "イスラーム世界の奴隷軍人", "q": "イスラーム世界で奴隷軍人（マムルーク）が重用された理由と、その歴史的な影響を説明せよ。", "a": "9世紀ごろから、アッバース朝のカリフは、中央アジア出身の【トルコ人】などを奴隷として購入し、軍事訓練をほどこして親衛隊とした。彼らは地縁・血縁にとらわれず【君主】に忠誠を誓う存在として重用された。やがて奴隷軍人が実権を握るようになり、エジプトでは【マムルーク朝】、インドでは【奴隷王朝】のように、奴隷軍人出身者が王朝を開いた。"},
  {"id": "whx475", "s": "wh", "lv": 3, "topic": "ローマの属州支配", "q": "共和政ローマの属州支配の特徴と、それがローマ社会に与えた影響を説明せよ。", "a": "ローマはシチリアをはじめ海外の征服地を【属州】とし、総督を派遣して統治した。属州の徴税は【徴税請負人】に請け負わせたため、彼らは住民から過酷に取り立てた。徴税請負や公共事業で富を得た【騎士】（エクイテス）が台頭し、属州の総督となった元老院議員も富を蓄えた。こうした富の集中と【中小農民】の没落が、共和政の動揺の背景となった。"},
  {"id": "whx476", "s": "wh", "lv": 3, "topic": "東南アジアの港市国家", "q": "東南アジアで港市国家が発達した理由について説明せよ。", "a": "東南アジアは、【インド洋】と【南シナ海】を結ぶ海上交易路の中継点にあたった。季節風を利用する帆船は、【風待ち】のために港に滞在する必要があった。そのため、水や食料を補給し、香辛料などの産物を集める【港市】が発達し、港市を中心とする国家が生まれた。【扶南】やシュリーヴィジャヤ、マラッカ王国などがその例である。"},
  {"id": "whx477", "s": "wh", "lv": 3, "topic": "郷勇", "q": "太平天国の鎮圧において郷勇が果たした役割と、それが清朝の政治に与えた影響について説明せよ。", "a": "清の正規軍である【八旗】や緑営は弱体化しており、太平天国を鎮圧できなかった。そこで【曾国藩】の湘軍や【李鴻章】の淮軍など、漢人官僚が郷里で組織した義勇軍（【郷勇】）が鎮圧の主力となった。これにより漢人官僚が軍事力と地方での権力を握り、【洋務運動】を主導した。のちの【軍閥】の形成にもつながった。"},
  {"id": "whx478", "s": "wh", "lv": 3, "topic": "山西商人と徽州商人", "q": "明清時代に山西商人や徽州商人が全国的に活動した背景を説明せよ。", "a": "明清時代には商品経済が発達し、遠隔地間の商業が盛んになった。山西商人は、明が北方防衛のために行った【塩】の専売に関わる制度を通じて富を蓄え、のちに金融業でも活躍した。徽州（新安）商人も塩の取引などで富を築いた。彼らは各地の都市に同郷者の施設である【会館】や同業者の【公所】を設けて相互扶助を行い、全国的な【商業ネットワーク】を形成した。"},
  {"id": "whx479", "s": "wh", "lv": 3, "topic": "皇帝教皇主義", "q": "ビザンツ帝国における皇帝と教会の関係について、西ヨーロッパと比較して説明せよ。", "a": "ビザンツ帝国では、皇帝が政治だけでなく【教会】に対しても大きな権限をもち、コンスタンティノープル総主教を任命するなど、宗教上の事柄にも介入した。この体制を【皇帝教皇主義】という。これに対し西ヨーロッパでは、【ローマ教皇】が皇帝や国王から自立した権威をもち、【叙任権闘争】のように聖俗の権力が対立した。"},
  {"id": "whx480", "s": "wh", "lv": 3, "topic": "近世ヨーロッパの軍事革命", "q": "16〜17世紀のヨーロッパにおける軍事革命とは何か。それが国家のあり方に与えた影響を説明せよ。", "a": "【火器】の普及により、騎士による戦闘は時代遅れとなり、大量の歩兵や大砲を用いる戦術、それに対応した【稜堡】式の要塞が発達した。戦争の規模が拡大し、膨大な戦費や兵士が必要となった。そのため国家は【常備軍】を整え、課税と徴税のための【官僚制】を発達させた。軍事革命は、【主権国家】の形成をうながした。"},
  {"id": "whx481", "s": "wh", "lv": 3, "topic": "環大西洋革命", "q": "18世紀後半から19世紀前半の大西洋をはさむ地域の革命は、どのように連動していたか説明せよ。", "a": "【アメリカ独立革命】は、啓蒙思想に基づく共和国の成立を示し、ヨーロッパに影響を与えた。また独立戦争への参戦でフランスの財政が悪化したことは、【フランス革命】の一因となった。フランス革命の理念はカリブ海の【ハイチ】の黒人奴隷の革命を引き起こし、ナポレオンのスペイン侵入は【ラテンアメリカ】諸国の独立運動を促した。これらを一連の【環大西洋革命】ととらえる見方がある。"},
  {"id": "whx482", "s": "wh", "lv": 3, "topic": "中国の不平等条約撤廃", "q": "中国は不平等条約の撤廃をどのように進めたか、その過程を説明せよ。", "a": "北伐を完了した【国民政府】は、不平等条約の改正に取り組み、1928年から30年にかけて列強との交渉で【関税自主権】をほぼ回復した。【領事裁判権】の撤廃は難航したが、第二次世界大戦中の1943年、連合国の一員として抗日戦争を戦う中国に対し、【アメリカ】とイギリスが治外法権を撤廃した。この過程は中国の国際的地位の向上を示している。"},
  {"id": "whx483", "s": "wh", "lv": 3, "topic": "中世の教会組織", "q": "中世西ヨーロッパのローマ=カトリック教会の組織と、その社会的な影響力について説明せよ。", "a": "ローマ=カトリック教会は、【教皇】を頂点に、大司教・司教・司祭などからなる【階層制組織】を形成した。教会は農民から【十分の一税】を徴収し、広大な所領をもつ大領主でもあった。人々の誕生から死までの生活は秘跡などを通じて教会と結びつき、教会は【破門】などの手段で国王や諸侯にも影響力を及ぼした。"},
  {"id": "whx484", "s": "wh", "lv": 3, "topic": "国民軍の形成", "q": "フランス革命期に形成された国民軍は、それ以前の軍隊とどのように異なっていたか。その影響とあわせて説明せよ。", "a": "絶対王政期の軍隊は、【傭兵】や職業軍人が中心の常備軍であった。フランス革命期には、革命を守るため1793年に【国民総動員令】（徴兵制）が出され、国民が祖国のために戦う【国民軍】が形成された。【ナショナリズム】に支えられた国民軍は大規模で士気も高く、ナポレオン戦争で威力を発揮した。他の国々もこれにならって【徴兵制】を導入していった。"},
  {"id": "whx485", "s": "wh", "lv": 3, "topic": "ビザンツ文化の影響", "q": "ビザンツ帝国の文化は、周辺地域やのちの時代にどのような影響を与えたか説明せよ。", "a": "ビザンツ帝国は、ギリシア古典の文化と【ギリシア正教】を融合させた独自の文化を発展させた。教会建築では【ハギア=ソフィア聖堂】に代表されるビザンツ様式が生まれ、【モザイク壁画】やイコンが用いられた。ビザンツ文化は、【スラヴ人】の世界に伝わり、ロシアなどの文化の基礎となった。またビザンツで保存されたギリシア古典は、イタリアの【ルネサンス】にも影響を与えた。"},
  {"id": "whx486", "s": "wh", "lv": 3, "topic": "ペルシア語文化圏", "q": "イスラーム世界の東方で、ペルシア語が文化的に広く用いられた理由について説明せよ。", "a": "アッバース朝以降、イラン系の人々は官僚や学者として活躍し、10世紀ごろから【アラビア文字】を用いた近世ペルシア語の文学が発達した。【フィルドゥシー】の『シャー=ナーメ』などが生まれた。トルコ系やモンゴル系の王朝もペルシア語を【行政】や文学の言語として用い、【ムガル帝国】では公用語とされた。こうして中央アジアからインドにかけて【ペルシア語文化圏】が形成された。"},
  {"id": "whx487", "s": "wh", "lv": 3, "topic": "地域経済統合", "q": "冷戦終結後、世界各地で地域経済統合が進んだ理由と、その例について説明せよ。", "a": "冷戦の終結とグローバル化の進展の中で、各国は地域内の貿易や投資を自由化し、【経済協力】を強めて国際競争力を高めようとした。ヨーロッパでは1993年に【ヨーロッパ連合】（EU）が発足し、北米では1994年に【北米自由貿易協定】（NAFTA）が発効した。アジア太平洋地域では【APEC】が発足し、東南アジアでは【ASEAN】が自由貿易地域の形成をめざした。"},
  {"id": "whx488", "s": "wh", "lv": 2, "topic": "匈奴", "q": "前3世紀末にモンゴル高原で強大となった匈奴と、漢との関係について説明せよ。", "a": "前3世紀末、【冒頓単于】のもとで匈奴は遊牧民を統合し、強大な遊牧国家を築いた。漢の高祖【劉邦】は匈奴に敗れ、その後漢は絹などを贈る【和親策】をとった。前2世紀後半、【武帝】は匈奴を攻撃し、張騫を【大月氏】に派遣して挟撃を図った。匈奴はのちに東西に分裂し、さらに南北に分裂した。"},
  {"id": "whx489", "s": "wh", "lv": 2, "topic": "楽浪郡", "q": "漢の武帝が朝鮮半島に楽浪郡などを設置したことは、東アジアにどのような影響を与えたか説明せよ。", "a": "前108年、漢の【武帝】は【衛氏朝鮮】を滅ぼし、朝鮮半島に【楽浪郡】など4郡を設置した。楽浪郡は中国文化が朝鮮半島や日本列島に伝わる窓口となった。倭の諸国の中には楽浪郡を通じて漢に使者を送るものもあった。4世紀初め、楽浪郡は【高句麗】によって滅ぼされた。"},
  {"id": "geox61", "s": "geo", "lv": 1, "topic": "サバナ気候", "q": "サバナ気候で雨季と乾季が交互に現れる理由を説明せよ。", "a": "太陽の回帰に伴って気圧帯が南北に季節移動するため。高日季には【赤道低圧帯】がかかって上昇気流により雨が多い【雨季】となり、低日季には【亜熱帯高圧帯】におおわれて下降気流が卓越し【乾季】となる。"},
  {"id": "geox62", "s": "geo", "lv": 1, "topic": "ツンドラ気候", "q": "ツンドラ気候の地域で樹木が育たない理由と、そこでの伝統的な生業を説明せよ。", "a": "最暖月平均気温が10℃未満と夏も低温で、地中には【永久凍土】が広がるため樹木が生育できず、短い夏に【コケ類】や地衣類が育つだけである。人々はそれを飼料とする【トナカイ】の遊牧や狩猟・漁労を営んできた。"},
  {"id": "geox63", "s": "geo", "lv": 2, "topic": "パタゴニアの乾燥", "q": "南アメリカ南部で、アンデス山脈の西側のチリ南部は多雨なのに東側のパタゴニアは乾燥する理由を説明せよ。", "a": "この緯度帯では一年中【偏西風】が吹く。太平洋から湿った風が山脈にぶつかると、風上側のチリ南部で上昇して多量の雨を降らせる。山脈を越えて乾いた風が吹き下ろす風下側は【雨陰】となり、パタゴニアは【ステップ】や砂漠の乾燥した景観となる。"},
  {"id": "geox64", "s": "geo", "lv": 1, "topic": "U字谷", "q": "氷河がつくる谷が、河川がつくる谷と異なる形になる理由を説明せよ。", "a": "河川は主に谷底を下方に削るため断面が【V字谷】になる。これに対し【氷河】は谷全体を埋めて流れ、底だけでなく側面も大きく削るため、谷底が広く谷壁が急な【U字谷】となる。氷河の末端には削られた岩屑が堆積して【モレーン】ができる。"},
  {"id": "geox65", "s": "geo", "lv": 2, "topic": "自然堤防と後背湿地", "q": "氾濫原に見られる自然堤防と後背湿地の成り立ちと、それぞれの伝統的な土地利用を説明せよ。", "a": "洪水で川があふれると、流路のすぐ脇で流速が落ちて砂などの粗い土砂が積もり、微高地の【自然堤防】ができる。その外側には細かい泥が堆積して水はけの悪い低湿地の【後背湿地】ができる。自然堤防は水害を受けにくいので【集落】や畑に、後背湿地は【水田】に利用されてきた。"},
  {"id": "geox66", "s": "geo", "lv": 2, "topic": "海岸段丘", "q": "海岸段丘はどのようにして形成されるか説明せよ。", "a": "波の侵食によって海岸に平坦な【海食台】や海食崖がつくられたのち、土地の【隆起】や海面の低下によって海食台が陸上にあらわれる。これがくり返されると階段状の地形となる。平坦面は【段丘面】、急斜面は段丘崖とよばれ、地震による隆起が多い地域で発達する。"},
  {"id": "geox67", "s": "geo", "lv": 2, "topic": "エスチュアリー", "q": "大河の河口に、三角州ではなくエスチュアリー(三角江)が形成される条件を説明せよ。", "a": "河川が運ぶ【土砂】の量が少なく、さらに【潮汐】の干満差が大きく潮流が強い場合、土砂が河口付近に堆積せず沖へ運ばれる。そのため沈水によってできたラッパ状の河口がそのまま残り【エスチュアリー】となる。水深が大きく【港湾】の立地に適し、テムズ川河口のロンドンなどが発達した。"},
  {"id": "geox68", "s": "geo", "lv": 1, "topic": "砂嘴と砂州", "q": "砂嘴と砂州のちがいと、その成り立ちを説明せよ。", "a": "海岸に沿って流れる【沿岸流】によって運ばれた砂が堆積してできる地形である。一端が陸地についてくちばし状に海へ突き出したものを【砂嘴】、湾の口をふさぐように細長くのびたものを【砂州】という。砂州で閉ざされた水域は【潟湖】(ラグーン)となる。"},
  {"id": "geox69", "s": "geo", "lv": 2, "topic": "アフリカ大地溝帯", "q": "東アフリカにアフリカ大地溝帯が形成されている理由を、プレートの動きから説明せよ。", "a": "東アフリカではプレートが引き離される【広がる境界】が陸上にある。地殻が両側に引っぱられて【正断層】が生じ、中央部が落ち込んで細長い【地溝】ができた。マグマも上昇しやすく、キリマンジャロなどの【火山】や、タンガニーカ湖のような細長く深い湖がつくられている。"},
  {"id": "geox70", "s": "geo", "lv": 2, "topic": "ヒマラヤ山脈の形成", "q": "ヒマラヤ山脈が高く険しい山脈となった理由を説明せよ。", "a": "北上してきた【インド・オーストラリアプレート】上のインド亜大陸が、ユーラシアプレートと【衝突】した。大陸どうしはともに軽く、一方が深く沈み込みにくいため、地層が押し曲げられて大規模に【隆起】し、世界最高峰を含む新期造山帯の大山脈となった。現在も隆起が続いている。"},
  {"id": "geox71", "s": "geo", "lv": 2, "topic": "古期造山帯と石炭", "q": "古期造山帯の山地が新期造山帯と比べてなだらかな理由と、古期造山帯に石炭資源が多い理由を説明せよ。", "a": "古期造山帯は【古生代】に造山運動を受けたのち、長期間の【侵食】を受けたため山容がなだらかである。また古生代後半の【石炭紀】には大森林が繁茂し、その植物が地中で炭化して石炭となったため、アパラチア山脈などの周辺には良質な【石炭】の産地が多い。"},
  {"id": "geox72", "s": "geo", "lv": 2, "topic": "焼畑農業", "q": "熱帯で伝統的に行われてきた焼畑農業のしくみと、近年問題になっている点を説明せよ。", "a": "森林を伐採して焼き、その【草木灰】を肥料としてキャッサバやタロいもなどを栽培する。【地力】が低下すると別の土地へ移り、元の土地は長い休閑期間で森林を回復させるので、本来は持続的な農法である。しかし【人口増加】によって休閑期間が短くなり、森林が回復しないまま耕作がくり返され、【熱帯林】の破壊につながっている。"},
  {"id": "geox73", "s": "geo", "lv": 1, "topic": "遊牧", "q": "乾燥地域で遊牧が行われてきた理由を説明せよ。", "a": "降水量が少なく【農耕】に適さない乾燥地域では、草や水が限られ、同じ場所で家畜を飼い続けると草が食べつくされてしまう。そこで【水】と【牧草】を求めて季節的に移動しながら、羊・ヤギ・ラクダなど乾燥に強い【家畜】を飼育する遊牧が営まれてきた。"},
  {"id": "geox74", "s": "geo", "lv": 2, "topic": "オアシス農業", "q": "乾燥地域のオアシス農業はどのような水源によって成り立っているか、具体例を挙げて説明せよ。", "a": "湧水や【外来河川】、地下水を利用して、ナツメヤシや小麦などを栽培する。イランでは山麓の地下水を【地下水路】で導く【カナート】が用いられ、水の【蒸発】を防ぎながら遠くの耕地まで水を運んでいる。北アフリカではフォガラ、アフガニスタンではカレーズとよばれる。"},
  {"id": "geox75", "s": "geo", "lv": 2, "topic": "フィードロット", "q": "アメリカ合衆国のグレートプレーンズなどで発達したフィードロットとはどのような経営か説明せよ。", "a": "肉牛を出荷前に【肥育】するための大規模な施設で、多数の牛を囲いに集め、トウモロコシや大豆かすなどの【濃厚飼料】を与えて短期間で太らせる。周辺の灌漑による飼料生産と結びついた【企業的牧畜】であり、食肉加工まで一体となって大量生産を行うが、【地下水】の枯渇や糞尿による環境負荷も指摘されている。"},
  {"id": "geox76", "s": "geo", "lv": 3, "topic": "アグリビジネス", "q": "アメリカ合衆国の農業におけるアグリビジネスと穀物メジャーの役割を説明せよ。", "a": "【アグリビジネス】とは、種子・肥料・農業機械の供給から、農産物の加工・流通・販売までを担う農業関連産業をいう。なかでも【穀物メジャー】とよばれる巨大企業は、集荷・貯蔵施設や輸送網をもち、世界の【穀物取引】に大きな影響力をもつ。また【ハイブリッド種子】や遺伝子組換え作物の開発を通じて、生産そのものにも影響を及ぼしている。"},
  {"id": "geox77", "s": "geo", "lv": 1, "topic": "園芸農業", "q": "園芸農業のうち、近郊農業と輸送園芸のちがいを説明せよ。", "a": "園芸農業は野菜・果実・花などを集約的に栽培する農業である。【近郊農業】は大消費地である【大都市】の近くで、鮮度を生かして出荷するものをいう。【輸送園芸】は、【気候】などの条件を生かして遠隔地で生産し、高速道路やフェリーなど交通の発達を背景に大都市へ輸送するものをいう。"},
  {"id": "geox78", "s": "geo", "lv": 1, "topic": "促成栽培と抑制栽培", "q": "日本の促成栽培と抑制栽培について、それぞれ自然条件と結びつけて説明せよ。", "a": "【促成栽培】は、冬でも温暖な高知平野や宮崎平野で、ビニールハウスなどを用いて野菜を他産地より早く出荷する。【抑制栽培】は、夏も冷涼な長野県などの【高冷地】で、キャベツやレタスなどを他産地より遅らせて出荷する。どちらも出荷量の少ない時期に出して【高値】で販売することをねらいとしている。"},
  {"id": "geox79", "s": "geo", "lv": 1, "topic": "アジア式稲作", "q": "モンスーンアジアで稲作がさかんな理由を、自然条件から説明せよ。", "a": "夏に海洋から吹く湿った【季節風】によって高温多雨となり、稲の生育に必要な【高温】と豊富な【水】が得られる。また大河川の下流には肥沃な【沖積平野】や三角州が広がり、水田をつくりやすい。稲は単位面積あたりの収量が多く、多くの人口を養うことができた。"},
  {"id": "geox80", "s": "geo", "lv": 2, "topic": "移牧", "q": "アルプス地方などで行われる移牧とはどのような牧畜か、遊牧との違いにふれて説明せよ。", "a": "【移牧】は、夏には涼しい山地の高地にある牧場(アルプ)へ家畜を移し、冬には【麓】の村の畜舎に戻すというように、季節によって【垂直的】に移動する牧畜である。家族全員が家畜とともに移動を続ける【遊牧】と異なり、生活の拠点となる【定住】の村をもつ点に特色がある。"},
  {"id": "geox81", "s": "geo", "lv": 1, "topic": "潮目", "q": "三陸沖が世界有数の好漁場となっている理由を説明せよ。", "a": "三陸沖では、暖流の【黒潮】(日本海流)と寒流の【親潮】(千島海流)がぶつかる【潮目】(潮境)が形成される。親潮は栄養塩に富み、潮目ではプランクトンがよく繁殖するため、それを食べる魚が集まり、【寒流系】と暖流系の魚がともにとれる好漁場となっている。"},
  {"id": "geox82", "s": "geo", "lv": 2, "topic": "日本の遠洋漁業の衰退", "q": "1970年代以降、日本の遠洋漁業が衰退した理由を説明せよ。", "a": "1970年代に各国が沿岸から200海里までの【排他的経済水域】を設定し、外国船の操業を制限したため、日本の遠洋漁船は従来の漁場を失った。さらに【石油危機】による燃料費の高騰も経営を圧迫した。その後は【養殖業】や栽培漁業が重視され、水産物の【輸入】も増加した。"},
  {"id": "geox83", "s": "geo", "lv": 1, "topic": "養殖業と栽培漁業", "q": "「育てる漁業」とよばれる養殖業と栽培漁業のちがいを説明せよ。", "a": "【養殖業】は、いけすなどで魚介類を出荷できる大きさになるまで人工的に育てて【出荷】する漁業である。【栽培漁業】は、卵からかえした【稚魚】や稚貝をある程度まで育てたのち海や川に【放流】し、自然の中で成長したものを漁獲する漁業である。"},
  {"id": "geox84", "s": "geo", "lv": 2, "topic": "資源ナショナリズム", "q": "第二次世界大戦後、産油国で資源ナショナリズムが高まった背景と、その結果を説明せよ。", "a": "戦後しばらくは、欧米の【国際石油資本】(メジャー)が中東などの油田の採掘から販売までを支配し、産油国の利益は少なかった。これに対し産油国は自国の資源は自国のものとする【資源ナショナリズム】を強め、1960年に【OPEC】を結成した。1970年代には石油産業の【国有化】や原油価格の引き上げを進め、【石油危機】をもたらした。"},
  {"id": "geox85", "s": "geo", "lv": 2, "topic": "レアメタル", "q": "レアメタルが重要視される理由と、供給上の問題点を説明せよ。", "a": "【レアメタル】は、存在量が少ないか取り出すのが難しい金属で、【先端技術産業】の電子部品や電池、特殊鋼などに欠かせない。しかし産出が【中国】や南アフリカなど特定の国に【偏在】しているため、価格の変動や輸出規制などによる供給不安が生じやすい。そこで使用済み製品から回収する【都市鉱山】の活用などが進められている。"},
  {"id": "geox86", "s": "geo", "lv": 2, "topic": "再生可能エネルギーの課題", "q": "太陽光や風力などの再生可能エネルギーの利点と課題を説明せよ。", "a": "【再生可能エネルギー】は、枯渇せず、発電時に【二酸化炭素】をほとんど出さないという利点がある。一方で、発電量が天候や時間帯で変動して【不安定】であり、発電コストが比較的高いことや、広い用地が必要なことが課題である。そのため【蓄電池】の整備や送電網の強化が求められている。"},
  {"id": "geox87", "s": "geo", "lv": 3, "topic": "シェール革命", "q": "2000年代後半以降のアメリカ合衆国におけるシェール革命とその影響を説明せよ。", "a": "地下深くの頁岩層に含まれる【シェールガス】やシェールオイルは、従来は採掘が困難だったが、【水圧破砕法】や水平掘削の技術の進歩によって大量に生産できるようになった。これによりアメリカは世界最大級の【産油国】となり、エネルギーの輸入依存を低下させて輸出も始めた。一方で、地下水の汚染など【環境】への影響も懸念されている。"},
  {"id": "geox88", "s": "geo", "lv": 2, "topic": "市場指向型工業", "q": "ビール工業が大消費地の近くに立地しやすい理由を説明せよ。", "a": "ビールの原料の大部分を占める【水】はどこでも得やすい【普遍原料】であり、製品は原料より重くかさばるようになる。そのため製品を消費地まで運ぶ【輸送費】をおさえることが重要になる。また鮮度も重視されるため、大都市などの消費地に立地する【市場指向型】の工業となる。"},
  {"id": "geox89", "s": "geo", "lv": 2, "topic": "労働力指向型工業", "q": "衣類の縫製などの工場が、発展途上国に多く立地する理由を説明せよ。", "a": "衣類の縫製は機械化が難しく多くの人手を必要とする【労働集約型】の工業であり、生産費に占める【賃金】の割合が大きい。そのため【低賃金】の労働力が豊富な発展途上国に立地する【労働力指向型】工業となる。先進国の企業は生産拠点を中国から、より賃金の安い東南アジアや南アジアへ移しつつある。"},
  {"id": "geox90", "s": "geo", "lv": 2, "topic": "垂直分業と水平分業", "q": "国際分業における垂直分業と水平分業のちがいを説明せよ。", "a": "【垂直分業】は、発展途上国が原料や一次産品を輸出し、先進国が工業製品を輸出するような、【発展段階】の異なる国どうしの分業である。【水平分業】は、先進国どうしが互いに【工業製品】を輸出しあうような、発展段階の近い国どうしの分業である。近年は企業内の工程ごとに国をまたいで分担する【工程間分業】も進んでいる。"},
  {"id": "geox91", "s": "geo", "lv": 1, "topic": "デジタルデバイド", "q": "情報通信技術の普及にともなって問題となっているデジタルデバイドとは何か説明せよ。", "a": "【デジタルデバイド】とは、インターネットなどの【情報通信技術】を利用できる人とできない人との間に生じる格差である。国家間では先進国と【発展途上国】の間に、国内では都市と農村、若者と【高齢者】、所得の高低などの間に生じ、それが情報量や就業機会の差となって経済的な格差をさらに広げるおそれがある。"},
  {"id": "geox92", "s": "geo", "lv": 1, "topic": "散村", "q": "富山県の砺波平野に見られる散村とはどのような村落か。その利点にもふれて説明せよ。", "a": "【散村】は、家屋が一戸ずつ離れて散らばって分布する村落である。砺波平野では、各農家が自分の【耕地】の中に家を建てたため、家のまわりに耕地がまとまり、農作業の移動に便利である。家屋は冬の季節風や火災を防ぐ【屋敷林】に囲まれている。家屋が集まる【集村】と対比される。"},
  {"id": "geox93", "s": "geo", "lv": 1, "topic": "メルカトル図法", "q": "メルカトル図法の特徴と、この図法が航海に用いられた理由を説明せよ。", "a": "メルカトル図法は経線と緯線が直交する円筒図法で、図上の任意の2点を結ぶ直線が【等角航路】となる。この直線と経線との角度を保って進めば目的地に着けるため、【海図】として航海に用いられた。ただし高緯度ほど面積が拡大して表されるため、【面積】や【距離】を比べるのには適さない。"},
  {"id": "geox94", "s": "geo", "lv": 1, "topic": "正距方位図法", "q": "正距方位図法はどのような用途に適しているか。その特徴とともに説明せよ。", "a": "正距方位図法は、図の【中心】からの【距離】と【方位】を正しく表す図法である。中心と任意の地点を結ぶ直線は【大圏航路】(最短経路)となるため、【航空図】に用いられる。ただし中心以外の2点間の距離や方位は正しくなく、外側ほど形のゆがみが大きい。"},
  {"id": "geox95", "s": "geo", "lv": 1, "topic": "ハザードマップ", "q": "ハザードマップの役割と、それを活用するうえで注意すべき点を説明せよ。", "a": "【ハザードマップ】は、洪水・土砂災害・津波などの【自然災害】について、被害が予想される範囲や程度、【避難場所】や避難経路を示した地図である。住民が地域の危険を事前に知り、【防災】や避難に役立てることができる。ただし想定を超える災害も起こりうるため、表示された範囲外なら安全とは限らない点に注意が必要である。"},
  {"id": "geox96", "s": "geo", "lv": 1, "topic": "フェアトレード", "q": "フェアトレードとはどのような取り組みか。その目的とともに説明せよ。", "a": "【フェアトレード】は、発展途上国でつくられた【コーヒー】やカカオなどの農産物や製品を、生産者の生活が成り立つ【適正な価格】で継続的に購入する取り組みである。国際市場価格の変動や買いたたきから【生産者】を守り、生活の改善や自立を支えることを目的としている。"},
  {"id": "geox97", "s": "geo", "lv": 1, "topic": "時差", "q": "東京とロンドンの時差が9時間である理由を説明せよ。", "a": "地球は24時間で360度【自転】するため、経度【15度】ごとに1時間の時差が生じる。ロンドンは経度0度の【本初子午線】を標準時とし、日本は東経【135度】の経線を標準時子午線としている。経度差135度を15度で割ると9となり、東にある日本のほうが9時間進んでいる。"},
  {"id": "geox98", "s": "geo", "lv": 1, "topic": "やませ", "q": "東北地方の太平洋側で、夏にやませが吹くと何が起こりやすいか説明せよ。", "a": "【やませ】は、初夏から夏にかけて【オホーツク海高気圧】から吹き出す冷たく湿った北東風である。寒流の【親潮】の上を通ってさらに冷やされ、東北地方の太平洋側に低温と霧・日照不足をもたらす。そのため稲の生育が妨げられ、【冷害】が起こりやすい。"},
  {"id": "geox99", "s": "geo", "lv": 2, "topic": "ハブ空港", "q": "ハブ空港とは何か。各国が大規模なハブ空港の整備を競う理由とともに説明せよ。", "a": "【ハブ空港】は、自転車の車輪の軸(ハブ)から輻(スポーク)がのびるように、多くの航空路線が集まり、【乗り継ぎ】の拠点となる空港である。ハブ空港には人や貨物が集中し、航空会社の拠点や関連産業が集まるため、国や地域の【経済】に大きな利益をもたらす。そのためシンガポールや韓国などは、長い【滑走路】をもち24時間運用できる空港を整備し、国際的な【拠点】の地位を競っている。"},
  {"id": "geox100", "s": "geo", "lv": 2, "topic": "モーダルシフト", "q": "貨物輸送におけるモーダルシフトとは何か。その目的とともに説明せよ。", "a": "【モーダルシフト】とは、貨物輸送の手段を、主に【トラック】から、大量輸送が可能な【鉄道】や船舶へと転換することである。単位輸送量あたりの【二酸化炭素】排出量を減らして環境への負荷を小さくするとともに、トラック運転手の【人手不足】や道路の混雑への対策にもなる。"},
  {"id": "geox101", "s": "geo", "lv": 2, "topic": "一人っ子政策", "q": "中国の一人っ子政策の目的と、それがもたらした問題を説明せよ。", "a": "1970年代末から、急速な【人口増加】をおさえて経済発展を進めるため、夫婦の子どもを原則1人に制限する【一人っ子政策】が実施された。出生率は大きく低下したが、急速な【少子高齢化】や将来の労働力不足、男児を望む傾向による【男女比】の不均衡などの問題が生じた。そのため2015年に廃止され、2人までの出産が認められた。"},
  {"id": "geox102", "s": "geo", "lv": 2, "topic": "発展途上国のスラム", "q": "発展途上国の大都市でスラムが形成される理由を説明せよ。", "a": "農村の貧困や人口増加を背景に、仕事を求めて多くの人々が大都市に流入する【向都離村】が起きる。しかし工業化が不十分で【雇用】が追いつかないため、人々は露天商などの【インフォーマルセクター】で働き、住宅を得られずに空き地や河川敷などに住みつく。こうして上下水道などの【インフラ】が整わない劣悪な住環境の【スラム】が形成される。"},
  {"id": "geox103", "s": "geo", "lv": 2, "topic": "コンパクトシティ", "q": "日本の地方都市でコンパクトシティが目指されている理由を説明せよ。", "a": "地方都市では、自動車の普及により郊外に住宅や大型商業施設が広がり、中心市街地が衰退して【シャッター通り】が生まれた。人口減少と高齢化が進むなかで市街地が拡散したままだと、道路や上下水道などの【維持費】がかさみ、車を運転できない【高齢者】の生活も不便になる。そこで住宅や公共施設を中心部に集め、【公共交通】で結ぶ【コンパクトシティ】が目指されている。"},
  {"id": "geox104", "s": "geo", "lv": 2, "topic": "ケベック問題", "q": "カナダのケベック州で分離・独立をめぐる運動が起こってきた理由を説明せよ。", "a": "カナダはイギリス系住民が多数を占めるが、ケベック州はかつて【フランス】の植民地であったため、住民の多くが【フランス語】を話す【カトリック】の人々である。言語や文化の違いから、英語系社会の中で独自性を守ろうとする意識が強く、【分離独立】を求める住民投票も行われた。連邦政府は英語とフランス語を【公用語】とし、多文化主義を掲げている。"},
  {"id": "geox105", "s": "geo", "lv": 2, "topic": "白豪主義から多文化主義へ", "q": "オーストラリアが白豪主義を放棄し、多文化主義へと転換した背景を説明せよ。", "a": "オーストラリアは20世紀前半まで、有色人種の移民を制限する【白豪主義】をとっていた。しかしイギリスのEC加盟などでイギリスとの経済関係が弱まり、【アジア】諸国との貿易の重要性が高まった。また労働力確保の必要もあって1970年代に白豪主義を放棄し、アジアからの移民を受け入れ、先住民の【アボリジニ】を含む多様な文化を尊重する【多文化主義】へ転換した。"},
  {"id": "geox106", "s": "geo", "lv": 2, "topic": "砂漠化", "q": "サヘル地域で砂漠化が進行した原因を、自然的要因と人為的要因に分けて説明せよ。", "a": "自然的要因としては、降水量の少ない年が続く【干ばつ】が挙げられる。人為的要因としては、【人口増加】にともなう家畜の【過放牧】や、休閑期間を短くした【過耕作】、燃料用の樹木の【過伐採】が挙げられる。これらにより植生が失われ、土壌が風で飛ばされたり固まったりして、不毛な土地が広がった。"},
  {"id": "geox107", "s": "geo", "lv": 2, "topic": "島嶼国の海面上昇", "q": "ツバルなど太平洋の島嶼国が、地球温暖化の影響を強く受けるとされる理由を説明せよ。", "a": "ツバルなどは【サンゴ礁】の上にできた島からなり、海抜が数メートルしかない。地球温暖化によって海水の【熱膨張】や陸上の氷河の融解が進んで【海面上昇】が起こると、国土の水没や高潮被害の拡大が懸念される。さらに地下水への【塩水】の浸入により飲料水や農作物に被害が出ている。"},
  {"id": "geox108", "s": "geo", "lv": 2, "topic": "アラル海の縮小", "q": "中央アジアのアラル海が急激に縮小した理由と、その影響を説明せよ。", "a": "旧ソ連時代に、アラル海に注ぐアムダリア川・シルダリア川の水を大規模に【灌漑】に利用し、乾燥地で【綿花】の栽培を進めた。その結果、湖に流入する水量が激減して湖面積が大きく縮小した。漁業が壊滅したほか、干上がった湖底から【塩分】を含む砂が舞い上がり、周辺の農地で【塩害】や住民の健康被害が生じた。"},
  {"id": "geox109", "s": "geo", "lv": 2, "topic": "フォッサマグナ", "q": "フォッサマグナとは何か。日本列島の地形区分の上での意義とともに説明せよ。", "a": "【フォッサマグナ】は、本州中央部を南北に横切る大きな【地溝帯】で、その西縁が【糸魚川・静岡構造線】である。これを境に日本列島は【東北日本】と西南日本に分けられ、東北日本では山地が南北に、西南日本では東西に連なる。西南日本は【中央構造線】によってさらに内帯と外帯に分けられる。"},
  {"id": "geox110", "s": "geo", "lv": 2, "topic": "高山気候", "q": "赤道付近のアンデス山脈の高地に、ラパスなどの大都市が発達している理由を説明せよ。", "a": "気温は高度が100m上がるごとに約【0.6℃】低下する。そのため赤道付近でも標高の高い高地は年中温和で、一年中春のような気候となる【高山気候】がみられる。気温の【年較差】は小さく、低地のように暑さや熱帯の病気に悩まされにくいため、【インカ帝国】の時代から人々が住み、ラパスやキトなどの【高山都市】が発達した。"},
  {"id": "geox111", "s": "geo", "lv": 3, "topic": "輸入代替から輸出指向へ", "q": "東南アジア諸国の工業化政策が、輸入代替型から輸出指向型へと転換した理由と、その成果を説明せよ。", "a": "独立後の東南アジア諸国は、輸入していた工業製品を国産化する【輸入代替型】の工業化を進めたが、国内市場が小さく技術も不足していたため行き詰まった。そこで【輸出加工区】を設け、税制上の優遇などで【外国資本】を誘致し、豊富な【低賃金】労働力を生かして製品を海外へ輸出する【輸出指向型】へ転換した。その結果、電気機械などの工業が成長し、【NIEs】やASEAN諸国の急速な経済発展につながった。"},
  {"id": "geox112", "s": "geo", "lv": 3, "topic": "EU東方拡大", "q": "2000年代のEU東方拡大がEU内部にもたらした経済的な変化と課題を説明せよ。", "a": "2004年以降、旧社会主義国の東ヨーロッパ諸国がEUに加盟した。これらの国は【賃金】水準が低いため、西ヨーロッパの企業が自動車などの【生産拠点】を移した。一方、東欧から西欧へ多くの【労働者】が移動し、受け入れ国では雇用をめぐる不満が高まった。また加盟国間の【経済格差】が大きくなり、地域政策による財政負担も増えた。こうした不満はイギリスの【EU離脱】の背景の一つにもなった。"},
  {"id": "geox113", "s": "geo", "lv": 3, "topic": "人口ボーナス", "q": "人口ボーナスとは何か。それが経済発展に与える影響と、その後に生じる課題を説明せよ。", "a": "【人口ボーナス】とは、出生率の低下によって子どもの割合が減る一方、高齢者の割合はまだ低く、【生産年齢人口】の割合が高い状態をいう。扶養負担が軽く、労働力が豊富で【貯蓄】や投資が増えやすいため、経済成長が促進される。しかしその後、高齢化が進むと社会保障の負担が増え、生産年齢人口の割合が下がる【人口オーナス】の時期に入るため、それまでに社会保障制度や産業構造を整える必要がある。"},
  {"id": "geox114", "s": "geo", "lv": 3, "topic": "ジェントリフィケーション", "q": "大都市のジェントリフィケーションとはどのような現象か。その功罪を説明せよ。", "a": "【ジェントリフィケーション】とは、衰退した【インナーシティ】などの古い市街地が再開発され、比較的所得の高い人々が流入して地域が高級化する現象である。治安の改善や商業の活性化、【税収】の増加などの効果がある一方、地価や家賃の【上昇】によって、もとから住んでいた低所得の住民が住み続けられなくなり、【立ち退き】を迫られるという問題がある。"},
  {"id": "geox115", "s": "geo", "lv": 3, "topic": "アスワンハイダム", "q": "エジプトのアスワンハイダム建設がナイル川流域にもたらした効果と問題点を説明せよ。", "a": "1970年に完成したアスワンハイダムにより、ナイル川の【洪水】が制御され、年間を通じた【灌漑】による耕地の拡大や多毛作、水力発電が可能になった。一方で、それまで毎年の氾濫が運んでいた肥沃な土砂が下流に届かなくなり、【化学肥料】への依存が高まった。また灌漑による土壌の【塩害】や、河口の【三角州】の海岸侵食などの問題も生じた。"},
  {"id": "geox116", "s": "geo", "lv": 3, "topic": "黄河の断流", "q": "1990年代を中心に黄河下流で断流が頻発した理由を説明せよ。", "a": "黄河の流域は降水量が少なく、もともと水資源が乏しい。そこに流域での【人口増加】や工業化が進み、中・上流で【灌漑】用水や工業・生活用水を大量に取水したため、河口近くまで水が届かず流れが途切れる【断流】が起こった。下流の農業や生態系に大きな影響が出たため、流域全体での【水資源】の統一的な管理が進められた。"},
  {"id": "geox117", "s": "geo", "lv": 3, "topic": "ケスタ地形", "q": "パリ盆地に見られるケスタ地形の形成過程と、その土地利用を説明せよ。", "a": "緩やかに傾いた【硬軟互層】の地層が侵食を受けると、侵食されやすい軟らかい層が削られて低地となり、侵食に強い硬い層が残って、一方が急崖、他方が緩やかな斜面をなす丘陵の列が形成される。これが【ケスタ】である。パリ盆地では盆地の中心を囲むように同心円状にケスタが並び、急崖の日当たりのよい斜面は【ブドウ】畑に、緩斜面は【小麦】畑などに利用されている。"},
  {"id": "geox118", "s": "geo", "lv": 3, "topic": "EUの共通農業政策", "q": "EUの共通農業政策(CAP)の目的と、それが生んだ問題、その後の改革を説明せよ。", "a": "共通農業政策は、域内の農産物に【統一価格】を設けて買い支える一方、域外からの安い農産物に【課徴金】を課して域内の農業と農家の所得を保護するものである。その結果、【食料自給率】は向上したが、生産過剰による在庫の増大や、EU予算に占める農業関連支出の膨張、輸出補助金による【貿易摩擦】が問題となった。そこで価格支持を引き下げ、農家への【直接支払い】や環境保全を重視する方向へ改革された。"},
  {"id": "geox119", "s": "geo", "lv": 3, "topic": "湾岸産油国の人口構成", "q": "アラブ首長国連邦やカタールなどの湾岸産油国で、人口ピラミッドに男性の割合が著しく大きいという特徴がみられる理由を説明せよ。", "a": "湾岸産油国では【石油】収入をもとに都市開発や大規模な建設事業が進められ、多くの労働力が必要となった。自国民だけでは不足するため、南アジアなどから多数の【外国人労働者】を受け入れている。その多くが単身で出稼ぎに来た【青壮年】の【男性】であるため、人口ピラミッドの生産年齢層で男性の割合が突出して大きくなっている。"},
  {"id": "geox120", "s": "geo", "lv": 3, "topic": "アフリカの国境線", "q": "アフリカに直線的な国境線が多いことは、独立後の国家にどのような問題をもたらしたか説明せよ。", "a": "アフリカの国境の多くは、19世紀末に【ヨーロッパ列強】が植民地分割の際に経線や緯線などを利用して引いた【人為的国境】である。そのため一つの【民族】が複数の国に分断されたり、対立する民族が一つの国に組み込まれたりした。独立後もこの国境が引き継がれたため、民族間の対立による【内戦】や【難民】の発生、国境紛争の原因となった。"},
  {"id": "seikeix61", "s": "seikei", "lv": 1, "topic": "自由権から社会権へ", "q": "20世紀になって、人権の中心が自由権に加えて社会権へと広がった理由を説明せよ。", "a": "18〜19世紀の人権宣言は、国家の干渉を排除する【自由権】を中心としていた。しかし資本主義の発展にともなって貧困や失業、劣悪な労働条件が深刻になり、自由だけでは人間らしい生活が保障されなくなった。そこで国家が積極的に関与して生活を保障する【社会権】が求められ、1919年の【ワイマール憲法】がはじめて【生存権】を規定した。"},
  {"id": "seikeix62", "s": "seikei", "lv": 1, "topic": "象徴天皇制", "q": "日本国憲法における天皇の地位と権能を、大日本帝国憲法と比較して説明せよ。", "a": "大日本帝国憲法では、天皇は【主権者】であり、統治権を総攬する元首とされた。日本国憲法では、天皇は日本国と日本国民統合の【象徴】とされ、その地位は主権の存する国民の総意にもとづく。天皇は国政に関する権能をもたず、【内閣の助言と承認】にもとづいて形式的・儀礼的な【国事行為】のみを行う。"},
  {"id": "seikeix63", "s": "seikei", "lv": 1, "topic": "法の下の平等", "q": "日本国憲法第14条の「法の下の平等」について、最高裁判所の違憲判決の例を挙げて説明せよ。", "a": "憲法第14条は、人種・信条・性別・社会的身分・門地により、政治的・経済的・社会的関係において【差別】されないと定める。最高裁判所はこれにもとづき、尊属殺人を重く罰する規定を違憲とした【尊属殺重罰規定】違憲判決や、結婚していない男女の子(【婚外子】)の【相続分】を半分とする民法の規定を違憲とした判決を出した。"},
  {"id": "seikeix64", "s": "seikei", "lv": 1, "topic": "環境権", "q": "環境権が主張されるようになった背景と、その憲法上の根拠とされる条文を説明せよ。", "a": "高度経済成長期に【公害】が深刻化し、良好な環境のもとで生活する権利の保障が求められるようになった。憲法に明文の規定はないが、第13条の【幸福追求権】と第25条の【生存権】を根拠として、【新しい人権】の一つとして主張されている。大阪空港公害訴訟などで争われたが、最高裁判所は環境権を正面からは認めていない。"},
  {"id": "seikeix65", "s": "seikei", "lv": 1, "topic": "知る権利", "q": "知る権利とはどのような権利か。それを具体化した制度とともに説明せよ。", "a": "【知る権利】は、国民が国や地方公共団体のもつ情報を受け取り、また【公開】を求める権利であり、【国民主権】のもとで政治に参加するための前提となる。憲法第21条の表現の自由などを根拠とする新しい人権である。地方公共団体の情報公開条例に続いて、国では1999年に【情報公開法】が制定された。"},
  {"id": "seikeix66", "s": "seikei", "lv": 1, "topic": "国会の地位", "q": "日本国憲法が国会を「国権の最高機関」かつ「唯一の立法機関」と定めている意味を説明せよ。", "a": "国会は主権者である国民が選んだ代表者で構成されるため、【国権の最高機関】として国政の中心に位置づけられる。また【唯一の立法機関】として、国会以外の機関が法律を制定することは原則として許されず、法律は国会の議決のみで成立する。ただし【三権分立】のもとで、国会の行為も裁判所の【違憲審査】を受ける。"},
  {"id": "seikeix67", "s": "seikei", "lv": 1, "topic": "裁判員制度", "q": "裁判員制度のしくみと、その導入のねらいを説明せよ。", "a": "【裁判員制度】は、くじで選ばれた【18歳以上】の国民が、重大な【刑事裁判】の第一審に参加し、裁判官とともに有罪・無罪と【量刑】を決める制度で、2009年に始まった。司法に国民の感覚を反映させ、司法に対する国民の理解と【信頼】を高めることをねらいとしている。"},
  {"id": "seikeix68", "s": "seikei", "lv": 1, "topic": "地方自治の本旨", "q": "日本国憲法がいう「地方自治の本旨」の二つの要素を説明せよ。", "a": "一つは、地域の政治をその地域の【住民】の意思にもとづいて行う【住民自治】である。もう一つは、地方公共団体が国から【独立】して、自らの権限と責任で地域の政治を行う【団体自治】である。地方自治は住民が身近な政治に参加する機会となり、「【民主主義の学校】」ともよばれる。"},
  {"id": "seikeix69", "s": "seikei", "lv": 1, "topic": "選挙の原則", "q": "民主的な選挙の基本原則を四つ挙げ、それぞれ説明せよ。", "a": "一定の年齢に達したすべての国民に選挙権を認める【普通選挙】、一人一票で票の価値を等しくする【平等選挙】、有権者が代表者を直接選ぶ【直接選挙】、だれに投票したかを秘密にする【秘密選挙】である。秘密選挙は、投票者が圧力を受けずに自由な意思で投票できるようにするためのものである。"},
  {"id": "seikeix70", "s": "seikei", "lv": 2, "topic": "明治憲法との比較", "q": "大日本帝国憲法と日本国憲法における人権保障のちがいを説明せよ。", "a": "大日本帝国憲法では、権利は天皇が恩恵として与えた【臣民の権利】とされ、【法律の留保】がつけられていたため、法律によっていくらでも制限することができた。これに対し日本国憲法は、基本的人権を人が生まれながらにもつ【永久の権利】として保障し、法律によっても侵すことのできないものとした。さらに【社会権】も新たに規定した。"},
  {"id": "seikeix71", "s": "seikei", "lv": 2, "topic": "憲法第9条と自衛隊", "q": "日本国憲法第9条と自衛隊の関係について、政府の解釈を説明せよ。", "a": "憲法第9条は【戦争の放棄】、戦力の不保持、交戦権の否認を定めている。政府は、主権国家には固有の【自衛権】があり、自衛のための必要最小限度の実力は第9条が禁じる【戦力】にあたらないとして、【自衛隊】は合憲であるという立場をとっている。この解釈のもとで、海外での武力行使などには制約があると説明されてきた。"},
  {"id": "seikeix72", "s": "seikei", "lv": 2, "topic": "自己決定権", "q": "自己決定権とはどのような権利か。医療の場面を例に説明せよ。", "a": "【自己決定権】とは、自分の生き方や生活にかかわる重要なことがらを、他者から干渉されずに自分で決める権利であり、憲法第13条の【幸福追求権】を根拠とする。医療の場面では、医師が病状や治療法について十分に説明し、患者が理解・納得したうえで治療方法を選ぶ【インフォームド・コンセント】が重視される。宗教上の理由による【輸血拒否】をめぐる裁判では、患者の意思決定の権利が尊重された。"},
  {"id": "seikeix73", "s": "seikei", "lv": 2, "topic": "国政調査権", "q": "国会の国政調査権の内容と、その行使の限界を説明せよ。", "a": "【国政調査権】は、各議院が国政に関して調査を行い、【証人】の出頭・証言や記録の提出を求めることができる権限であり、内閣の行政を監視する役割をもつ。ただし、裁判の内容に立ち入って批判するなど【司法権の独立】を侵すような調査や、個人の【人権】を不当に侵害する調査は許されないとされる。"},
  {"id": "seikeix74", "s": "seikei", "lv": 2, "topic": "裁判官の罷免", "q": "日本国憲法のもとで、裁判官の身分はどのように保障され、どのような場合に罷免されるか説明せよ。", "a": "裁判官は【司法権の独立】を守るため身分が保障され、行政機関による懲戒処分は禁じられている。罷免されるのは、心身の故障で職務を行えないと裁判で決定された場合と、国会に設けられた【弾劾裁判所】で罷免の判決を受けた場合に限られる。また【最高裁判所】の裁判官は、これに加えて【国民審査】で罷免を可とする票が多数となった場合に罷免される。"},
  {"id": "seikeix75", "s": "seikei", "lv": 2, "topic": "直接請求権", "q": "地方自治における直接請求権について、請求の種類とその手続きを説明せよ。", "a": "住民は一定数の署名を集めて直接請求ができる。【条例】の制定・改廃と【事務の監査】は、有権者の50分の1以上の署名で、それぞれ首長と監査委員に請求する。議会の解散や首長・議員の【解職】(リコール)は、原則として有権者の3分の1以上の署名で【選挙管理委員会】に請求し、【住民投票】で過半数の同意があれば成立する。"},
  {"id": "seikeix76", "s": "seikei", "lv": 2, "topic": "圧力団体", "q": "圧力団体と政党のちがいを説明し、圧力団体の功罪を述べよ。", "a": "【政党】は政権の獲得をめざして政策を掲げるのに対し、【圧力団体】(利益集団)は政権の獲得はめざさず、経済団体や労働組合のように特定の【利益】の実現のために政府や議員に働きかける。議会に反映されにくい多様な国民の要求を政治に伝える機能をもつ一方、資金力などにより特定の集団の利益が優先され、【政官財】の癒着や汚職を生むおそれがある。"},
  {"id": "seikeix77", "s": "seikei", "lv": 2, "topic": "世論とマスメディア", "q": "民主政治においてマスメディアが果たす役割と、その問題点を説明せよ。", "a": "マスメディアは、政治に関する情報を国民に伝えて【世論】の形成を助け、権力を監視する役割から「第四の権力」ともよばれる。一方で、報道内容の取捨選択によって世論を特定の方向へ導く【世論操作】や、商業主義による扇情的な報道のおそれもある。そのため受け手には、情報を批判的に読み解く【メディア・リテラシー】が求められる。"},
  {"id": "seikeix78", "s": "seikei", "lv": 2, "topic": "政党交付金", "q": "1994年に導入された政党交付金制度の目的と、その問題点を説明せよ。", "a": "1990年代初めの汚職事件などで【政治とカネ】の問題が批判され、企業などからの【政治献金】への依存を減らすため、【政党助成法】により国が一定の要件を満たした政党に【政党交付金】を交付する制度が導入された。財源は【税金】であるため、支持していない政党にも国民の負担が回ることや、政党の国への依存が強まることなどが問題点として指摘される。"},
  {"id": "seikeix79", "s": "seikei", "lv": 2, "topic": "行政国家", "q": "20世紀に行政国家化が進んだ理由と、それにともなう問題点を説明せよ。", "a": "福祉国家として国家が経済や社会保障に積極的に関与するようになると、行政の役割が拡大し、専門的な知識をもつ【官僚】の影響力が強まった。法律では大枠だけを定めて具体的な内容を政令などに任せる【委任立法】も増えた。その結果、選挙で選ばれた議会による【行政の統制】が弱まり、【官僚制】の肥大化や天下りなどの問題が生じた。"},
  {"id": "seikeix80", "s": "seikei", "lv": 2, "topic": "オンブズマン制度", "q": "オンブズマン制度とはどのような制度か。その目的と日本での導入状況を説明せよ。", "a": "【オンブズマン制度】は、【スウェーデン】で始まった制度で、議会などが任命した第三者が、行政に対する住民の苦情を受けつけて調査し、是正を勧告するものである。【行政の監視】と住民の権利救済を目的とする。日本では国レベルの制度はないが、1990年の【川崎市】をはじめ、一部の地方公共団体で導入されている。"},
  {"id": "seikeix81", "s": "seikei", "lv": 2, "topic": "行政委員会", "q": "行政委員会とはどのような機関か。一般の行政機関から独立して設けられる理由とともに説明せよ。", "a": "【行政委員会】は、公正取引委員会や国家公安委員会のように、内閣や首長から一定の【独立】性をもって職務を行う合議制の機関である。【政治的中立】性や専門性が求められる分野で、特定の政党や政治的圧力に左右されずに公正な行政を行うために設けられる。規則を定める【準立法】的機能や、争いを裁定する【準司法】的機能をもつものもある。"},
  {"id": "seikeix82", "s": "seikei", "lv": 2, "topic": "国際司法裁判所", "q": "国際司法裁判所の役割と、その限界を説明せよ。", "a": "【国際司法裁判所】は国連の主要機関で、オランダの【ハーグ】に置かれ、国家間の紛争を国際法にもとづいて裁判する。しかし裁判を始めるには原則として紛争の【当事国】双方の【同意】が必要であり、一方が拒否すれば裁判は行えない。また個人を裁くことはできず、戦争犯罪などを犯した個人は2003年に発足した【国際刑事裁判所】が裁く。"},
  {"id": "seikeix83", "s": "seikei", "lv": 2, "topic": "PKO", "q": "国連の平和維持活動(PKO)の性格と、日本の参加の経緯を説明せよ。", "a": "【PKO】は、国連憲章に明文の規定はないが、紛争地域で【停戦監視】や選挙監視などを行い、紛争の再発を防ぐ活動である。原則として紛争当事者の【同意】を得て、中立的立場で行われる点で、強制措置とは異なる。日本は1992年に【PKO協力法】を制定し、【カンボジア】に初めて自衛隊を派遣した。参加には停戦合意の成立など五原則が設けられている。"},
  {"id": "seikeix84", "s": "seikei", "lv": 3, "topic": "表現の自由の優越的地位", "q": "表現の自由が経済的自由よりも手厚く保障されるべきだとする「二重の基準」の考え方を説明せよ。", "a": "表現の自由などの【精神的自由】は、民主政治の過程を支える権利であり、いったん不当に制限されると選挙などの民主的な過程によって是正することが難しい。一方、【経済的自由】の制限は、民主的な過程で是正しうるうえ、社会・経済政策上の判断は議会の裁量にゆだねられる面が大きい。そこで裁判所は、精神的自由を規制する法律については【経済的自由】の場合より厳格な基準で【違憲審査】を行うべきだとするのが【二重の基準】論である。"},
  {"id": "seikeix85", "s": "seikei", "lv": 3, "topic": "外国人の人権", "q": "日本に在留する外国人の人権保障について、判例の考え方をふまえて説明せよ。", "a": "最高裁判所は【マクリーン事件】判決で、基本的人権の保障は、権利の【性質】上日本国民のみを対象とするものを除き、在留外国人にも及ぶとした。ただしそれは在留制度の枠内で与えられるものとされる。【参政権】のうち国政選挙の選挙権は認められていないが、【地方参政権】については、定住外国人に法律で選挙権を与えることは憲法上禁止されていないとする判断が示されている。"},
  {"id": "seikeix86", "s": "seikei", "lv": 3, "topic": "二院制の意義", "q": "日本の国会が二院制をとる意義と、参議院の存在をめぐる議論を説明せよ。", "a": "二院制は、慎重な審議によって一院の【行き過ぎ】を抑え、多様な民意を反映させる意義をもつ。参議院は任期6年で【解散】がなく、3年ごとに半数を改選するため、長期的視野からの審議が期待される。一方、選挙制度が衆議院と似て独自性に乏しく「【衆議院のカーボンコピー】」との批判がある。また両院の多数派が異なる【ねじれ国会】では、法案が成立しにくく政治が停滞するとの指摘もある。"},
  {"id": "seikeix87", "s": "seikei", "lv": 3, "topic": "憲法改正の手続き", "q": "日本国憲法の改正手続きを説明し、それが「硬性憲法」とよばれる理由を述べよ。", "a": "憲法改正は、各議院の【総議員の3分の2以上】の賛成で国会が発議し、【国民投票】で過半数の賛成を得て承認され、天皇が国民の名で公布する。国民投票の具体的な手続きは2007年制定の国民投票法で定められた。通常の法律の改正よりも厳しい手続きが求められるため【硬性憲法】とよばれ、これは憲法が国の【最高法規】として、時の多数派による安易な変更から【人権】を守る意味をもつ。"},
  {"id": "seikeix88", "s": "seikei", "lv": 3, "topic": "人道的介入", "q": "冷戦後に議論されるようになった人道的介入と「保護する責任」について、その意義と問題点を説明せよ。", "a": "冷戦後、民族紛争などで大規模な人権侵害が起きても、【内政不干渉】の原則のもとで国際社会が十分に対応できない事態が生じた。1999年にはNATOが安保理決議を経ずに【コソボ】紛争でユーゴスラビアを空爆し、【人道的介入】の是非が問われた。2005年の国連首脳会合では、国家が自国民を守れない場合に国際社会が対応する「【保護する責任】」が確認されたが、大国による【武力行使】の口実に利用されるおそれも指摘されている。"},
  {"id": "seikeix89", "s": "seikei", "lv": 3, "topic": "核抑止と核軍縮", "q": "核拡散防止条約(NPT)と核兵器禁止条約の内容を比較し、核軍縮をめぐる対立を説明せよ。", "a": "【NPT】は、1967年以前に核実験を行った5か国に核保有を認め、それ以外の国の核保有を禁じる一方、保有国に【核軍縮】の交渉義務を課している。しかし保有国と非保有国の間の【不平等】性が批判されてきた。2017年に採択された【核兵器禁止条約】は核兵器の保有や使用を全面的に禁止するが、核保有国や、核の傘による【核抑止】に依存する日本などは参加しておらず、抑止論と廃絶論の対立が続いている。"},
  {"id": "seikeix90", "s": "seikei", "lv": 1, "topic": "需要曲線のシフト", "q": "ある商品の価格が変化した場合と、消費者の所得が増加した場合とで、需要曲線の上での変化がどう異なるか説明せよ。", "a": "商品自体の【価格】が変化した場合は、需要曲線そのものは動かず、曲線上を移動して需要量が変化する。これに対し、所得の増加など価格以外の条件が変化すると、どの価格でも需要量が増えるため【需要曲線】全体が【右】へ【シフト】する。その結果、供給曲線との交点が移動し、【均衡価格】は上昇し、取引量も増加する。"},
  {"id": "seikeix91", "s": "seikei", "lv": 1, "topic": "独占禁止法", "q": "独占禁止法の目的と、その運用にあたる機関について説明せよ。", "a": "【独占禁止法】は1947年に制定され、市場での【公正】かつ自由な競争を促進して、消費者の利益を守ることを目的とする。企業が他社を排除して市場を支配する私的独占や、企業どうしが価格や生産量を協定する【カルテル】などを禁止している。その運用には、内閣から独立した行政委員会である【公正取引委員会】があたる。"},
  {"id": "seikeix92", "s": "seikei", "lv": 1, "topic": "企業の社会的責任", "q": "企業の社会的責任(CSR)とはどのような考え方か。具体例を挙げて説明せよ。", "a": "【CSR】とは、企業は利潤を追求するだけでなく、社会の一員として、従業員・消費者・地域社会などの【ステークホルダー】(利害関係者)に対して責任を果たすべきだという考え方である。法令を守る【コンプライアンス】の徹底や環境保全、情報開示に加え、芸術・文化活動を支援する【メセナ】や慈善活動などの社会貢献も含まれる。"},
  {"id": "seikeix93", "s": "seikei", "lv": 1, "topic": "直接税と間接税", "q": "直接税と間接税のちがいを説明し、それぞれの長所を述べよ。", "a": "【直接税】は所得税のように納税者と税を負担する者が同じ税であり、【間接税】は消費税のように納税者と負担者が異なる税である。直接税は【累進課税】によって所得の多い人ほど多く負担させることができ、所得の再分配に役立つ。間接税は景気の影響を受けにくく【税収】が安定しており、所得の捕捉の不公平も生じにくい。"},
  {"id": "seikeix94", "s": "seikei", "lv": 1, "topic": "戦後の経済民主化", "q": "第二次世界大戦後、GHQの指令によって進められた経済の民主化政策を三つ挙げて説明せよ。", "a": "第一は、戦争に協力した巨大な企業集団を解体した【財閥解体】である。第二は、地主の土地を政府が買い上げて小作人に売り渡し、【自作農】を大量に生み出した【農地改革】である。第三は、労働組合法などの労働三法を制定して労働者の権利を保障した【労働の民主化】である。これらは戦後の経済成長の土台となった。"},
  {"id": "seikeix95", "s": "seikei", "lv": 1, "topic": "男女雇用機会均等法", "q": "男女雇用機会均等法が制定された背景と、その後の改正の内容を説明せよ。", "a": "1979年に国連で採択された【女子差別撤廃条約】を日本が批准するため、1985年に【男女雇用機会均等法】が制定された。当初は募集・採用や配置・昇進での男女の均等な扱いは事業主の【努力義務】にとどまっていたが、1997年の改正で【差別】の禁止が義務化され、【セクシュアル・ハラスメント】の防止についても事業主に配慮が求められるようになった。"},
  {"id": "seikeix96", "s": "seikei", "lv": 1, "topic": "クーリング・オフ", "q": "クーリング・オフ制度とは何か。設けられている理由とともに説明せよ。", "a": "【クーリング・オフ】は、【訪問販売】や電話勧誘販売などで契約した場合に、一定の期間内であれば、理由を問わず書面などで無条件に契約を【解除】できる制度である。不意打ち的な勧誘を受けた消費者は、冷静に判断できないまま契約してしまうことが多いため、【消費者保護】の観点から頭を冷やして考え直す機会を与えている。店舗での通常の買い物には適用されない。"},
  {"id": "seikeix97", "s": "seikei", "lv": 1, "topic": "夜警国家と福祉国家", "q": "夜警国家と福祉国家のちがいを、国家の役割の観点から説明せよ。", "a": "【夜警国家】は、自由放任主義のもとで、国家の役割を国防や治安の維持など最小限にとどめる「小さな政府」である。これに対し【福祉国家】は、世界恐慌などを経て、国家が経済に積極的に介入し、【社会保障】の充実や【完全雇用】の実現によって国民の生活を保障する「【大きな政府】」である。"},
  {"id": "seikeix98", "s": "seikei", "lv": 1, "topic": "国民皆保険", "q": "日本の国民皆保険・皆年金はいつ、どのように実現したか説明せよ。", "a": "それまで医療保険や年金に加入していなかった自営業者や農業従事者なども対象とする【国民健康保険】と【国民年金】の制度が整えられ、1961年に、すべての国民が何らかの公的な医療保険と年金に加入する【国民皆保険】・皆年金が実現した。これにより【社会保険】を中心とする日本の社会保障制度の骨格がつくられた。"},
  {"id": "seikeix99", "s": "seikei", "lv": 2, "topic": "所有と経営の分離", "q": "株式会社において「所有と経営の分離」が進む理由と、それにともなう問題を説明せよ。", "a": "株式会社は多数の【株主】から資本を集めるため、大企業になるほど株式が分散し、個々の株主が経営に直接かかわることは難しくなる。そのため経営は専門的な能力をもつ【経営者】に任され、【所有と経営の分離】が進む。その結果、経営者が株主の利益に反する行動をとるおそれが生じるため、株主総会や社外取締役などによる経営の監視、すなわち【コーポレート・ガバナンス】の強化が求められる。"},
  {"id": "seikeix100", "s": "seikei", "lv": 2, "topic": "GDPの限界", "q": "国内総生産(GDP)が国民の豊かさを測る指標として不十分だとされる理由を説明せよ。", "a": "GDPは市場で取引された財・サービスの【付加価値】の合計であるため、【家事労働】やボランティアのように市場で取引されない活動は含まれない。一方で、公害による健康被害の治療費や環境破壊をもたらす生産も加算され、【環境】の悪化や余暇の価値は反映されない。そこで環境破壊を差し引いた【グリーンGDP】や、国民純福祉(NNW)などの指標も考案されている。"},
  {"id": "seikeix101", "s": "seikei", "lv": 2, "topic": "名目と実質の経済成長率", "q": "名目経済成長率と実質経済成長率のちがいを説明し、デフレ期に両者の関係がどうなるか述べよ。", "a": "【名目経済成長率】はその時々の市場価格で測ったGDPの伸び率であり、【実質経済成長率】はそこから【物価変動】の影響を取り除いた伸び率である。物価が上昇するインフレ期には名目が実質を上回るが、物価が下落する【デフレ】期には、生産量が増えていても価格が下がるため、名目成長率が実質成長率を下回る【名実逆転】が生じる。"},
  {"id": "seikeix102", "s": "seikei", "lv": 2, "topic": "スタグフレーション", "q": "1970年代に先進国でみられたスタグフレーションとは何か。それが経済政策にもたらした困難とともに説明せよ。", "a": "【スタグフレーション】とは、景気停滞(スタグネーション)と【インフレーション】が同時に進む現象である。1970年代には【石油危機】による原油価格の高騰で生産費が上昇する【コストプッシュ・インフレ】が起き、同時に不況が進んだ。景気を刺激すれば物価がさらに上がり、物価を抑えれば不況が深まるため、従来の【ケインズ】的な需要管理政策では対応が難しくなった。"},
  {"id": "seikeix103", "s": "seikei", "lv": 2, "topic": "財政投融資", "q": "財政投融資とは何か。2001年の改革でその資金の調達方法がどう変わったか説明せよ。", "a": "【財政投融資】は、国が有償の資金を用いて、政府系金融機関や独立行政法人などを通じて、社会資本の整備や中小企業への融資などを行うもので、「第二の予算」ともよばれた。かつては【郵便貯金】や年金積立金が自動的に原資とされていたため、規模が膨らみ非効率な事業も生まれた。2001年の改革でこの仕組みは廃止され、国が【財投債】を発行したり、各機関が【財投機関債】を発行したりして、市場から資金を調達するようになった。"},
  {"id": "seikeix104", "s": "seikei", "lv": 2, "topic": "租税の公平", "q": "租税における「水平的公平」と「垂直的公平」のちがいを説明せよ。", "a": "【水平的公平】とは、同じ経済力(所得)をもつ人は同じ税負担をすべきだという考え方である。【垂直的公平】とは、経済力の大きい人ほど多くの税を負担すべきだという考え方で、所得税の【累進課税】がこれにあたる。消費税は所得の低い人ほど負担率が高くなる【逆進性】をもつため、垂直的公平の点で問題があるとされる。"},
  {"id": "seikeix105", "s": "seikei", "lv": 2, "topic": "高度成長期の経済的要因", "q": "1950年代半ばから1970年代初めまで続いた日本の高度経済成長の要因を説明せよ。", "a": "国民の高い【貯蓄率】に支えられ、銀行を通じて企業に資金が供給され、活発な【設備投資】と技術革新が進んだ。また農村から都市へ豊富な【労働力】が供給された。さらに1ドル=360円の【固定相場制】のもとでの円安や、安価な【石油】の輸入も輸出と生産の拡大を助けた。所得の上昇は耐久消費財への旺盛な消費を生み、国内市場も拡大した。"},
  {"id": "seikeix106", "s": "seikei", "lv": 2, "topic": "石油危機と産業構造の転換", "q": "石油危機をきっかけに、日本の産業構造はどのように変化したか説明せよ。", "a": "1973年の【第一次石油危機】で原油価格が高騰し、エネルギーを大量に消費する鉄鋼・石油化学などの【重厚長大】型産業は打撃を受けた。企業は【省エネルギー】や減量経営を進め、産業の中心は、エレクトロニクスや自動車など付加価値の高い加工組立型産業へと移った。こうして知識や技術を重視する【知識集約型】の【軽薄短小】型産業が成長した。"},
  {"id": "seikeix107", "s": "seikei", "lv": 2, "topic": "中小企業の二重構造", "q": "日本経済における「二重構造」とは何か。中小企業がおかれてきた立場とともに説明せよ。", "a": "【二重構造】とは、近代的な【大企業】と、前近代的な【中小企業】の間に、資本装備率・生産性・【賃金】などで大きな格差が存在する状態をいう。中小企業の多くは大企業の【下請け】として系列に組み込まれ、不況時には発注の削減や単価の引き下げを受ける「景気の調整弁」とされてきた。一方で、独自の技術をもつ【ベンチャー企業】など、経済の活力の源となる中小企業もある。"},
  {"id": "seikeix108", "s": "seikei", "lv": 2, "topic": "非正規雇用の増加", "q": "1990年代以降、日本で非正規雇用が増加した理由と、それにともなう問題を説明せよ。", "a": "【バブル崩壊】後の長期不況や国際競争の激化のなかで、企業は【人件費】を抑え、景気に応じて雇用量を調整しやすいパートや派遣などの【非正規雇用】を増やした。【労働者派遣法】の改正による規制緩和もこれを後押しした。非正規雇用は正規雇用に比べて賃金が低く雇用も不安定なため、働いても生活が苦しい【ワーキングプア】や格差の拡大が問題となり、【同一労働同一賃金】の取り組みが進められている。"},
  {"id": "seikeix109", "s": "seikei", "lv": 2, "topic": "日本型雇用慣行", "q": "日本型雇用慣行の三つの特徴を挙げ、それが変化しつつある理由を説明せよ。", "a": "日本型雇用慣行は、定年まで同じ企業で働く【終身雇用】、勤続年数に応じて賃金が上がる【年功序列型賃金】、企業ごとに労働組合を組織する【企業別労働組合】を特徴とする。従業員の企業への帰属意識を高めたが、低成長期に入り、グローバル化による競争の激化や中高年層の人件費の負担増から、【成果主義】の導入や中途採用の拡大など、雇用の流動化が進んでいる。"},
  {"id": "seikeix110", "s": "seikei", "lv": 2, "topic": "製造物責任法", "q": "製造物責任法(PL法)は、消費者の被害救済にどのような変化をもたらしたか説明せよ。", "a": "従来の民法では、欠陥製品で被害を受けた消費者が損害賠償を求めるには、製造業者の【過失】を証明する必要があり、専門知識をもたない消費者には困難であった。1995年に施行された【製造物責任法】では、製品の【欠陥】によって被害が生じたことを証明すれば、製造業者の過失を証明しなくても賠償を受けられるようになった。これを【無過失責任】という。"},
  {"id": "seikeix111", "s": "seikei", "lv": 2, "topic": "国際連盟と国際連合", "q": "国際連盟と国際連合を比較し、国際連合が国際連盟の欠陥をどのように改めようとしたか説明せよ。", "a": "国際連盟は、総会などの議決が原則【全会一致】で意思決定が難しく、制裁も【経済制裁】が中心であった。またアメリカが参加せず、日本・ドイツなどが脱退して機能を失った。これに対し国際連合は【多数決】制を採用し、安全保障理事会の決定にもとづいて【軍事的措置】をとることも可能とした。また大国の協調を重視し、【五大国】に拒否権を与えた。"},
  {"id": "seikeix112", "s": "seikei", "lv": 2, "topic": "難民問題", "q": "難民条約における難民の定義と、難民の保護をめぐる課題を説明せよ。", "a": "【難民条約】は、人種・宗教・国籍・政治的意見などを理由に迫害を受けるおそれがあるために国外に逃れた人を難民と定め、迫害の危険のある国へ送還してはならないという【ノン・ルフールマン】の原則を定めている。しかし紛争などで国内にとどまる【国内避難民】は条約の対象外である。難民の支援には【UNHCR】があたるが、受け入れ国の負担は大きく、日本は難民【認定】数が少ないことが指摘されている。"},
  {"id": "seikeix113", "s": "seikei", "lv": 2, "topic": "ブレトンウッズ体制", "q": "第二次世界大戦後のブレトンウッズ体制のしくみと、その目的を説明せよ。", "a": "1930年代のブロック経済と為替切り下げ競争が戦争の一因になった反省から、1944年の協定によって【IMF】と国際復興開発銀行(世界銀行)が設立された。ドルを【金】と一定の比率で交換できる基軸通貨とし、各国通貨をドルに対して【固定相場制】で結びつけることで、為替を安定させ【自由貿易】の拡大をはかった。日本は1ドル=360円とされた。"},
  {"id": "seikeix114", "s": "seikei", "lv": 2, "topic": "京都議定書とパリ協定", "q": "地球温暖化対策における京都議定書とパリ協定のちがいを説明せよ。", "a": "1997年の【京都議定書】は、先進国にのみ温室効果ガスの削減の【数値目標】を義務づけ、発展途上国には義務を課さなかったため、排出量の多い中国などが対象外となり、アメリカも離脱した。2015年の【パリ協定】は、気温上昇を産業革命前から2℃未満に抑えることを目標とし、発展途上国を含む【すべての国】が削減目標を自ら定めて提出し、【取り組み】を報告することとした。"},
  {"id": "seikeix115", "s": "seikei", "lv": 3, "topic": "価格弾力性", "q": "需要の価格弾力性とは何か。農産物が豊作になると農家の収入がかえって減ることがある理由を、これを用いて説明せよ。", "a": "【需要の価格弾力性】とは、価格の変化に対して需要量がどの程度変化するかを示す度合いである。米や野菜などの【生活必需品】は、安くなっても消費量はあまり増えないため弾力性が小さい。そのため豊作で供給が増えると、需要量をわずかに増やすだけで価格が大きく【下落】し、販売量の増加を価格の低下が上回って収入が減る。これを【豊作貧乏】という。"},
  {"id": "seikeix116", "s": "seikei", "lv": 3, "topic": "プラザ合意", "q": "1985年のプラザ合意の内容と、それが日本経済に与えた影響を説明せよ。", "a": "1980年代前半のアメリカは高金利でドル高となり、巨額の【貿易赤字】を抱えていた。1985年、先進5か国(G5)は【ドル高】を是正するための協調介入に合意した(【プラザ合意】)。その結果急速な【円高】が進み、日本の輸出産業は打撃を受けて円高不況となった。日本銀行は不況対策として低金利政策をとり、その余剰資金が株や土地に流れて【バブル経済】が生じた。また製造業の【海外移転】が進んだ。"},
  {"id": "seikeix117", "s": "seikei", "lv": 3, "topic": "コメの市場開放", "q": "戦後日本のコメ政策が、食糧管理制度から市場開放へとどのように変化したか説明せよ。", "a": "戦時中に始まった【食糧管理制度】のもとで、政府はコメを農家から買い入れて消費者に売る形で価格と流通を管理してきた。しかし生産過剰と財政負担から1970年代に【減反政策】が始まった。1993年の【ウルグアイ・ラウンド】の合意で一定量の輸入(【ミニマム・アクセス】)を受け入れ、1995年には食糧法の施行により流通が自由化された。1999年には輸入制限を関税に置き換える【関税化】が実施された。"},
  {"id": "seikeix118", "s": "seikei", "lv": 3, "topic": "ユーロの課題", "q": "単一通貨ユーロの導入がもたらした利点と、ユーロ圏が抱える構造的な課題を説明せよ。", "a": "ユーロの導入により、加盟国間では為替変動のリスクや両替の手間がなくなり、貿易や投資が活発になった。金融政策は【欧州中央銀行】が一元的に担う。しかし【財政政策】は各国に残されているため、景気の状況が異なる国々に同じ金利を適用せざるをえず、不況国は自国通貨の切り下げや独自の【金融政策】も使えない。2009年以降の【ギリシャ】の財政危機は、こうした【通貨統合】と財政の分立という矛盾を浮き彫りにした。"},
  {"id": "seikeix119", "s": "seikei", "lv": 3, "topic": "ポリシー・ミックス", "q": "ポリシー・ミックスとは何か。不況期に財政政策と金融政策を組み合わせる理由を説明せよ。", "a": "【ポリシー・ミックス】とは、景気の安定や物価の安定などの複数の政策目標を達成するため、【財政政策】と【金融政策】などを組み合わせて実施することである。不況期に公共投資の拡大や減税だけを行うと、国債の大量発行で資金需要が増えて金利が上昇し、民間の投資を抑えてしまう【クラウディング・アウト】が起こりうる。そこで同時に【金融緩和】を行って金利の上昇を抑え、景気回復の効果を高める。"},
  {"id": "seikeix120", "s": "seikei", "lv": 3, "topic": "保護貿易論", "q": "リストの保護貿易論の内容を、リカードの自由貿易論と比較して説明せよ。", "a": "リカードは【比較生産費説】にもとづき、各国が得意な産業に特化して自由に貿易すれば双方が利益を得るとして【自由貿易】を主張した。これに対し19世紀ドイツの【リスト】は、経済には発展段階があり、工業化の遅れた国が自由貿易を行えば先進国の工業製品に圧倒されると考えた。そのため将来成長が見込まれる【幼稚産業】を、成長するまで【関税】などで一時的に保護すべきだと主張した。"},
  {"id": "rinrix41", "s": "rinri", "lv": 1, "topic": "ソフィスト", "q": "ソフィストの思想の特徴と、それに対するソクラテスの立場を説明せよ。", "a": "ソフィストは、民主政のアテネで報酬を受けて【弁論術】などを教えた職業教師である。プロタゴラスは「【人間は万物の尺度】である」と述べ、真理や善悪は人それぞれの判断によるとする【相対主義】の立場をとった。これに対しソクラテスは、対話を通じて誰にとっても成り立つ【普遍的】な真理や徳を探究しようとした。"},
  {"id": "rinrix42", "s": "rinri", "lv": 1, "topic": "アルケー", "q": "古代ギリシアの自然哲学者たちは何を探究したか。代表的な人物の考えを挙げて説明せよ。", "a": "自然哲学者たちは、神話(ミュトス)による説明から離れ、理性(【ロゴス】)によって万物の根源である【アルケー】を探究した。【タレス】はそれを水であるとし、ヘラクレイトスは「万物は流転する」と説いて火を根源とした。またデモクリトスは、それ以上分割できない【原子】(アトム)が万物を構成すると考えた。"},
  {"id": "rinrix43", "s": "rinri", "lv": 1, "topic": "六信五行", "q": "イスラームの信者が信じるべき「六信」と、実践すべき「五行」について説明せよ。", "a": "【六信】とは、唯一神アッラー、天使、啓典、預言者、【来世】、天命(定命)の六つを信じることである。【五行】とは、信仰告白、1日5回の【礼拝】、貧しい人々への施しである【喜捨】、ラマダーン月の断食、メッカへの巡礼の五つの務めである。これらは【シャリーア】(イスラーム法)とともに信者の生活全体を規律している。"},
  {"id": "rinrix44", "s": "rinri", "lv": 1, "topic": "ルターの宗教改革", "q": "ルターは、当時のカトリック教会のどのような点を批判し、どのような信仰を説いたか説明せよ。", "a": "ルターは、教会が【贖宥状】(免罪符)の購入によって罪が許されると説いたことを批判し、1517年に九十五か条の論題を発表した。人は善行によってではなく、神への【信仰】によってのみ義とされるという【信仰義認】を説き、信仰のよりどころは教会ではなく【聖書】のみであるとした。また信者はみな等しく神の前に立つとする【万人司祭】主義を唱えた。"},
  {"id": "rinrix45", "s": "rinri", "lv": 1, "topic": "考える葦", "q": "パスカルが人間を「考える葦」と表現した意味を説明せよ。", "a": "パスカルは、人間は自然の中で最も弱い【葦】のような存在で、わずかな水滴でも殺されてしまうと述べた。しかし人間は自分が死ぬことや宇宙の大きさを【考える】ことができる点で、何も知らない宇宙よりも尊いとした。人間は【悲惨】さと【偉大】さの間をゆれ動く【中間者】であり、その尊厳は思考にあると考えたのである。"},
  {"id": "rinrix46", "s": "rinri", "lv": 1, "topic": "帰納法", "q": "ベーコンが唱えた帰納法とはどのような方法か。デカルトの演繹法と対比して説明せよ。", "a": "【帰納法】は、【観察】や【実験】によって集めた個々の事実から、それらに共通する一般的な法則を導き出す方法である。ベーコンは「【知は力なり】」と述べ、自然の法則を知ることで自然を支配し、人間の生活を改善できると考えた。これに対しデカルトの【演繹法】は、確実な原理から理性による推論によって個々の結論を導く方法である。"},
  {"id": "rinrix47", "s": "rinri", "lv": 1, "topic": "欲求階層説", "q": "マズローの欲求階層説の内容を説明せよ。", "a": "マズローは、人間の欲求を下から、【生理的欲求】、安全の欲求、所属と愛情の欲求、【承認】(自尊)の欲求、【自己実現】の欲求の五つの階層に分けた。下位の欲求がある程度満たされると、より上位の欲求が現れるとした。下の四つは不足を満たそうとする欠乏欲求であり、最上位の自己実現の欲求は、自分の可能性を発揮しようとする【成長欲求】である。"},
  {"id": "rinrix48", "s": "rinri", "lv": 1, "topic": "防衛機制", "q": "防衛機制とは何か。具体例を二つ挙げて説明せよ。", "a": "【防衛機制】とは、欲求が満たされない【欲求不満】(フラストレーション)や葛藤による不安から自分を守ろうとする、【無意識】の心のはたらきである。たとえば、もっともらしい理由をつけて自分を正当化する【合理化】や、満たされない欲求を芸術やスポーツなど社会的に価値のある活動に向ける【昇華】がある。"},
  {"id": "rinrix49", "s": "rinri", "lv": 1, "topic": "縁起", "q": "ブッダが説いた縁起の考え方と、そこから導かれる生き方を説明せよ。", "a": "【縁起】とは、すべての事物は他との相互の【依存】関係によって生じ、それ自体で成り立つ固定的な実体はないという考え方である。そのため万物は移り変わり(【諸行無常】)、不変の自我もない(諸法無我)。この真理を知らずに自我や事物に【執着】することが苦の原因であるから、執着を離れ、あらゆる生きものに【慈悲】をもって生きることが説かれた。"},
  {"id": "rinrix50", "s": "rinri", "lv": 1, "topic": "聖徳太子の思想", "q": "聖徳太子の思想の特徴を、十七条憲法や彼の言葉をもとに説明せよ。", "a": "十七条憲法では「【和】をもって貴しとなす」として、人々が対立せずに話し合うことを重んじた。また人はみな欲望にとらわれた【凡夫】であると自覚すれば、他人を責めずに協調できると説いた。さらに「【世間虚仮】、唯仏是真」という言葉には、この世ははかなく、【仏】の教えのみが真実であるという仏教への深い信仰が示されている。"},
  {"id": "rinrix51", "s": "rinri", "lv": 1, "topic": "専修念仏", "q": "法然の専修念仏とはどのような教えか。その背景とともに説明せよ。", "a": "平安末期の戦乱や災害のなかで、仏の教えが衰えた【末法】の世に入ったという意識が広まった。法然は、末法の凡夫が自力の修行で悟るのは困難であるとして、ひたすら「【南無阿弥陀仏】」と唱えれば、【阿弥陀仏】の本願の力(【他力】)によって誰もが極楽浄土に往生できると説いた。これを【専修念仏】といい、浄土宗の開祖となった。"},
  {"id": "rinrix52", "s": "rinri", "lv": 1, "topic": "ガンディーの非暴力", "q": "ガンディーの非暴力・不服従運動を支えた思想を説明せよ。", "a": "ガンディーは、真理をつかみ保つことを意味する【サティヤーグラハ】を根本とし、あらゆる生命を傷つけない【アヒンサー】(不殺生)を実践の原則とした。また欲望を抑えて自己を浄化する【ブラフマチャリヤー】を重んじた。これにもとづき、イギリスの植民地支配に対して暴力を用いずに抵抗する【非暴力・不服従】運動を指導した。"},
  {"id": "rinrix53", "s": "rinri", "lv": 2, "topic": "形相と質料", "q": "アリストテレスは、プラトンのイデア論をどのように批判し、事物の本質をどのように考えたか説明せよ。", "a": "プラトンは、事物の本質である【イデア】が現実の世界を超えたイデア界に存在するとした。アリストテレスはこれを批判し、本質は個々の事物そのものに内在すると考えた。事物は、それが何であるかを決める【形相】(エイドス)と、その素材となる【質料】(ヒュレー)からなり、質料のなかに【可能態】として潜む形相が実現して【現実態】となる過程として、事物の生成を説明した。"},
  {"id": "rinrix54", "s": "rinri", "lv": 2, "topic": "プラトンの理想国家", "q": "プラトンが説いた理想国家のあり方を、魂の三部分説と結びつけて説明せよ。", "a": "プラトンは、魂を【理性】・気概・欲望の三部分に分け、それぞれが知恵・勇気・節制の徳を備え、理性が全体を導くとき【正義】の徳が実現するとした。国家も同様に、統治者・防衛者・生産者の三階級がそれぞれの徳を発揮し調和するとき正義が実現する。そして善のイデアを知る【哲学者】が統治する【哲人政治】を理想とした。これら四つの徳を【四元徳】という。"},
  {"id": "rinrix55", "s": "rinri", "lv": 2, "topic": "パウロの思想", "q": "パウロはイエスの死をどのように意味づけ、救いについてどのように説いたか説明せよ。", "a": "パウロは、人間は生まれながらに【原罪】を負っており、律法を守る努力だけでは救われないと考えた。そしてイエスの十字架上の死は、人類の罪をつぐなう【贖罪】であり、イエスの【復活】を信じる【信仰】によってのみ人は義とされ救われると説いた。またキリスト教徒の徳として、信仰・希望・【愛】を挙げた。"},
  {"id": "rinrix56", "s": "rinri", "lv": 2, "topic": "信仰と理性の調和", "q": "トマス・アクィナスは、信仰と理性の関係をどのように考えたか説明せよ。", "a": "トマス・アクィナスは『【神学大全】』を著し、【アリストテレス】の哲学を取り入れてキリスト教の教義を体系化した。理性によって知りうる真理と、神の啓示による【信仰】の真理とは矛盾せず、理性は信仰を補い支えるものであるとして、両者の【調和】をはかった。ただし信仰の真理は理性を超えるものとされ、「哲学は【神学】の侍女」という考え方につながった。"},
  {"id": "rinrix57", "s": "rinri", "lv": 2, "topic": "予定説と職業倫理", "q": "カルヴァンの予定説と職業観は、近代の経済活動にどのような影響を与えたとされるか説明せよ。", "a": "カルヴァンは、誰が救われるかは神によってあらかじめ定められているという【予定説】を説いた。また職業は神から与えられた【召命】であり、勤勉に職業に励むことが神の栄光をあらわすとした。人々は救いの確信を得るために【禁欲】的に働き、その結果得た利潤を肯定した。【マックス・ウェーバー】は、こうした倫理が【資本主義】の精神を生み出したと論じた。"},
  {"id": "rinrix58", "s": "rinri", "lv": 2, "topic": "人間の尊厳", "q": "ルネサンス期のピコ・デラ・ミランドラは、人間の尊厳をどこに見いだしたか説明せよ。", "a": "ピコは『【人間の尊厳について】』で、他の被造物はあらかじめ本性が定められているが、人間だけは神から【自由意志】を与えられており、自分のあり方を自分で選ぶことができると説いた。人間は獣のように堕落することも、【神】に近い存在へと高まることもできる。この自ら自己を形成する自由にこそ人間の【尊厳】があるとした。"},
  {"id": "rinrix59", "s": "rinri", "lv": 2, "topic": "モンテーニュの懐疑", "q": "モンテーニュが「私は何を知っているか(ク・セ・ジュ)」と問いかけた意図を、時代背景とともに説明せよ。", "a": "モンテーニュは、フランスで新旧両派が争う【宗教戦争】の時代に生き、『【エセー】』を著した。人間の知識や判断は不確かであると自覚させる「【ク・セ・ジュ】」という問いによって、自分の考えを絶対視する【独断】をいましめた。そのうえで、異なる意見や習慣を認める【寛容】な態度の大切さを説いた。"},
  {"id": "rinrix60", "s": "rinri", "lv": 2, "topic": "物心二元論", "q": "デカルトの物心二元論の内容と、それが近代の自然観に与えた影響を説明せよ。", "a": "デカルトは、世界を、思考することを本質とする【精神】と、空間的な広がりである【延長】を本質とする物体という、互いに独立した二つの実体に分けた。自然は精神をもたない物体の世界として、数学的な法則で説明できる【機械論的自然観】が確立され、近代科学の発展を支えた。一方で、精神と身体がどのように関係するのかという【心身問題】が残された。"},
  {"id": "rinrix61", "s": "rinri", "lv": 2, "topic": "ルソーの一般意志", "q": "ルソーの社会契約説における「一般意志」とは何か。ホッブズやロックとの違いにふれて説明せよ。", "a": "ルソーは、自然状態の人間は自由で平等だったが、文明と【私有財産】が不平等を生んだと考えた。そこで人々が全員で契約を結び、共同体全体の利益をめざす【一般意志】に従うことで自由を回復すべきだとした。一般意志は個々の利益の総和である【全体意志】とは異なり、譲渡も代表もできないため、主権は人民にあり、【直接民主制】が求められる。この点で代表制を認めたロックとも、主権者への権利の譲渡を説いた【ホッブズ】とも異なる。"},
  {"id": "rinrix62", "s": "rinri", "lv": 2, "topic": "デューイの道具主義", "q": "デューイの道具主義とはどのような考え方か。教育論とあわせて説明せよ。", "a": "アメリカの【プラグマティズム】を大成したデューイは、知性や思想は、生活の中で直面する問題を解決するための【道具】であると考えた(【道具主義】)。問題を解決し未来を切り開く知性を【創造的知性】とよんだ。教育においては、知識の詰め込みではなく、子どもが自ら問題を見つけて解決する【問題解決学習】を重視し、それが民主主義社会を支えるとした。"},
  {"id": "rinrix63", "s": "rinri", "lv": 2, "topic": "唯物史観", "q": "マルクスの唯物史観(史的唯物論)の内容を説明せよ。", "a": "マルクスは、社会の土台は物質的な生産を行う経済のしくみである【下部構造】であり、それが政治・法律・思想などの【上部構造】を規定すると考えた。【生産力】が発展すると、それまでの【生産関係】との間に矛盾が生じ、支配階級と被支配階級の【階級闘争】を通じて社会が変革される。こうして歴史は発展し、最終的に資本主義から社会主義へ移行すると説いた。"},
  {"id": "rinrix64", "s": "rinri", "lv": 2, "topic": "SOLとQOL", "q": "生命倫理における「生命の尊厳(SOL)」と「生命の質(QOL)」の考え方を対比して説明せよ。", "a": "【SOL】(生命の尊厳)は、人間の生命はそれ自体がかけがえのない価値をもち、どのような状態であっても尊重されるべきだという考え方である。これに対し【QOL】(生命の質)は、本人がその人らしく満足できる生き方を送れているかを重視する考え方である。延命治療の差し控えや【尊厳死】をめぐっては、両者の対立が生じ、本人の意思を事前に示す【リヴィング・ウィル】の尊重などが議論されている。"},
  {"id": "rinrix65", "s": "rinri", "lv": 2, "topic": "脳死と臓器移植", "q": "日本における脳死と臓器移植をめぐる制度の変化と、そこにある倫理的問題を説明せよ。", "a": "1997年の【臓器移植法】では、本人が書面で臓器提供の意思を示し、家族も同意した場合に限り、【脳死】の人からの臓器提供が認められた。2009年の改正で、本人の意思が不明でも【家族の同意】があれば提供できるようになり、【15歳未満】の子どもからの提供も可能になった。しかし脳死を人の死とみなしてよいかについては、死生観の違いもあって議論が続いている。"},
  {"id": "rinrix66", "s": "rinri", "lv": 2, "topic": "環境倫理", "q": "環境倫理の主要な三つの主張を説明せよ。", "a": "一つめは、人間だけでなく動植物や生態系にも生存の権利があるとする【自然の生存権】である。二つめは、現在の世代は将来の世代の生存の可能性に責任を負うとする【世代間倫理】である。三つめは、地球の資源や環境は有限であり、その制約の中で行動を決めるべきだとする【地球有限主義】である。これらは人間中心主義を見直す考え方である。"},
  {"id": "rinrix67", "s": "rinri", "lv": 2, "topic": "万物斉同", "q": "荘子の万物斉同の思想と、彼が理想とした生き方を説明せよ。", "a": "荘子は、善と悪、美と醜、生と死などの区別は、人間の相対的な見方がつくり出したものにすぎず、根源である【道】の立場から見れば万物はすべて等しいと説いた。これを【万物斉同】という。こうした区別へのとらわれから解放され、自然と一体となって自由に遊ぶように生きる境地を【逍遙遊】とよび、その境地に達した人を【真人】として理想とした。"},
  {"id": "rinrix68", "s": "rinri", "lv": 2, "topic": "王道政治", "q": "孟子の説いた王道政治と易姓革命の思想を説明せよ。", "a": "孟子は、為政者が【仁義】の徳によって民の生活を安定させる【王道】政治を理想とし、武力や刑罰によって支配する【覇道】を退けた。また君主の地位は【天命】によって与えられたものであり、民意は天意の現れであるから、民の信頼を失い徳を欠いた君主は天命が改まって位を追われるとした。これを【易姓革命】という。"},
  {"id": "rinrix69", "s": "rinri", "lv": 2, "topic": "兼愛", "q": "墨子は儒家の仁をどのように批判し、何を説いたか説明せよ。", "a": "墨子は、家族などの身近な者から順に愛を及ぼす儒家の【仁】は、親疎によって差別をつける「別愛」であり、それが争いのもとになると批判した。そして自他の区別なく広く人々を愛する【兼愛】を説き、互いに利益を与え合う交利を主張した。またこの立場から、侵略戦争を否定する【非攻】を唱えた。"},
  {"id": "rinrix70", "s": "rinri", "lv": 2, "topic": "最澄と空海", "q": "平安時代の最澄と空海の教えを比較して説明せよ。", "a": "最澄は比叡山に【天台宗】を開き、【法華経】にもとづいて、すべての生きものは仏となる素質をもつという「【一切衆生悉有仏性】」を説いた。空海は高野山に【真言宗】を開き、【密教】の修行によって、この身のままで仏と一体になる【即身成仏】を説いた。いずれも国家の安泰を祈る鎮護国家の役割も担った。"},
  {"id": "rinrix71", "s": "rinri", "lv": 2, "topic": "石田梅岩の心学", "q": "石田梅岩は、江戸時代の商人の営みをどのように意義づけたか説明せよ。", "a": "江戸時代には、商人の利益は人をだまして得るものとして低くみられがちであった。石田梅岩は【石門心学】を開き、商人が売買によって得る利益は、武士が受け取る俸禄と同じく【正当】なものであると主張した。ただし商人は【正直】と【倹約】を守り、自分の身分に満足する【知足安分】の心をもって家業に励むべきであると説いた。"},
  {"id": "rinrix72", "s": "rinri", "lv": 2, "topic": "柳田国男の民俗学", "q": "柳田国男が創始した民俗学は、どのような人々の何を明らかにしようとしたか説明せよ。", "a": "柳田国男は、歴史の記録に残る支配者や知識人ではなく、文字による記録を残さなかった名もなき庶民を【常民】とよび、その生活や信仰を明らかにしようとした。そのため各地の【伝承】や習俗、年中行事などを調査し、日本の【民俗学】を確立した。『【遠野物語】』などを通じて、日本人の祖先信仰など基層文化を探った。"},
  {"id": "rinrix73", "s": "rinri", "lv": 3, "topic": "スピノザの汎神論", "q": "スピノザの「神即自然」の思想と、そこから導かれる自由の考え方を説明せよ。", "a": "スピノザは、神を世界の外にある人格的な創造主とは考えず、唯一の実体である神が自然そのものであるとした(【神即自然】)。この【汎神論】のもとでは、すべての事物は神の本性から【必然】的に生じる。したがって人間の自由とは、何ものにも束縛されないことではなく、世界の必然性を理性によって認識し、「【永遠の相のもとに】」ものごとをとらえることで、情念の束縛から解放されることにあるとした。"},
  {"id": "rinrix74", "s": "rinri", "lv": 3, "topic": "構造主義", "q": "レヴィ=ストロースの構造主義は、西洋近代の思想に対してどのような問題提起を行ったか説明せよ。", "a": "レヴィ=ストロースは、未開社会の親族関係や神話を分析し、人々が意識しないまま思考や行動を規定している【構造】があることを明らかにした。『【野生の思考】』では、未開社会の思考は劣ったものではなく、身近な具体物を用いて世界を秩序づける独自の論理をもつと論じた。これにより、西洋の科学的思考を最も進んだものとみなす【西洋中心主義】や、主体的な人間を出発点とする【実存主義】の人間観を批判した。"},
  {"id": "rinrix75", "s": "rinri", "lv": 3, "topic": "他者の顔", "q": "レヴィナスは他者との関係をどのように考えたか。「顔」という概念を用いて説明せよ。", "a": "レヴィナスは、西洋哲学が他者を自己の理解の枠組みに取り込み、同一のものとして【全体性】へ回収してきたと批判した。他者は自己によって理解し尽くすことのできない【無限】の存在であり、その他者が私の前に現れる【顔】は、「汝殺すなかれ」と私に呼びかけてくる。私はこの呼びかけに応答する【責任】を負っており、そこに【倫理】の根源があるとした。"},
  {"id": "rinrix76", "s": "rinri", "lv": 3, "topic": "未来への責任", "q": "ハンス・ヨナスが『責任という原理』で説いた倫理の特徴を、従来の倫理と比較して説明せよ。", "a": "従来の倫理は、同時代に生きる人々どうしの身近な行為の責任を問題にしてきた。しかし現代の【科学技術】の力は、環境破壊などを通じて遠い【未来世代】の存在そのものを脅かすようになった。ヨナスは、まだ存在しない未来の人類が存続することに対して、現在の世代が一方的に【責任】を負うと主張した。そして技術の帰結については楽観的な予測よりも悪い予測を優先して考える「【恐れに基づく発見術】」を提唱した。"},
  {"id": "rinrix77", "s": "rinri", "lv": 3, "topic": "恩賜的民権", "q": "中江兆民の「恩賜的民権」と「恢復的民権」の考え方を説明せよ。", "a": "【中江兆民】はルソーの『社会契約論』を漢訳した『【民約訳解】』を著し、「東洋のルソー」とよばれた。『三酔人経綸問答』では、人民が自ら勝ち取った【恢復的民権】と、為政者から与えられた【恩賜的民権】を区別した。日本の民権は上から与えられた恩賜的なものであるが、それを大切に育てていけば、実質において恢復的民権と変わらないものにできると説き、【民権】の着実な発展を主張した。"},
  {"id": "rinrix78", "s": "rinri", "lv": 3, "topic": "語りえぬもの", "q": "ウィトゲンシュタインは前期と後期で言語をどのようにとらえたか説明せよ。", "a": "前期の『【論理哲学論考】』では、言語は世界の事実を写しとる【写像】であるとし、事実について有意味に語れることと語れないことを区別した。倫理や形而上学の問題は事実ではないため有意味には語れず、「【語りえぬもの】については沈黙しなければならない」と述べた。後期には、言葉の意味は日常生活の具体的な場面での用いられ方によって決まるとし、言語活動をルールに従う【言語ゲーム】としてとらえた。"},
  {"id": "rinrix79", "s": "rinri", "lv": 3, "topic": "共感と公平な観察者", "q": "アダム・スミスの『道徳感情論』における「共感」の考え方と、それが経済活動の考え方とどう結びつくか説明せよ。", "a": "アダム・スミスは、人間には他人の感情を自分のことのように感じとる【共感】の能力があるとした。人は自分の心の中に利害関係のない【公平な観察者】を想定し、その共感が得られるかどうかで自分の行為の適否を判断する。各人が【利己心】にもとづいて経済活動を行っても、この共感による道徳的な制約のもとで公正なルールが守られていれば、【見えざる手】に導かれて社会全体の利益が実現すると考えた。"},
  {"id": "rinrix80", "s": "rinri", "lv": 3, "topic": "自然世", "q": "安藤昌益は、江戸時代の封建社会をどのように批判したか説明せよ。", "a": "安藤昌益は『【自然真営道】』を著し、すべての人がみずから田畑を耕して生活する【万人直耕】の平等な社会を、本来のあるべき【自然世】とした。これに対し、武士などが自分では耕さずに農民の生産物を奪う【不耕貪食】によって成り立つ身分制の社会を【法世】とよび、それを正当化する儒学や仏教とともに厳しく批判した。"},
  {"id": "physx26", "s": "phys", "lv": 1, "topic": "水平投射", "q": "同じ高さから、一方の小球を水平に投げ、同時にもう一方を静かに落とすと、両者は同時に床に着く。その理由を説明せよ。", "a": "空気抵抗を無視すると、水平に投げた小球には水平方向の力がはたらかないので、水平方向には【等速直線運動】をする。一方、鉛直方向には【重力】だけがはたらくため、静かに落とした小球と同じく初速度0の【自由落下】をする。水平方向と鉛直方向の運動は【独立】しているので、落下にかかる時間は両者で等しくなる。"},
  {"id": "physx27", "s": "phys", "lv": 1, "topic": "静止摩擦力と動摩擦力", "q": "床に置いた重い箱を水平に押すとき、動き出すまでは大きな力が必要だが、動き出すと小さな力で動かし続けられる。この理由を説明せよ。", "a": "箱が静止している間は、押す力とつりあうように【静止摩擦力】がはたらき、押す力を大きくすると静止摩擦力も大きくなる。その上限が【最大摩擦力】で、これを超えると箱は動き出す。動いている箱には【動摩擦力】がはたらくが、一般に動摩擦係数は【静止摩擦係数】より小さいため、動摩擦力は最大摩擦力より小さく、小さな力で動かし続けられる。"},
  {"id": "physx28", "s": "phys", "lv": 1, "topic": "力のモーメント", "q": "ドアを開けるとき、ちょうつがいから遠い位置を押すほうが小さな力で開けられる理由を説明せよ。", "a": "物体を回転させるはたらきは、力の大きさと、回転軸から力の作用線までの距離(【うでの長さ】)の積である【力のモーメント】で決まる。ちょうつがいが【回転軸】であるから、そこから遠い位置を押すほどうでの長さが大きくなり、小さな力でも同じ大きさの力のモーメントを与えることができる。"},
  {"id": "physx29", "s": "phys", "lv": 1, "topic": "全反射", "q": "光ファイバーの中を光が外にもれずに遠くまで伝わる理由を説明せよ。", "a": "光が【屈折率】の大きい物質から小さい物質へ進むとき、入射角が【臨界角】を超えると、光は境界面ですべて反射される。これを【全反射】という。光ファイバーは、屈折率の大きい中心部(コア)を屈折率の小さい外側(【クラッド】)で包んだ構造になっており、光はその境界で全反射をくり返しながら進むため、外にもれずに遠くまで伝わる。"},
  {"id": "physx30", "s": "phys", "lv": 1, "topic": "凸レンズの像", "q": "凸レンズで、物体を焦点の外側に置いた場合と内側に置いた場合とで、できる像がどのように異なるか説明せよ。", "a": "物体を【焦点】の外側に置くと、レンズを通った光が反対側で実際に集まり、スクリーンに映すことのできる上下左右が逆の【倒立実像】ができる。焦点の内側に置くと、光は集まらずに広がるが、その光を逆にのばした位置に、物体と同じ向きで大きな【正立虚像】が見える。【虫めがね】はこの虚像を利用している。"},
  {"id": "physx31", "s": "phys", "lv": 1, "topic": "家庭の配線", "q": "家庭の電気器具がコンセントに並列に接続されている理由と、使いすぎるとブレーカーが落ちる理由を説明せよ。", "a": "【並列】接続では、どの電気器具にも同じ【電圧】(約100V)がかかるため、それぞれが決められた性能を発揮でき、一つのスイッチを切っても他の器具は使い続けられる。一方、全体を流れる電流は各器具に流れる電流の【和】になるので、多くの器具を同時に使うと電流が大きくなりすぎる。そこで過熱による火災を防ぐため、【ブレーカー】が電流を遮断する。"},
  {"id": "physx32", "s": "phys", "lv": 1, "topic": "半減期", "q": "放射性同位体の半減期とは何か。それが年代測定に利用できる理由とともに説明せよ。", "a": "【半減期】とは、放射性同位体の原子核が【放射線】を出して別の原子核に変わり、もとの量が半分になるまでの時間である。半減期は温度や圧力などの条件によらず、核種ごとに一定である。そのため、たとえば生物の遺体に含まれる【炭素14】の割合が、生きていたときから何回半分になったかを調べることで、その生物が死んでから経過した【年代】を推定できる。"},
  {"id": "physx33", "s": "phys", "lv": 1, "topic": "熱の伝わり方", "q": "熱の伝わり方の三つの種類を、身近な例を挙げて説明せよ。", "a": "物質の中を高温部から低温部へ熱が順に伝わる【伝導】は、金属のスプーンの柄が熱くなる例にみられる。液体や気体が移動することで熱が運ばれる【対流】は、やかんの水全体があたたまる例にみられる。物体が出す赤外線などの電磁波によって、空間を隔てて熱が伝わる【放射】は、【太陽】の光や焚き火であたたかさを感じる例にみられる。"},
  {"id": "physx34", "s": "phys", "lv": 2, "topic": "運動量保存則", "q": "2物体が衝突するとき、外力がはたらかなければ全体の運動量が保存される理由を説明せよ。", "a": "衝突の間、2物体は互いに力をおよぼしあう。【作用・反作用の法則】により、その力は大きさが等しく向きが逆であり、はたらく時間も等しい。したがって各物体が受ける【力積】は大きさが等しく逆向きとなる。各物体の運動量の変化は受けた力積に等しいので、2物体の運動量の変化は打ち消しあい、外力がなければ全体の【運動量】の和は一定に保たれる。これが【運動量保存則】である。"},
  {"id": "physx35", "s": "phys", "lv": 2, "topic": "反発係数", "q": "反発係数(はねかえり係数)の値と、衝突における力学的エネルギーの変化との関係を説明せよ。", "a": "【反発係数】eは、衝突前に近づく速さに対する衝突後に遠ざかる速さの比で、0≦e≦1の値をとる。e=1の【弾性衝突】では力学的エネルギーが保存される。0≦e<1の【非弾性衝突】では、力学的エネルギーの一部が【熱】や音などに変わって減少し、e=0の完全非弾性衝突では2物体は一体となって運動する。どの場合も外力がなければ運動量は保存される。"},
  {"id": "physx36", "s": "phys", "lv": 2, "topic": "等速円運動", "q": "等速円運動をする物体は、速さが一定なのに加速度をもつ。その理由と、加速度の向き・大きさを説明せよ。", "a": "等速円運動では速さは一定でも、速度の【向き】が絶えず変化しているため、加速度が生じる。その加速度は常に円の【中心】を向き、大きさは速さv、半径rを用いてv²/rと表される。したがって物体には、中心向きに大きさmv²/rの合力が必要であり、これを【向心力】という。物体とともに回転する立場から見ると、これとつりあう慣性力として【遠心力】がはたらくように見える。"},
  {"id": "physx37", "s": "phys", "lv": 2, "topic": "ばね振り子", "q": "ばね振り子の周期は、振幅やばねを鉛直につるすか水平に置くかによらない。その理由を説明せよ。", "a": "ばね振り子の物体は、つりあいの位置からの変位に比例し逆向きの【復元力】を受けて【単振動】をする。単振動の周期は、質量mとばね定数kだけで決まり、T=2π√(m/k)となるため、【振幅】によらない。鉛直につるす場合は重力によってつりあいの位置がずれるだけで、そこからの変位に対する復元力は同じであるため、周期は水平の場合と【等しい】。"},
  {"id": "physx38", "s": "phys", "lv": 2, "topic": "振り子の等時性", "q": "単振り子の周期は何によって決まるか。おもりの質量や振れ幅との関係とともに説明せよ。", "a": "振れ幅が小さいとき、単振り子のおもりは【単振動】とみなすことができ、周期は糸の長さlと重力加速度gを用いてT=2π√(l/g)と表される。そのため周期はおもりの【質量】にも振れ幅にもよらず、【糸の長さ】だけで決まる。この性質を振り子の【等時性】といい、ガリレイが発見したとされる。"},
  {"id": "physx39", "s": "phys", "lv": 2, "topic": "熱力学第一法則", "q": "気体の温度を同じだけ上げるのに、体積一定のときより圧力一定のときのほうが多くの熱が必要な理由を、熱力学第一法則を用いて説明せよ。", "a": "【熱力学第一法則】によれば、気体が得た熱量は【内部エネルギー】の増加と、気体が外部にした仕事の和に等しい。理想気体の内部エネルギーは温度だけで決まるので、同じ温度上昇なら増加量は等しい。体積一定では気体は外部に【仕事】をしないが、圧力一定では気体が膨張して外部に仕事をするため、その分だけ多くの熱が必要になる。そのため【定圧モル比熱】は定積モル比熱より大きい。"},
  {"id": "physx40", "s": "phys", "lv": 2, "topic": "弦の固有振動", "q": "ギターの弦を強く張ったり、押さえて短くしたりすると音が高くなる理由を説明せよ。", "a": "両端を固定した弦には、両端を【節】とする【定常波】ができ、基本振動の波長は弦の長さの2倍となる。振動数は波の速さを波長で割ったものなので、弦を押さえて【短く】すると波長が短くなり振動数が大きくなる。また弦を伝わる波の速さは【張力】が大きいほど速くなるため、強く張ると振動数が大きくなる。振動数が大きいほど音は高くなる。"},
  {"id": "physx41", "s": "phys", "lv": 2, "topic": "開管と閉管", "q": "同じ長さの開管と閉管では、出る音の基本振動数や倍音の構成にどのような違いがあるか説明せよ。", "a": "気柱には、開口端が【腹】、閉口端が【節】となる定常波ができる。両端が開いた【開管】では基本振動の波長は管の長さの2倍で、その整数倍の振動数の倍音がすべて生じる。一端が閉じた【閉管】では基本振動の波長は管の長さの4倍となるので、基本振動数は開管の半分になり、倍音は基本振動数の【奇数倍】のものだけが生じる。"},
  {"id": "physx42", "s": "phys", "lv": 2, "topic": "ヤングの実験", "q": "ヤングの二重スリットの実験で明暗の縞が生じる理由と、この実験の意義を説明せよ。", "a": "二つのスリットを通った光は【回折】して広がり、スクリーン上で重なりあう。二つの光の【経路差】が波長の整数倍の点では山と山が重なって強めあい明線となり、半波長の奇数倍の点では弱めあい暗線となるため、明暗の【干渉縞】が生じる。この実験は、光が【波】の性質をもつことを示した。"},
  {"id": "physx43", "s": "phys", "lv": 2, "topic": "偏光", "q": "偏光とは何か。光で偏光が起こり音波では起こらない理由と、偏光サングラスのしくみを説明せよ。", "a": "【偏光】とは、波の振動方向が特定の方向にそろった状態である。光は振動方向が進行方向に垂直な【横波】であるため、偏光板で特定の向きの振動だけを取り出すことができるが、音波は【縦波】なので偏光は起こらない。水面などで反射した光は特定の方向に振動する成分が多いので、その成分を通さない【偏光板】を用いたサングラスで、まぶしい反射光をさえぎることができる。"},
  {"id": "physx44", "s": "phys", "lv": 2, "topic": "モーターの原理", "q": "直流モーターが回転を続けるしくみを説明せよ。", "a": "磁場の中に置いたコイルに電流を流すと、コイルの導線は磁場から【力】を受け、その向きは【フレミングの左手の法則】で決まる。コイルの両側で受ける力が逆向きになるため、コイルは回転する。半回転ごとに【整流子】とブラシによってコイルを流れる電流の向きが切りかわるので、常に同じ向きに回転させる力がはたらき、回転が続く。"},
  {"id": "physx45", "s": "phys", "lv": 2, "topic": "音の三要素", "q": "音の大きさ・高さ・音色は、それぞれ音波のどのような性質によって決まるか説明せよ。", "a": "音の大きさは、音波の【振幅】によって決まり、振幅が大きいほど大きな音になる。音の高さは、【振動数】によって決まり、振動数が大きいほど高い音になる。音色は、音波の【波形】によって決まる。同じ高さの音でも楽器ごとに含まれる倍音の割合が異なるため、波形が異なり、音色の違いとして聞き分けられる。"},
  {"id": "physx46", "s": "phys", "lv": 3, "topic": "ケプラーの第二法則", "q": "惑星が太陽に近いところで速く、遠いところで遅く運動する理由を、ケプラーの第二法則と万有引力の性質から説明せよ。", "a": "惑星にはたらく【万有引力】は常に太陽の方向を向く【中心力】であり、太陽のまわりの力のモーメントは0である。そのため惑星の【角運動量】は保存され、これは太陽と惑星を結ぶ線分が単位時間に描く面積が一定であるという【面積速度一定】の法則と同じ内容になる。面積速度は太陽からの距離と速度の垂直成分の積に比例するので、距離が小さい【近日点】付近では速く、遠日点付近では遅くなる。"},
  {"id": "physx47", "s": "phys", "lv": 3, "topic": "気体分子運動論", "q": "気体分子運動論の立場から、気体の圧力が生じるしくみと、絶対温度の意味を説明せよ。", "a": "気体の圧力は、多数の分子が容器の壁に衝突してはね返る際の【運動量】の変化によって、壁が受ける力の平均として生じる。これを計算すると、圧力は分子の数密度と分子1個の【平均運動エネルギー】に比例することがわかる。これを理想気体の【状態方程式】と比べると、分子の平均運動エネルギーは【絶対温度】に比例する。つまり絶対温度は、分子の熱運動の激しさを表す量である。"},
  {"id": "physx48", "s": "phys", "lv": 3, "topic": "誘電体とコンデンサー", "q": "平行板コンデンサーの極板間に誘電体を入れると電気容量が大きくなる理由を説明せよ。", "a": "極板間に誘電体を入れると、電場によって誘電体の分子の電荷の分布がかたよる【誘電分極】が起こり、誘電体の表面に極板とは逆符号の電荷があらわれる。この電荷がつくる電場によって誘電体内部の【電場】が弱められるため、極板に同じ電気量を蓄えても極板間の【電位差】は小さくなる。電気容量は電気量を電位差で割ったものなので、【比誘電率】倍に大きくなる。"},
  {"id": "physx49", "s": "phys", "lv": 3, "topic": "ローレンツ力と円運動", "q": "一様な磁場に垂直に入射した荷電粒子が等速円運動をする理由と、サイクロトロンの原理につながるその性質を説明せよ。", "a": "荷電粒子が磁場から受ける【ローレンツ力】は常に速度に垂直であるため、粒子に【仕事】をせず、速さは変わらない。そのため速さ一定で向きだけが変わり、ローレンツ力を向心力とする【等速円運動】となる。円の半径は速さに比例するが、1周する【周期】はT=2πm/qBとなって速さによらない。サイクロトロンはこの性質を利用し、一定の周期で電場を切りかえて粒子をくり返し【加速】する。"},
  {"id": "physx50", "s": "phys", "lv": 3, "topic": "物質波", "q": "ド・ブロイの物質波の考え方と、それが電子顕微鏡に応用されている理由を説明せよ。", "a": "ド・ブロイは、光が粒子性をもつのと同様に、電子などの粒子も【波動性】をもつと考え、その波長は【プランク定数】を運動量で割ったλ=h/mvで表されるとした。これは電子線の【回折】実験によって確かめられた。加速した電子の波長は可視光よりはるかに短く、波長が短いほど細かいものを見分ける【分解能】が高くなるため、【電子顕微鏡】では光学顕微鏡よりも微小な構造を観察できる。"},
  {"id": "chemx26", "s": "chem", "lv": 1, "topic": "同位体", "q": "同位体とは何か。同位体どうしの化学的性質がほぼ同じである理由とともに説明せよ。", "a": "【同位体】とは、【陽子】の数(原子番号)が同じで、【中性子】の数が異なるために質量数が異なる原子どうしをいう。化学的性質は主に原子の【電子配置】、特に最外殻電子によって決まる。同位体は陽子の数が同じなので電子の数と配置も同じになり、化学的性質はほぼ同じになる。元素の原子量は、同位体の相対質量を【存在比】で平均した値である。"},
  {"id": "chemx27", "s": "chem", "lv": 1, "topic": "分子量と沸点", "q": "ハロゲンの単体は、常温でフッ素・塩素が気体、臭素が液体、ヨウ素が固体である。この違いが生じる理由を説明せよ。", "a": "ハロゲンの単体はいずれも二原子分子からなる【分子結晶】をつくる物質で、分子どうしは弱い【分子間力】(ファンデルワールス力)で引きあっている。構造が似た分子では、【分子量】が大きいほど分子間力が強くなるため、融点・沸点が高くなる。分子量はF₂<Cl₂<Br₂<I₂の順に大きいので、この順に融点・【沸点】が高くなり、常温での状態が異なる。"},
  {"id": "chemx28", "s": "chem", "lv": 1, "topic": "分留", "q": "原油から石油ガス・ナフサ・灯油・軽油などを分ける方法と、その原理を説明せよ。", "a": "原油は多くの炭化水素の【混合物】である。これを加熱して蒸発させ、精留塔で【沸点】の違いを利用して成分ごとに分ける。塔の上部ほど温度が低いため、沸点の低い石油ガスやナフサは上部で、灯油・軽油などは中段で、沸点の高い成分は下部で取り出される。このように蒸留によって複数の成分に分ける操作を【分留】(分別蒸留)という。"},
  {"id": "chemx29", "s": "chem", "lv": 1, "topic": "再結晶", "q": "少量の塩化ナトリウムを含む硝酸カリウムから、純粋な硝酸カリウムを取り出す方法とその原理を説明せよ。", "a": "混合物を高温の水に溶かしてから冷却すると、温度による【溶解度】の変化が大きい【硝酸カリウム】は、溶けきれなくなった分が結晶として析出する。一方、量の少ない塩化ナトリウムは【飽和】に達しないため溶液中に残る。この析出した結晶をろ過して取り出す。このように溶解度の差を利用して物質を精製する方法を【再結晶】という。"},
  {"id": "chemx30", "s": "chem", "lv": 1, "topic": "イオン化傾向", "q": "硫酸銅(Ⅱ)水溶液に亜鉛板を入れると、亜鉛板の表面に銅が析出する理由を説明せよ。", "a": "金属が水溶液中で電子を失って【陽イオン】になろうとする性質を【イオン化傾向】という。亜鉛は銅よりもイオン化傾向が大きいため、亜鉛が電子を放出して亜鉛イオンとなって溶け出し、その電子を銅(Ⅱ)イオンが受け取って銅として析出する。このとき亜鉛は【酸化】され、銅(Ⅱ)イオンは【還元】されている。"},
  {"id": "chemx31", "s": "chem", "lv": 1, "topic": "鉄の製錬", "q": "溶鉱炉で鉄鉱石から鉄を取り出すしくみと、得られた銑鉄から鋼をつくる理由を説明せよ。", "a": "溶鉱炉に鉄鉱石・【コークス】・石灰石を入れ、熱風を送ると、コークスから生じた【一酸化炭素】が酸化鉄から酸素を奪って【還元】し、鉄が得られる。この【銑鉄】は炭素を約4%含み、硬いがもろい。そこで【転炉】で酸素を吹き込んで炭素を燃焼させて減らし、ねばり強い【鋼】にする。"},
  {"id": "chemx32", "s": "chem", "lv": 1, "topic": "エステル化", "q": "酢酸とエタノールから酢酸エチルをつくる反応について、反応の種類と条件を説明せよ。", "a": "カルボン酸とアルコールから水がとれて結合する反応を【エステル化】といい、酢酸とエタノールからは果実のような香りをもつ【酢酸エチル】が生じる。この反応は【濃硫酸】を触媒として加熱して行う。この反応は【可逆反応】であり、逆に酢酸エチルに水を加えて分解する反応を加水分解という。"},
  {"id": "chemx33", "s": "chem", "lv": 1, "topic": "熱可塑性樹脂と熱硬化性樹脂", "q": "熱可塑性樹脂と熱硬化性樹脂のちがいを、分子の構造と関連づけて説明せよ。", "a": "【熱可塑性樹脂】は、ポリエチレンのように長い【鎖状構造】の分子からなり、加熱すると分子が動きやすくなってやわらかくなるため、成形やリサイクルがしやすい。【熱硬化性樹脂】は、フェノール樹脂のように分子が三次元的につながった【立体網目構造】をもち、加熱しても軟らかくならず、硬く熱に強いため、食器や電気部品に使われる。"},
  {"id": "chemx34", "s": "chem", "lv": 2, "topic": "イオン化エネルギーの周期性", "q": "イオン化エネルギーが周期表の同じ周期では右ほど、同じ族では上ほど大きくなる傾向がある理由を説明せよ。", "a": "【イオン化エネルギー】は、原子から電子1個を取り去って1価の陽イオンにするのに必要なエネルギーである。同じ周期では右にいくほど原子核の【正電荷】が増え、最外殻電子が強く引きつけられるので大きくなり、【貴ガス】で最大となる。同じ族では下にいくほど最外殻が原子核から【遠く】なり、電子が取れやすくなるので小さくなる。そのためアルカリ金属は陽イオンになりやすい。"},
  {"id": "chemx35", "s": "chem", "lv": 2, "topic": "極性分子", "q": "二酸化炭素と水はどちらも極性のある結合をもつが、二酸化炭素は無極性分子、水は極性分子である。その理由を説明せよ。", "a": "C=O結合やO-H結合では、【電気陰性度】の大きい酸素原子の側に共有電子対がかたよるため、結合に【極性】がある。二酸化炭素は【直線形】の分子なので、二つの結合の極性が互いに打ち消しあい、分子全体として無極性となる。一方、水は【折れ線形】の分子なので、結合の極性が打ち消されず、分子全体として【極性分子】となる。"},
  {"id": "chemx36", "s": "chem", "lv": 2, "topic": "氷の密度", "q": "多くの物質では固体のほうが液体より密度が大きいが、水では氷が水に浮く。その理由を説明せよ。", "a": "氷では、各水分子が周囲の4個の分子と【水素結合】で結びつき、【正四面体】の配置がくり返されたすき間の多い結晶構造をつくっている。そのため体積が大きく密度が小さい。融解すると水素結合の一部が切れて、分子がすき間に入りこむので体積が減り、【密度】が大きくなる。水の密度は約【4℃】で最大となる。"},
  {"id": "chemx37", "s": "chem", "lv": 2, "topic": "ヘンリーの法則", "q": "炭酸飲料の栓を開けると泡が発生する理由を、気体の溶解度と関連づけて説明せよ。", "a": "溶解度の小さい気体では、温度が一定のとき、一定量の溶媒に溶ける気体の物質量は、その気体の【分圧】に比例する。これを【ヘンリーの法則】という。炭酸飲料は高い圧力の【二酸化炭素】を溶かして密封されている。栓を開けると容器内の二酸化炭素の分圧が下がり、溶けていられる量が減るため、溶けきれなくなった二酸化炭素が【気泡】となって出てくる。"},
  {"id": "chemx38", "s": "chem", "lv": 2, "topic": "凝析と塩析", "q": "疎水コロイドと親水コロイドについて、電解質を加えたときの沈殿のしかたのちがいを説明せよ。", "a": "【疎水コロイド】は、水和している水分子が少なく、コロイド粒子が同じ符号に【帯電】して反発しあうことで分散している。そのため少量の電解質を加えると電荷が中和されて沈殿する(【凝析】)。【親水コロイド】は多数の水分子が【水和】して安定しているため、少量の電解質では沈殿せず、多量の電解質を加えて水和水を奪うことで沈殿する(【塩析】)。"},
  {"id": "chemx39", "s": "chem", "lv": 2, "topic": "鉛蓄電池", "q": "鉛蓄電池が放電すると電解液の濃度が低下する理由と、充電が可能である理由を説明せよ。", "a": "鉛蓄電池は、負極に【鉛】、正極に酸化鉛(Ⅳ)、電解液に【希硫酸】を用いる。放電すると両極で硫酸イオンが反応して水に溶けにくい【硫酸鉛(Ⅱ)】が電極表面に付着し、同時に水が生成するため、硫酸の濃度が低下する。外部の電源で逆向きに電流を流すと逆の反応が起こってもとの物質にもどるため、充電してくり返し使える【二次電池】となる。"},
  {"id": "chemx40", "s": "chem", "lv": 2, "topic": "燃料電池", "q": "水素を燃料とする燃料電池のしくみと、その利点を説明せよ。", "a": "【燃料電池】は、負極に【水素】、正極に酸素を供給し、水素が電子を放出する酸化反応と、酸素が電子を受け取る還元反応を別々の電極で行わせて電流を取り出す。全体としては水素と酸素から【水】ができる反応である。燃焼させて熱を利用する方法よりも、化学エネルギーを直接【電気エネルギー】に変えるためエネルギー効率が高く、発電時に二酸化炭素を出さない。"},
  {"id": "chemx41", "s": "chem", "lv": 2, "topic": "ヘスの法則", "q": "ヘスの法則の内容と、それが反応熱(反応エンタルピー)を求めるうえで役立つ理由を説明せよ。", "a": "【ヘスの法則】とは、反応熱(【反応エンタルピー】)は反応の最初と最後の状態だけで決まり、途中の【経路】によらないという法則である。たとえば黒鉛から一酸化炭素だけを生成させる反応は、二酸化炭素も生じてしまうため【直接測定】が難しい。しかし黒鉛と一酸化炭素の【燃焼】の反応熱がわかれば、その差から計算によって求めることができる。"},
  {"id": "chemx42", "s": "chem", "lv": 2, "topic": "アルミニウムの溶融塩電解", "q": "アルミニウムを水溶液の電気分解ではなく溶融塩電解で製造する理由と、その工夫を説明せよ。", "a": "アルミニウムは【イオン化傾向】が大きいため、水溶液を電気分解すると陰極では水が還元されて水素が発生し、アルミニウムは得られない。そこで水を含まない融解状態で電気分解する【溶融塩電解】を行う。原料の【酸化アルミニウム】は融点が非常に高いため、融解した【氷晶石】に溶かして融点を下げている。大量の電力を必要とするため、【リサイクル】の意義が大きい。"},
  {"id": "chemx43", "s": "chem", "lv": 2, "topic": "ベンゼンの反応性", "q": "ベンゼンは不飽和結合をもつにもかかわらず、付加反応よりも置換反応を起こしやすい。その理由を説明せよ。", "a": "ベンゼンの6個の炭素原子間の結合はすべて等しく、電子が環全体に広がって【非局在化】した特別に安定な構造をもつ。【付加反応】が起こるとこの安定な環の構造が失われるため起こりにくく、【置換反応】では環の構造が保たれるため起こりやすい。たとえば鉄を触媒として塩素を反応させると、【クロロベンゼン】が生じる置換反応が起こる。"},
  {"id": "chemx44", "s": "chem", "lv": 2, "topic": "デンプンとセルロース", "q": "デンプンとセルロースはどちらもグルコースからなるのに、性質が大きく異なる理由を説明せよ。", "a": "デンプンは【α-グルコース】が縮合重合してできており、分子が【らせん構造】をとるため、ヨウ素デンプン反応を示し、アミラーゼによって分解されるので人は消化できる。セルロースは【β-グルコース】が直線状につながり、分子どうしが【水素結合】で強く結びついて丈夫な繊維となる。人はセルロースを分解する酵素をもたないため、消化することができない。"},
  {"id": "chemx45", "s": "chem", "lv": 2, "topic": "ハロゲンの酸化力", "q": "臭化カリウム水溶液に塩素を通じると臭素が生じるが、塩化カリウム水溶液に臭素を加えても反応しない。その理由を説明せよ。", "a": "ハロゲンの単体は電子を受け取って陰イオンになろうとする【酸化剤】としてはたらく。その強さは原子番号が小さいほど大きく、F₂>Cl₂>Br₂>I₂の順になる。原子半径が小さいほど原子核が電子を強く引きつけるためである。【塩素】は臭素より【酸化力】が強いので、臭化物イオンから電子を奪って【臭素】を遊離させるが、酸化力の弱い臭素は塩化物イオンを酸化できない。"},
  {"id": "chemx46", "s": "chem", "lv": 3, "topic": "平衡定数と温度", "q": "化学平衡の平衡定数は、濃度・圧力・触媒・温度のうち何によって変化するか。発熱反応の場合を例に説明せよ。", "a": "【平衡定数】は、一定の温度では濃度や圧力を変えても変化せず、【温度】によってのみ変化する。濃度や圧力を変えると平衡は移動するが、新しい平衡状態でも平衡定数は同じ値をとる。【触媒】は正反応と逆反応の速さを同じ割合で大きくするので、平衡に達する時間は短くなるが平衡は移動しない。【発熱反応】では、温度を上げると【吸熱】方向の逆反応へ平衡が移動するため、平衡定数は小さくなる。"},
  {"id": "chemx47", "s": "chem", "lv": 3, "topic": "ハーバー・ボッシュ法", "q": "ハーバー・ボッシュ法でアンモニアを合成する際、平衡の点では有利な低温ではなく約500℃で反応させる理由を説明せよ。", "a": "アンモニアの生成は【発熱反応】で、気体の分子数が減少する反応であるから、ルシャトリエの原理より【低温】・【高圧】ほど平衡は生成側に移動する。しかし温度が低すぎると【反応速度】が極めて小さくなり、平衡に達するまでに長い時間がかかる。そこで【鉄】を主成分とする触媒を用い、平衡上の不利と反応速度とを兼ね合わせて、約500℃・高圧という条件で効率よく生産している。"},
  {"id": "chemx48", "s": "chem", "lv": 3, "topic": "弱酸の電離度", "q": "酢酸水溶液を水で薄めていくと、酢酸の電離度はどのように変化するか。理由とともに説明せよ。", "a": "酢酸は一部だけが電離する【弱酸】で、温度が一定なら【電離定数】Kaは一定である。濃度c、電離度αのとき、αが十分小さければKa≒cα²となり、α≒√(Ka/c)と表される。したがって溶液を薄めて濃度が小さくなるほど【電離度】は大きくなる。これは、薄めるとイオンどうしが出会う機会が減り、【電離平衡】が電離する方向へ移動するためである。ただし水素イオン濃度√(cKa)は小さくなる。"},
  {"id": "chemx49", "s": "chem", "lv": 3, "topic": "アンモニアソーダ法", "q": "アンモニアソーダ法で炭酸ナトリウムを製造する過程と、その工夫を説明せよ。", "a": "飽和食塩水に【アンモニア】を十分に吸収させてから二酸化炭素を吹き込むと、水への溶解度が比較的小さい【炭酸水素ナトリウム】が沈殿する。アンモニアを先に溶かすのは、溶液を塩基性にして二酸化炭素を多く吸収させるためである。これを熱分解すると炭酸ナトリウムが得られる。生じる二酸化炭素や、塩化アンモニウムと水酸化カルシウムから得たアンモニアを【回収・再利用】するため、全体では塩化ナトリウムと【炭酸カルシウム】から炭酸ナトリウムと塩化カルシウムを得る効率的な方法となる。"},
  {"id": "chemx50", "s": "chem", "lv": 3, "topic": "フェノールの酸性", "q": "フェノールがアルコールと異なり弱い酸性を示す理由と、炭酸との酸の強さの関係を説明せよ。", "a": "フェノールは【ヒドロキシ基】がベンゼン環に直接結合しており、水素イオンを放出して生じるフェノキシドイオンの負電荷がベンゼン環に【非局在化】して安定化されるため、わずかに電離して弱い【酸性】を示す。アルコールではこのような安定化がないため中性である。フェノールは【炭酸】よりも弱い酸なので、ナトリウムフェノキシドの水溶液に二酸化炭素を通じると【フェノール】が遊離する。"},
  {"id": "biox26", "s": "bio", "lv": 1, "topic": "原核細胞と真核細胞", "q": "原核細胞と真核細胞の構造上のちがいと共通点を説明せよ。", "a": "【原核細胞】は【核膜】をもたず、DNAが細胞質中に存在し、ミトコンドリアなど膜で囲まれた細胞小器官ももたない。細菌やシアノバクテリアがこれにあたる。【真核細胞】は核膜で囲まれた核をもち、ミトコンドリアなどの細胞小器官が発達している。一方、どちらも【細胞膜】で囲まれ、遺伝物質として【DNA】をもち、タンパク質を合成するリボソームをもつ点は共通である。"},
  {"id": "biox27", "s": "bio", "lv": 1, "topic": "赤血球と浸透", "q": "ヒトの赤血球を蒸留水と濃い食塩水にそれぞれ入れると、どのような変化が起こるか。理由とともに説明せよ。", "a": "細胞膜は水を通しやすく、多くの溶質を通しにくい性質をもつ。赤血球を蒸留水のような【低張液】に入れると、【浸透】によって水が細胞内に入り、赤血球は膨張して破裂する(【溶血】)。濃い食塩水のような【高張液】に入れると、細胞内の水が外へ出ていき、赤血球は【収縮】する。"},
  {"id": "biox28", "s": "bio", "lv": 1, "topic": "転写と翻訳", "q": "遺伝子の情報からタンパク質が合成されるまでの過程を説明せよ。", "a": "まず核内で、DNAの塩基配列が写しとられて【mRNA】が合成される。これを【転写】という。mRNAは細胞質へ移動し、【リボソーム】で、連続する3つの塩基からなる【コドン】に対応するアミノ酸がtRNAによって運ばれ、順につながれてタンパク質が合成される。これを【翻訳】という。このような遺伝情報の流れをセントラルドグマという。"},
  {"id": "biox29", "s": "bio", "lv": 1, "topic": "自然免疫と獲得免疫", "q": "自然免疫と獲得免疫のちがいを説明せよ。", "a": "【自然免疫】は、好中球や【マクロファージ】などが、侵入した異物を【食作用】によって非特異的に排除するしくみで、すばやくはたらく。【獲得免疫】は、T細胞やB細胞などのリンパ球が特定の【抗原】を認識して特異的に排除するしくみで、はたらき始めるまでに時間がかかるが、【記憶細胞】が残るため、同じ抗原が再び侵入すると速く強く反応できる。"},
  {"id": "biox30", "s": "bio", "lv": 1, "topic": "自律神経", "q": "自律神経系の交感神経と副交感神経のはたらきを、具体例を挙げて説明せよ。", "a": "自律神経系は、意思とは関係なく内臓などのはたらきを調節し、その中枢は間脳の【視床下部】にある。【交感神経】は活動時や緊張時にはたらき、心臓の拍動を促進し、消化管の運動を抑制する。【副交感神経】は休息時にはたらき、心臓の拍動を抑制し、消化管の運動を促進する。多くの器官は両者の支配を受け、互いに【拮抗的】に作用して調節されている。"},
  {"id": "biox31", "s": "bio", "lv": 1, "topic": "血液凝固", "q": "血管が傷ついたとき、出血が止まるしくみを説明せよ。", "a": "血管が傷つくと、まず傷口に【血小板】が集まって付着する。さらに血小板などから放出される凝固因子のはたらきで、血しょう中のフィブリノーゲンが繊維状の【フィブリン】に変化する。フィブリンが赤血球などの血球をからめとって【血ぺい】をつくり、傷口をふさいで出血を止める。これを【血液凝固】という。"},
  {"id": "biox32", "s": "bio", "lv": 1, "topic": "生態ピラミッド", "q": "生態系で、栄養段階が上がるほど個体数や生物量が小さくなる傾向がある理由を、エネルギーの流れから説明せよ。", "a": "生産者が光合成で取りこんだエネルギーは、【食物連鎖】を通じて上位の消費者へ移っていく。しかし各【栄養段階】では、取りこんだエネルギーの多くが【呼吸】で消費されたり、枯死・死亡や不消化の排出物として分解者へ渡ったりするため、次の段階へ移るのはその一部にすぎない。そのため上位ほど利用できるエネルギーが少なく、個体数や生物量を積み重ねると【生態ピラミッド】の形になる。"},
  {"id": "biox33", "s": "bio", "lv": 1, "topic": "外来生物", "q": "外来生物が在来の生態系に大きな影響を与えることがある理由を説明せよ。", "a": "【外来生物】とは、人間の活動によって本来の生息地以外から持ちこまれ定着した生物である。移入先には【天敵】がいないことが多いため急速に増え、【在来種】を捕食したり、食物やすみかをめぐって競争したり、近縁種と交雑したりする。その結果、在来種が減少して【生物多様性】が損なわれる。日本では【外来生物法】により特定外来生物の飼育や放出などが規制されている。"},
  {"id": "biox34", "s": "bio", "lv": 2, "topic": "細胞内共生説", "q": "ミトコンドリアと葉緑体が、もともと独立した原核生物であったとする細胞内共生説の根拠を説明せよ。", "a": "【細胞内共生説】では、ミトコンドリアは【好気性細菌】が、葉緑体は【シアノバクテリア】が、別の細胞に取りこまれて共生するようになったものと考える。その根拠として、両者が核とは別の独自の【DNA】をもつこと、【二重膜】で包まれていること、細胞内で【分裂】によって増えることなどが挙げられる。"},
  {"id": "biox35", "s": "bio", "lv": 2, "topic": "ナトリウムポンプ", "q": "ナトリウムポンプのはたらきと、それが細胞にとって重要である理由を説明せよ。", "a": "【ナトリウムポンプ】は細胞膜にあるタンパク質で、【ATP】を分解して得たエネルギーを用いて、Na⁺を細胞外へ、K⁺を細胞内へ、それぞれ濃度の低い側から高い側へ輸送する。このような濃度勾配に逆らう輸送を【能動輸送】という。これにより細胞内外のイオン濃度の差が維持され、神経細胞の【静止電位】の形成や細胞の体積の調節などに役立っている。"},
  {"id": "biox36", "s": "bio", "lv": 2, "topic": "鎌状赤血球症", "q": "鎌状赤血球症の原因となる遺伝子の変化と、この遺伝子がアフリカの一部地域で高い頻度でみられる理由を説明せよ。", "a": "鎌状赤血球症は、ヘモグロビンの遺伝子のわずか1塩基が別の塩基に【置換】したことで、アミノ酸の1つがグルタミン酸からバリンに変わって生じる。この異常なヘモグロビンをもつ赤血球は、酸素が少ないと鎌状に変形し、重い【貧血】を起こす。しかしこの遺伝子を一方だけもつ【ヘテロ接合体】は【マラリア】にかかりにくいため、マラリアの多い地域では自然選択によってこの遺伝子が残りやすい。"},
  {"id": "biox37", "s": "bio", "lv": 2, "topic": "エイズ", "q": "HIVに感染すると、さまざまな感染症にかかりやすくなる理由を説明せよ。", "a": "【HIV】は、獲得免疫の司令塔の役割を果たす【ヘルパーT細胞】に感染して、これを破壊する。ヘルパーT細胞はB細胞による【抗体】の産生やキラーT細胞の活性化を助けているため、その数が減ると【獲得免疫】全体のはたらきが低下する。その結果、健康な人ではほとんど発症しない病原体にも感染して発症する【日和見感染】が起こりやすくなる。この状態がエイズである。"},
  {"id": "biox38", "s": "bio", "lv": 2, "topic": "筋収縮のしくみ", "q": "骨格筋が収縮するしくみを、フィラメントの動きとカルシウムイオンの役割にふれて説明せよ。", "a": "運動神経からの刺激で筋細胞が興奮すると、【筋小胞体】から【カルシウムイオン】が放出される。これがアクチンフィラメント上のトロポニンに結合すると、ミオシン頭部がアクチンと結合できるようになる。ミオシンは【ATP】を分解したエネルギーで【アクチンフィラメント】をたぐり寄せ、フィラメント自体の長さは変わらないまま、両者の重なりが大きくなってサルコメアが短縮する。これを【滑り説】という。"},
  {"id": "biox39", "s": "bio", "lv": 2, "topic": "シナプスでの伝達", "q": "シナプスにおいて興奮が一方向にしか伝わらない理由を説明せよ。", "a": "興奮が軸索の末端に達すると、【シナプス小胞】からアセチルコリンなどの【神経伝達物質】がシナプス間隙に放出される。これが次の細胞の膜にある【受容体】に結合するとイオンチャネルが開き、興奮が伝わる。神経伝達物質を放出するしくみは軸索末端側(シナプス前細胞)にしかなく、受容体は受け取る側(シナプス後細胞)にしかないため、興奮の【伝達】は一方向に限られる。"},
  {"id": "biox40", "s": "bio", "lv": 2, "topic": "形成体と誘導", "q": "シュペーマンの移植実験から明らかになった形成体のはたらきを説明せよ。", "a": "シュペーマンは、イモリの初期原腸胚の【原口背唇部】を別の胚の腹側に移植すると、そこに神経管などをもつ【二次胚】が形成されることを示した。原口背唇部は、接する外胚葉にはたらきかけて神経管に分化させる。このように胚の一部が他の部分の分化の方向を決めることを【誘導】といい、誘導をはたらきかける部域を【形成体】(オーガナイザー)という。発生では誘導が連鎖的に起こって器官が形成される。"},
  {"id": "biox41", "s": "bio", "lv": 2, "topic": "頂芽優勢", "q": "植物の頂芽を切り取ると、側芽が成長し始める理由を説明せよ。", "a": "頂芽が成長している間は、頂芽でつくられた【オーキシン】が茎の中を下方へ移動し、【側芽】の成長を抑制している。これを【頂芽優勢】という。オーキシンは茎での【サイトカイニン】の合成を抑えると考えられており、頂芽を切り取るとオーキシンの供給が断たれてサイトカイニンが側芽にはたらき、側芽が成長し始める。"},
  {"id": "biox42", "s": "bio", "lv": 2, "topic": "光発芽種子", "q": "レタスなどの光発芽種子の発芽が光の種類によってどのように制御されるか、その生態的な意義とともに説明せよ。", "a": "光発芽種子では、光受容体の【フィトクロム】が【赤色光】を吸収すると活性型に変わり、ジベレリンの合成を促して発芽が起こる。【遠赤色光】を吸収すると不活性型にもどり、発芽は抑えられる。他の植物の葉の下では赤色光が葉に吸収されて遠赤色光の割合が高くなる。そのため、上をおおう植物がなく、【光合成】に十分な光が届く場所でのみ発芽できるという意義がある。"},
  {"id": "biox43", "s": "bio", "lv": 2, "topic": "密度効果", "q": "個体群の成長曲線がS字状になる理由を、密度効果を用いて説明せよ。", "a": "個体数が少ないうちは個体群は急速に増加する。しかし【個体群密度】が高くなると、食物や生活空間の不足、排出物の蓄積などによって出生率が低下し死亡率が上昇する。このように密度が個体群の性質に影響を与えることを【密度効果】という。そのため増加は次第に鈍り、その環境で維持できる最大の個体数である【環境収容力】に近づいて頭打ちとなり、成長曲線は【S字状】になる。"},
  {"id": "biox44", "s": "bio", "lv": 2, "topic": "窒素固定", "q": "窒素固定とは何か。それが生態系の窒素循環で果たす役割を説明せよ。", "a": "大気中には窒素が豊富にあるが、ほとんどの生物は窒素分子(N₂)を直接利用できない。【根粒菌】やアゾトバクター、一部の【シアノバクテリア】などは、窒素分子をアンモニウムイオンに変える【窒素固定】を行う。生じたアンモニウムイオンや、それが硝化菌によって変えられた硝酸イオンを植物が吸収し、【窒素同化】によってアミノ酸などの有機窒素化合物を合成する。こうして窒素が生態系に取りこまれる。"},
  {"id": "biox45", "s": "bio", "lv": 2, "topic": "PCR法", "q": "PCR法によってDNAの特定の領域を大量に増やすしくみを説明せよ。", "a": "PCR法では、まず約95℃に加熱して2本鎖DNAを1本ずつに【解離】させる。次に温度を下げて、増やしたい領域の両端に相補的な短い1本鎖の【プライマー】を結合させる。さらに約72℃にして【耐熱性】の【DNAポリメラーゼ】によりプライマーに続く新しい鎖を合成する。この温度変化の1サイクルごとに目的の領域が約2倍になるため、くり返すことで【指数関数的】に増幅できる。"},
  {"id": "biox46", "s": "bio", "lv": 3, "topic": "選択的スプライシング", "q": "真核生物のスプライシングとは何か。選択的スプライシングがもつ意義とともに説明せよ。", "a": "真核生物では、転写されたmRNA前駆体から、タンパク質の情報をもたない【イントロン】の部分が取り除かれ、【エキソン】の部分どうしがつながれて成熟したmRNAとなる。これを【スプライシング】という。どのエキソンを残すかの組み合わせを変える【選択的スプライシング】によって、1つの遺伝子から複数の種類のmRNAがつくられるため、遺伝子の数よりも多くの種類の【タンパク質】を合成することが可能になる。"},
  {"id": "biox47", "s": "bio", "lv": 3, "topic": "母性効果遺伝子", "q": "ショウジョウバエの前後軸の決定において、ビコイド遺伝子がどのようにはたらくか説明せよ。", "a": "ビコイド遺伝子は、子の形質が母親の遺伝子型によって決まる【母性効果遺伝子】である。卵形成の過程で、母親の細胞から供給された【ビコイドmRNA】が卵の前端に局在する。受精後にこれが翻訳されると、ビコイドタンパク質が前方で高く後方で低い【濃度勾配】をつくる。この濃度に応じて異なる遺伝子の発現が調節され、【前後軸】が決まり、前方に頭部が形成される。"},
  {"id": "biox48", "s": "bio", "lv": 3, "topic": "ハーディ・ワインベルグの法則", "q": "ハーディ・ワインベルグの法則が成り立つ条件を挙げ、この法則が進化の理解にとってもつ意味を説明せよ。", "a": "ハーディ・ワインベルグの法則は、集団が十分に【大きく】、自由に交配し、【突然変異】が起こらず、他集団との移出入がなく、【自然選択】がはたらかないとき、集団の【遺伝子頻度】は世代を経ても変化しないというものである。進化とは集団の遺伝子頻度が変化することであるから、逆に言えば、現実の集団でこれらの条件が崩れることが、自然選択や【遺伝的浮動】などによる進化の要因となることを示している。"},
  {"id": "biox49", "s": "bio", "lv": 3, "topic": "分子時計", "q": "分子時計とは何か。それによって生物の系統を推定できる理由を、中立説と関連づけて説明せよ。", "a": "DNAの塩基配列やタンパク質のアミノ酸配列に生じる置換が、ほぼ一定の速度で蓄積していく性質を【分子時計】という。【木村資生】の【中立説】によれば、生存に有利でも不利でもない中立的な突然変異は自然選択を受けず、遺伝的浮動によって一定の速さで集団に広がる。そのため2つの生物の間の配列の【違いの数】は、共通祖先から分かれてからの時間におおよそ比例し、分岐年代や【系統樹】の推定に利用できる。"},
  {"id": "biox50", "s": "bio", "lv": 3, "topic": "競争的排除", "q": "ガウゼのゾウリムシの実験をもとに、生態的地位(ニッチ)と種間競争・共存の関係を説明せよ。", "a": "ゾウリムシとヒメゾウリムシを同じ容器で混合飼育すると、食物などの要求が似ているため【種間競争】が起こり、やがて一方が絶滅した。このように【生態的地位】が大きく重なる種どうしは共存できない(【競争的排除】)。一方、ゾウリムシとミドリゾウリムシでは、容器内で主に生活する場所が上部と底部に分かれ、共存できた。このように、ニッチを分けあう【すみわけ】や食い分けによって共存が可能になる。"},
  {"id": "earthx26", "s": "earth", "lv": 1, "topic": "深成岩と火山岩", "q": "花こう岩と玄武岩などで、岩石の組織が異なる理由を、マグマの冷え方から説明せよ。", "a": "花こう岩のような【深成岩】は、マグマが地下深くで【ゆっくり】冷え固まったため、鉱物が大きく成長し、ほぼ同じ大きさの結晶がそろった【等粒状組織】を示す。玄武岩のような【火山岩】は、マグマが地表や地表付近で急に冷え固まったため、大きな結晶(斑晶)が細かい粒やガラス(石基)の中に散らばる【斑状組織】を示す。"},
  {"id": "earthx27", "s": "earth", "lv": 1, "topic": "地層累重の法則", "q": "地層累重の法則とは何か。この法則を用いる際の注意点とともに説明せよ。", "a": "地層は下から順に積み重なっていくので、地層が逆転していなければ、【下】にある地層ほど古い。これを【地層累重の法則】という。ただし激しい地殻変動による褶曲などで地層が【逆転】していることがあるため、粒子が下ほど粗くなる【級化層理】や、水流の跡であるリプルマークなどの堆積構造から、地層の上下を判定する必要がある。"},
  {"id": "earthx28", "s": "earth", "lv": 1, "topic": "不整合", "q": "不整合とは何か。不整合ができるまでの過程を説明せよ。", "a": "【不整合】とは、上下の地層の間に長い時間の堆積の【中断】がある重なり方である。海底で地層が堆積したのち、【隆起】して陸上に出ると、表面が風化・【侵食】を受ける。その後再び沈降して海底となり、その上に新しい地層が堆積すると、侵食面を境に不整合ができる。不整合面の直上には、侵食された岩石のかけらからなる【基底礫岩】がみられることが多い。"},
  {"id": "earthx29", "s": "earth", "lv": 1, "topic": "大気の層構造", "q": "地球の大気が、高さによる気温の変化をもとにどのように区分されるか説明せよ。", "a": "地表から約11kmまでの【対流圏】では、太陽放射で暖められた地表から大気が暖められるため、上空ほど気温が下がり、雲や降水などの気象現象が起こる。その上の【成層圏】では、【オゾン】が太陽の紫外線を吸収するため上空ほど気温が上がる。さらにその上の中間圏では再び気温が下がり、最上層の【熱圏】では波長の短い紫外線などを吸収して気温が高くなる。"},
  {"id": "earthx30", "s": "earth", "lv": 1, "topic": "寒冷前線と温暖前線", "q": "寒冷前線と温暖前線とで、雲のでき方や降水の特徴がどのように異なるか説明せよ。", "a": "【寒冷前線】では、寒気が暖気の下にもぐりこんで暖気を急激に押し上げるため、【積乱雲】が発達し、狭い範囲に短時間の強い雨が降り、突風や雷をともなうことが多い。通過後は気温が下がる。【温暖前線】では、暖気が寒気の上をゆるやかにはい上がるため、【乱層雲】などの層状の雲が広がり、広い範囲に長時間の【弱い雨】が降る。通過後は気温が上がる。"},
  {"id": "earthx31", "s": "earth", "lv": 1, "topic": "液状化現象", "q": "地震の際に液状化現象が起こりやすい場所と、そのしくみを説明せよ。", "a": "液状化は、【埋立地】や旧河道など、【地下水】で満たされた、ゆるく堆積した砂の地盤で起こりやすい。ふだんは砂粒どうしがかみ合って建物を支えているが、地震の揺れでかみ合いが外れると、砂粒が水の中に浮いたような状態になり、地盤が【液体】のようにふるまう。その結果、建物が傾いたり沈んだり、地下のマンホールが浮き上がったり、砂と水が地表に噴き出す【噴砂】が起こったりする。"},
  {"id": "earthx32", "s": "earth", "lv": 1, "topic": "マグニチュードと震度", "q": "地震のマグニチュードと震度のちがいを説明せよ。", "a": "【マグニチュード】は地震そのものの規模、すなわち地震が放出した【エネルギー】の大きさを表す尺度で、一つの地震に一つの値が決まる。マグニチュードが1大きくなるとエネルギーは約【32倍】になる。【震度】は各地点での揺れの強さを表し、日本では0〜7の10段階で示される。同じ地震でも震源からの距離や【地盤】の性質によって、地点ごとに震度は異なる。"},
  {"id": "earthx33", "s": "earth", "lv": 1, "topic": "地球型惑星と木星型惑星", "q": "太陽系の惑星を地球型惑星と木星型惑星に分け、その特徴を比較して説明せよ。", "a": "水星・金星・地球・火星の【地球型惑星】は、半径と質量が小さいが、主に岩石と金属からなるため【平均密度】が大きい。衛星は少なく、環をもたない。木星・土星・天王星・海王星の【木星型惑星】は、半径と質量が大きいが、主に【水素】やヘリウムなどの軽い物質からなるため平均密度が小さく、多数の【衛星】と環をもつ。"},
  {"id": "earthx34", "s": "earth", "lv": 2, "topic": "海洋底拡大説", "q": "海洋底拡大説の内容と、それを支持する証拠を説明せよ。", "a": "【海洋底拡大説】は、中央海嶺でマントル物質が上昇して新しい海洋底がつくられ、海嶺の両側へ広がっていくという説である。証拠として、海洋底の岩石の年代が【海嶺】から離れるほど古くなることや、海洋底の岩石に記録された【地磁気】の正逆の縞模様が海嶺を軸として【対称】に分布することが挙げられる。この説は、のちのプレートテクトニクスの基礎となった。"},
  {"id": "earthx35", "s": "earth", "lv": 2, "topic": "変成作用", "q": "接触変成作用と広域変成作用のちがいを、できる岩石の例を挙げて説明せよ。", "a": "【接触変成作用】は、マグマが貫入した周辺の岩石が主にその【熱】によって変化するもので、範囲は狭い。泥岩からは硬く緻密な【ホルンフェルス】が、石灰岩からは結晶質石灰岩(大理石)ができる。【広域変成作用】は、プレートの沈み込み帯などで、広い範囲の岩石が高い温度と圧力を受けて変化するもので、鉱物が一方向に並んだ片理をもつ【結晶片岩】や片麻岩ができる。"},
  {"id": "earthx36", "s": "earth", "lv": 2, "topic": "放射年代", "q": "放射性同位体を用いて岩石の年代を求める方法の原理を説明せよ。", "a": "岩石中の【放射性同位体】(親核種)は、一定の【半減期】で崩壊して別の原子核(娘核種)に変わっていく。半減期は温度や圧力などの条件に左右されないため、鉱物が結晶したときから、残っている親核種と生じた娘核種の量の【比】を測定すれば、その鉱物ができてから経過した年代を求めることができる。これを【放射年代】という。"},
  {"id": "earthx37", "s": "earth", "lv": 2, "topic": "白亜紀末の大量絶滅", "q": "白亜紀末の大量絶滅の原因として有力な説と、その根拠を説明せよ。", "a": "約6600万年前の白亜紀末には、【恐竜】やアンモナイトなど多くの生物が絶滅した。その原因として、巨大な【隕石】の衝突説が有力である。根拠として、世界各地のこの時代の地層に、地球の表層には少なく隕石に多い【イリジウム】が濃集していることや、メキシコの【ユカタン半島】に巨大な衝突クレーターが見つかったことが挙げられる。衝突で舞い上がった粉じんが日光をさえぎり、環境が激変したと考えられている。"},
  {"id": "earthx38", "s": "earth", "lv": 2, "topic": "生物の陸上進出", "q": "古生代に生物が陸上へ進出できるようになった理由を、大気の変化と関連づけて説明せよ。", "a": "かつて地表には生物に有害な強い【紫外線】が降り注いでおり、生物は紫外線が届かない水中でしか生活できなかった。【光合成】を行う生物の活動によって大気中の【酸素】が増加すると、上空に【オゾン層】が形成され、紫外線の多くが吸収されるようになった。その結果、古生代には植物が陸上に進出し、続いて節足動物や両生類などの動物も陸上へ進出した。"},
  {"id": "earthx39", "s": "earth", "lv": 2, "topic": "緯度による熱収支", "q": "低緯度では受け取る太陽放射が放出する地球放射を上回るのに、気温が上がり続けない理由を説明せよ。", "a": "低緯度では【太陽放射】の吸収量が【地球放射】による放出量を上回り、高緯度では逆に下回る。それでも低緯度が加熱され続けず、高緯度が冷え続けないのは、【大気】の大循環や【海流】によって、低緯度の余った熱が高緯度へ【輸送】されているためである。その結果、地球全体として熱収支がつりあい、各緯度の平均気温がほぼ一定に保たれている。"},
  {"id": "earthx40", "s": "earth", "lv": 2, "topic": "梅雨", "q": "日本で梅雨が生じ、やがて梅雨明けを迎えるしくみを説明せよ。", "a": "初夏になると、北の冷たく湿った【オホーツク海高気圧】と、南の暖かく湿った【太平洋高気圧】の勢力がほぼつりあい、その境界に東西にのびる【停滞前線】(梅雨前線)ができる。前線付近では雲が発達し、長雨が続く。7月ごろ太平洋高気圧の勢力が強まって前線が【北上】すると、日本列島は太平洋高気圧におおわれて梅雨明けとなる。"},
  {"id": "earthx41", "s": "earth", "lv": 2, "topic": "年周視差", "q": "恒星の年周視差とは何か。それを用いて恒星までの距離を求める方法と、その歴史的意義を説明せよ。", "a": "【年周視差】とは、地球の【公転】によって、近い恒星が遠い恒星を背景に1年周期で位置を変えて見える現象で、その角度の半分で表す。年周視差は恒星までの距離に【反比例】し、年周視差が1″のときの距離を1【パーセク】(約3.26光年)とする。年周視差の観測は、地球が太陽のまわりを公転していることの直接的な証拠となった。"},
  {"id": "earthx42", "s": "earth", "lv": 2, "topic": "絶対等級", "q": "恒星の見かけの等級と絶対等級のちがいと、絶対等級が用いられる理由を説明せよ。", "a": "【見かけの等級】は地球から見た恒星の明るさで、恒星本来の明るさだけでなく地球からの【距離】にも左右される。そこで恒星を一律に【10パーセク】の距離に置いたと仮定したときの明るさを【絶対等級】として、恒星そのものの明るさを比較する。等級が5等級小さいと明るさは【100倍】となる。"},
  {"id": "earthx43", "s": "earth", "lv": 2, "topic": "銀河系の構造", "q": "銀河系(天の川銀河)の構造と、地球から天の川が帯状に見える理由を説明せよ。", "a": "銀河系は数千億個の恒星などからなり、中心の膨らんだ【バルジ】、直径約10万光年の薄い【円盤部】、それらを球状に取り巻き【球状星団】が分布するハローからなる。太陽系は円盤部の中にあり、中心から約2.8万光年離れている。地球から円盤部の方向を見ると多数の恒星が重なって見えるため、夜空に帯状の【天の川】として見える。"},
  {"id": "earthx44", "s": "earth", "lv": 2, "topic": "太陽のエネルギー源", "q": "太陽が長期間にわたって輝き続けているエネルギー源を説明せよ。", "a": "太陽の中心部の【中心核】は約1600万Kの高温・高密度の状態にあり、4個の【水素】原子核が融合して1個の【ヘリウム】原子核ができる【核融合】反応が起きている。反応の前後でわずかに【質量】が減少し、その分がE=mc²に従って膨大なエネルギーとして放出される。このエネルギーが内部を外側へ運ばれ、表面から放射されている。"},
  {"id": "earthx45", "s": "earth", "lv": 2, "topic": "日食と月食", "q": "日食と月食はそれぞれ月がどの位置にあるときに起こるか。また、毎月起こらない理由を説明せよ。", "a": "【日食】は、太陽・月・地球の順に一直線に並び、月が太陽を隠すときに起こるので【新月】のときに限られる。【月食】は、太陽・地球・月の順に並び、月が地球の影に入るときに起こるので【満月】のときに限られる。しかし月の公転軌道面は地球の公転軌道面(【黄道面】)に対して約5°傾いているため、新月や満月のたびに三者が一直線に並ぶわけではなく、毎月は起こらない。"},
  {"id": "earthx46", "s": "earth", "lv": 3, "topic": "地衡風", "q": "上空の風が等圧線に平行に吹き、地表付近の風が等圧線を斜めに横切って吹く理由を説明せよ。", "a": "空気には気圧の高い方から低い方へ向かう【気圧傾度力】がはたらくが、動き出すと地球の自転による【転向力】(コリオリの力)を受け、北半球では進行方向の右へ曲げられる。摩擦のない上空では、両者がつりあった状態で等圧線に【平行】に吹く。これを【地衡風】という。地表付近では【摩擦力】もはたらいて風速が弱まり、転向力が小さくなるため、等圧線を斜めに横切って低圧側へ吹きこむ。"},
  {"id": "earthx47", "s": "earth", "lv": 3, "topic": "西岸強化", "q": "黒潮やメキシコ湾流のように、大洋の西側を流れる海流が東側の海流よりも強く速い理由を説明せよ。", "a": "北太平洋や北大西洋には、偏西風と貿易風によって駆動される時計回りの【亜熱帯環流】がある。地球の自転による【転向力】が高緯度ほど大きいという性質のために、環流の中心は大洋の西に偏り、大洋の西側では幅が狭く流れの強い海流となる。これを【西岸強化】という。そのため日本近海の【黒潮】や北大西洋の【メキシコ湾流】は、大洋の東側の海流よりも強く速い。"},
  {"id": "earthx48", "s": "earth", "lv": 3, "topic": "会合周期", "q": "外惑星の会合周期とは何か。それが惑星の公転周期とどのような関係にあるか説明せよ。", "a": "【会合周期】とは、惑星が衝などの同じ位置関係に戻るまでの期間である。外惑星は地球より公転周期が長いので、地球が外惑星を1周分【追い越す】ごとに同じ位置関係になる。地球と外惑星の公転周期をE、P、会合周期をSとすると、1/S=1/E−1/Pが成り立つ。たとえば【火星】の会合周期は約2年2か月である。公転周期が長い外惑星ほど、会合周期は【1年】に近づく。"},
  {"id": "earthx49", "s": "earth", "lv": 3, "topic": "宇宙背景放射", "q": "宇宙背景放射とは何か。それがビッグバン宇宙論の証拠とされる理由を説明せよ。", "a": "【ビッグバン】直後の宇宙は高温・高密度で、光は自由電子に散乱されて直進できなかった。約38万年後に宇宙が冷えて電子が原子核と結合すると、光は直進できるようになった(【宇宙の晴れ上がり】)。そのときの光が宇宙の【膨張】によって波長がのばされ、現在では約3Kの物体が出す【マイクロ波】として全天からほぼ一様に観測される。これが【宇宙背景放射】であり、宇宙がかつて高温・高密度であったことを示す証拠とされる。"},
  {"id": "earthx50", "s": "earth", "lv": 3, "topic": "ミランコビッチ・サイクル", "q": "第四紀に氷期と間氷期がくり返された原因として、ミランコビッチ・サイクルの考え方を説明せよ。", "a": "地球の公転軌道の【離心率】、【地軸の傾き】、地軸の向きが変わる【歳差運動】は、それぞれ約10万年、約4万年、約2万年の周期で変化している。これらが重なりあうことで、特に高緯度地域が夏に受ける【日射量】が周期的に変化し、氷床の拡大と縮小が起こると考えられている。さらに氷床による太陽光の反射率の変化や、大気中の【二酸化炭素】濃度の変化が、気候の変化を増幅したとされる。"}
];
